func TestValidRef(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"absent is legal", "", true},
		{"branch", "refs/heads/main", true},
		{"tag", "refs/tags/v1.2.0", true},

		{"unqualified branch", "main", false},
		{"double dot", "refs/heads/a..b", false},
		{"reflog syntax", "refs/heads/a@{1}", false},
		{"trailing slash", "refs/heads/", false},
		{"lock suffix", "refs/heads/main.lock", false},
		{"leading dot", "refs/heads/.hidden", false},
		{"caret", "refs/heads/a^b", false},
		{"space", "refs/heads/a b", false},

		// Narrower than git on purpose: these are legal ref names that would
		// break out of a markdown table cell or an inline-code span, and every
		// other field in this package is an allowlist so that no consumer has
		// to escape anything.
		{"pipe breaks a table cell", "refs/heads/a|b", false},
		{"backtick breaks a code span", "refs/heads/a`b", false},
		{"brackets open a link", "refs/heads/a[b]c", false},
		{"parens close a link", "refs/heads/a(b)c", false},
		{"hash opens a heading", "refs/heads/a#b", false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidRef(tc.in), tc.name)
	}
}

// Package txlink provides utilities for creating transaction-related links
// compatible with Gnoweb, Gnobro, and other clients within the Gno ecosystem.
//
// This package is optimized for generating lightweight transaction links with
// flexible arguments, allowing users to build dynamic links that integrate
// seamlessly with various Gno clients.
//
// The package offers a way to generate clickable transaction MD links
// for the current "relative realm":
//
//  Using a builder pattern for more structured URLs:
//     txlink.NewLink("MyFunc").
//         AddArgs("k1", "v1", "k2", "v2"). // or multiple at once
//         SetSend("1000000ugnot").
//         URL()
//
// The builder pattern (TxBuilder) provides a fluent interface for constructing
// transaction URLs in the current "relative realm". Like Call, it supports both
// local realm paths and fully qualified paths through the underlying Call
// implementation.
//
// The Call function remains the core implementation, used both directly and
// internally by the builder pattern to generate the final URLs.
//
// This package is a streamlined alternative to helplink, providing similar
// functionality for transaction links without the full feature set of helplink.

package txlink

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"net/url"
	"strings"
)

var chainDomain = runtime.ChainDomain()

// Realm represents a specific realm for generating tx links.
type Realm string

// TxBuilder provides a fluent interface for building transaction URLs
type TxBuilder struct {
	fn        string   // function name
	args      []string // key-value pairs
	send      string   // optional send amount
	realm_XXX Realm    // realm for the URL
}

// NewLink creates a transaction link builder for the specified function in the current realm.
func NewLink(fn string) *TxBuilder {
	return Realm("").NewLink(fn)
}

// NewLink creates a transaction link builder for the specified function in this realm.
func (r Realm) NewLink(fn string) *TxBuilder {
	if fn == "" {
		return nil
	}
	return &TxBuilder{fn: fn, realm_XXX: r}
}

// addArg adds a key-value argument pair. Returns the builder for chaining.
func (b *TxBuilder) addArg(key, value string) *TxBuilder {
	if b == nil {
		return nil
	}
	if key == "" {
		return b
	}

	// Special case: "." prefix is for reserved keywords.
	if strings.HasPrefix(key, ".") {
		panic("invalid key")
	}

	b.args = append(b.args, key, value)
	return b
}

// AddArgs adds multiple key-value pairs at once. Arguments should be provided
// as pairs: AddArgs("key1", "value1", "key2", "value2").
func (b *TxBuilder) AddArgs(args ...string) *TxBuilder {
	if b == nil {
		return nil
	}
	if len(args)%2 != 0 {
		panic("odd number of arguments")
	}
	// Add key-value pairs
	for i := 0; i < len(args); i += 2 {
		key := args[i]
		value := args[i+1]
		b.addArg(key, value)
	}
	return b
}

// SetSend adds a send amount. (Only one send amount can be specified.)
func (b *TxBuilder) SetSend(amount string) *TxBuilder {
	if b == nil {
		return nil
	}
	if amount == "" {
		return b
	}
	b.send = amount
	return b
}

// URL generates the final URL using the standard $help&func=name format.
func (b *TxBuilder) URL() string {
	if b == nil || b.fn == "" {
		return ""
	}
	args := b.args
	if b.send != "" {
		args = append(args, ".send", b.send)
	}
	return b.realm_XXX.Call(b.fn, args...)
}

// Call returns a URL for the specified function with optional key-value
// arguments, for the current realm.
func Call(fn string, args ...string) string {
	return Realm("").Call(fn, args...)
}

// prefix returns the URL prefix for the realm.
func (r Realm) prefix() string {
	// relative
	if r == "" {
		curPath := unsafe.CurrentRealm().PkgPath()
		return strings.TrimPrefix(curPath, chainDomain)
	}

	// local realm -> /realm
	rlm := string(r)
	if strings.HasPrefix(rlm, chainDomain) {
		return strings.TrimPrefix(rlm, chainDomain)
	}

	// remote realm -> https://remote.land/realm
	return "https://" + string(r)
}

// Call returns a URL for the specified function with optional key-value
// arguments.
func (r Realm) Call(fn string, args ...string) string {
	if len(args) == 0 {
		return r.prefix() + "$help&func=" + fn
	}

	// Create url.Values to properly encode parameters.
	// But manage &func=fn as a special case to keep it as the first argument.
	values := url.Values{}

	// Check if args length is even
	if len(args)%2 != 0 {
		panic("odd number of arguments")
	}
	// Add key-value pairs to values
	for i := 0; i < len(args); i += 2 {
		key := args[i]
		value := args[i+1]
		values.Add(key, value)
	}

	// Build the base URL and append encoded query parameters
	return r.prefix() + "$help&func=" + fn + "&" + values.Encode()
}

package txlink

import (
	"chain/runtime"
	"testing"

	"gno.land/p/nt/urequire/v0"
)

func TestCall(t *testing.T) {
	cd := runtime.ChainDomain()

	tests := []struct {
		fn        string
		args      []string
		want      string
		realm_XXX Realm
	}{
		{"foo", []string{"bar", "1", "baz", "2"}, "/p/moul/txlink/v0$help&func=foo&bar=1&baz=2", ""},
		{"testFunc", []string{"key", "value"}, "/p/moul/txlink/v0$help&func=testFunc&key=value", ""},
		{"noArgsFunc", []string{}, "/p/moul/txlink/v0$help&func=noArgsFunc", ""},
		{"oddArgsFunc", []string{"key"}, "/p/moul/txlink/v0$help&func=oddArgsFunc&error=odd+number+of+arguments", ""},
		{"foo", []string{"bar", "1", "baz", "2"}, "/r/lorem/ipsum$help&func=foo&bar=1&baz=2", Realm(cd + "/r/lorem/ipsum")},
		{"testFunc", []string{"key", "value"}, "/r/lorem/ipsum$help&func=testFunc&key=value", Realm(cd + "/r/lorem/ipsum")},
		{"noArgsFunc", []string{}, "/r/lorem/ipsum$help&func=noArgsFunc", Realm(cd + "/r/lorem/ipsum")},
		{"oddArgsFunc", []string{"key"}, "/r/lorem/ipsum$help&func=oddArgsFunc&error=odd+number+of+arguments", Realm(cd + "/r/lorem/ipsum")},
		{"foo", []string{"bar", "1", "baz", "2"}, "https://gno.world/r/lorem/ipsum$help&func=foo&bar=1&baz=2", "gno.world/r/lorem/ipsum"},
		{"testFunc", []string{"key", "value"}, "https://gno.world/r/lorem/ipsum$help&func=testFunc&key=value", "gno.world/r/lorem/ipsum"},
		{"noArgsFunc", []string{}, "https://gno.world/r/lorem/ipsum$help&func=noArgsFunc", "gno.world/r/lorem/ipsum"},
		{"oddArgsFunc", []string{"key"}, "https://gno.world/r/lorem/ipsum$help&func=oddArgsFunc&error=odd+number+of+arguments", "gno.world/r/lorem/ipsum"},
		{"test", []string{"key", "hello world"}, "/p/moul/txlink/v0$help&func=test&key=hello+world", ""},
		{"test", []string{"key", "a&b=c"}, "/p/moul/txlink/v0$help&func=test&key=a%26b%3Dc", ""},
		{"test", []string{"key", ""}, "/p/moul/txlink/v0$help&func=test&key=", ""},
		{"testSend", []string{"key", "hello world", ".send", "1000000ugnot"}, "/p/moul/txlink/v0$help&func=testSend&.send=1000000ugnot&key=hello+world", ""},
	}

	for _, tt := range tests {
		title := string(tt.realm_XXX) + "_" + tt.fn
		t.Run(title, func(t *testing.T) {
			if tt.fn == "oddArgsFunc" {
				defer func() {
					if r := recover(); r != nil {
						if r != "odd number of arguments" {
							t.Errorf("expected panic with message 'odd number of arguments', got: %v", r)
						}
					} else {
						t.Error("expected panic for odd number of arguments, but did not panic")
					}
				}()
			}
			got := tt.realm_XXX.Call(tt.fn, tt.args...)
			urequire.Equal(t, tt.want, got)
		})
	}
}

func TestBuilder(t *testing.T) {
	cases := []struct {
		name     string
		build    func() string
		expected string
	}{
		// Basic functionality tests
		{
			name: "empty_function",
			build: func() string {
				return NewLink("").URL()
			},
			expected: "",
		},
		{
			name: "function_without_args",
			build: func() string {
				return NewLink("MyFunc").URL()
			},
			expected: "/p/moul/txlink/v0$help&func=MyFunc",
		},

		// Realm tests
		{
			name: "gnoland_realm",
			build: func() string {
				return Realm("gno.land/r/demo").
					NewLink("MyFunc").
					AddArgs("key", "value").
					URL()
			},
			expected: "/r/demo$help&func=MyFunc&key=value",
		},
		{
			name: "external_realm",
			build: func() string {
				return Realm("gno.world/r/demo").
					NewLink("MyFunc").
					AddArgs("key", "value").
					URL()
			},
			expected: "https://gno.world/r/demo$help&func=MyFunc&key=value",
		},
		{
			name: "empty_realm",
			build: func() string {
				return Realm("").
					NewLink("func").
					AddArgs("key", "value").
					URL()
			},
			expected: "/p/moul/txlink/v0$help&func=func&key=value",
		},

		// URL encoding tests
		{
			name: "url_encoding_with_spaces",
			build: func() string {
				return NewLink("test").
					AddArgs("key", "hello world").
					URL()
			},
			expected: "/p/moul/txlink/v0$help&func=test&key=hello+world",
		},
		{
			name: "url_encoding_with_special_chars",
			build: func() string {
				return NewLink("test").
					AddArgs("key", "a&b=c").
					URL()
			},
			expected: "/p/moul/txlink/v0$help&func=test&key=a%26b%3Dc",
		},
		{
			name: "url_encoding_with_unicode",
			build: func() string {
				return NewLink("func").
					AddArgs("key", "🌟").
					URL()
			},
			expected: "/p/moul/txlink/v0$help&func=func&key=%F0%9F%8C%9F",
		},
		{
			name: "url_encoding_with_special_chars_in_key",
			build: func() string {
				return NewLink("func").
					AddArgs("my/key", "value").
					URL()
			},
			expected: "/p/moul/txlink/v0$help&func=func&my%2Fkey=value",
		},

		// AddArgs tests
		{
			name: "addargs_with_multiple_pairs",
			build: func() string {
				return NewLink("MyFunc").
					AddArgs("key1", "value1", "key2", "value2").
					URL()
			},
			expected: "/p/moul/txlink/v0$help&func=MyFunc&key1=value1&key2=value2",
		},
		{
			name: "addargs_with_odd_number_of_args",
			build: func() string {
				defer func() {
					if r := recover(); r != nil {
						if r != "odd number of arguments" {
							t.Errorf("expected panic with message 'odd number of arguments', got: %v", r)
						}
					} else {
						t.Error("expected panic for odd number of arguments, but did not panic")
					}
				}()
				return NewLink("MyFunc").
					AddArgs("key1", "value1", "orphan").
					URL()
			},
			expected: "",
		},

		// Empty values tests
		{
			name: "empty_key_should_be_ignored",
			build: func() string {
				return NewLink("func").
					AddArgs("", "value").
					URL()
			},
			expected: "/p/moul/txlink/v0$help&func=func",
		},
		{
			name: "empty_value_should_be_kept",
			build: func() string {
				return NewLink("func").
					AddArgs("key", "").
					URL()
			},
			expected: "/p/moul/txlink/v0$help&func=func&key=",
		},

		// Send tests
		{
			name: "send_via_addsend_method",
			build: func() string {
				return NewLink("MyFunc").
					AddArgs("key", "value").
					SetSend("1000000ugnot").
					URL()
			},
			expected: "/p/moul/txlink/v0$help&func=MyFunc&.send=1000000ugnot&key=value",
		},
		{
			name: "send_via_addarg_method_panic",
			build: func() string {
				defer func() {
					if r := recover(); r != nil {
						if r != "invalid key" {
							t.Errorf("expected panic with message 'invalid key', got: %v", r)
						}
					} else {
						t.Errorf("expected panic for .send key, but did not panic")
					}
				}()
				NewLink("MyFunc").AddArgs(".send", "1000000ugnot")
				return "no panic occurred"
			},
			expected: "",
		},
		{
			name: "addsend_should_override_previous_addsend",
			build: func() string {
				return NewLink("MyFunc").
					SetSend("1000000ugnot").
					SetSend("2000000ugnot").
					URL()
			},
			expected: "/p/moul/txlink/v0$help&func=MyFunc&.send=2000000ugnot",
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := tc.build()
			urequire.Equal(t, tc.expected, got)
		})
	}
}

// Package greet is a tiny pure package used as a canary: it proves that
// versioned cross-package resolution (gno.land/p/moul/greet/v0) works in the
// workspace and in CI. Replace or remove it once real packages land.
package greet

import "strings"

// Greet returns a friendly greeting for name (defaults to "world").
func Greet(name string) string {
	name = strings.TrimSpace(name)
	if name == "" {
		name = "world"
	}
	return "Hello, " + name + "!"
}

package greet

import "testing"

func TestGreet(t *testing.T) {
	cases := map[string]string{
		"":      "Hello, world!",
		"  ":    "Hello, world!",
		"moul":  "Hello, moul!",
		" gno ": "Hello, gno!",
	}
	for in, want := range cases {
		if got := Greet(in); got != want {
			t.Errorf("Greet(%q) = %q, want %q", in, got, want)
		}
	}
}

// Package store is the auto-id ordered collection every r/moul realm was
// building by hand: an avl.Tree, an int counter, and a private function that
// zero-pads the counter into a key so the tree iterates in the order a human
// expects.
//
// Sixteen realm files in this repo carry that third piece. They do not agree:
//
//	padID  width 6   for len(s) < 6 { s = "0" + s }            asciiart
//	pad    width 12  for len(s) < 12 { s = "0" + s }           tictactoe
//	key    width 12  the same loop, a different name           blog, crowdfund,
//	                                                           englishauction,
//	                                                           erc721, splitter
//	idKey  width 12  the same loop, a third name               connect4
//	idKey  width 12  strings.Repeat, guarded by len(s) >= 12   governor, todos
//	idKey  width 12  strings.Repeat, UNGUARDED                 timecapsule
//	seqKey width 16  strings.Repeat, guarded                   guestbook
//
// Every one of them is a silent ceiling. Past the width, the padding stops and
// the tree starts ordering "1000000000000" before "999999999999", so the list
// a realm renders is simply wrong from that entry on. The unguarded variant is
// worse: strings.Repeat panics on a negative count, so the realm stops
// accepting writes rather than merely mis-sorting them. asciiart's width of 6
// puts that ceiling at one million entries.
//
// The ceiling exists because the key is a decimal string, and decimal strings
// do not sort numerically. This package removes the ceiling by removing the
// decision: keys are the big-endian bytes of a [gno.land/p/nt/seqid/v0] ID, a
// fixed 8 bytes whose lexicographic order IS numeric order, for every value a
// uint64 can hold. There is no width to pick and no width to outgrow.
//
// # Usage
//
//	var games store.Store             // the zero value is an empty store
//
//	func NewGame(cur realm) int64 {
//		id := games.Add(&Game{...})
//		return int64(id)
//	}
//
//	func Move(cur realm, gameID int64, cell int) {
//		g := games.MustGet(store.ID(gameID)).(*Game)
//		...
//	}
//
//	func Render(path string) string {
//		for _, e := range games.PageReverse(1, 20) {   // newest first
//			g := e.Value.(*Game)
//			... e.ID ...
//		}
//	}
//
// # Identifiers
//
// An ID is a uint64 that renders as a plain decimal number, so a realm ported
// to this package keeps showing "#7" exactly as it did before. Only the avl
// key changes, and the key was never user-visible.
//
// IDs start at 1. The zero ID is never assigned, so it is usable as "absent",
// and [Store.Get] on it always misses.
//
// Removing an entry does not free its ID. IDs are a history, not a dense
// index: reusing one would silently repoint an old link at a new object.
package store

import (
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

// ID identifies one entry. It is a plain integer to the outside world and an
// ordered fixed-width key inside the tree.
type ID uint64

// String renders the ID in decimal, which is how realms show it and how it
// arrives back in a Render path.
func (id ID) String() string { return strconv.FormatUint(uint64(id), 10) }

// Key is the avl key for the ID: the 8 big-endian bytes of the underlying
// seqid, whose byte order is its numeric order.
//
// Exposed because a realm that keeps a secondary index keyed by the same ID
// needs the identical key, and because it is the one place the encoding is
// decided.
func (id ID) Key() string { return seqid.ID(id).Binary() }

// ParseID reads an ID from its decimal form, the shape it has in a Render
// path or a function argument.
//
// It returns false for anything that is not a plain unsigned decimal, which
// includes "", "-1", "1.0", a value past uint64, and the zero ID (never
// assigned, so accepting it would only produce a lookup that cannot hit).
// Leading zeros are accepted: "007" is the ID 7.
func ParseID(s string) (ID, bool) {
	n, err := strconv.ParseUint(s, 10, 64)
	if err != nil || n == 0 {
		return 0, false
	}
	return ID(n), true
}

// Entry is one ID/value pair, as returned by the paging methods.
type Entry struct {
	ID    ID
	Value any
}

// Store is an ordered collection of values under auto-assigned IDs.
//
// The zero Store is an empty store and is ready to use, so a realm can declare
// one as a package-level var without an initializer. [New] exists for the
// pointer form.
type Store struct {
	tree  avl.Tree
	last  seqid.ID
	label string
}

// New returns an empty store.
func New() *Store { return &Store{} }

// Named is [New] with a noun for what the store holds, used in the panic
// [Store.MustGet] raises: store.Named("game") makes it "game #7 not found"
// instead of "store: no entry #7".
//
// It exists so porting a realm to this package does not have to trade its own
// error wording for one shared implementation. The realms being replaced here
// panic "game not found", "proposal not found", "capsule not found"; the label
// keeps that and adds the id they all omitted.
func Named(label string) *Store { return &Store{label: label} }

// Add stores v under the next ID and returns it.
//
// It panics if the ID space is exhausted, which is [seqid.ID.Next]'s behaviour
// and requires 2^64 insertions to reach.
func (s *Store) Add(v any) ID {
	id := ID(s.last.Next())
	s.tree.Set(id.Key(), v)
	return id
}

// Set writes v at an existing or explicit ID, and reports whether it replaced
// a value.
//
// Use it to update an entry in place. It does not move the ID counter, so
// setting an ID above [Store.LastID] leaves a gap that [Store.Add] will later
// walk into and overwrite. Prefer [Store.Add] to create.
func (s *Store) Set(id ID, v any) (replaced bool) {
	return s.tree.Set(id.Key(), v)
}

// Get returns the value at id, and whether it was there.
//
// Unlike avl.Tree.Get, a nil value stored at a live ID is distinguishable from
// an absent one, because the second result comes from Has rather than from the
// value being nil.
func (s *Store) Get(id ID) (any, bool) {
	k := id.Key()
	if !s.tree.Has(k) {
		return nil, false
	}
	return s.tree.Get(k), true
}

// MustGet returns the value at id, or panics.
//
// This is the "get or panic" the realms wrote eighteen times, with one
// implementation instead of eighteen. The panic names the id, which none of
// them did: "store: no entry #7", or "game #7 not found" for a store built
// with [Named].
func (s *Store) MustGet(id ID) any {
	v, ok := s.Get(id)
	if !ok {
		panic(s.missing(id))
	}
	return v
}

func (s *Store) missing(id ID) string {
	if s.label == "" {
		return "store: no entry #" + id.String()
	}
	return s.label + " #" + id.String() + " not found"
}

// Has reports whether id is present.
func (s *Store) Has(id ID) bool { return s.tree.Has(id.Key()) }

// Remove deletes the entry at id and returns the value it held.
//
// The ID is not recycled: see the package doc.
func (s *Store) Remove(id ID) (any, bool) { return s.tree.Remove(id.Key()) }

// Len reports how many entries are present. Removals lower it; [Store.LastID]
// does not move.
func (s *Store) Len() int { return s.tree.Size() }

// LastID is the highest ID ever assigned, or 0 when nothing has been added.
// It is the count of insertions, not of live entries.
func (s *Store) LastID() ID { return ID(s.last) }

// Each visits every entry in ascending ID order.
//
// It takes no stop signal on purpose: this is the common case, and a callback
// whose bool means "stop" reads identically to one whose bool means
// "continue". When iteration has to end early, say so in the name and use
// [Store.EachUntil].
func (s *Store) Each(fn func(id ID, v any)) {
	s.tree.Iterate("", "", func(k string, v any) bool {
		fn(keyID(k), v)
		return false
	})
}

// EachReverse is [Store.Each] in descending ID order, which is what a
// newest-first list wants.
func (s *Store) EachReverse(fn func(id ID, v any)) {
	s.tree.ReverseIterate("", "", func(k string, v any) bool {
		fn(keyID(k), v)
		return false
	})
}

// EachUntil visits entries in ascending ID order and stops when fn returns
// true. It reports whether it stopped early.
//
// True means stop, matching avl.IterCbFn exactly, so a callback moved between
// this package and a raw tree keeps its meaning.
func (s *Store) EachUntil(fn func(id ID, v any) bool) bool {
	return s.tree.Iterate("", "", func(k string, v any) bool {
		return fn(keyID(k), v)
	})
}

// EachReverseUntil is [Store.EachUntil] in descending ID order.
func (s *Store) EachReverseUntil(fn func(id ID, v any) bool) bool {
	return s.tree.ReverseIterate("", "", func(k string, v any) bool {
		return fn(keyID(k), v)
	})
}

// Page returns page number page of size entries, in ascending ID order.
//
// Pages are 1-based, because they are shown to a reader ("page 1 of 4") and an
// off-by-one between the URL and the label is the bug this saves. A page past
// the end, or a page or size below 1, returns an empty slice rather than
// panicking: the page number usually comes from a Render path, which is user
// input.
//
// It walks only the requested window, not the whole tree.
func (s *Store) Page(page, size int) []Entry {
	return s.slice(page, size, false)
}

// PageReverse is [Store.Page] in descending ID order: page 1 holds the newest
// entries.
func (s *Store) PageReverse(page, size int) []Entry {
	return s.slice(page, size, true)
}

func (s *Store) slice(page, size int, reverse bool) []Entry {
	if page < 1 || size < 1 {
		return nil
	}
	offset := (page - 1) * size
	out := make([]Entry, 0, size)
	cb := func(k string, v any) bool {
		out = append(out, Entry{ID: keyID(k), Value: v})
		return false
	}
	if reverse {
		s.tree.ReverseIterateByOffset(offset, size, cb)
	} else {
		s.tree.IterateByOffset(offset, size, cb)
	}
	return out
}

// Pages reports how many pages of the given size the store holds, which is
// what a pager footer needs. A size below 1 gives 0.
func (s *Store) Pages(size int) int {
	if size < 1 {
		return 0
	}
	n := s.Len()
	return (n + size - 1) / size
}

// keyID decodes an avl key back to its ID. The keys in this tree are always
// written by ID.Key, so a short or malformed key means the tree was written by
// something other than this package.
func keyID(k string) ID {
	if len(k) != 8 {
		panic("store: foreign key in tree")
	}
	var n uint64
	for i := 0; i < 8; i++ {
		n = n<<8 | uint64(k[i])
	}
	return ID(n)
}

package store

import (
	"strconv"
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestZeroValueIsUsable(t *testing.T) {
	var s Store
	uassert.Equal(t, 0, s.Len())
	uassert.Equal(t, uint64(0), uint64(s.LastID()))
	uassert.Equal(t, uint64(1), uint64(s.Add("first")))
	uassert.Equal(t, 1, s.Len())
}

func TestAddAssignsSequentialIDsFromOne(t *testing.T) {
	s := New()
	for want := uint64(1); want <= 5; want++ {
		uassert.Equal(t, want, uint64(s.Add("v"+strconv.FormatUint(want, 10))))
	}
	uassert.Equal(t, 5, s.Len())
	uassert.Equal(t, uint64(5), uint64(s.LastID()))
}

func TestGetHasMustGet(t *testing.T) {
	s := New()
	id := s.Add("hello")

	got, ok := s.Get(id)
	uassert.True(t, ok, "live id is found")
	uassert.Equal(t, "hello", got.(string))
	uassert.True(t, s.Has(id), "Has agrees with Get")
	uassert.Equal(t, "hello", s.MustGet(id).(string))

	_, ok = s.Get(ID(2))
	uassert.False(t, ok, "unassigned id misses")
	_, ok = s.Get(ID(0))
	uassert.False(t, ok, "the zero id always misses")
	uassert.False(t, s.Has(ID(0)), "the zero id is never present")
}

// A nil value at a live id must still read as present. avl.Tree.Get alone
// cannot tell those apart, which is why Get consults Has.
func TestNilValueIsDistinguishableFromAbsent(t *testing.T) {
	s := New()
	id := s.Add(nil)

	v, ok := s.Get(id)
	uassert.True(t, ok, "a stored nil is present")
	uassert.Nil(t, v, "and reads back as nil")
	uassert.Equal(t, 1, s.Len())
}

func TestMustGetPanicsNamingTheEntry(cur realm, t *testing.T) {
	s := New()
	s.Add("only")
	uassert.PanicsWithMessage(t, cur, "store: no entry #7", func() { s.MustGet(ID(7)) })
	uassert.NotPanics(t, cur, func() { s.MustGet(ID(1)) })
}

// A labelled store keeps the realm's own wording, so porting one does not
// trade "game not found" for a generic message.
func TestNamedStoreUsesItsLabelInThePanic(cur realm, t *testing.T) {
	s := Named("game")
	s.Add("only")
	uassert.PanicsWithMessage(t, cur, "game #7 not found", func() { s.MustGet(ID(7)) })
	uassert.NotPanics(t, cur, func() { s.MustGet(ID(1)) })

	// The label changes nothing else.
	uassert.Equal(t, uint64(1), uint64(s.LastID()))
	uassert.Equal(t, 1, s.Len())
}

func TestSetReplacesInPlace(t *testing.T) {
	s := New()
	id := s.Add("before")

	uassert.True(t, s.Set(id, "after"), "Set reports the replacement")
	uassert.Equal(t, "after", s.MustGet(id).(string))
	uassert.Equal(t, 1, s.Len(), "replacing does not grow the store")
	uassert.Equal(t, uint64(1), uint64(s.LastID()), "replacing does not move the counter")
}

func TestRemoveDoesNotRecycleIDs(t *testing.T) {
	s := New()
	a := s.Add("a")
	s.Add("b")

	v, ok := s.Remove(a)
	uassert.True(t, ok, "removing a live id succeeds")
	uassert.Equal(t, "a", v.(string))
	uassert.Equal(t, 1, s.Len())

	_, ok = s.Remove(a)
	uassert.False(t, ok, "removing twice is a miss, not a panic")

	// The next Add continues the history rather than refilling the hole.
	uassert.Equal(t, uint64(3), uint64(s.Add("c")))
}

func TestParseID(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want ID
		ok   bool
	}{
		{"plain", "7", 7, true},
		{"leading zeros", "007", 7, true},
		{"max uint64", "18446744073709551615", ID(18446744073709551615), true},
		{"empty", "", 0, false},
		{"zero is never assigned", "0", 0, false},
		{"negative", "-1", 0, false},
		{"signed positive", "+1", 0, false},
		{"decimal point", "1.0", 0, false},
		{"not a number", "abc", 0, false},
		{"trailing space", "7 ", 0, false},
		{"overflows uint64", "18446744073709551616", 0, false},
	}
	for _, tc := range cases {
		got, ok := ParseID(tc.in)
		uassert.Equal(t, tc.ok, ok, tc.name+": ok")
		uassert.Equal(t, uint64(tc.want), uint64(got), tc.name+": value")
	}
}

