// Package tally orders a scoreboard: highest score first, ties broken by key.
//
// Sixteen realms in this repo carry their own sort.Interface triple, because
// gno has no sort.Slice and every leaderboard therefore needs a named type
// with Len, Less and Swap. Eight of them rank on ONE score and then break the
// tie, which is what this package is; the rest rank on two scores and keep
// their own comparator. They do not agree on what happens at a tie, and one of
// them does not break ties at all.
//
// # The tie-break is the point
//
// A Render that reshuffles between identical calls is a bug, so the final
// comparison must be a total order. Comparing the score again (as
// r/moul/x/daily/rpgroom's third clause does) is not one: two rows with equal
// scores compare false in both directions, and their order then falls out of
// whatever the sort algorithm did with the input, which is reproducible but
// nobody chose it. [Sort] always ends on the key, so equal scores render in a
// stable, explicable order.
//
// # What is not here
//
// Storage: the caller keeps its own avl tree and maps it to [Entry]. That is
// what makes this adoptable by realms that already have their state, and
// [Board] is for new ones that do not.
//
// Rendering: a podium and a table already have an owner in
// [p/moul/kit/ui](/p/moul/kit/ui/v0).
package tally

import (
	"sort"

	"gno.land/p/nt/avl/v0"
)

// Entry is one row of a scoreboard: an opaque key and its score.
//
// Key is whatever the caller ranks by, usually an address in its String form.
// It is the tie-break, so it must be unique within one board.
type Entry struct {
	Key   string
	Score int64
}

type byScore []Entry

func (e byScore) Len() int      { return len(e) }
func (e byScore) Swap(i, j int) { e[i], e[j] = e[j], e[i] }
func (e byScore) Less(i, j int) bool {
	if e[i].Score != e[j].Score {
		return e[i].Score > e[j].Score
	}
	return e[i].Key < e[j].Key
}

// Sort orders entries in place: highest score first, ties by key ascending.
func Sort(entries []Entry) { sort.Sort(byScore(entries)) }

// Top returns the n highest entries, sorted. A n at or below zero returns
// nothing; a n past the end returns everything. The input is not modified.
func Top(entries []Entry, n int) []Entry {
	if n <= 0 || len(entries) == 0 {
		return nil
	}
	out := make([]Entry, len(entries))
	copy(out, entries)
	Sort(out)
	if n > len(out) {
		n = len(out)
	}
	return out[:n]
}

// Rank returns the 1-based position of key once entries are sorted, or 0 if
// the key is absent. Equal scores still get distinct ranks, decided by the
// same key tie-break Sort uses, so no two rows ever claim the same place.
func Rank(entries []Entry, key string) int {
	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	Sort(sorted)
	for i, e := range sorted {
		if e.Key == key {
			return i + 1
		}
	}
	return 0
}

// Board is a scoreboard that owns its storage, for a realm that does not
// already have one. It is backed by a tree rather than a map: gno map
// iteration order is unspecified, and a Render built on one is not
// reproducible.
type Board struct {
	scores *avl.Tree // key -> int64
}

// NewBoard returns an empty Board.
func NewBoard() *Board { return &Board{scores: avl.NewTree()} }

// Add increases key's score by delta, which may be negative, and returns the
// new score. A key that was absent starts at zero.
func (b *Board) Add(key string, delta int64) int64 {
	n := b.Score(key) + delta
	b.scores.Set(key, n)
	return n
}

// Set replaces key's score outright.
func (b *Board) Set(key string, score int64) { b.scores.Set(key, score) }

// Score returns key's score, or zero if it has none. It does not distinguish
// an absent key from one scoring zero; use [Board.Has] when that matters.
func (b *Board) Score(key string) int64 {
	v := b.scores.Get(key)
	if v == nil {
		return 0
	}
	return v.(int64)
}

// Has reports whether key has been scored at all.
func (b *Board) Has(key string) bool { return b.scores.Get(key) != nil }

// Remove drops key, reporting whether it was there.
func (b *Board) Remove(key string) bool {
	_, removed := b.scores.Remove(key)
	return removed
}

// Len is the number of scored keys.
func (b *Board) Len() int { return b.scores.Size() }

// Entries returns every row, sorted by [Sort].
func (b *Board) Entries() []Entry {
	out := make([]Entry, 0, b.scores.Size())
	b.scores.Iterate("", "", func(k string, v any) bool {
		out = append(out, Entry{Key: k, Score: v.(int64)})
		return false
	})
	Sort(out)
	return out
}

// Top returns the n highest rows, sorted.
func (b *Board) Top(n int) []Entry { return Top(b.Entries(), n) }

// Rank returns key's 1-based position, or 0 if it is not on the board.
func (b *Board) Rank(key string) int {
	if !b.Has(key) {
		return 0
	}
	return Rank(b.Entries(), key)
}

package tally

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func keys(entries []Entry) string {
	out := ""
	for i, e := range entries {
		if i > 0 {
			out += ","
		}
		out += e.Key
	}
	return out
}

func TestSortOrdersByScoreThenKey(t *testing.T) {
	cases := []struct {
		name string
		in   []Entry
		want string
	}{
		{"already ordered", []Entry{{"a", 3}, {"b", 2}, {"c", 1}}, "a,b,c"},
		{"reversed", []Entry{{"c", 1}, {"b", 2}, {"a", 3}}, "a,b,c"},
		{"all tied, key decides", []Entry{{"c", 5}, {"a", 5}, {"b", 5}}, "a,b,c"},
		{"partial tie", []Entry{{"z", 1}, {"b", 9}, {"a", 9}}, "a,b,z"},
		{"negatives sort below", []Entry{{"a", -1}, {"b", 0}, {"c", 1}}, "c,b,a"},
		{"single", []Entry{{"only", 7}}, "only"},
		{"empty", nil, ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			in := make([]Entry, len(tc.in))
			copy(in, tc.in)
			Sort(in)
			uassert.Equal(t, tc.want, keys(in))
		})
	}
}

// TestSortIsATotalOrder is the defect this package exists to remove. A
// comparator whose last clause repeats the score (rpgroom's third clause) is
// not a total order: two equal rows compare false both ways and their order is
// decided by the algorithm. Sorting twice from different inputs must agree.
func TestSortIsATotalOrder(t *testing.T) {
	a := []Entry{{"x", 5}, {"y", 5}, {"z", 5}, {"w", 9}}
	b := []Entry{{"z", 5}, {"w", 9}, {"y", 5}, {"x", 5}}
	Sort(a)
	Sort(b)
	uassert.Equal(t, keys(a), keys(b))
	uassert.Equal(t, "w,x,y,z", keys(a))
}

func TestTop(t *testing.T) {
	in := []Entry{{"c", 1}, {"a", 3}, {"b", 2}}
	uassert.Equal(t, "a,b", keys(Top(in, 2)))
	uassert.Equal(t, "a,b,c", keys(Top(in, 10)))
	uassert.Equal(t, "", keys(Top(in, 0)))
	uassert.Equal(t, "", keys(Top(in, -1)))
	uassert.Equal(t, "", keys(Top(nil, 3)))
}

// TestTopDoesNotDisturbTheCaller pins that Top copies. A realm that renders a
// Top(3) and then iterates its own slice must not find it reordered.
func TestTopDoesNotDisturbTheCaller(t *testing.T) {
	in := []Entry{{"c", 1}, {"a", 3}, {"b", 2}}
	_ = Top(in, 2)
	uassert.Equal(t, "c,a,b", keys(in))
}

func TestRank(t *testing.T) {
	in := []Entry{{"c", 1}, {"a", 3}, {"b", 2}}
	uassert.Equal(t, 1, Rank(in, "a"))
	uassert.Equal(t, 2, Rank(in, "b"))
	uassert.Equal(t, 3, Rank(in, "c"))
	uassert.Equal(t, 0, Rank(in, "absent"))
}

// TestRankNeverTies is what makes a rendered "#3" mean something: two equal
// scores still get 2 and 3, never 2 and 2.
func TestRankNeverTies(t *testing.T) {
	in := []Entry{{"a", 5}, {"b", 5}, {"c", 5}}
	seen := map[int]bool{}
	for _, e := range in {
		r := Rank(in, e.Key)
		if seen[r] {
			t.Errorf("rank %d claimed twice", r)
		}
		seen[r] = true
	}
	uassert.Equal(t, 3, len(seen))
}

func TestBoardAddAndScore(t *testing.T) {
	b := NewBoard()
	uassert.Equal(t, 0, b.Len())
	uassert.Equal(t, int64(5), b.Add("a", 5))
	uassert.Equal(t, int64(8), b.Add("a", 3))
	uassert.Equal(t, int64(6), b.Add("a", -2))
	uassert.Equal(t, int64(6), b.Score("a"))
	uassert.Equal(t, int64(0), b.Score("never"))
	uassert.Equal(t, 1, b.Len())
}

func TestBoardHasDistinguishesAbsentFromZero(t *testing.T) {
	b := NewBoard()
	b.Set("zero", 0)
	uassert.True(t, b.Has("zero"))
	uassert.False(t, b.Has("absent"))
	uassert.Equal(t, int64(0), b.Score("zero"))
	uassert.Equal(t, int64(0), b.Score("absent"))
}

func TestBoardRemove(t *testing.T) {
	b := NewBoard()
	b.Set("a", 1)
	uassert.True(t, b.Remove("a"))
	uassert.False(t, b.Remove("a"))
	uassert.Equal(t, 0, b.Len())
}

func TestBoardEntriesAndTop(t *testing.T) {
	b := NewBoard()
	b.Set("c", 1)
	b.Set("a", 3)
	b.Set("b", 3)
	uassert.Equal(t, "a,b,c", keys(b.Entries()))
	uassert.Equal(t, "a,b", keys(b.Top(2)))
	uassert.Equal(t, 1, b.Rank("a"))
	uassert.Equal(t, 2, b.Rank("b"))
	uassert.Equal(t, 0, b.Rank("absent"))
}

// TestBoardOrderDoesNotDependOnInsertion is the reason Board is backed by a
// tree and not a map: the same scores inserted in a different order must
// render identically.
func TestBoardOrderDoesNotDependOnInsertion(t *testing.T) {
	one := NewBoard()
	for _, e := range []Entry{{"a", 5}, {"b", 5}, {"c", 9}} {
		one.Set(e.Key, e.Score)
	}
	two := NewBoard()
	for _, e := range []Entry{{"c", 9}, {"b", 5}, {"a", 5}} {
		two.Set(e.Key, e.Score)
	}
	uassert.Equal(t, keys(one.Entries()), keys(two.Entries()))
	uassert.Equal(t, "c,a,b", keys(one.Entries()))
}

// Package memo provides a simple memoization utility to cache function results.
//
// The package offers a Memoizer type that can cache function results based on keys,
// with optional validation of cached values. This is useful for expensive computations
// that need to be cached and potentially invalidated based on custom conditions.
//
// It is the B+ tree successor to [gno.land/p/moul/memo/v0] (which is backed by
// an AVL tree): a bump to v3 because the backing data structure — and thus the
// on-chain storage layout — changed. The exported API is identical to v2
// (New/Memoize/MemoizeWithValidator/Invalidate/Clear/Size). A B+ tree packs
// many entries per persisted node, so it costs materially less storage and gas
// per cached entry — prefer v3 when the cache is part of persisted realm state.
//
// Because the B+ tree backing mutates in place (the AVL backing was
// copy-on-write), do NOT invalidate or add entries to the same Memoizer from
// inside a callback that is iterating it, and do NOT copy a non-zero Memoizer
// by value.
//
// /!\ Important Warning for Gno Usage:
// In Gno, storage updates only persist during transactions. This means:
//   - Cache entries created during queries will NOT persist
//   - Creating cache entries during queries will actually decrease performance
//     as it wastes resources trying to save data that won't be saved
//
// Best Practices:
// - Use this pattern in transaction-driven contexts rather than query/render scenarios
// - Consider controlled cache updates, e.g., by specific accounts (like oracles)
// - Ideal for cases where cache updates happen every N blocks or on specific events
// - Carefully evaluate if caching will actually improve performance in your use case
//
// Basic usage example:
//
//	m := memo.New()
//
//	// Cache expensive computation
//	result := m.Memoize("key", func() any {
//	    // expensive operation
//	    return "computed-value"
//	})
//
//	// Subsequent calls with same key return cached result
//	result = m.Memoize("key", func() any {
//	    // function won't be called, cached value is returned
//	    return "computed-value"
//	})
//
// Example with validation:
//
//	type TimestampedValue struct {
//	    Value     string
//	    Timestamp time.Time
//	}
//
//	m := memo.New()
//
//	// Cache value with timestamp
//	result := m.MemoizeWithValidator(
//	    "key",
//	    func() any {
//	        return TimestampedValue{
//	            Value:     "data",
//	            Timestamp: time.Now(),
//	        }
//	    },
//	    func(cached any) bool {
//	        // Validate that the cached value is not older than 1 hour
//	        if tv, ok := cached.(TimestampedValue); ok {
//	            return time.Since(tv.Timestamp) < time.Hour
//	        }
//	        return false
//	    },
//	)
package memo

import (
	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/ufmt/v0"
)

// keyString derives a stable string key from an arbitrary value. Keys are
// compared by their string representation, mirroring the previous ordering
// behavior.
func keyString(key any) string {
	return ufmt.Sprintf("%v", key)
}

// Memoizer is a structure to handle memoization of function results.
type Memoizer struct {
	cache *bptree.BPTree
}

// New creates a new Memoizer instance.
func New() *Memoizer {
	return &Memoizer{
		cache: bptree.NewBPTree32(),
	}
}

// Memoize ensures the result of the given function is cached for the specified key.
func (m *Memoizer) Memoize(key any, fn func() any) any {
	k := keyString(key)
	if m.cache.Has(k) {
		return m.cache.Get(k)
	}

	value := fn()
	m.cache.Set(k, value)
	return value
}

// MemoizeWithValidator ensures the result is cached and valid according to the validator function.
func (m *Memoizer) MemoizeWithValidator(key any, fn func() any, isValid func(any) bool) any {
	k := keyString(key)
	if m.cache.Has(k) {
		cached := m.cache.Get(k)
		if isValid(cached) {
			return cached
		}
	}

	value := fn()
	m.cache.Set(k, value)
	return value
}

// Invalidate removes the cached value for the specified key.
func (m *Memoizer) Invalidate(key any) {
	m.cache.Remove(keyString(key))
}

// Clear clears all cached values.
func (m *Memoizer) Clear() {
	m.cache = bptree.NewBPTree32()
}

// Size returns the number of items currently in the cache.
func (m *Memoizer) Size() int {
	return m.cache.Size()
}

package memo

import (
	"testing"
	"time"
)

type timestampedValue struct {
	value     any
	timestamp time.Time
}

// complexKey is used to test struct keys
type complexKey struct {
	ID   int
	Name string
}

func TestMemoize(t *testing.T) {
	tests := []struct {
		name      string
		key       any
		value     any
		callCount *int
	}{
		{
			name:      "string key and value",
			key:       "test-key",
			value:     "test-value",
			callCount: new(int),
		},
		{
			name:      "int key and value",
			key:       42,
			value:     123,
			callCount: new(int),
		},
		{
			name:      "mixed types",
			key:       "number",
			value:     42,
			callCount: new(int),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			m := New()
			if m.Size() != 0 {
				t.Errorf("Initial size = %d, want 0", m.Size())
			}

			fn := func() any {
				*tt.callCount++
				return tt.value
			}

			// First call should compute
			result := m.Memoize(tt.key, fn)
			if result != tt.value {
				t.Errorf("Memoize() = %v, want %v", result, tt.value)
			}
			if *tt.callCount != 1 {
				t.Errorf("Function called %d times, want 1", *tt.callCount)
			}
			if m.Size() != 1 {
				t.Errorf("Size after first call = %d, want 1", m.Size())
			}

			// Second call should use cache
			result = m.Memoize(tt.key, fn)
			if result != tt.value {
				t.Errorf("Memoize() second call = %v, want %v", result, tt.value)
			}
			if *tt.callCount != 1 {
				t.Errorf("Function called %d times, want 1", *tt.callCount)
			}
			if m.Size() != 1 {
				t.Errorf("Size after second call = %d, want 1", m.Size())
			}
		})
	}
}

func TestMemoizeWithValidator(t *testing.T) {
	tests := []struct {
		name            string
		key             any
		value           any
		validDuration   time.Duration
		waitDuration    time.Duration
		expectedCalls   int
		shouldRecompute bool
	}{
		{
			name:            "valid cache",
			key:             "key1",
			value:           "value1",
			validDuration:   time.Hour,
			waitDuration:    time.Millisecond,
			expectedCalls:   1,
			shouldRecompute: false,
		},
		{
			name:            "expired cache",
			key:             "key2",
			value:           "value2",
			validDuration:   time.Millisecond,
			waitDuration:    time.Millisecond * 2,
			expectedCalls:   2,
			shouldRecompute: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			m := New()
			callCount := 0

			fn := func() any {
				callCount++
				return timestampedValue{
					value:     tt.value,
					timestamp: time.Now(),
				}
			}

			isValid := func(cached any) bool {
				if tv, ok := cached.(timestampedValue); ok {
					return time.Since(tv.timestamp) < tt.validDuration
				}
				return false
			}

			// First call
			result := m.MemoizeWithValidator(tt.key, fn, isValid)
			if tv, ok := result.(timestampedValue); !ok || tv.value != tt.value {
				t.Errorf("MemoizeWithValidator() = %v, want value %v", result, tt.value)
			}

			// Wait
			testing.SkipHeights(10)

			// Second call
			result = m.MemoizeWithValidator(tt.key, fn, isValid)
			if tv, ok := result.(timestampedValue); !ok || tv.value != tt.value {
				t.Errorf("MemoizeWithValidator() second call = %v, want value %v", result, tt.value)
			}

			if callCount != tt.expectedCalls {
				t.Errorf("Function called %d times, want %d", callCount, tt.expectedCalls)
			}
		})
	}
}

func TestInvalidate(t *testing.T) {
	tests := []struct {
		name      string
		key       any
		value     any
		callCount *int
	}{
		{
			name:      "invalidate existing key",
			key:       "test-key",
			value:     "test-value",
			callCount: new(int),
		},
		{
			name:      "invalidate non-existing key",
			key:       "missing-key",
			value:     "test-value",
			callCount: new(int),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			m := New()
			fn := func() any {
				*tt.callCount++
				return tt.value
			}

			// First call
			m.Memoize(tt.key, fn)
			if m.Size() != 1 {
				t.Errorf("Size after first call = %d, want 1", m.Size())
			}

			// Invalidate
			m.Invalidate(tt.key)
			if m.Size() != 0 {
				t.Errorf("Size after invalidate = %d, want 0", m.Size())
			}

			// Call again should recompute
			result := m.Memoize(tt.key, fn)
			if result != tt.value {
				t.Errorf("Memoize() after invalidate = %v, want %v", result, tt.value)
			}
			if *tt.callCount != 2 {
				t.Errorf("Function called %d times, want 2", *tt.callCount)
			}
			if m.Size() != 1 {
				t.Errorf("Size after recompute = %d, want 1", m.Size())
			}
		})
	}
}

func TestClear(t *testing.T) {
	m := New()
	callCount := 0

	fn := func() any {
		callCount++
		return "value"
	}

	// Cache some values
	m.Memoize("key1", fn)
	m.Memoize("key2", fn)

	if callCount != 2 {
		t.Errorf("Initial calls = %d, want 2", callCount)
	}
	if m.Size() != 2 {
		t.Errorf("Size after initial calls = %d, want 2", m.Size())
	}

	// Clear cache
	m.Clear()
	if m.Size() != 0 {
		t.Errorf("Size after clear = %d, want 0", m.Size())
	}

	// Recompute values
	m.Memoize("key1", fn)
	m.Memoize("key2", fn)

	if callCount != 4 {
		t.Errorf("Calls after clear = %d, want 4", callCount)
	}
	if m.Size() != 2 {
		t.Errorf("Size after recompute = %d, want 2", m.Size())
	}
}

func TestSize(t *testing.T) {
	m := New()

	if m.Size() != 0 {
		t.Errorf("Initial size = %d, want 0", m.Size())
	}

	callCount := 0
	fn := func() any {
		callCount++
		return "value"
	}

	// Add items
	m.Memoize("key1", fn)
	if m.Size() != 1 {
		t.Errorf("Size after first insert = %d, want 1", m.Size())
	}

	m.Memoize("key2", fn)
	if m.Size() != 2 {
		t.Errorf("Size after second insert = %d, want 2", m.Size())
	}

	// Duplicate key should not increase size
	m.Memoize("key1", fn)
	if m.Size() != 2 {
		t.Errorf("Size after duplicate insert = %d, want 2", m.Size())
	}

	// Remove item
	m.Invalidate("key1")
	if m.Size() != 1 {
		t.Errorf("Size after invalidate = %d, want 1", m.Size())
	}

	// Clear all
	m.Clear()
	if m.Size() != 0 {
		t.Errorf("Size after clear = %d, want 0", m.Size())
	}
}

func TestMemoizeWithDifferentKeyTypes(t *testing.T) {
	tests := []struct {
		name      string
		keys      []any    // Now an array of keys
		values    []string // Corresponding values
		callCount *int
	}{
		{
			name:      "integer keys",
			keys:      []any{42, 43},
			values:    []string{"value-for-42", "value-for-43"},
			callCount: new(int),
		},
		{
			name:      "float keys",
			keys:      []any{3.14, 2.718},
			values:    []string{"value-for-pi", "value-for-e"},
			callCount: new(int),
		},
		{
			name:      "bool keys",
			keys:      []any{true, false},
			values:    []string{"value-for-true", "value-for-false"},
			callCount: new(int),
		},
		/*
			{
				name: "struct keys",
				keys: []any{
					complexKey{ID: 1, Name: "test1"},
					complexKey{ID: 2, Name: "test2"},
				},
				values:    []string{"value-for-struct1", "value-for-struct2"},
				callCount: new(int),
			},
			{
				name:      "nil and empty interface keys",
				keys:      []any{nil, any(nil)},
				values:    []string{"value-for-nil", "value-for-empty-interface"},
				callCount: new(int),
			},
		*/
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			m := New()

			// Test both keys
			for i, key := range tt.keys {
				value := tt.values[i]
				fn := func() any {
					*tt.callCount++
					return value
				}

				// First call should compute
				result := m.Memoize(key, fn)
				if result != value {
					t.Errorf("Memoize() for key %v = %v, want %v", key, result, value)
				}
				if *tt.callCount != i+1 {
					t.Errorf("Function called %d times, want %d", *tt.callCount, i+1)
				}
			}

			// Verify size includes both entries
			if m.Size() != 2 {
				t.Errorf("Size after both inserts = %d, want 2", m.Size())
			}

			// Second call for each key should use cache
			for i, key := range tt.keys {
				initialCount := *tt.callCount
				result := m.Memoize(key, func() any {
					*tt.callCount++
					return "should-not-be-called"
				})

				if result != tt.values[i] {
					t.Errorf("Memoize() second call for key %v = %v, want %v", key, result, tt.values[i])
				}
				if *tt.callCount != initialCount {
					t.Errorf("Cache miss for key %v", key)
				}
			}

			// Test invalidate for each key
			for i, key := range tt.keys {
				m.Invalidate(key)
				if m.Size() != 1-i {
					t.Errorf("Size after invalidate %d = %d, want %d", i+1, m.Size(), 1-i)
				}
			}
		})
	}
}

func TestMultipleKeyTypes(t *testing.T) {
	m := New()
	callCount := 0

	// Insert different key types simultaneously (two of each type)
	keys := []any{
		42, 43, // ints
		"string-key1", "string-key2", // strings
		3.14, 2.718, // floats
		true, false, // bools
	}

	for i, key := range keys {
		value := i
		m.Memoize(key, func() any {
			callCount++
			return value
		})
	}

	// Verify size includes all entries
	if m.Size() != len(keys) {
		t.Errorf("Size = %d, want %d", m.Size(), len(keys))
	}

	// Verify all values are cached correctly
	for i, key := range keys {
		initialCount := callCount
		result := m.Memoize(key, func() any {
			callCount++
			return -1 // Should never be returned if cache works
		})

		if result != i {
			t.Errorf("Memoize(%v) = %v, want %v", key, result, i)
		}
		if callCount != initialCount {
			t.Errorf("Cache miss for key %v", key)
		}
	}

	// Test invalidation of pairs
	for i := 0; i < len(keys); i += 2 {
		m.Invalidate(keys[i])
		m.Invalidate(keys[i+1])
		expectedSize := len(keys) - (i + 2)
		if m.Size() != expectedSize {
			t.Errorf("Size after invalidating pair %d = %d, want %d", i/2, m.Size(), expectedSize)
		}
	}

	// Clear and verify
	m.Clear()
	if m.Size() != 0 {
		t.Errorf("Size after clear = %d, want 0", m.Size())
	}
}

// Package mygnoscan builds links into a mygnoscan block explorer.
//
// A realm knows things a reader cannot see from its Render output: which chain
// it is on, what its address is, which block it was last written at. Turning
// any of those into a link means knowing the explorer's route table, and a
// route table hand-written into thirty realms is thirty places to fix when it
// moves. This package is the one place.
//
// # The routes are measured, not guessed
//
// Every path below was read out of the explorer's own router (its single-page
// frontend, `route()`), not inferred from the UI, on 2026-09-22. Two of them
// are retired and deliberately absent: `?tab=graph` (folded into `deps`, still
// redirected) and `?tab=inert` (folded into the default tab, silently dropped).
//
// # An unknown path renders the home page
//
// The explorer's router falls through to `home` rather than to a 404, so a
// misspelled route is not visible as an error: the link works, it just goes
// somewhere else. That is why the page names here are constants and why Page
// is the only door to them.
//
// # The network is per instance, not per chain
//
// The explorer takes `?network=<id>`, and the ids are chosen by whoever runs
// the instance: moul's names mainnet `mainnet`, while the upstream default
// config names the same chain `gnoland1`. NetworkFor maps a chain-id to the
// ids DefaultBase serves. Point Scanner at another instance and you very
// likely also want WithNetwork.
//
// Omitting the parameter is not the same as asking for mainnet: the explorer
// then blends every chain it indexes, which looks plausible and is wrong. A
// Scanner whose network is empty emits no parameter, so New on a chain nobody
// indexes produces a link to the blend. Set it explicitly when it matters.
//
// # Usage
//
// The whole point is a realm footer that stays right when the chain changes:
//
//	func Render(path string) string {
//		return body + "\n\n---\n\n" + mygnoscan.Default().CurrentRealmFooter()
//	}
//
// and, for a realm that wants to hand out sharper links:
//
//	s := mygnoscan.Default()
//	s.Address(someAddr)                              // an account
//	s.Block(runtime.ChainHeight())                   // the block we are at
//	s.Realm("gno.land/r/moul/home", mygnoscan.TabSource)
//	s.RealmFunc("gno.land/r/moul/config", "Set")     // straight at one function
//
// Nothing here reads chain state except ChainDomain, ChainID and ChainHeight,
// and nothing here writes. Building a link is free.
package mygnoscan

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"net/url"
	"strconv"
	"strings"
)

// DefaultBase is moul's instance, the one the rest of this repo links to.
const DefaultBase = "https://mygnoscan.moul.p2p.team"

// The realm-page tabs, as the explorer's own tabNames list has them. An
// unknown tab name lands on the default tab rather than erroring, so these
// exist to keep a typo out of a deployed realm.
const (
	TabInfo    = "info"    // the default; passing it emits no parameter
	TabDocs    = "docs"    // exported symbols
	TabSource  = "source"  // the .gno files as deployed
	TabCalls   = "calls"   // transactions that called this realm
	TabEvents  = "events"  // events it emitted
	TabStorage = "storage" // what it pays to store
	TabDefi    = "defi"    // balances and token positions
	TabDeps    = "deps"    // imports, dependents and the graph over them
)

// The explorer's list pages. Page takes one of these.
const (
	PageRealms     = "realms"
	PagePackages   = "packages"
	PageContracts  = "contracts"
	PageApps       = "apps"
	PageTxs        = "txs"
	PageBlocks     = "blocks"
	PageAccounts   = "accounts"
	PageDefi       = "defi"
	PageCoins      = "coins"
	PageGRC20      = "grc20"
	PageValidators = "validators"
	PageGovDAO     = "govdao"
	PageProposals  = "govdao/proposals"
	PageVoters     = "govdao/voters"
	PageOptions    = "govdao/options"
	PageParams     = "params"
	PageEvents     = "events"
	PageGas        = "gas"
	PageGasRealms  = "gas/realms"
	PageGasUsers   = "gas/users"
	PageGasTxs     = "gas/txs"
	PageStorage    = "storage"
	PageAnalytics  = "analytics"
	PageDashboards = "dashboards"
	PageSanity     = "sanity"
	PageWatch      = "watch"
)

// The sub-views of the packages and accounts pages, the only two list pages
// that restore a view from the URL.
//
// Every other list page writes its state into the query string (?by=, ?page=,
// ?status=, ?window=, ?section=, ?failed=, ?storage=, ?txs=) and does NOT read
// any of it back on load: a link carrying one of those opens the page on its
// default view instead, silently. So there are no helpers for them here.
// Measured against the explorer's router on 2026-09-22.
const (
	PackagesAll      = "all"      // every package
	PackagesInert    = "inert"    // the parked queue: submitted, not yet approved
	AccountsActivity = "activity" // ranked by what they have done
	AccountsBalances = "balances" // ranked by what they hold
)

// Scanner is one explorer instance plus the network its links should open on.
// It is a value: copying one is free and there is nothing to close.
type Scanner struct {
	base    string
	network string
}

// Default returns a Scanner pointed at DefaultBase, on whichever network
// answers for the running chain.
func Default() Scanner { return New(DefaultBase) }

// New returns a Scanner pointed at base, on whichever network answers for the
// running chain. A trailing slash on base is dropped so New("…/") and New("…")
// build the same links.
func New(base string) Scanner {
	return Scanner{
		base:    strings.TrimSuffix(base, "/"),
		network: NetworkFor(runtime.ChainID()),
	}
}

// WithNetwork returns a copy of s whose links carry ?network=id. The empty
// string removes the parameter, which asks the explorer for every chain at
// once rather than for this one.
func (s Scanner) WithNetwork(id string) Scanner {
	s.network = id
	return s
}

// Base returns the instance root, without a trailing slash.
func (s Scanner) Base() string { return s.base }

// Network returns the network id these links carry, empty when they carry none.
func (s Scanner) Network() string { return s.network }

// NetworkFor maps a chain-id to the network id DefaultBase serves it under, or
// "" when that instance does not index the chain (a gnodev, a local test).
//
// Verified against DefaultBase's /api/networks on 2026-09-22: it serves
// mainnet, pearl and staging. sapphire is mapped because the chain exists and
// an instance configured for it uses that id; DefaultBase currently answers
// for it with the blend, which is the same failure mode as an unknown chain
// and is why the caller can override with WithNetwork.
func NetworkFor(chainID string) string {
	switch chainID {
	case "gnoland-1":
		return "mainnet"
	case "pearl-1":
		return "pearl"
	case "sapphire-1":
		return "sapphire"
	case "staging":
		return "staging"
	default:
		return ""
	}
}

// URL is the one place a link is assembled: an absolute link to path on this
// instance, carrying query as key/value pairs plus the network. A pair with an
// empty key or value is dropped, so an optional parameter needs no branch at
// the call site.
//
// Prefer the typed helpers below; this is the escape hatch for a route added
// to the explorer after this package was last touched.
func (s Scanner) URL(path string, query ...string) string {
	if len(query)%2 != 0 {
		panic("mygnoscan: odd number of query arguments")
	}
	if path == "" {
		path = "/"
	} else if !strings.HasPrefix(path, "/") {
		path = "/" + path
	}

	v := url.Values{}
	for i := 0; i < len(query); i += 2 {
		if query[i] == "" || query[i+1] == "" {
			continue
		}
		v.Set(query[i], query[i+1])
	}
	if s.network != "" {
		v.Set("network", s.network)
	}

	out := s.base + path
	if len(v) > 0 {
		out += "?" + v.Encode()
	}
	return out
}

// Home links the explorer's front page on this network.
func (s Scanner) Home() string { return s.URL("/") }

// Page links one of the Page* list pages. A name that is not shaped like one
// falls back to the front page rather than to the explorer's own
// unknown-path-renders-home behaviour, which would look identical and mean
// something else.
func (s Scanner) Page(name string) string {
	n := strings.Trim(name, "/")
	if !safePath(n) {
		return s.Home()
	}
	return s.URL("/" + n)
}

// Packages links the package list, on the PackagesAll or PackagesInert view.
// The empty string takes the page's own default, which is PackagesAll.
func (s Scanner) Packages(view string) string {
	return s.URL("/"+PagePackages, "pv", view)
}

// Accounts links the account list, on the AccountsActivity or AccountsBalances
// view. The empty string takes the page's own default, which is
// AccountsActivity.
func (s Scanner) Accounts(view string) string {
	return s.URL("/"+PageAccounts, "av", view)
}

// Realm links a package or realm page, optionally opening one tab.
//
// pkgPath is accepted either fully qualified ("gno.land/r/moul/home") or bare
// ("r/moul/home"): TrimDomain normalises it. Passing TabInfo, or no tab at
// all, emits no tab parameter.
func (s Scanner) Realm(pkgPath string, tab ...string) string {
	p := TrimDomain(pkgPath)
	if p == "" {
		return s.Home()
	}
	return s.URL("/realm/"+p, "tab", oneTab(tab))
}

// CurrentRealm links the page of the realm that called into this package.
//
// It stack-walks (unsafe.CurrentRealm), so it names whichever realm was
// current when it ran. For a plain read like this one that is the BORROWER,
// which is the wanted answer: a realm asking for "my page" gets its own, and
// so does one asking through a shared config realm, because a borrowed call
// opens no realm frame. Measured in the test harness on 2026-09-22.
//
// Inside a CROSSING function it names that function's realm instead. That is
// also correct and rarely what a link wants, so pass the path explicitly
// there. Never branch on it for authorisation either way.
func (s Scanner) CurrentRealm(tab ...string) string {
	return s.Realm(unsafe.CurrentRealm().PkgPath(), tab...)
}

// RealmFunc links a realm's source tab scrolled to one exported function.
func (s Scanner) RealmFunc(pkgPath, fn string) string {
	p := TrimDomain(pkgPath)
	if p == "" || fn == "" {
		return s.Realm(pkgPath)
	}
	return s.URL("/realm/"+p, "tab", TabSource, "fn", fn)
}

// RealmFile links a realm's source tab scrolled to one line of one file.
// A line of 0 or less links the file without an anchor.
func (s Scanner) RealmFile(pkgPath, file string, line int) string {
	p := TrimDomain(pkgPath)
	if p == "" || file == "" {
		return s.Realm(pkgPath)
	}
	if line <= 0 {
		return s.URL("/realm/"+p, "tab", TabSource, "file", file)
	}
	return s.URL("/realm/"+p, "tab", TabSource, "file", file, "line", strconv.Itoa(line))
}

// Address links an account page: its balance, its transactions, what it deployed.
//
// The address is escaped rather than trusted. `address` is a string type and
// nothing stops a realm casting a caller's input into one, so a value reaching
// here is not necessarily bech32.
func (s Scanner) Address(addr address) string {
	if addr == "" {
		return s.Page(PageAccounts)
	}
	return s.URL("/address/" + escapeSegment(addr.String()))
}

// Tx links one transaction. The hash is the base64 form the indexer and gnokey
// print, which carries "+", "/" and "="; the whole segment is percent-escaped
// so the explorer's decodeURIComponent gives it back byte for byte.
func (s Scanner) Tx(hash string) string {
	if hash == "" {
		return s.Page(PageTxs)
	}
	return s.URL("/tx/" + escapeSegment(hash))
}

// Block links one block by height.
func (s Scanner) Block(height int64) string {
	if height <= 0 {
		return s.Page(PageBlocks)
	}
	return s.URL("/block/" + strconv.FormatInt(height, 10))
}

// CurrentBlock links the block this call is executing in.
func (s Scanner) CurrentBlock() string { return s.Block(runtime.ChainHeight()) }

// Validator links one validator by address.
func (s Scanner) Validator(addr address) string {
	if addr == "" {
		return s.Page(PageValidators)
	}
	return s.URL("/validator/" + escapeSegment(addr.String()))
}

// Proposal links one GovDAO proposal by id.
func (s Scanner) Proposal(id int) string {
	if id < 0 {
		return s.Page(PageProposals)
	}
	return s.URL("/govdao/" + strconv.Itoa(id))
}

// Token links one GRC20 asset by its ledger key, which looks like
// "gno.land/r/gnoswap/gns.GNS.0000000". That key carries both slashes and
// dots, and neither is a route separator, so it is percent-escaped whole.
func (s Scanner) Token(key string) string {
	if key == "" {
		return s.Page(PageGRC20)
	}
	return s.URL("/grc20/" + escapeSegment(key))
}

// TrimDomain strips the chain domain from a package path, so both
// "gno.land/r/moul/home" and "r/moul/home" become "r/moul/home". A path that
// is not shaped like a package path (see safePath) comes back empty, and every
// caller here treats empty as "no such target" and falls back to a list page.
//
// It tries the running chain's domain first, then the literal "gno.land/",
// because the explorer's own realm route reassembles the path by prepending
// "gno.land/" unconditionally: on a chain whose domain is something else, a
// bare path is still what the link must carry.
func TrimDomain(pkgPath string) string {
	p := strings.TrimPrefix(pkgPath, runtime.ChainDomain()+"/")
	p = strings.TrimPrefix(p, "gno.land/")
	p = strings.Trim(p, "/")
	if !safePath(p) {
		return ""
	}
	return p
}

// escapeSegment percent-encodes everything outside the RFC 3986 unreserved
// set, which is exactly what JavaScript's encodeURIComponent does and
// therefore exactly what the explorer's decodeURIComponent round-trips.
//
// url.PathEscape is the obvious choice and is wrong here twice: it leaves '/'
// alone in some modes and, more importantly, it never escapes '(' or ')',
// which are legal URL sub-delims and which close a markdown link early. Since
// every link this package builds may end up inside one, the segment escaper
// has to be stricter than the URL spec requires.
func escapeSegment(s string) string {
	const hex = "0123456789ABCDEF"
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9',
			c == '-', c == '_', c == '.', c == '~':
			b.WriteByte(c)
		default:
			b.WriteByte('%')
			b.WriteByte(hex[c>>4])
			b.WriteByte(hex[c&0x0f])
		}
	}
	return b.String()
}

// safePath reports whether p is shaped like a package path: [A-Za-z0-9._/-],
// and no empty segment.
//
// This is a rendering guard, not a validity check. Everything built here ends
// up inside a markdown link, so a path carrying ')' would close the link early
// and the rest would render as page text; a path carrying a space or a newline
// breaks it differently. Percent-escaping cannot be the answer because '(' and
// ')' are legal sub-delims in a URL path and url.PathEscape leaves them alone,
// and escaping the separators would break the route. So the characters are
// refused instead.
//
// It matters because a realm may well pass a path a caller typed (a registry,
// a directory, a "link to my realm" form), and this package cannot tell.
func safePath(p string) bool {
	if p == "" {
		return false
	}
	lastSlash := true // a leading slash was already trimmed, so no empty first segment
	for i := 0; i < len(p); i++ {
		c := p[i]
		switch {
		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
			lastSlash = false
		case c == '.', c == '-', c == '_':
			lastSlash = false
		case c == '/':
			if lastSlash {
				return false // "" or "a//b"
			}
			lastSlash = true
		default:
			return false
		}
	}
	return !lastSlash // no trailing slash left over
}

// Link renders a markdown link. Neither argument is escaped: everything this
// package builds is a path or a constant, never text a caller typed. Passing a
// user-supplied label through here would let it break out of the link.
func Link(text, target string) string { return "[" + text + "](" + target + ")" }

// RealmFooter is the line a realm appends under its Render output: the four
// views of itself worth one click, separated by middots.
//
// Deliberately plain markdown with no leading rule, so the caller decides
// where it sits and what separates it from the body.
func (s Scanner) RealmFooter(pkgPath string) string {
	p := TrimDomain(pkgPath)
	if p == "" {
		return ""
	}
	return Link("explorer", s.Realm(p)) +
		" · " + Link("source", s.Realm(p, TabSource)) +
		" · " + Link("calls", s.Realm(p, TabCalls)) +
		" · " + Link("deps", s.Realm(p, TabDeps))
}

// CurrentRealmFooter is RealmFooter for the realm that called in. It carries
// the same stack-walking caveat as CurrentRealm.
func (s Scanner) CurrentRealmFooter() string {
	return s.RealmFooter(unsafe.CurrentRealm().PkgPath())
}

// oneTab reads the optional tab argument. More than one is a call-site bug and
// panics rather than silently using the first, and TabInfo is dropped because
// it is the default the explorer lands on anyway.
func oneTab(tab []string) string {
	switch len(tab) {
	case 0:
		return ""
	case 1:
		if tab[0] == TabInfo {
			return ""
		}
		return tab[0]
	default:
		panic("mygnoscan: at most one tab")
	}
}

package mygnoscan

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// mainnet is what a Scanner looks like on the chain that matters. Tests build
// it explicitly rather than calling Default(), because the test harness runs
// with chain-id "dev", which NetworkFor maps to no network at all: pinning
// Default()'s output would pin the absence of the parameter and prove nothing
// about the case every real link is in.
func mainnet() Scanner { return New(DefaultBase).WithNetwork("mainnet") }

func TestNetworkFor(t *testing.T) {
	tests := []struct {
		chainID string
		want    string
	}{
		{"gnoland-1", "mainnet"},
		{"pearl-1", "pearl"},
		{"sapphire-1", "sapphire"},
		{"staging", "staging"},
		{"dev", ""},          // gnodev, and what `gno test` reports
		{"", ""},             // no chain at all
		{"gnoland1", ""},     // the upstream default instance's id, not a chain-id
		{"test3", ""},        // a retired testnet
		{"mainnet", ""},      // the network id, fed back in by mistake
	}
	for _, tt := range tests {
		uassert.Equal(t, tt.want, NetworkFor(tt.chainID), "NetworkFor("+tt.chainID+")")
	}
}

func TestTrimDomain(t *testing.T) {
	tests := []struct {
		in   string
		want string
	}{
		{"gno.land/r/moul/home", "r/moul/home"},
		{"r/moul/home", "r/moul/home"},
		{"/r/moul/home", "r/moul/home"},
		{"gno.land/p/moul/mygnoscan/v0", "p/moul/mygnoscan/v0"},
		{"gno.land/r/gnoland/blog", "r/gnoland/blog"},
		{"", ""},
		{"gno.land/", ""},
		// A path whose own name starts with the domain is only trimmed once,
		// so a realm cannot be linked out of its own namespace by its name.
		{"gno.land/r/moul/gno.land", "r/moul/gno.land"},
		// Anything not shaped like a package path comes back empty, so the
		// caller falls back to a list page instead of emitting it.
		{"r/moul/home)", ""},
		{"r/moul/ho me", ""},
		{"r/moul//home", ""},
		{"r/moul/home\n", ""},
	}
	for _, tt := range tests {
		uassert.Equal(t, tt.want, TrimDomain(tt.in), "TrimDomain("+tt.in+")")
	}
}

func TestBaseNormalisation(t *testing.T) {
	uassert.Equal(t, DefaultBase, New(DefaultBase+"/").Base())
	uassert.Equal(t, DefaultBase, New(DefaultBase).Base())
	uassert.Equal(t, "https://scan.example.com", New("https://scan.example.com/").Base())
}

func TestTargets(t *testing.T) {
	s := mainnet()
	const b = DefaultBase
	tests := []struct {
		name string
		got  string
		want string
	}{
		{"home", s.Home(), b + "/?network=mainnet"},
		{"page", s.Page(PageTxs), b + "/txs?network=mainnet"},
		{"page nested", s.Page(PageGasRealms), b + "/gas/realms?network=mainnet"},
		{"page slashed", s.Page("/blocks/"), b + "/blocks?network=mainnet"},
		{"realm qualified", s.Realm("gno.land/r/moul/home"), b + "/realm/r/moul/home?network=mainnet"},
		{"realm bare", s.Realm("r/moul/home"), b + "/realm/r/moul/home?network=mainnet"},
		{"realm tab", s.Realm("r/moul/home", TabSource), b + "/realm/r/moul/home?network=mainnet&tab=source"},
		// TabInfo is the tab the explorer lands on, so asking for it adds nothing.
		{"realm tab info", s.Realm("r/moul/home", TabInfo), b + "/realm/r/moul/home?network=mainnet"},
		{"realm empty", s.Realm(""), b + "/?network=mainnet"},
		{"realm func", s.RealmFunc("r/moul/config", "Set"), b + "/realm/r/moul/config?fn=Set&network=mainnet&tab=source"},
		{"realm file", s.RealmFile("r/moul/home", "render.gno", 42), b + "/realm/r/moul/home?file=render.gno&line=42&network=mainnet&tab=source"},
		{"realm file no line", s.RealmFile("r/moul/home", "render.gno", 0), b + "/realm/r/moul/home?file=render.gno&network=mainnet&tab=source"},
		{"address", s.Address("g1manfred47kzduec920z88wfr64ylksmdcedlf5"), b + "/address/g1manfred47kzduec920z88wfr64ylksmdcedlf5?network=mainnet"},
		{"address empty", s.Address(""), b + "/accounts?network=mainnet"},
		{"block", s.Block(80618), b + "/block/80618?network=mainnet"},
		{"block zero", s.Block(0), b + "/blocks?network=mainnet"},
		{"validator", s.Validator("g1manfred47kzduec920z88wfr64ylksmdcedlf5"), b + "/validator/g1manfred47kzduec920z88wfr64ylksmdcedlf5?network=mainnet"},
		{"proposal", s.Proposal(7), b + "/govdao/7?network=mainnet"},
		{"proposal negative", s.Proposal(-1), b + "/govdao/proposals?network=mainnet"},
		{"token empty", s.Token(""), b + "/grc20?network=mainnet"},
	}
	for _, tt := range tests {
		uassert.Equal(t, tt.want, tt.got, tt.name)
	}
}

// TestEscaping covers the two routes whose argument is not URL-safe. Both are
// read back with decodeURIComponent by the explorer, so percent-escaping the
// whole segment is what round-trips; leaving the slashes alone would split the
// segment and land on a different route entirely.
func TestEscaping(t *testing.T) {
	s := mainnet()

	// A 32-byte hash in the base64 form the indexer and gnokey print, picked
	// to carry all three of the characters that make base64 awkward in a URL.
	// Everything outside the unreserved set moves, which is what the
	// explorer's decodeURIComponent undoes byte for byte.
	uassert.Equal(t,
		DefaultBase+"/tx/BppSxd7qRiAPsMHzDx5mys%2BYpeDCMUzxI1qeb%2FEhaYc%3D?network=mainnet",
		s.Tx("BppSxd7qRiAPsMHzDx5mys+YpeDCMUzxI1qeb/EhaYc="))
	uassert.Equal(t, DefaultBase+"/txs?network=mainnet", s.Tx(""))

	// A GRC20 ledger key carries both slashes and dots.
	uassert.Equal(t,
		DefaultBase+"/grc20/gno.land%2Fr%2Fgnoswap%2Fgns.GNS.0000000?network=mainnet",
		s.Token("gno.land/r/gnoswap/gns.GNS.0000000"))
}

func TestURLQuery(cur realm, t *testing.T) {
	s := mainnet()

	uassert.Equal(t, DefaultBase+"/anything?network=mainnet", s.URL("anything"))
	uassert.Equal(t, DefaultBase+"/anything?network=mainnet", s.URL("/anything"))
	uassert.Equal(t, DefaultBase+"/a?k=v&network=mainnet", s.URL("/a", "k", "v"))

	// An empty key or value is dropped, so an optional parameter needs no
	// branch at the call site.
	uassert.Equal(t, DefaultBase+"/a?network=mainnet", s.URL("/a", "k", ""))
	uassert.Equal(t, DefaultBase+"/a?network=mainnet", s.URL("/a", "", "v"))

	uassert.PanicsWithMessage(t, cur, "mygnoscan: odd number of query arguments", func() {
		s.URL("/a", "k")
	})
}

// TestNoNetwork pins what a Scanner emits when it does not know the chain:
// nothing. The explorer then answers for every chain it indexes at once, which
// is a real answer to a different question, so this is worth being explicit
// about rather than discovering from a plausible-looking page.
func TestNoNetwork(t *testing.T) {
	s := New(DefaultBase).WithNetwork("")
	uassert.Equal(t, "", s.Network())
	uassert.Equal(t, DefaultBase+"/realm/r/moul/home", s.Realm("r/moul/home"))
	uassert.Equal(t, DefaultBase+"/realm/r/moul/home?tab=calls", s.Realm("r/moul/home", TabCalls))
