	cd := runtime.ChainDomain()
	tests := []struct {
		fn        string
		args      []string
		want      string
		realm_XXX Realm
	}{
		{"foo", []string{"bar", "1", "baz", "2"}, "/p/moul/helplink/v0$help&func=foo&bar=1&baz=2", ""},
		{"testFunc", []string{"key", "value"}, "/p/moul/helplink/v0$help&func=testFunc&key=value", ""},
		{"noArgsFunc", []string{}, "/p/moul/helplink/v0$help&func=noArgsFunc", ""},
