// The RFC 4648 §10 test vectors — every partial-group length.
func TestRFC4648Vectors(t *testing.T) {
	cases := []struct{ in, want string }{
		{"", ""},
		{"f", "MY======"},
		{"fo", "MZXQ===="},
		{"foo", "MZXW6==="},
		{"foob", "MZXW6YQ="},
		{"fooba", "MZXW6YTB"},
		{"foobar", "MZXW6YTBOI======"},
	}
	for _, c := range cases {
		got, err := Encode(c.in)
		uassert.NoError(t, err)
		uassert.Equal(t, c.want, got)
	}
}

func TestRFC4648RoundTrip(t *testing.T) {
	for _, s := range []string{"", "f", "fo", "foo", "foob", "fooba", "foobar", "hello world"} {
		enc, err := Encode(s)
		uassert.NoError(t, err)
		dec, err2 := Decode(enc)
		uassert.NoError(t, err2)
		uassert.Equal(t, s, dec)
	}
}

func TestUnpadded(t *testing.T) {
	got, _ := EncodeUnpadded("foobar")
	uassert.Equal(t, "MZXW6YTBOI", got)
	dec, err := Decode(got) // decoding tolerates the missing padding
	uassert.NoError(t, err)
	uassert.Equal(t, "foobar", dec)
}

func TestDecodeToleratesLowercase(t *testing.T) {
	dec, err := Decode("mzxw6ytboi")
	uassert.NoError(t, err)
	uassert.Equal(t, "foobar", dec)
}

func TestCrockfordRoundTrip(t *testing.T) {
	for _, s := range []string{"", "f", "foo", "foobar", "hello"} {
		enc, err := EncodeCrockford(s)
		uassert.NoError(t, err)
		dec, err2 := DecodeCrockford(enc)
		uassert.NoError(t, err2)
		uassert.Equal(t, s, dec)
	}
}

// The point of Crockford: a mis-typed identifier still decodes.
func TestCrockfordIsForgiving(t *testing.T) {
	enc, _ := EncodeCrockford("hello")
	want, _ := DecodeCrockford(enc)

	// lowercase
	got, err := DecodeCrockford(strings.ToLower(enc))
	uassert.NoError(t, err)
	uassert.Equal(t, want, got)

	// hyphens are ignored, wherever they land
	got2, err2 := DecodeCrockford(enc[:2] + "-" + enc[2:])
	uassert.NoError(t, err2)
	uassert.Equal(t, want, got2)

	// O reads as 0, I and L read as 1
	a, _ := DecodeCrockford("0")
	b, _ := DecodeCrockford("O")
	uassert.Equal(t, a, b)
	c, _ := DecodeCrockford("1")
	d, _ := DecodeCrockford("I")
	e, _ := DecodeCrockford("L")
	uassert.Equal(t, c, d)
	uassert.Equal(t, c, e)
}

// U is excluded from the Crockford alphabet on purpose.
func TestCrockfordExcludesU(t *testing.T) {
	uassert.Equal(t, -1, strings.IndexByte(CrockfordAlphabet, 'U'))
	_, err := DecodeCrockford("U")
	uassert.ErrorIs(t, err, ErrCorrupt)
}

func TestDecodeRejectsGarbage(t *testing.T) {
	for _, s := range []string{"!!!", "MZXW6YTB@", "0189"} { // 0/1/8/9 are not RFC 4648
		_, err := Decode(s)
		uassert.Error(t, err)
	}
}

// Leftover bits must be zero padding, never smuggled data.
func TestDecodeRejectsNonZeroLeftoverBits(t *testing.T) {
	// "MB" would leave non-zero bits after emitting one byte
	_, err := Decode("MB")
	uassert.ErrorIs(t, err, ErrCorrupt)
}

func TestTooLong(t *testing.T) {
	_, err := Encode(strings.Repeat("a", MaxLen+1))
	uassert.ErrorIs(t, err, ErrTooLong)
}

// Padded output is always a multiple of 8 characters.
func TestPaddingLength(t *testing.T) {
	for _, s := range []string{"f", "fo", "foo", "foob", "fooba", "foobar"} {
		enc, _ := Encode(s)
		uassert.Equal(t, 0, len(enc)%8)
	}
}

// Package bech32 implements the Bech32 and Bech32m string formats of BIP-173
// and BIP-350 as a pure, reusable package.
//
// A Bech32 string is a human-readable part ("g", "bc", "cosmos"), the separator
// '1', and a data part written in a 32-character alphabet that ends in a 6-character
// BCH checksum. The checksum is the point: it detects every error of up to four
// characters, and locates a single wrong character well enough for a wallet to say
// which one it is. That is why a gno.land address, a Bitcoin segwit address and a
// Cosmos account address all look the way they do.
//
// Two variants, differing only in the constant the checksum is xored with:
//
//   - [Bech32] (constant 1), BIP-173. What gno.land addresses use.
//   - [Bech32m] (constant 0x2bc830a3), BIP-350. Adopted after a length-extension
//     weakness was found in the original: a Bech32 string ending in 'p' keeps its
//     checksum valid when 'q' characters are inserted before that final 'p'.
//
// [Decode] accepts either and reports which one it read, so a caller that cares
// (segwit v1 and later must be Bech32m) can check rather than assume.
//
// The data part is a sequence of 5-bit groups. [ConvertBits] regroups an ordinary
// 8-bit payload into those groups and back, and [EncodeBytes] / [DecodeBytes] are
// the two wrapped together for the common case:
//
//	hrp, payload, _, err := bech32.DecodeBytes("g1manfred47kzduec920z88wfr64ylksmdcedlf5")
//	// hrp == "g", payload is the 20-byte address
//
// A live demo of this package is at
// [r/moul/x/daily/bech32demo](/r/moul/x/daily/bech32demo/v0).
package bech32

import "errors"

// Variant distinguishes the two checksum constants.
type Variant int

// The two variants.
const (
	// Bech32 is BIP-173, checksum constant 1.
	Bech32 Variant = iota
	// Bech32m is BIP-350, checksum constant 0x2bc830a3.
	Bech32m
)

// String names the variant, "bech32" or "bech32m".
func (v Variant) String() string {
	switch v {
	case Bech32:
		return "bech32"
	case Bech32m:
		return "bech32m"
	}
	return "invalid"
}

func (v Variant) constant() uint32 {
	if v == Bech32m {
		return 0x2bc830a3
	}
	return 1
}

var (
	// ErrTooLong is returned when a string exceeds MaxLen.
	ErrTooLong = errors.New("bech32: string too long")
	// ErrTooShort is returned when a string is shorter than the minimum.
	ErrTooShort = errors.New("bech32: string too short")
	// ErrMixedCase is returned when a string mixes upper and lower case.
	ErrMixedCase = errors.New("bech32: mixed case")
	// ErrNoSeparator is returned when the '1' separator is missing.
	ErrNoSeparator = errors.New("bech32: no separator")
	// ErrInvalidHRP is returned for an out-of-range human-readable part.
	ErrInvalidHRP = errors.New("bech32: invalid human-readable part")
	// ErrInvalidChar is returned when the data part holds a non-charset byte.
	ErrInvalidChar = errors.New("bech32: invalid data character")
	// ErrInvalidData is returned when a group does not fit its bit width.
	ErrInvalidData = errors.New("bech32: invalid data value")
	// ErrChecksum is returned when the trailing checksum does not verify.
	ErrChecksum = errors.New("bech32: bad checksum")
	// ErrInvalidBits is returned for an unsupported ConvertBits width.
	ErrInvalidBits = errors.New("bech32: invalid bit width")
	// ErrInvalidPadding is returned when unpadded conversion leaves bits over.
	ErrInvalidPadding = errors.New("bech32: invalid padding")
	// ErrInvalidVariant is returned for a Variant that is neither constant.
	ErrInvalidVariant = errors.New("bech32: invalid variant")
)


// MaxLen is BIP-173's cap on the whole encoded string, separator and checksum
// included. It exists so that a wrong character can always be located, and it is
// what keeps a decode bounded in gas.
const MaxLen = 90

// ChecksumLen is the number of data characters the checksum occupies.
const ChecksumLen = 6

// Charset is the 32-character data alphabet. It omits '1', 'b', 'i' and 'o',
// the four that are easiest to misread.
const Charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

// Encode builds a Bech32 string from a human-readable part and 5-bit groups.
func Encode(hrp string, data []byte) (string, error) {
	return EncodeVariant(hrp, data, Bech32)
}

// EncodeVariant is [Encode] with an explicit checksum variant.
//
// hrp is lowercased; every data byte must be below 32. The result is always
// lowercase, which is the form BIP-173 requires anything machine-generated to use.
func EncodeVariant(hrp string, data []byte, v Variant) (string, error) {
	if v != Bech32 && v != Bech32m {
		return "", ErrInvalidVariant
	}
	hrp = toLower(hrp)
	if err := checkHRP(hrp); err != nil {
		return "", err
	}
	for _, d := range data {
		if d >= 32 {
			return "", ErrInvalidData
		}
	}
	if len(hrp)+1+len(data)+ChecksumLen > MaxLen {
		return "", ErrTooLong
	}

	out := make([]byte, 0, len(hrp)+1+len(data)+ChecksumLen)
	out = append(out, hrp...)
	out = append(out, '1')
	for _, d := range data {
		out = append(out, Charset[d])
	}
	for _, d := range checksum(hrp, data, v) {
		out = append(out, Charset[d])
	}
	return string(out), nil
}

// Decode parses a Bech32 or Bech32m string into its human-readable part, its
// 5-bit data groups (checksum removed) and the variant whose checksum verified.
//
// The input may be all upper or all lower case, never a mix; the returned
// human-readable part is lowercase.
func Decode(s string) (string, []byte, Variant, error) {
	if len(s) > MaxLen {
		return "", nil, Bech32, ErrTooLong
	}
	hasUpper, hasLower := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < 33 || c > 126 {
			return "", nil, Bech32, ErrInvalidChar
		}
		if c >= 'A' && c <= 'Z' {
			hasUpper = true
		}
		if c >= 'a' && c <= 'z' {
			hasLower = true
		}
	}
	if hasUpper && hasLower {
		return "", nil, Bech32, ErrMixedCase
	}
	s = toLower(s)

	sep := lastIndexByte(s, '1')
	if sep < 0 {
		return "", nil, Bech32, ErrNoSeparator
	}
	hrp := s[:sep]
	if err := checkHRP(hrp); err != nil {
		return "", nil, Bech32, err
	}
	part := s[sep+1:]
	if len(part) < ChecksumLen {
		return "", nil, Bech32, ErrTooShort
	}

	data := make([]byte, 0, len(part))
	for i := 0; i < len(part); i++ {
		idx := indexByte(Charset, part[i])
		if idx < 0 {
			return "", nil, Bech32, ErrInvalidChar
		}
		data = append(data, byte(idx))
	}

	v := Bech32
	got := polymod(append(hrpExpand(hrp), data...))
	if got != v.constant() {
		v = Bech32m
		if got != v.constant() {
			return "", nil, Bech32, ErrChecksum
		}
	}
	return hrp, data[:len(data)-ChecksumLen], v, nil
}

// ConvertBits regroups data from one bit width to another, most significant bit
// first. Going 8 to 5 needs pad set, since the last group is rarely full; coming
// back 5 to 8 must not pad, so that leftover bits are reported rather than turned
// into a trailing zero byte.
func ConvertBits(data []byte, from, to uint8, pad bool) ([]byte, error) {
	if from < 1 || from > 8 || to < 1 || to > 8 {
		return nil, ErrInvalidBits
	}
	maxv := uint32(1)<<to - 1
	acc := uint32(0)
	bits := uint8(0)
	out := make([]byte, 0, len(data)*int(from)/int(to)+1)
	for _, b := range data {
		if from < 8 && uint32(b) >= uint32(1)<<from {
			return nil, ErrInvalidData
		}
		acc = acc<<from | uint32(b)
		bits += from
		for bits >= to {
			bits -= to
			out = append(out, byte(acc>>bits&maxv))
		}
	}
	if pad {
		if bits > 0 {
			out = append(out, byte(acc<<(to-bits)&maxv))
		}
		return out, nil
	}
	if bits >= from || acc<<(to-bits)&maxv != 0 {
		return nil, ErrInvalidPadding
	}
	return out, nil
}

// EncodeBytes encodes an 8-bit payload as Bech32, converting to 5-bit groups
// first. This is the call an address wants.
func EncodeBytes(hrp string, payload []byte) (string, error) {
	if err := checkHRP(toLower(hrp)); err != nil {
		return "", err
	}
	// Refuse before regrouping, not after: ConvertBits would otherwise scan and
	// materialise a payload of any size only for Encode to reject the result.
	if len(payload) > MaxPayloadLen(hrp) {
		return "", ErrTooLong
	}
	data, err := ConvertBits(payload, 8, 5, true)
	if err != nil {
		return "", err
	}
	return Encode(hrp, data)
}

// DecodeBytes decodes a string and converts its data part back to 8-bit bytes.
func DecodeBytes(s string) (string, []byte, Variant, error) {
	hrp, data, v, err := Decode(s)
	if err != nil {
		return "", nil, Bech32, err
	}
	payload, err := ConvertBits(data, 5, 8, false)
	if err != nil {
		return "", nil, Bech32, err
	}
	return hrp, payload, v, nil
}

// MaxPayloadLen is the largest 8-bit payload [EncodeBytes] can fit under hrp
// without passing MaxLen. It is 51 bytes for a gno.land address, whose
// human-readable part is one character, and 0 when hrp leaves no room at all.
func MaxPayloadLen(hrp string) int {
	groups := MaxLen - len(hrp) - 1 - ChecksumLen
	if groups <= 0 {
		return 0
	}
	// A payload of b bytes needs ceil(8b/5) groups, so b groups fit exactly
	// while 8b <= 5*groups.
	return groups * 5 / 8
}

// checksum returns the six 5-bit groups that terminate the data part.
func checksum(hrp string, data []byte, v Variant) []byte {
	values := append(hrpExpand(hrp), data...)
	values = append(values, 0, 0, 0, 0, 0, 0)
	mod := polymod(values) ^ v.constant()
	out := make([]byte, ChecksumLen)
	for i := 0; i < ChecksumLen; i++ {
		out[i] = byte(mod>>uint(5*(5-i))) & 31
	}
	return out
}

// polymod is the BCH code of BIP-173 over GF(32).
func polymod(values []byte) uint32 {
	gen := [5]uint32{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	chk := uint32(1)
	for _, v := range values {
		top := chk >> 25
		chk = (chk&0x1ffffff)<<5 ^ uint32(v)
		for i := 0; i < 5; i++ {
			if (top>>uint(i))&1 == 1 {
				chk ^= gen[i]
			}
		}
	}
	return chk
}

// hrpExpand spreads the human-readable part into the 5-bit groups the checksum
// is computed over: every high 3 bits, a zero, then every low 5 bits.
func hrpExpand(hrp string) []byte {
	out := make([]byte, 0, len(hrp)*2+1)
	for i := 0; i < len(hrp); i++ {
		out = append(out, hrp[i]>>5)
	}
	out = append(out, 0)
	for i := 0; i < len(hrp); i++ {
		out = append(out, hrp[i]&31)
	}
	return out
}

// checkHRP rejects an empty human-readable part and any byte outside printable
// US-ASCII, which is what BIP-173 allows there.
func checkHRP(hrp string) error {
	if len(hrp) == 0 {
		return ErrInvalidHRP
	}
	for i := 0; i < len(hrp); i++ {
		if hrp[i] < 33 || hrp[i] > 126 {
			return ErrInvalidHRP
		}
	}
	return nil
}

func toLower(s string) string {
	out := []byte(s)
	for i := 0; i < len(out); i++ {
		if out[i] >= 'A' && out[i] <= 'Z' {
			out[i] += 32
		}
	}
	return string(out)
}

func indexByte(s string, c byte) int {
	for i := 0; i < len(s); i++ {
		if s[i] == c {
			return i
		}
	}
	return -1
}

func lastIndexByte(s string, c byte) int {
	for i := len(s) - 1; i >= 0; i-- {
		if s[i] == c {
			return i
		}
	}
	return -1
}

package bech32

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// BIP-173 §Test vectors: strings that must decode with the Bech32 constant.
func TestValidBech32(t *testing.T) {
	cases := []struct{ s, hrp string }{
		{"A12UEL5L", "a"},
		{"a12uel5l", "a"},
		{"?1ezyfcl", "?"},
		{"abcdef1qpzry9x8gf2tvdw0s3jn54khce6mua7lmqqqxw", "abcdef"},
		{"split1checkupstagehandshakeupstreamerranterredcaperred2y9e3w", "split"},
	}
	for _, c := range cases {
		hrp, data, v, err := Decode(c.s)
		uassert.NoError(t, err, c.s)
		uassert.Equal(t, c.hrp, hrp)
		uassert.Equal(t, "bech32", v.String())
		// Re-encoding the decoded parts must reproduce the lowercase input.
		back, err2 := Encode(hrp, data)
		uassert.NoError(t, err2)
		uassert.Equal(t, lower(c.s), back)
	}
}

// BIP-350 §Test vectors: the same shapes under the Bech32m constant.
func TestValidBech32m(t *testing.T) {
	for _, c := range []struct{ s, hrp string }{
		{"A1LQFN3A", "a"},
		{"a1lqfn3a", "a"},
		{"?1v759aa", "?"},
		{"split1checkupstagehandshakeupstreamerranterredcaperredlc445v", "split"},
	} {
		hrp, data, v, err := Decode(c.s)
		uassert.NoError(t, err, c.s)
		uassert.Equal(t, c.hrp, hrp)
		uassert.Equal(t, "bech32m", v.String())
		back, err2 := EncodeVariant(hrp, data, Bech32m)
		uassert.NoError(t, err2)
		uassert.Equal(t, lower(c.s), back)
	}
}

// A gno.land address is a Bech32 string with hrp "g" over a 20-byte payload,
// which is the externally-anchored check that the checksum maths is right.
func TestGnoAddress(t *testing.T) {
	const addr = "g1manfred47kzduec920z88wfr64ylksmdcedlf5"
	hrp, payload, v, err := DecodeBytes(addr)
	uassert.NoError(t, err)
	uassert.Equal(t, "g", hrp)
	uassert.Equal(t, 20, len(payload))
	uassert.Equal(t, "bech32", v.String())

	back, err2 := EncodeBytes(hrp, payload)
	uassert.NoError(t, err2)
	uassert.Equal(t, addr, back)
}

// One flipped data character invalidates the checksum.
func TestBadChecksum(t *testing.T) {
	const addr = "g1manfred47kzduec920z88wfr64ylksmdcedlf5"
	broken := addr[:len(addr)-1] + "4"
	_, _, _, err := Decode(broken)
	uassert.ErrorIs(t, err, ErrChecksum)
}

func TestDecodeRejects(t *testing.T) {
	cases := []struct {
		s    string
		want error
	}{
		{"A12UEL5l", ErrMixedCase},
		{"abcdef", ErrNoSeparator},
		{"1qzzfhee", ErrInvalidHRP},  // empty human-readable part
		{"a1qqqqq", ErrTooShort},     // data part shorter than the 6-char checksum
		{"a1bqqqqqq", ErrInvalidChar}, // 'b' is not in the charset
	}
	for _, c := range cases {
		_, _, _, err := Decode(c.s)
		uassert.ErrorIs(t, err, c.want, c.s)
	}
}

func TestTooLong(t *testing.T) {
	long := "a1"
	for i := 0; i < MaxLen; i++ {
		long += "q"
	}
	_, _, _, err := Decode(long)
	uassert.ErrorIs(t, err, ErrTooLong)

	payload := make([]byte, 80)
	_, err2 := EncodeBytes("hrp", payload)
	uassert.ErrorIs(t, err2, ErrTooLong)
}

func TestConvertBits(t *testing.T) {
	// 8 -> 5 with padding, then back, is the identity.
	for _, in := range [][]byte{{}, {0x00}, {0xff}, {0xde, 0xad, 0xbe, 0xef}, {1, 2, 3, 4, 5, 6, 7}} {
		five, err := ConvertBits(in, 8, 5, true)
		uassert.NoError(t, err)
		eight, err2 := ConvertBits(five, 5, 8, false)
		uassert.NoError(t, err2)
		uassert.Equal(t, len(in), len(eight))
		for i := range in {
			uassert.Equal(t, int(in[i]), int(eight[i]))
		}
	}
	// Every produced group fits in 5 bits.
	five, _ := ConvertBits([]byte{0xff, 0xff}, 8, 5, true)
	for _, g := range five {
		uassert.True(t, g < 32)
	}
	// A 5-bit input holding a 6-bit value is refused.
	_, err := ConvertBits([]byte{32}, 5, 8, true)
	uassert.ErrorIs(t, err, ErrInvalidData)
	// An unsupported width is refused.
	_, err2 := ConvertBits([]byte{1}, 0, 5, true)
	uassert.ErrorIs(t, err2, ErrInvalidBits)
}

func TestEncodeRejects(t *testing.T) {
	_, err := Encode("", []byte{0})
	uassert.ErrorIs(t, err, ErrInvalidHRP)
	// A human-readable part must stay in the printable US-ASCII range.
	_, err2 := Encode("a\x7f", []byte{0})
	uassert.ErrorIs(t, err2, ErrInvalidHRP)
	// A data group wider than 5 bits is not representable.
	_, err3 := Encode("a", []byte{32})
	uassert.ErrorIs(t, err3, ErrInvalidData)
}

func TestVariantString(t *testing.T) {
	uassert.Equal(t, "bech32", Bech32.String())
	uassert.Equal(t, "bech32m", Bech32m.String())
}

func lower(s string) string {
	out := []byte(s)
	for i, c := range out {
		if c >= 'A' && c <= 'Z' {
			out[i] = c + 32
		}
	}
	return string(out)
}

// Why Bech32m exists. A Bech32 string whose final character is 'p' keeps a valid
// checksum when 'q' characters are inserted in front of that 'p', so a reader
// accepts a string it was never handed. Both of these verify under the Bech32
// constant, and they decode to different data parts.
func TestLengthExtensionWeakness(t *testing.T) {
	const base = "a1q3g6mnsp"
	const extended = "a1q3g6mnsqp"

	_, d1, v1, err := Decode(base)
	uassert.NoError(t, err)
	uassert.Equal(t, "bech32", v1.String())

	_, d2, v2, err2 := Decode(extended)
	uassert.NoError(t, err2, "the inserted 'q' does not break the Bech32 checksum")
	uassert.Equal(t, "bech32", v2.String())
	uassert.Equal(t, len(d1)+1, len(d2))

	// Bech32m's constant closes it: the same insertion on a Bech32m string of the
	// same shape is refused.
	_, _, _, err3 := Decode("a1q6dp699qp")
	uassert.ErrorIs(t, err3, ErrChecksum)
	_, _, vm, err4 := Decode("a1q6dp699p")
	uassert.NoError(t, err4)
	uassert.Equal(t, "bech32m", vm.String())
}

// Variant is an exported int, so a caller can hand over a value that is neither
// constant. Encoding one as Bech32 anyway would answer a question nobody asked.
func TestUnknownVariant(t *testing.T) {
	_, err := EncodeVariant("a", nil, Variant(2))
	uassert.ErrorIs(t, err, ErrInvalidVariant)
	_, err2 := EncodeVariant("a", nil, Variant(-1))
	uassert.ErrorIs(t, err2, ErrInvalidVariant)
	uassert.Equal(t, "invalid", Variant(2).String())
}

// ConvertBits promises ErrInvalidPadding, and a round trip never reaches it:
// the padded direction always lands on a group boundary.
func TestConvertBitsPadding(t *testing.T) {
	// Five bits in, eight out, unpadded: one group is not a whole byte.
	_, err := ConvertBits([]byte{1}, 5, 8, false)
	uassert.ErrorIs(t, err, ErrInvalidPadding)
	// Ten bits in, eight out: the two leftover bits are not zero, so they are
	// data the caller would lose rather than padding the encoder added.
	_, err2 := ConvertBits([]byte{0, 1}, 5, 8, false)
	uassert.ErrorIs(t, err2, ErrInvalidPadding)
	// The same ten bits with zero leftovers convert cleanly.
	out, err3 := ConvertBits([]byte{0, 4}, 5, 8, false)
	uassert.NoError(t, err3)
	uassert.Equal(t, 1, len(out))
}

// An oversized payload is refused before it is regrouped, so the work stays
// bounded by the 90-character format rather than by what the caller sent.
func TestEncodeBytesBoundsBeforeWork(t *testing.T) {
	// "g" plus the separator plus six checksum characters leaves 82 groups,
	// which is 51 whole bytes.
	uassert.Equal(t, 51, MaxPayloadLen("g"))

	ok, err := EncodeBytes("g", make([]byte, MaxPayloadLen("g")))
	uassert.NoError(t, err)
	uassert.Equal(t, MaxLen, len(ok))

	_, err2 := EncodeBytes("g", make([]byte, MaxPayloadLen("g")+1))
	uassert.ErrorIs(t, err2, ErrTooLong)

	// A human-readable part that leaves no room at all.
	uassert.Equal(t, 0, MaxPayloadLen(longHRP()))
	_, err3 := EncodeBytes(longHRP(), []byte{1})
	uassert.ErrorIs(t, err3, ErrTooLong)
}

func longHRP() string {
	s := ""
	for i := 0; i < MaxLen; i++ {
		s += "a"
	}
	return s
}

// Package bencode implements bencoding, the serialization format BitTorrent
// uses for .torrent files and tracker responses, as a pure reusable package.
//
// Four types, and that is the whole format: integers (i42e), byte strings
// (5:hello), lists (l...e) and dictionaries (d...e). There is no float, no
// boolean and no null, which is most of why the format fits in one file.
//
// The reason to reach for it over JSON is that bencode is CANONICAL: one value
// has exactly one encoding. Dictionary keys are sorted bytewise, integers carry
// no leading zeros and no negative zero, and strings carry their length instead
// of an escape syntax. An infohash is the digest of a re-encoded sub-dictionary,
// so a decoder that accepts a sloppy encoding and re-emits a tidy one silently
// changes the identity of the thing it parsed.
//
// This decoder is therefore strict: it REJECTS non-canonical input rather than
// normalizing it, so for every input it accepts, Decode followed by Encode
// returns the original bytes unchanged.
//
// A live demo of this package is at
// [r/moul/x/daily/bencodedemo](/r/moul/x/daily/bencodedemo/v0).
package bencode

import (
	"errors"
	"strconv"
	"strings"
)

// Limits, so a decode stays bounded on chain.
const (
	// MaxLen is the longest input Decode will look at.
	MaxLen = 8192
	// MaxDepth is how deeply lists and dictionaries may nest.
	MaxDepth = 16
)

// Kind is the type of a [Value]: one of the four bencode types.
type Kind int

// The four bencode types, plus the zero value.
const (
	KindInvalid Kind = iota
	KindInt
	KindString
	KindList
	KindDict
)

// String names the kind, for rendering and error messages.
func (k Kind) String() string {
	switch k {
	case KindInt:
		return "int"
	case KindString:
		return "string"
	case KindList:
		return "list"
	case KindDict:
		return "dict"
	default:
		return "invalid"
	}
}

// Errors returned by [Decode]. They are distinguishable on purpose: a caller
// feeding the decoder a user-pasted torrent wants to say which of the four
// strictness rules the paste broke.
var (
	// ErrTooLong is returned when input is longer than [MaxLen].
	ErrTooLong = errors.New("bencode: input too long")
	// ErrSyntax is returned when input is not bencode at all.
	ErrSyntax = errors.New("bencode: malformed input")
	// ErrNotCanonical is returned for input that is parseable but could never
	// have been produced by an encoder: a leading zero, a negative zero, or
	// dictionary keys that are unsorted or duplicated.
	ErrNotCanonical = errors.New("bencode: input is not canonical")
	// ErrTrailingData is returned when bytes follow the top-level value.
	ErrTrailingData = errors.New("bencode: trailing data after top-level value")
	// ErrTooDeep is returned when nesting exceeds [MaxDepth].
	ErrTooDeep = errors.New("bencode: nesting too deep")
)

// Value is one bencode value. Build one with [NewInt], [NewString], [NewList]
// or [NewDict], or get one from [Decode]. Accessors that do not match the
// value's kind return the zero value rather than panicking, so a chain of
// lookups through a document of unknown shape never aborts a realm call.
type Value struct {
	kind  Kind
	num   int64
	text  string
	elems []*Value
	keys  []string
	vals  []*Value
}

// NewInt returns an integer value.
func NewInt(n int64) *Value { return &Value{kind: KindInt, num: n} }

// NewString returns a byte-string value.
func NewString(s string) *Value { return &Value{kind: KindString, text: s} }

// NewList returns a list of the given items, in order. A nil item, and the
// zero Value, are dropped: both encode to nothing, which would turn a three
// item list into a two item encoding that still reports a length of three.
func NewList(items ...*Value) *Value {
	l := &Value{kind: KindList, elems: []*Value{}}
	for _, it := range items {
		if it.Kind() == KindInvalid {
			continue
		}
		l.elems = append(l.elems, it)
	}
	return l
}

// NewDict returns an empty dictionary. Fill it with [Value.Set], in any order:
// the encoding sorts.
func NewDict() *Value {
	return &Value{kind: KindDict, keys: []string{}, vals: []*Value{}}
}

// Kind reports the value's type. A nil value is [KindInvalid].
func (v *Value) Kind() Kind {
	if v == nil {
		return KindInvalid
	}
	return v.kind
}

// Int returns the integer, or 0 for any other kind.
func (v *Value) Int() int64 {
	if v == nil || v.kind != KindInt {
		return 0
	}
	return v.num
}

// Text returns the byte string, or "" for any other kind.
func (v *Value) Text() string {
	if v == nil || v.kind != KindString {
		return ""
	}
	return v.text
}

// Len returns the number of list items or dictionary entries, 0 otherwise.
func (v *Value) Len() int {
	if v == nil {
		return 0
	}
	switch v.kind {
	case KindList:
		return len(v.elems)
	case KindDict:
		return len(v.keys)
	default:
		return 0
	}
}

// At returns the i-th list item, or the i-th dictionary value in key order.
// Out of range, or any other kind, returns nil.
func (v *Value) At(i int) *Value {
	if v == nil || i < 0 {
		return nil
	}
	switch v.kind {
	case KindList:
		if i >= len(v.elems) {
			return nil
		}
		return v.elems[i]
	case KindDict:
		if i >= len(v.vals) {
			return nil
		}
		return v.vals[i]
	default:
		return nil
	}
}

// Get returns the dictionary entry for key, or nil when it is absent or the
// value is not a dictionary.
func (v *Value) Get(key string) *Value {
	if v == nil || v.kind != KindDict {
		return nil
	}
	i, found := v.find(key)
	if !found {
		return nil
	}
	return v.vals[i]
}

// Keys returns the dictionary's keys in bytewise order, nil for other kinds.
func (v *Value) Keys() []string {
	if v == nil || v.kind != KindDict {
		return nil
	}
	out := make([]string, len(v.keys))
	copy(out, v.keys)
	return out
}

// Set inserts or replaces a dictionary entry and returns the dictionary, so
// calls chain. Four things are refused rather than stored, each because it
// would make the encoding disagree with the structure: a receiver that is not
// a dictionary, a nil value, the zero Value, and the dictionary itself. The
// first three encode to nothing, which would emit a key with no value and
// produce a dictionary this package's own Decode rejects; the fourth is a
// cycle. Removing an entry is deliberately not spelled "set it to nil",
// because nothing here removes.
//
// An indirect cycle (two dictionaries holding each other) is not detectable
// here without walking the whole structure on every insert, so it is caught by
// [Value.Encode] instead, which is depth-bounded and returns "".
//
// It never writes through the slices a previous Set produced. gno lets a
// caller copy the struct behind the pointer, and two copies sharing a backing
// array would see each other's replacements but not each other's insertions.
func (v *Value) Set(key string, val *Value) *Value {
	if v == nil || v.kind != KindDict || val.Kind() == KindInvalid || val == v {
		return v
	}
	i, found := v.find(key)
	rest := i
	if found {
		rest = i + 1
	}
	keys := make([]string, 0, len(v.keys)+1)
	vals := make([]*Value, 0, len(v.vals)+1)
	keys = append(append(append(keys, v.keys[:i]...), key), v.keys[rest:]...)
	vals = append(append(append(vals, v.vals[:i]...), val), v.vals[rest:]...)
	v.keys, v.vals = keys, vals
	return v
}

// find returns the index of key, or where it would be inserted.
func (v *Value) find(key string) (int, bool) {
	lo, hi := 0, len(v.keys)
	for lo < hi {
		mid := (lo + hi) / 2
		if v.keys[mid] < key {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo, lo < len(v.keys) && v.keys[lo] == key
}

// Encode returns the canonical bencoding of the value, or "" for a value that
// has no canonical encoding: a nil, the zero Value, anything nested deeper
// than [MaxDepth], and therefore any cycle a caller assembled by hand. "" is
// not a legal bencode document, so a caller can test for it.
//
// Encode has no error to return and is called from a realm's Render, so it is
// total by construction: the depth bound is what keeps a structure the decoder
// could never have produced from aborting the call that encodes it.
func (v *Value) Encode() string {
	var b strings.Builder
	if !v.writeTo(&b, 0) {
		return ""
	}
	return b.String()
}

// writeTo reports whether the whole value fit within MaxDepth. The bound is
// counted on containers only, exactly as the decoder counts it, so the two
// agree about which structures exist. A false leaves b holding a partial
// encoding, which is why Encode discards it.
func (v *Value) writeTo(b *strings.Builder, depth int) bool {
	if v == nil {
		return true
	}
	switch v.kind {
	case KindInt:
		b.WriteString("i")
		b.WriteString(strconv.FormatInt(v.num, 10))
		b.WriteString("e")
	case KindString:
		b.WriteString(strconv.Itoa(len(v.text)))
		b.WriteString(":")
		b.WriteString(v.text)
	case KindList:
		if depth >= MaxDepth {
			return false
		}
		b.WriteString("l")
		for _, e := range v.elems {
			if !e.writeTo(b, depth+1) {
				return false
			}
		}
		b.WriteString("e")
	case KindDict:
		if depth >= MaxDepth {
			return false
		}
		b.WriteString("d")
		for i, k := range v.keys {
			b.WriteString(strconv.Itoa(len(k)))
			b.WriteString(":")
			b.WriteString(k)
			if !v.vals[i].writeTo(b, depth+1) {
				return false
			}
		}
		b.WriteString("e")
	}
	return true
}

// Decode parses one bencode value and rejects anything after it. It also
// rejects input that is parseable but not canonical, which is the whole point:
// see the package doc.
func Decode(s string) (*Value, error) {
	if len(s) > MaxLen {
		return nil, ErrTooLong
	}
	v, next, err := decodeValue(s, 0, 0)
	if err != nil {
		return nil, err
	}
	if next != len(s) {
		return nil, ErrTrailingData
	}
	return v, nil
}

func decodeValue(s string, i, depth int) (*Value, int, error) {
	if i >= len(s) {
		return nil, i, ErrSyntax
	}
	switch c := s[i]; {
	case c == 'i':
		return decodeInt(s, i)
	case c == 'l':
		return decodeList(s, i, depth)
	case c == 'd':
		return decodeDict(s, i, depth)
	case c >= '0' && c <= '9':
		return decodeString(s, i)
	default:
		return nil, i, ErrSyntax
	}
}

func decodeInt(s string, i int) (*Value, int, error) {
	end := strings.IndexByte(s[i:], 'e')
	if end < 0 {
		return nil, i, ErrSyntax
	}
	end += i
	body := s[i+1 : end]
	if err := checkIntLiteral(body); err != nil {
		return nil, i, err
	}
	n, err := strconv.ParseInt(body, 10, 64)
	if err != nil {
		return nil, i, ErrSyntax
	}
	return NewInt(n), end + 1, nil
}

// checkIntLiteral enforces the canonical integer grammar: optional '-', then
// digits, with no leading zero and no negative zero.
func checkIntLiteral(body string) error {
	digits := body
	neg := false
	if strings.HasPrefix(digits, "-") {
		neg = true
		digits = digits[1:]
	}
	if digits == "" {
		return ErrSyntax
	}
	for k := 0; k < len(digits); k++ {
		if digits[k] < '0' || digits[k] > '9' {
			return ErrSyntax
		}
	}
	if len(digits) > 1 && digits[0] == '0' {
		return ErrNotCanonical
	}
	if neg && digits == "0" {
		return ErrNotCanonical
	}
	return nil
}

func decodeString(s string, i int) (*Value, int, error) {
	colon := strings.IndexByte(s[i:], ':')
	if colon < 0 {
		return nil, i, ErrSyntax
	}
	colon += i
	lit := s[i:colon]
	for k := 0; k < len(lit); k++ {
		if lit[k] < '0' || lit[k] > '9' {
			return nil, i, ErrSyntax
		}
	}
	if len(lit) > 1 && lit[0] == '0' {
		return nil, i, ErrNotCanonical
	}
	n, err := strconv.Atoi(lit)
	if err != nil || n < 0 {
		return nil, i, ErrSyntax
	}
	start := colon + 1
	// Compare against what is left rather than computing start+n: the length
	// literal is bounded only by MaxLen, so a 19-digit length fits in the
	// input and in an int64, and the sum would wrap to a negative slice bound.
	if n > len(s)-start {
		return nil, i, ErrSyntax
	}
	return NewString(s[start : start+n]), start + n, nil
}

func decodeList(s string, i, depth int) (*Value, int, error) {
	if depth+1 > MaxDepth {
		return nil, i, ErrTooDeep
	}
	l := NewList()
	j := i + 1
	for {
		if j >= len(s) {
			return nil, j, ErrSyntax
		}
		if s[j] == 'e' {
			return l, j + 1, nil
		}
		item, next, err := decodeValue(s, j, depth+1)
		if err != nil {
			return nil, next, err
		}
		l.elems = append(l.elems, item)
		j = next
	}
}

func decodeDict(s string, i, depth int) (*Value, int, error) {
	if depth+1 > MaxDepth {
		return nil, i, ErrTooDeep
	}
	d := NewDict()
	j := i + 1
	last := ""
	for {
		if j >= len(s) {
			return nil, j, ErrSyntax
		}
		if s[j] == 'e' {
			return d, j + 1, nil
		}
		if s[j] < '0' || s[j] > '9' {
			// A key is always a byte string. Anything else is not a dict.
			return nil, j, ErrSyntax
		}
		kv, next, err := decodeString(s, j)
		if err != nil {
			return nil, next, err
		}
		key := kv.Text()
		if len(d.keys) > 0 && key <= last {
			// Unsorted or duplicated: parseable, but no encoder emits it.
			return nil, next, ErrNotCanonical
		}
		val, next2, err := decodeValue(s, next, depth+1)
		if err != nil {
			return nil, next2, err
		}
		d.keys = append(d.keys, key)
		d.vals = append(d.vals, val)
		last = key
		j = next2
	}
}

package bencode

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestDecodeRoundTrip(t *testing.T) {
	cases := []struct {
		name string
		in   string
	}{
		{"zero", "i0e"},
		{"positive", "i42e"},
		{"negative", "i-42e"},
		{"empty string", "0:"},
		{"string", "5:hello"},
		{"string with colon", "9:a:b:c:d:e"},
		{"empty list", "le"},
		{"list of ints", "li1ei2ei3ee"},
		{"nested list", "ll1:aee"},
		{"empty dict", "de"},
		{"dict", "d3:cow3:moo4:spam4:eggse"},
		{"dict of list", "d4:spaml1:a1:bee"},
		{"torrent-ish", "d8:announce9:udp://x:y4:infod6:lengthi1024e4:name4:fileee"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			v, err := Decode(c.in)
			uassert.NoError(t, err)
			uassert.Equal(t, c.in, v.Encode())
		})
	}
}

func TestDecodeRejects(t *testing.T) {
	cases := []struct {
		name string
		in   string
	}{
		{"empty input", ""},
		{"bare letter", "x"},
		{"unterminated int", "i42"},
		{"empty int", "ie"},
		{"int with leading zero", "i03e"},
		{"negative zero", "i-0e"},
		{"explicit plus", "i+1e"},
		{"lone minus", "i-e"},
		{"non digit int", "i4a2e"},
		{"string too short", "5:abc"},
		{"string length leading zero", "03:abc"},
		{"string without colon", "5abcde"},
		{"unterminated list", "li1e"},
		{"unterminated dict", "d3:cow3:mooe4:spam"},
		{"dict with odd entries", "d3:cowe"},
		{"dict with int key", "di1e3:mooe"},
		{"dict keys out of order", "d4:spam4:eggs3:cow3:mooe"},
		{"dict duplicate keys", "d3:cow3:moo3:cow3:mooe"},
		{"trailing data", "i1ei2e"},
		{"trailing junk", "lexx"},
		{"over MaxLen", "0:" + strings.Repeat("x", MaxLen)},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			v, err := Decode(c.in)
			uassert.Error(t, err)
			if v != nil {
				t.Errorf("want nil value on error, got %s", v.Encode())
			}
		})
	}
}

func TestDecodeTooDeep(t *testing.T) {
	ok := strings.Repeat("l", MaxDepth) + strings.Repeat("e", MaxDepth)
	_, err := Decode(ok)
	uassert.NoError(t, err)

	deep := strings.Repeat("l", MaxDepth+1) + strings.Repeat("e", MaxDepth+1)
	_, err = Decode(deep)
	uassert.ErrorIs(t, err, ErrTooDeep)
}

func TestDecodeErrorKinds(t *testing.T) {
	cases := []struct {
		in   string
		want error
	}{
		{"i007e", ErrNotCanonical},
		{"d4:spam4:eggs3:cow3:mooe", ErrNotCanonical},
		{"i1ei2e", ErrTrailingData},
		{"lx", ErrSyntax},
		{"0:" + strings.Repeat("x", MaxLen), ErrTooLong},
	}
	for _, c := range cases {
		t.Run(c.in, func(t *testing.T) {
			_, err := Decode(c.in)
			uassert.ErrorIs(t, err, c.want)
		})
	}
}

func TestAccessors(t *testing.T) {
	v, err := Decode("d3:cowl1:ai7ee4:spam4:eggse")
	uassert.NoError(t, err)
	uassert.Equal(t, KindDict.String(), v.Kind().String())
	uassert.Equal(t, 2, v.Len())
	uassert.Equal(t, "cow,spam", strings.Join(v.Keys(), ","))

	cow := v.Get("cow")
	uassert.Equal(t, KindList.String(), cow.Kind().String())
	uassert.Equal(t, 2, cow.Len())
	uassert.Equal(t, "a", cow.At(0).Text())
	uassert.Equal(t, int64(7), cow.At(1).Int())

	uassert.Equal(t, "eggs", v.Get("spam").Text())
	uassert.True(t, v.Get("absent") == nil)
	uassert.True(t, cow.At(9) == nil)
	uassert.True(t, cow.At(-1) == nil)
}

func TestWrongKindAccessorsAreZero(t *testing.T) {
	s := NewString("hi")
	uassert.Equal(t, int64(0), s.Int())
	uassert.Equal(t, 0, s.Len())
	uassert.True(t, s.At(0) == nil)
	uassert.True(t, s.Get("k") == nil)
	uassert.Equal(t, 0, len(s.Keys()))

	n := NewInt(3)
	uassert.Equal(t, "", n.Text())

	var nilv *Value
	uassert.Equal(t, KindInvalid.String(), nilv.Kind().String())
	uassert.Equal(t, "", nilv.Encode())
}

func TestDictEncodesSortedWhateverTheInsertionOrder(t *testing.T) {
	d := NewDict()
	d.Set("spam", NewString("eggs"))
	d.Set("cow", NewString("moo"))
	d.Set("announce", NewInt(1))
	uassert.Equal(t, "announce,cow,spam", strings.Join(d.Keys(), ","))
	uassert.Equal(t, "d8:announcei1e3:cow3:moo4:spam4:eggse", d.Encode())
}

func TestSetReplacesInPlace(t *testing.T) {
	d := NewDict()
	d.Set("k", NewInt(1))
	d.Set("k", NewInt(2))
	uassert.Equal(t, 1, d.Len())
	uassert.Equal(t, int64(2), d.Get("k").Int())
}

func TestEncodeBuiltValues(t *testing.T) {
	l := NewList(NewInt(-3), NewString("x"), NewList())
	uassert.Equal(t, "li-3e1:xlee", l.Encode())
	uassert.Equal(t, "i-3e", NewInt(-3).Encode())
	uassert.Equal(t, "4:spam", NewString("spam").Encode())
}

func TestKindString(t *testing.T) {
	cases := []struct {
		k    Kind
		want string
	}{
		{KindInvalid, "invalid"},
		{KindInt, "int"},
		{KindString, "string"},
		{KindList, "list"},
		{KindDict, "dict"},
		{Kind(99), "invalid"},
	}
	for _, c := range cases {
		uassert.Equal(t, c.want, c.k.String())
	}
}

func TestCanonicalIsAFixedPoint(t *testing.T) {
	// Every value this package builds encodes to something it accepts, and
	// decoding that again changes nothing. That is what makes a bencode
	// digest reproducible.
	d := NewDict()
	d.Set("b", NewList(NewInt(0), NewString("")))
	d.Set("a", NewDict())
	first := d.Encode()

	v, err := Decode(first)
	uassert.NoError(t, err)
	uassert.Equal(t, first, v.Encode())
}

func TestNilValuesNeverReachTheEncoding(t *testing.T) {
	// A nil child would encode to nothing, which silently produces a
	// dictionary or a list that this package's own Decode rejects.
	d := NewDict()
	d.Set("k", nil)
	uassert.Equal(t, 0, d.Len())
	uassert.Equal(t, "de", d.Encode())

	d.Set("k", NewInt(1))
	d.Set("k", nil)
	uassert.Equal(t, int64(1), d.Get("k").Int(), "a nil never removes a live entry")

	l := NewList(NewInt(1), nil, NewString("x"))
	uassert.Equal(t, 2, l.Len())
	uassert.Equal(t, "li1e1:xe", l.Encode())

	// The property that matters: anything Encode emits, Decode accepts.
	for _, enc := range []string{d.Encode(), l.Encode()} {
		_, err := Decode(enc)
		uassert.NoError(t, err)
	}
}

func TestStringLengthNeverOverflows(t *testing.T) {
	// The length literal is bounded by nothing but MaxLen, so a 19-digit
	// length fits in the input and in an int64. start+n must not be the
	// thing that decides whether the slice is in range.
	for _, in := range []string{
		"9223372036854775807:x",
		"9223372036854775806:x",
		"8000000000000000000:x",
	} {
		v, err := Decode(in)
		uassert.Error(t, err)
		uassert.True(t, v == nil)
	}
}

func TestEncodeIsTotal(t *testing.T) {
	// A caller can build what no input can produce: a cycle, or nesting past
	// MaxDepth. Encode has no error to return, so it must not be the thing
	// that aborts a realm call.
	d := NewDict()
	d.Set("self", d)
	uassert.Equal(t, 0, d.Len(), "a dictionary cannot hold itself")
	uassert.Equal(t, "de", d.Encode())

	a, b := NewDict(), NewDict()
	a.Set("b", b)
	b.Set("a", a)
	uassert.Equal(t, "", a.Encode(), "an indirect cycle encodes to nothing")
	uassert.Equal(t, "", b.Encode())

	deep := NewList()
	for i := 0; i < MaxDepth; i++ {
		deep = NewList(deep)
	}
	uassert.Equal(t, "", deep.Encode(), "past MaxDepth there is no canonical encoding")

	shallow := NewList()
	for i := 0; i < MaxDepth-1; i++ {
		shallow = NewList(shallow)
	}
	_, err := Decode(shallow.Encode())
	uassert.NoError(t, err, "and everything under it still round-trips")
}

func TestZeroValuesNeverReachTheEncoding(t *testing.T) {
	// Value is zero-constructible from outside the package, and that zero is
	// KindInvalid, which writes nothing. Retaining one would make Len lie.
	l := NewList(NewInt(1), &Value{}, NewString("x"))
	uassert.Equal(t, 2, l.Len())
	uassert.Equal(t, "li1e1:xe", l.Encode())

	d := NewDict()
	d.Set("k", &Value{})
	uassert.Equal(t, 0, d.Len())
	uassert.Equal(t, "de", d.Encode())
}

func TestSetNeverWritesThroughAStructCopy(t *testing.T) {
	// *Value is the intended handle, but the struct is copyable, and slice
	// headers in a copied struct share their backing array.
	d := NewDict()
	d.Set("a", NewInt(1))
	d.Set("b", NewInt(2))

	c := *d
	c.Set("a", NewInt(99))
	uassert.Equal(t, int64(1), d.Get("a").Int(), "the original is untouched")
	uassert.Equal(t, int64(99), c.Get("a").Int())

	c.Set("c", NewInt(3))
	uassert.Equal(t, 2, d.Len(), "and an insertion does not leak either")
	uassert.Equal(t, 3, c.Len())
}

// Package bidimap is a bidirectional map — unique in both directions — as a
// pure, reusable package.
//
// A normal map answers "what is the value for this key". A bidirectional one
// also answers the reverse in O(1), by keeping a second index. The cost is an
// invariant a plain pair of maps does not give you: BOTH sides are unique, so
// inserting a pair whose value already belongs to another key must do something
// deliberate rather than silently corrupt the reverse index.
//
// This implementation makes that choice explicit. Put REPLACES: it evicts any
// existing pairing on either side first, so the two indexes can never disagree.
// PutUnique refuses instead, returning false. Pick whichever the caller wants;
// what is not on offer is a half-updated map.
//
// Iteration is over sorted keys, never a built-in map range: gno map iteration
// order is unspecified, and a Render built from one can differ between nodes,
// which is a consensus bug rather than a cosmetic one.
//
// A live demo of this package is at
// [r/moul/x/daily/bidimapdemo](/r/moul/x/daily/bidimapdemo/v0).
package bidimap

import "sort"

// MaxPairs bounds the map so gas stays predictable.
const MaxPairs = 4096

// BiMap is a string<->string map, unique in both directions.
type BiMap struct {
	fwd map[string]string
	rev map[string]string
}

// New returns an empty BiMap.
func New() *BiMap {
	return &BiMap{fwd: map[string]string{}, rev: map[string]string{}}
}

// Len returns the number of pairs.
func (m *BiMap) Len() int { return len(m.fwd) }

// Get returns the value bound to key.
func (m *BiMap) Get(key string) (string, bool) {
	v, ok := m.fwd[key]
	return v, ok
}

// GetKey returns the key bound to value — the reverse lookup, also O(1).
func (m *BiMap) GetKey(value string) (string, bool) {
	k, ok := m.rev[value]
	return k, ok
}

// Has reports whether key is present.
func (m *BiMap) Has(key string) bool { _, ok := m.fwd[key]; return ok }

// HasValue reports whether value is present.
func (m *BiMap) HasValue(value string) bool { _, ok := m.rev[value]; return ok }

// Put binds key<->value, REPLACING any existing pairing on either side. It
// returns the pairs that were evicted to make room, so the caller can see what
// it displaced rather than discovering it later.
//
// Returns ok=false only when the map is full and the pair is entirely new.
func (m *BiMap) Put(key, value string) (evicted [][2]string, ok bool) {
	oldValue, keyTaken := m.fwd[key]

	// Already exactly this pair: nothing to do.
	if keyTaken && oldValue == value {
		return nil, true
	}

	oldKey, valueTaken := m.rev[value]

	// Only a pair that is new on BOTH sides grows the map. Rebinding either
	// side reuses a slot, so it stays allowed at capacity. Checked up front:
	// evicting first and rolling back on failure would be unreachable code,
	// since any eviction frees the very slot the check is about.
	if !keyTaken && !valueTaken && len(m.fwd) >= MaxPairs {
		return nil, false
	}

	if keyTaken {
		evicted = append(evicted, [2]string{key, oldValue})
		delete(m.rev, oldValue)
		delete(m.fwd, key)
	}
	if valueTaken {
		evicted = append(evicted, [2]string{oldKey, value})
		delete(m.fwd, oldKey)
		delete(m.rev, value)
	}

	m.fwd[key] = value
	m.rev[value] = key
	return evicted, true
}

// PutUnique binds key<->value only when NEITHER side is already taken by a
// different pairing. Returns false without changing anything otherwise.
func (m *BiMap) PutUnique(key, value string) bool {
	if v, exists := m.fwd[key]; exists {
		return v == value // idempotent for the identical pair
	}
	if _, exists := m.rev[value]; exists {
		return false
	}
	if len(m.fwd) >= MaxPairs {
		return false
	}
	m.fwd[key] = value
	m.rev[value] = key
	return true
}

// Delete removes the pair for key. Returns false when key is absent.
func (m *BiMap) Delete(key string) bool {
	v, ok := m.fwd[key]
	if !ok {
		return false
	}
	delete(m.fwd, key)
	delete(m.rev, v)
	return true
}

// DeleteValue removes the pair for value. Returns false when value is absent.
func (m *BiMap) DeleteValue(value string) bool {
	k, ok := m.rev[value]
	if !ok {
		return false
	}
	delete(m.fwd, k)
	delete(m.rev, value)
	return true
}

// Keys returns every key, sorted. Sorted, not map order: a Render built from an
// unspecified order can differ between nodes.
func (m *BiMap) Keys() []string { return sortedKeys(m.fwd) }

// Values returns every value, sorted.
func (m *BiMap) Values() []string { return sortedKeys(m.rev) }

// Iterate calls fn for each pair in sorted key order. Returning true stops.
func (m *BiMap) Iterate(fn func(key, value string) bool) {
	for _, k := range m.Keys() {
		if fn(k, m.fwd[k]) {
			return
		}
	}
}

// Invert returns a new BiMap with keys and values swapped.
func (m *BiMap) Invert() *BiMap {
	out := New()
	for k, v := range m.fwd {
		out.fwd[v] = k
		out.rev[k] = v
	}
	return out
}

// Clone returns an independent copy.
func (m *BiMap) Clone() *BiMap {
	out := New()
	for k, v := range m.fwd {
		out.fwd[k] = v
		out.rev[v] = k
	}
	return out
}

// Consistent reports whether the two indexes agree. Always true through the
// public API; exported so tests and callers can assert the invariant directly.
func (m *BiMap) Consistent() bool {
	if len(m.fwd) != len(m.rev) {
		return false
	}
	for k, v := range m.fwd {
		if back, ok := m.rev[v]; !ok || back != k {
			return false
		}
	}
	return true
}

func sortedKeys(m map[string]string) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// Package bitset is a dense, fixed-capacity bit vector as a pure, reusable
// package: a compact set of small non-negative integers with the usual
// set algebra (union, intersection, difference).
//
// Storage is a []uint64 of ceil(n/64) words, so 1024 bits cost 16 words rather
// than 1024 booleans — the reason to reach for this on chain, where every byte
// is paid for.
//
// Capacity is fixed at construction and every operation is bounds-checked
// rather than growing: an out-of-range index is a caller bug, and silently
// growing would make gas unpredictable.
//
// A live demo of this package is at
// [r/moul/x/daily/bitsetdemo](/r/moul/x/daily/bitsetdemo/v0).
package bitset

import "strings"

// MaxBits bounds a BitSet so allocation and iteration stay predictable.
const MaxBits = 1 << 16 // 65536 bits = 1024 words = 8 KiB

// BitSet is a fixed-capacity set of integers in [0, n).
type BitSet struct {
	n     int
	words []uint64
}

// New returns a BitSet holding bits [0, n). n is clamped to [0, MaxBits].
func New(n int) *BitSet {
	if n < 0 {
		n = 0
	}
	if n > MaxBits {
		n = MaxBits
	}
	return &BitSet{n: n, words: make([]uint64, (n+63)/64)}
}

// Cap returns the capacity in bits.
func (b *BitSet) Cap() int { return b.n }

// InRange reports whether i is a valid index.
func (b *BitSet) InRange(i int) bool { return i >= 0 && i < b.n }

// Set turns bit i on and reports whether i was in range.
func (b *BitSet) Set(i int) bool {
	if !b.InRange(i) {
		return false
	}
	b.words[i/64] |= 1 << uint(i%64)
	return true
}

// Clear turns bit i off and reports whether i was in range.
func (b *BitSet) Clear(i int) bool {
	if !b.InRange(i) {
		return false
	}
	b.words[i/64] &^= 1 << uint(i%64)
	return true
}

// Flip inverts bit i and reports whether i was in range.
func (b *BitSet) Flip(i int) bool {
	if !b.InRange(i) {
		return false
	}
	b.words[i/64] ^= 1 << uint(i%64)
	return true
}

// Has reports whether bit i is set. Out of range is false, never a panic:
// membership of something that cannot be a member is simply false.
func (b *BitSet) Has(i int) bool {
	if !b.InRange(i) {
		return false
	}
	return b.words[i/64]&(1<<uint(i%64)) != 0
}

// Count returns the number of set bits (popcount).
func (b *BitSet) Count() int {
	total := 0
	for _, w := range b.words {
		total += popcount(w)
	}
	return total
}

// popcount counts set bits with the classic SWAR trick — no math/bits on gno.
func popcount(x uint64) int {
	n := 0
	for x != 0 {
		x &= x - 1 // clear the lowest set bit
		n++
	}
	return n
}

// Slice returns the set bits in ascending order.
func (b *BitSet) Slice() []int {
	out := []int{}
	for i := 0; i < b.n; i++ {
		if b.Has(i) {
			out = append(out, i)
		}
	}
	return out
}

// Clone returns an independent copy.
func (b *BitSet) Clone() *BitSet {
	c := New(b.n)
	copy(c.words, b.words)
	return c
}

// sameCap reports whether two sets can be combined word-wise.
func sameCap(a, b *BitSet) bool { return a != nil && b != nil && a.n == b.n }

// Union returns a ∪ b, or nil when the capacities differ. Mismatched capacities
// are a caller error rather than something to silently pad.
func Union(a, b *BitSet) *BitSet { return combine(a, b, "or") }

// Intersect returns a ∩ b, or nil when the capacities differ.
func Intersect(a, b *BitSet) *BitSet { return combine(a, b, "and") }

// Difference returns a \ b, or nil when the capacities differ.
func Difference(a, b *BitSet) *BitSet { return combine(a, b, "andnot") }

// SymmetricDifference returns a △ b, or nil when the capacities differ.
func SymmetricDifference(a, b *BitSet) *BitSet { return combine(a, b, "xor") }

func combine(a, b *BitSet, op string) *BitSet {
	if !sameCap(a, b) {
		return nil
	}
	out := New(a.n)
	for i := range a.words {
		switch op {
		case "or":
			out.words[i] = a.words[i] | b.words[i]
		case "and":
			out.words[i] = a.words[i] & b.words[i]
		case "andnot":
			out.words[i] = a.words[i] &^ b.words[i]
		case "xor":
			out.words[i] = a.words[i] ^ b.words[i]
		}
	}
	return out
}

// Equal reports whether two sets have the same capacity and the same bits.
func Equal(a, b *BitSet) bool {
	if !sameCap(a, b) {
		return false
	}
	for i := range a.words {
		if a.words[i] != b.words[i] {
			return false
		}
	}
	return true
}

// String renders the set as '0'/'1' from bit 0 upward, which reads left-to-right
// in index order (note this is the reverse of binary notation).
func (b *BitSet) String() string {
	var sb strings.Builder
	for i := 0; i < b.n; i++ {
		if b.Has(i) {
			sb.WriteByte('1')
		} else {
			sb.WriteByte('0')
		}
	}
	return sb.String()
}

// FromSlice builds a BitSet of capacity n containing the given indices.
// Out-of-range indices are ignored.
func FromSlice(n int, idx []int) *BitSet {
	b := New(n)
	for _, i := range idx {
		b.Set(i)
	}
	return b
}

package bitset

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestSetHasClear(t *testing.T) {
	b := New(100)
	uassert.False(t, b.Has(7))
	uassert.True(t, b.Set(7))
	uassert.True(t, b.Has(7))
	uassert.True(t, b.Clear(7))
	uassert.False(t, b.Has(7))
}

// Out of range is reported, never a panic — and Has is simply false.
func TestOutOfRange(t *testing.T) {
	b := New(64)
	for _, i := range []int{-1, 64, 1000} {
		uassert.False(t, b.Set(i))
		uassert.False(t, b.Clear(i))
		uassert.False(t, b.Flip(i))
		uassert.False(t, b.Has(i))
	}
	uassert.Equal(t, 0, b.Count())
}

// Word boundaries are where an off-by-one lives: check either side of 64.
func TestWordBoundaries(t *testing.T) {
	b := New(200)
	for _, i := range []int{0, 63, 64, 65, 127, 128, 199} {
		uassert.True(t, b.Set(i))
	}
	uassert.Equal(t, 7, b.Count())
	for _, i := range []int{0, 63, 64, 65, 127, 128, 199} {
		uassert.True(t, b.Has(i))
	}
	uassert.False(t, b.Has(62))
	uassert.False(t, b.Has(129))
}

func TestFlip(t *testing.T) {
	b := New(10)
	b.Flip(3)
	uassert.True(t, b.Has(3))
	b.Flip(3)
	uassert.False(t, b.Has(3))
}

func TestCountAndSlice(t *testing.T) {
	b := FromSlice(50, []int{1, 5, 9, 49})
	uassert.Equal(t, 4, b.Count())
	uassert.Equal(t, "1,5,9,49", join(b.Slice()))
}

func TestFromSliceIgnoresOutOfRange(t *testing.T) {
	b := FromSlice(10, []int{1, -3, 10, 99, 4})
	uassert.Equal(t, "1,4", join(b.Slice()))
}

func TestSetAlgebra(t *testing.T) {
	a := FromSlice(20, []int{1, 2, 3})
	b := FromSlice(20, []int{3, 4})
	uassert.Equal(t, "1,2,3,4", join(Union(a, b).Slice()))
	uassert.Equal(t, "3", join(Intersect(a, b).Slice()))
	uassert.Equal(t, "1,2", join(Difference(a, b).Slice()))
	uassert.Equal(t, "1,2,4", join(SymmetricDifference(a, b).Slice()))
}

// Combining different capacities is a caller error: nil, not a silent pad.
func TestMismatchedCapacityIsNil(t *testing.T) {
	a := New(10)
	b := New(20)
	uassert.True(t, Union(a, b) == nil)
	uassert.True(t, Intersect(a, b) == nil)
	uassert.True(t, Difference(a, b) == nil)
	uassert.True(t, SymmetricDifference(a, b) == nil)
	uassert.False(t, Equal(a, b))
}

func TestCloneIsIndependent(t *testing.T) {
	a := FromSlice(30, []int{1, 2})
	c := a.Clone()
	c.Set(29)
	uassert.False(t, a.Has(29))
	uassert.True(t, Equal(a, FromSlice(30, []int{1, 2})))
}

func TestEqual(t *testing.T) {
	uassert.True(t, Equal(FromSlice(8, []int{1, 3}), FromSlice(8, []int{3, 1})))
	uassert.False(t, Equal(FromSlice(8, []int{1}), FromSlice(8, []int{2})))
}

func TestString(t *testing.T) {
	uassert.Equal(t, "01010", FromSlice(5, []int{1, 3}).String())
}

func TestCapClamped(t *testing.T) {
	uassert.Equal(t, 0, New(-5).Cap())
	uassert.Equal(t, MaxBits, New(MaxBits+1000).Cap())
}

func TestPopcount(t *testing.T) {
	uassert.Equal(t, 0, popcount(0))
	uassert.Equal(t, 1, popcount(1))
	uassert.Equal(t, 64, popcount(^uint64(0)))
}

func join(xs []int) string {
	parts := []string{}
	for _, x := range xs {
		parts = append(parts, itoa(x))
	}
	return strings.Join(parts, ",")
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	neg := i < 0
	if neg {
		i = -i
	}
	var b []byte
	for i > 0 {
		b = append([]byte{byte('0' + i%10)}, b...)
		i /= 10
	}
	if neg {
		return "-" + string(b)
	}
	return string(b)
}

// Package cliffvesting computes cliff-then-linear vesting schedules as a PURE
// calculator: no state, no balances, no transfers.
//
// The shape is the standard employee/token grant: nothing vests until the
// cliff, the cliff releases the whole elapsed portion at once, and the rest
// accrues linearly until the end of the term. Keeping it pure is deliberate:
// the arithmetic is the part that is easy to get subtly wrong and easy to test,
// while custody belongs to the realm holding the coins.
//
// Everything is integer arithmetic. Vested is computed as
// total*elapsed/duration with the multiplication FIRST, so the usual rounding
// bug, dividing before multiplying and truncating the rate to zero, cannot
// happen. Rounding is always DOWN, which means the beneficiary never receives
// more than they have earned and the final instalment collects the remainder;
// at t >= end the result is exactly total, never total-1.
//
// The multiplication goes through a 128-bit intermediate. v0 did it in plain
// int64, which silently WRAPPED once total*elapsed passed 2^63: over a
// two-year term in seconds that is any grant above ~146,036 whole coins, and
// a large one reported a NEGATIVE vested amount rather than failing. See
// [Schedule.Vested].
//
// Times are int64 so the caller can use block heights or unix seconds. The unit
// only has to be consistent.
//
// A live demo of this package is at
// [r/moul/x/daily/cliffvestingdemo](/r/moul/x/daily/cliffvestingdemo/v0).
package cliffvesting

import (
	"errors"
	"math/bits"
)

var (
	ErrBadTotal    = errors.New("cliffvesting: total must be positive")
	ErrBadDuration = errors.New("cliffvesting: duration must be positive")
	ErrCliffAfter  = errors.New("cliffvesting: cliff must not fall after the end")
	ErrCliffBefore = errors.New("cliffvesting: cliff must not fall before the start")
)

// Schedule is a cliff-then-linear vesting plan. Construct with New so the
// invariants are checked once.
type Schedule struct {
	Total int64 // total amount to vest
	Start int64 // vesting begins
	Cliff int64 // nothing is claimable before this
	End   int64 // fully vested at or after this
}

// New validates and returns a Schedule. cliff must lie within [start, end].
// Passing cliff == start means "no cliff".
func New(total, start, cliff, end int64) (Schedule, error) {
	s := Schedule{Total: total, Start: start, Cliff: cliff, End: end}
	if total <= 0 {
		return Schedule{}, ErrBadTotal
	}
	if end <= start {
		return Schedule{}, ErrBadDuration
	}
	if cliff > end {
		return Schedule{}, ErrCliffAfter
	}
	if cliff < start {
		return Schedule{}, ErrCliffBefore
	}
	return s, nil
}

// NewLinear is New with no cliff.
func NewLinear(total, start, end int64) (Schedule, error) {
	return New(total, start, start, end)
}

// Duration returns the length of the vesting term.
func (s Schedule) Duration() int64 { return s.End - s.Start }

// HasCliff reports whether the schedule has a non-trivial cliff.
func (s Schedule) HasCliff() bool { return s.Cliff > s.Start }

// Vested returns how much has vested at time t. Zero before the cliff, exactly
// Total at or after End, and floor(total*elapsed/duration) in between.
//
// The product goes through [mulDiv] rather than int64. v0 computed
// `s.Total * elapsed / s.Duration()` directly, which is correct only while the
// product fits: with the term in seconds, a 318,720,000-coin grant over two
// years returned -6,264,395,224. Nothing signalled it, because a wrapped
// int64 is still a valid int64.
func (s Schedule) Vested(t int64) int64 {
	if t < s.Cliff || t < s.Start {
		return 0
	}
	if t >= s.End {
		return s.Total
	}
	// Multiply BEFORE dividing: the reverse truncates the per-tick rate to
	// zero whenever total < duration, which is the classic vesting bug.
	return mulDiv(s.Total, t-s.Start, s.Duration())
}

// Unvested returns the remainder still locked at time t.
func (s Schedule) Unvested(t int64) int64 { return s.Total - s.Vested(t) }

// Claimable returns what can be withdrawn at time t given how much has already
// been claimed. Never negative, even if claimed somehow exceeds vested.
func (s Schedule) Claimable(t, claimed int64) int64 {
	v := s.Vested(t) - claimed
	if v < 0 {
		return 0
	}
	return v
}

// IsFullyVested reports whether the term has completed at time t.
func (s Schedule) IsFullyVested(t int64) bool { return t >= s.End }

// PercentVested returns the vested share at t as an integer percentage,
// rounded down. Integer-only: no floats reach consensus state.
func (s Schedule) PercentVested(t int64) int64 {
	return mulDiv(s.Vested(t), 100, s.Total)
}

// CliffAmount returns the lump sum released the instant the cliff is reached.
func (s Schedule) CliffAmount() int64 { return s.Vested(s.Cliff) }

// mulDiv computes floor(a*b/den) through a 128-bit intermediate, so a product
// that leaves int64 does not wrap.
//
// Every caller here passes 0 <= b <= den with den > 0 and a >= 0, which is
// what makes the bits.Div64 precondition hold: the quotient is then at most a,
// so it fits in 64 bits, which is exactly the hi < den that Div64 requires and
// panics without. New enforces Total > 0 and End > Start; Vested only reaches
// this line with Start < t < End.
func mulDiv(a, b, den int64) int64 {
	if a == 0 || b == 0 {
		return 0
	}
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	q, _ := bits.Div64(hi, lo, uint64(den))
	return int64(q)
}

package cliffvesting

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func mustNew(t *testing.T, total, start, cliff, end int64) Schedule {
	s, err := New(total, start, cliff, end)
	uassert.NoError(t, err)
	return s
}

func TestNewValidation(t *testing.T) {
	_, err := New(0, 0, 0, 100)
	uassert.ErrorIs(t, err, ErrBadTotal)
	_, err = New(-5, 0, 0, 100)
	uassert.ErrorIs(t, err, ErrBadTotal)

	_, err = New(100, 50, 50, 50)
	uassert.ErrorIs(t, err, ErrBadDuration, "end must be after start")
	_, err = New(100, 50, 50, 10)
	uassert.ErrorIs(t, err, ErrBadDuration)

	_, err = New(100, 0, 200, 100)
	uassert.ErrorIs(t, err, ErrCliffAfter)

	_, err = New(100, 50, 10, 100)
	uassert.ErrorIs(t, err, ErrCliffBefore)

	_, err = New(100, 0, 100, 100)
	uassert.NoError(t, err, "a cliff exactly at the end is allowed")
}

func TestNewLinearHasNoCliff(t *testing.T) {
	s, err := NewLinear(1000, 0, 100)
	uassert.NoError(t, err)
	uassert.False(t, s.HasCliff())
	uassert.Equal(t, int64(0), s.CliffAmount())
	uassert.Equal(t, int64(500), s.Vested(50), "linear from the start")
}

// TestNothingBeforeCliff is the defining behaviour.
func TestNothingBeforeCliff(t *testing.T) {
	s := mustNew(t, 1200, 0, 300, 1200)

	uassert.Equal(t, int64(0), s.Vested(0))
	uassert.Equal(t, int64(0), s.Vested(299), "one tick before the cliff, still nothing")
	uassert.Equal(t, int64(1200), s.Unvested(299))
}

// TestCliffReleasesElapsedPortionAtOnce pins the step, not a ramp.
func TestCliffReleasesElapsedPortionAtOnce(t *testing.T) {
	s := mustNew(t, 1200, 0, 300, 1200)

	uassert.Equal(t, int64(300), s.Vested(300), "25% of the term elapsed, released in one step")
	uassert.Equal(t, int64(300), s.CliffAmount())
	uassert.Equal(t, int64(25), s.PercentVested(300))
}

func TestLinearAfterCliff(t *testing.T) {
	s := mustNew(t, 1200, 0, 300, 1200)

	uassert.Equal(t, int64(600), s.Vested(600))
	uassert.Equal(t, int64(900), s.Vested(900))
	uassert.Equal(t, int64(1199), s.Vested(1199))
}

// TestExactlyTotalAtEnd is what rounding down must never break.
func TestExactlyTotalAtEnd(t *testing.T) {
	s := mustNew(t, 1000, 0, 0, 3) // 1000/3 does not divide evenly

	uassert.Equal(t, int64(333), s.Vested(1))
	uassert.Equal(t, int64(666), s.Vested(2))
	uassert.Equal(t, int64(1000), s.Vested(3), "the last instalment collects the remainder")
	uassert.Equal(t, int64(0), s.Unvested(3))
	uassert.Equal(t, int64(1000), s.Vested(99999), "still exactly total long after the end")
}

// TestSmallTotalLongDuration is the rounding bug this package exists to avoid:
// with total < duration, dividing before multiplying truncates the rate to 0
// and nothing ever vests.
func TestSmallTotalLongDuration(t *testing.T) {
	s := mustNew(t, 7, 0, 0, 1000)

	uassert.Equal(t, int64(0), s.Vested(100), "7*100/1000 = 0.7, floors to 0")
	uassert.Equal(t, int64(1), s.Vested(150), "7*150/1000 = 1.05, floors to 1")
	uassert.Equal(t, int64(3), s.Vested(500), "half the term, half of 7, floored")
	uassert.Equal(t, int64(7), s.Vested(1000), "and still exactly total at the end")
}

func TestVestedIsMonotonic(t *testing.T) {
	s := mustNew(t, 997, 10, 40, 310)

	prev := int64(-1)
	for tick := int64(0); tick <= 320; tick++ {
		v := s.Vested(tick)
		uassert.True(t, v >= prev, "vested must never decrease")
		uassert.True(t, v <= s.Total, "vested must never exceed total")
		prev = v
	}
}

func TestUnvestedComplementsVested(t *testing.T) {
	s := mustNew(t, 500, 0, 100, 400)
	for _, tick := range []int64{0, 99, 100, 250, 399, 400, 500} {
		uassert.Equal(t, s.Total, s.Vested(tick)+s.Unvested(tick),
			"vested + unvested must always equal total")
	}
}

func TestClaimable(t *testing.T) {
	s := mustNew(t, 1000, 0, 0, 100)

	uassert.Equal(t, int64(500), s.Claimable(50, 0))
	uassert.Equal(t, int64(300), s.Claimable(50, 200), "already-claimed is deducted")
	uassert.Equal(t, int64(0), s.Claimable(50, 500), "nothing left right now")
	uassert.Equal(t, int64(500), s.Claimable(100, 500), "the rest at the end")
}

// TestClaimableNeverNegative guards the case where bookkeeping says more was
// claimed than has vested — the caller gets 0, not a negative payout.
func TestClaimableNeverNegative(t *testing.T) {
	s := mustNew(t, 1000, 0, 0, 100)
	uassert.Equal(t, int64(0), s.Claimable(10, 999))
}

func TestPercentVested(t *testing.T) {
	s := mustNew(t, 1000, 0, 0, 100)
	uassert.Equal(t, int64(0), s.PercentVested(0))
	uassert.Equal(t, int64(50), s.PercentVested(50))
	uassert.Equal(t, int64(99), s.PercentVested(99))
	uassert.Equal(t, int64(100), s.PercentVested(100))
	uassert.Equal(t, int64(100), s.PercentVested(1000))
}

// TestNonZeroStart checks the schedule is relative to Start, not to zero.
func TestNonZeroStart(t *testing.T) {
	s := mustNew(t, 400, 1000, 1100, 1400)

	uassert.Equal(t, int64(0), s.Vested(999), "before the start")
	uassert.Equal(t, int64(0), s.Vested(1099), "before the cliff")
	uassert.Equal(t, int64(100), s.Vested(1100), "cliff: a quarter elapsed")
	uassert.Equal(t, int64(200), s.Vested(1200))
	uassert.Equal(t, int64(400), s.Vested(1400))
}

func TestDurationAndFlags(t *testing.T) {
	s := mustNew(t, 100, 10, 20, 110)
	uassert.Equal(t, int64(100), s.Duration())
	uassert.True(t, s.HasCliff())
	uassert.False(t, s.IsFullyVested(109))
	uassert.True(t, s.IsFullyVested(110))
	uassert.True(t, s.IsFullyVested(999))
}

// TestCliffAtEndIsAllOrNothing covers the degenerate schedule.
func TestCliffAtEndIsAllOrNothing(t *testing.T) {
	s := mustNew(t, 100, 0, 100, 100)
	uassert.Equal(t, int64(0), s.Vested(99))
	uassert.Equal(t, int64(100), s.Vested(100))
	uassert.Equal(t, int64(100), s.CliffAmount())
}

// TestVestedDoesNotOverflow pins the defect that forced v1.
//
// v0 computed total*elapsed in plain int64. Over a term measured in seconds,
// the product passes 2^63 for any grant above roughly 146,036 whole coins, and
// the wrap is silent: the figures below came back NEGATIVE, which every caller
// then treated as a real vested amount.
func TestVestedDoesNotOverflow(t *testing.T) {
	// The real gno.land mainnet vesting term, 2026-09-12 to 2028-09-12.
	const (
		start int64 = 1789225200
		end   int64 = 1852383600
		term        = end - start // 63,158,400 seconds
	)

	for _, tc := range []struct {
		name  string
		total int64
	}{
		{"just under the v0 ceiling", 146035000000},
		{"just over the v0 ceiling", 146037000000},
		{"the largest genesis grant", 318720000000000},
		{"the whole genesis allocation", 1332999998328067},
	} {
		s, err := NewLinear(tc.total, start, end)
		uassert.NoError(t, err, tc.name)

		// Halfway through the term is exactly half the grant, and the naive
		// int64 product has long since wrapped by this size.
		uassert.Equal(t, tc.total/2, s.Vested(start+term/2), tc.name)

		// The curve stays inside its bounds and never goes backwards.
		prev := int64(0)
		for i := int64(0); i <= 8; i++ {
			got := s.Vested(start + term*i/8)
			uassert.True(t, got >= prev, tc.name+": vested went backwards")
			uassert.True(t, got >= 0, tc.name+": vested went negative")
			uassert.True(t, got <= tc.total, tc.name+": vested exceeded the total")
			prev = got
		}
		uassert.Equal(t, tc.total, prev, tc.name)

		// PercentVested multiplies by 100 on top, so it has its own ceiling.
		// It is 49 and not 50 at halfway for an ODD total: Vested floors to
		// (total-1)/2 and the percentage floors again, so two roundings in the
		// same direction land just under. That is the documented behaviour,
		// not the overflow, so the assertion allows both.
		half := s.PercentVested(start + term/2)
		uassert.True(t, half == 49 || half == 50, tc.name+": halfway percent left 49..50")
		uassert.Equal(t, int64(100), s.PercentVested(end), tc.name)
	}
}

// Package commitreveal implements the commit-then-reveal scheme as a pure,
// reusable package.
//
// The problem it solves: anything submitted to a chain is public before it is
// executed, so a naive sealed-bid auction or simultaneous-move game lets the
// last player read everyone else's move and win for free. Commit-reveal splits
// the action in two — first publish H(value || salt), later publish the value
// and salt. The commitment binds you to a choice without disclosing it.
//
// The SALT is not optional and this package refuses to let a caller skip it.
// Without one, a commitment over a small domain is trivially brute-forced: a
// rock-paper-scissors move has three possible hashes, so hashing all three
// breaks the scheme entirely. MinSaltLen is enforced at commit time rather than
// left as advice in a comment.
//
// Verification is CONSTANT-TIME over the digest. A short-circuiting comparison
// leaks, through timing, how many leading bytes of a guess were right, which is
// enough to reconstruct a commitment byte by byte.
//
// This package computes and checks commitments; it stores nothing and knows
// nothing about phases or deadlines. The realm owns that.
//
// A live demo of this package is at
// [r/moul/x/daily/commitrevealdemo](/r/moul/x/daily/commitrevealdemo/v0).
package commitreveal

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
)

// MinSaltLen is the shortest salt accepted. Short salts make a small-domain
// commitment brute-forceable, which defeats the whole scheme.
const MinSaltLen = 16

// MaxValueLen bounds the committed value so gas stays predictable.
const MaxValueLen = 4096

var (
	ErrShortSalt   = errors.New("commitreveal: salt is shorter than MinSaltLen")
	ErrLongValue   = errors.New("commitreveal: value exceeds MaxValueLen")
	ErrMismatch    = errors.New("commitreveal: reveal does not match the commitment")
	ErrBadHexDigest = errors.New("commitreveal: commitment is not a valid hex digest")
)

// DigestLen is the length in bytes of a commitment digest (SHA-256).
const DigestLen = 32

// Commit returns the hex-encoded commitment for value and salt.
//
// The salt is length-prefixed rather than simply concatenated: with plain
// concatenation, ("ab","cd") and ("a","bcd") hash identically, so one
// commitment could be opened two different ways.
func Commit(value, salt string) (string, error) {
	if len(salt) < MinSaltLen {
		return "", ErrShortSalt
	}
	if len(value) > MaxValueLen {
		return "", ErrLongValue
	}
	return hex.EncodeToString(digest(value, salt)), nil
}

// MustCommit is Commit, panicking on invalid input. For tests and for callers
// that have already validated.
func MustCommit(value, salt string) string {
	c, err := Commit(value, salt)
	if err != nil {
		panic(err.Error())
	}
	return c
}

// Verify reports whether value and salt open the given commitment. The digest
// comparison is constant-time.
func Verify(commitment, value, salt string) bool {
	if len(salt) < MinSaltLen || len(value) > MaxValueLen {
		return false
	}
	want, err := hex.DecodeString(commitment)
	if err != nil || len(want) != DigestLen {
		return false
	}
	return equalConstantTime(want, digest(value, salt))
}

// Open verifies and reports why it failed, for callers wanting a reason rather
// than a bool.
func Open(commitment, value, salt string) error {
	if len(salt) < MinSaltLen {
		return ErrShortSalt
	}
	if len(value) > MaxValueLen {
		return ErrLongValue
	}
	want, err := hex.DecodeString(commitment)
	if err != nil || len(want) != DigestLen {
		return ErrBadHexDigest
	}
	if !equalConstantTime(want, digest(value, salt)) {
		return ErrMismatch
	}
	return nil
}

// ValidCommitment reports whether s is well-formed as a commitment: hex, and
// exactly DigestLen bytes. It says nothing about what it commits to.
func ValidCommitment(s string) bool {
	b, err := hex.DecodeString(s)
	return err == nil && len(b) == DigestLen
}

// digest computes SHA-256 over a length-prefixed encoding of value and salt.
// gno's crypto/sha256 exposes only Sum256, so the message is assembled first
// rather than streamed through a hash.Hash.
func digest(value, salt string) []byte {
	buf := make([]byte, 0, 8+len(value)+len(salt))
	buf = append(buf, lengthPrefix(len(value))...)
	buf = append(buf, value...)
	buf = append(buf, lengthPrefix(len(salt))...)
	buf = append(buf, salt...)
	sum := sha256.Sum256(buf)
	return sum[:]
}

// lengthPrefix encodes n as 4 big-endian bytes.
func lengthPrefix(n int) []byte {
	return []byte{
		byte(n >> 24), byte(n >> 16), byte(n >> 8), byte(n),
	}
}

// equalConstantTime compares two byte slices without short-circuiting, so the
// time taken does not reveal how many leading bytes matched.
func equalConstantTime(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	var diff byte
	for i := range a {
		diff |= a[i] ^ b[i]
	}
	return diff == 0
}

package commitreveal

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

const goodSalt = "0123456789abcdef" // exactly MinSaltLen

func TestCommitAndVerify(t *testing.T) {
	c, err := Commit("rock", goodSalt)
	uassert.NoError(t, err)
	uassert.True(t, ValidCommitment(c), "a commitment is a 32-byte hex digest")
	uassert.Equal(t, 64, len(c), "32 bytes hex-encoded")

	uassert.True(t, Verify(c, "rock", goodSalt), "the correct opening verifies")
}

func TestCommitIsDeterministic(t *testing.T) {
	a, _ := Commit("paper", goodSalt)
	b, _ := Commit("paper", goodSalt)
	uassert.Equal(t, a, b, "same input, same commitment")
}

func TestDifferentValuesDiffer(t *testing.T) {
	a, _ := Commit("rock", goodSalt)
	b, _ := Commit("paper", goodSalt)
	uassert.False(t, a == b)
}

// TestSameValueDifferentSaltDiffers is why the salt exists: two players
// choosing the same move must not publish the same commitment.
func TestSameValueDifferentSaltDiffers(t *testing.T) {
	a, _ := Commit("rock", "salt-one-0123456789")
	b, _ := Commit("rock", "salt-two-0123456789")
	uassert.False(t, a == b, "the same move must not be recognisable across players")
}

func TestWrongOpeningFails(t *testing.T) {
	c, _ := Commit("rock", goodSalt)

	uassert.False(t, Verify(c, "paper", goodSalt), "wrong value")
	uassert.False(t, Verify(c, "rock", "a-different-salt-value"), "wrong salt")
	uassert.False(t, Verify(c, "", goodSalt), "empty value")
}

// TestShortSaltRefused is the enforced-not-advised part: a three-move game with
// a short salt is brute-forceable, so the package will not produce one.
func TestShortSaltRefused(t *testing.T) {
	_, err := Commit("rock", "tooshort")
	uassert.ErrorIs(t, err, ErrShortSalt)

	_, err = Commit("rock", strings.Repeat("x", MinSaltLen-1))
	uassert.ErrorIs(t, err, ErrShortSalt, "one byte under the minimum is still refused")

	_, err = Commit("rock", strings.Repeat("x", MinSaltLen))
	uassert.NoError(t, err, "exactly MinSaltLen is accepted")
}

func TestShortSaltNeverVerifies(t *testing.T) {
	// Even a digest that would match cannot be opened with a short salt.
	uassert.False(t, Verify(MustCommit("rock", goodSalt), "rock", "short"),
		"Verify enforces the salt floor too")
}

func TestLongValueRefused(t *testing.T) {
	_, err := Commit(strings.Repeat("x", MaxValueLen+1), goodSalt)
	uassert.ErrorIs(t, err, ErrLongValue)

	_, err = Commit(strings.Repeat("x", MaxValueLen), goodSalt)
	uassert.NoError(t, err, "exactly MaxValueLen is accepted")
}

// TestLengthPrefixPreventsAmbiguity is the subtle one: with plain
// concatenation, ("ab","cdefghijklmnopq") and ("abc","defghijklmnopq") produce
// the same bytes, so one commitment could be opened two ways.
func TestLengthPrefixPreventsAmbiguity(t *testing.T) {
	a, err := Commit("ab", "cdefghijklmnopqr")
	uassert.NoError(t, err)
	b, err := Commit("abc", "defghijklmnopqr0")
	uassert.NoError(t, err)

	uassert.False(t, a == b, "a split ambiguity must not collide")
	uassert.False(t, Verify(a, "abc", "defghijklmnopqr0"), "and must not cross-verify")
}

func TestOpenReportsReasons(t *testing.T) {
	c := MustCommit("rock", goodSalt)

	uassert.NoError(t, Open(c, "rock", goodSalt))
	uassert.ErrorIs(t, Open(c, "paper", goodSalt), ErrMismatch)
	uassert.ErrorIs(t, Open(c, "rock", "short"), ErrShortSalt)
	uassert.ErrorIs(t, Open(c, strings.Repeat("x", MaxValueLen+1), goodSalt), ErrLongValue)
	uassert.ErrorIs(t, Open("not-hex!!", "rock", goodSalt), ErrBadHexDigest)
	uassert.ErrorIs(t, Open("abcd", "rock", goodSalt), ErrBadHexDigest, "right charset, wrong length")
}

func TestMalformedCommitments(t *testing.T) {
	uassert.False(t, Verify("", "rock", goodSalt))
	uassert.False(t, Verify("zz", "rock", goodSalt), "not hex")
	uassert.False(t, Verify(strings.Repeat("ab", 16), "rock", goodSalt), "16 bytes, not 32")
}

func TestValidCommitment(t *testing.T) {
	uassert.True(t, ValidCommitment(MustCommit("x", goodSalt)))
	uassert.False(t, ValidCommitment(""))
	uassert.False(t, ValidCommitment("nothex"))
	uassert.False(t, ValidCommitment(strings.Repeat("a", 63)), "odd length")
	uassert.False(t, ValidCommitment(strings.Repeat("a", 66)), "too long")
	uassert.True(t, ValidCommitment(strings.Repeat("A", 64)), "uppercase hex is fine")
}

func TestMustCommitPanicsOnBadInput(t *testing.T) {
	defer func() {
		r := recover()
		uassert.True(t, r != nil, "MustCommit must panic on a short salt")
	}()
	MustCommit("rock", "short")
}

func TestEqualConstantTime(t *testing.T) {
	a := []byte{1, 2, 3}
	uassert.True(t, equalConstantTime(a, []byte{1, 2, 3}))
	uassert.False(t, equalConstantTime(a, []byte{1, 2, 4}), "differs in the last byte")
	uassert.False(t, equalConstantTime(a, []byte{9, 2, 3}), "differs in the first byte")
	uassert.False(t, equalConstantTime(a, []byte{1, 2}), "different lengths")
	uassert.True(t, equalConstantTime(nil, nil))
}

// TestFullRoundTrip walks the two phases the scheme is made of.
func TestFullRoundTrip(t *testing.T) {
	// Phase 1: both players publish only a commitment.
	aliceSalt := "alice-secret-salt-1"
	bobSalt := "bob-secret-salt-0001"
	aliceCommit := MustCommit("rock", aliceSalt)
	bobCommit := MustCommit("paper", bobSalt)

	uassert.False(t, aliceCommit == bobCommit)
	uassert.True(t, ValidCommitment(aliceCommit))

	// Phase 2: reveals are checked against the earlier commitments.
	uassert.NoError(t, Open(aliceCommit, "rock", aliceSalt))
	uassert.NoError(t, Open(bobCommit, "paper", bobSalt))

	// Bob cannot change his move after seeing Alice's.
	uassert.ErrorIs(t, Open(bobCommit, "scissors", bobSalt), ErrMismatch)
	// Nor can he claim Alice's commitment as his own.
	uassert.ErrorIs(t, Open(aliceCommit, "rock", bobSalt), ErrMismatch)
}

// Package countminsketch estimates element frequencies in sublinear space, as
// a pure, reusable package.
//
// An exact frequency map costs one entry per distinct element, which on chain
// means unbounded storage driven by whatever users feed it. A Count-Min Sketch
// trades exactness for a FIXED footprint: d rows of w counters, sized once and
// never grown, regardless of how many distinct elements arrive.
//
// The error is one-sided and that is the whole contract: Estimate NEVER
// UNDERCOUNTS. Collisions can only add other elements' counts to a row, so the
// true frequency is always <= the estimate. Taking the minimum across d
// independent rows makes an overestimate require a collision in every row at
// once. Callers must treat the result as an upper bound — "at most this often",
// never "exactly this often".
//
// Sizing: width controls the error, depth controls the odds of hitting it.
// Roughly, the overestimate stays within total/width with probability
// 1 - (1/2)^depth.
//
// Hashing is FNV-1a with a per-row seed, computed in pure gno — deterministic
// across every node, which a map-address-derived hash would not be.
//
// A live demo of this package is at
// [r/moul/x/daily/countminsketchdemo](/r/moul/x/daily/countminsketchdemo/v0).
package countminsketch

import "errors"

const (
	// MinWidth/MaxWidth bound each row.
	MinWidth = 4
	MaxWidth = 8192
	// MinDepth/MaxDepth bound the number of rows.
	MinDepth = 1
	MaxDepth = 16
)

var (
	ErrBadWidth = errors.New("countminsketch: width out of range")
	ErrBadDepth = errors.New("countminsketch: depth out of range")
	ErrBadCount = errors.New("countminsketch: count must be positive")
)

// Sketch is a Count-Min Sketch over string elements.
type Sketch struct {
	width  int
	depth  int
	rows   [][]int64 // depth rows of width counters
	total  int64     // sum of every increment applied
	adds   int64     // number of Add/AddN calls applied
}

// New returns a sketch with the given dimensions.
func New(width, depth int) (*Sketch, error) {
	if width < MinWidth || width > MaxWidth {
		return nil, ErrBadWidth
	}
	if depth < MinDepth || depth > MaxDepth {
		return nil, ErrBadDepth
	}
	rows := make([][]int64, depth)
	for i := range rows {
		rows[i] = make([]int64, width)
	}
	return &Sketch{width: width, depth: depth, rows: rows}, nil
}

// NewDefault returns a sketch sized for general use: 256 x 4.
func NewDefault() *Sketch {
	s, _ := New(256, 4)
	return s
}

// Width returns the number of counters per row.
func (s *Sketch) Width() int { return s.width }

// Depth returns the number of rows.
func (s *Sketch) Depth() int { return s.depth }

// Counters returns the total number of counters — the fixed storage cost.
func (s *Sketch) Counters() int { return s.width * s.depth }

// Total returns the sum of every increment applied.
func (s *Sketch) Total() int64 { return s.total }

// Distinct is deliberately absent: a Count-Min Sketch cannot answer it. Use a
// HyperLogLog for cardinality.

// Add records one occurrence of e.
func (s *Sketch) Add(e string) { s.AddN(e, 1) }

// AddN records n occurrences of e. A non-positive n is ignored.
func (s *Sketch) AddN(e string, n int64) error {
	if n <= 0 {
		return ErrBadCount
	}
	for r := 0; r < s.depth; r++ {
		s.rows[r][s.index(e, r)] += n
	}
	s.total += n
	s.adds++
	return nil
}

// Estimate returns an UPPER BOUND on how often e was added. It never
// undercounts; it may overcount when every row collided.
func (s *Sketch) Estimate(e string) int64 {
	var min int64 = -1
	for r := 0; r < s.depth; r++ {
		v := s.rows[r][s.index(e, r)]
		if min < 0 || v < min {
			min = v
		}
	}
	if min < 0 {
		return 0
	}
	return min
}

// MightHave reports whether e may have been added. A false result is
// definitive: it was never added.
func (s *Sketch) MightHave(e string) bool { return s.Estimate(e) > 0 }

// Merge adds another sketch into this one. Both must have identical dimensions;
// merging is what makes sketches useful across shards or time windows.
func (s *Sketch) Merge(other *Sketch) error {
	if s.width != other.width {
		return ErrBadWidth
	}
	if s.depth != other.depth {
		return ErrBadDepth
	}
	for r := 0; r < s.depth; r++ {
		for c := 0; c < s.width; c++ {
			s.rows[r][c] += other.rows[r][c]
		}
	}
	s.total += other.total
	s.adds += other.adds
	return nil
}

// Reset zeroes every counter, keeping the dimensions.
func (s *Sketch) Reset() {
	for r := range s.rows {
		for c := range s.rows[r] {
			s.rows[r][c] = 0
		}
	}
	s.total = 0
	s.adds = 0
}

// Clone returns an independent copy.
func (s *Sketch) Clone() *Sketch {
	cp, _ := New(s.width, s.depth)
	for r := range s.rows {
		copy(cp.rows[r], s.rows[r])
	}
	cp.total = s.total
	cp.adds = s.adds
	return cp
}

// Row returns a copy of row r, for rendering and inspection.
func (s *Sketch) Row(r int) []int64 {
	if r < 0 || r >= s.depth {
		return nil
	}
	out := make([]int64, s.width)
	copy(out, s.rows[r])
	return out
}

// Index returns the column e maps to in row r — exported so a demo can show
// where collisions happen.
func (s *Sketch) Index(e string, r int) int {
	if r < 0 || r >= s.depth {
		return -1
	}
	return s.index(e, r)
}

// index hashes e for row r with FNV-1a, seeded per row.
func (s *Sketch) index(e string, row int) int {
	const (
		offset64 = uint64(14695981039346656037)
		prime64  = uint64(1099511628211)
	)
	h := offset64
	// Seed the row so each row hashes independently.
	h ^= uint64(row + 1)
	h *= prime64
	for i := 0; i < len(e); i++ {
		h ^= uint64(e[i])
		h *= prime64
	}
	return int(h % uint64(s.width))
}

package countminsketch

import (
	"strconv"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestNewValidation(t *testing.T) {
	_, err := New(MinWidth-1, 4)
	uassert.ErrorIs(t, err, ErrBadWidth)
	_, err = New(MaxWidth+1, 4)
	uassert.ErrorIs(t, err, ErrBadWidth)
	_, err = New(256, MinDepth-1)
	uassert.ErrorIs(t, err, ErrBadDepth)
	_, err = New(256, MaxDepth+1)
	uassert.ErrorIs(t, err, ErrBadDepth)

	_, err = New(MinWidth, MinDepth)
	uassert.NoError(t, err, "the minimum dimensions are valid")
	_, err = New(MaxWidth, MaxDepth)
	uassert.NoError(t, err, "the maximum dimensions are valid")
}

func TestDimensions(t *testing.T) {
	s, _ := New(64, 3)
	uassert.Equal(t, 64, s.Width())
	uassert.Equal(t, 3, s.Depth())
	uassert.Equal(t, 192, s.Counters(), "storage is width*depth, fixed")

	d := NewDefault()
	uassert.Equal(t, 256, d.Width())
	uassert.Equal(t, 4, d.Depth())
}

func TestEmptyEstimatesZero(t *testing.T) {
	s := NewDefault()
	uassert.Equal(t, int64(0), s.Estimate("anything"))
	uassert.False(t, s.MightHave("anything"))
	uassert.Equal(t, int64(0), s.Total())
}

func TestAddAndEstimate(t *testing.T) {
	s := NewDefault()
	for i := 0; i < 5; i++ {
		s.Add("apple")
	}
	s.Add("pear")

	uassert.Equal(t, int64(5), s.Estimate("apple"))
	uassert.Equal(t, int64(1), s.Estimate("pear"))
	uassert.Equal(t, int64(6), s.Total())
	uassert.True(t, s.MightHave("apple"))
}

func TestAddNRejectsNonPositive(t *testing.T) {
	s := NewDefault()
	uassert.ErrorIs(t, s.AddN("x", 0), ErrBadCount)
	uassert.ErrorIs(t, s.AddN("x", -3), ErrBadCount)
	uassert.Equal(t, int64(0), s.Total(), "a rejected add changes nothing")
}

func TestAddNAccumulates(t *testing.T) {
	s := NewDefault()
	uassert.NoError(t, s.AddN("x", 100))
	uassert.NoError(t, s.AddN("x", 50))
	uassert.Equal(t, int64(150), s.Estimate("x"))
	uassert.Equal(t, int64(150), s.Total())
}

// TestNeverUndercounts is THE contract. A tiny sketch guarantees collisions;
// the estimate must still never fall below the truth.
func TestNeverUndercounts(t *testing.T) {
	s, _ := New(MinWidth, 2) // deliberately tiny: 4 columns, collisions certain

	truth := map[string]int64{}
	for i := 0; i < 300; i++ {
		e := "e" + strconv.Itoa(i%40)
		s.Add(e)
		truth[e]++
	}

	for e, want := range truth {
		got := s.Estimate(e)
		uassert.True(t, got >= want,
			"estimate must never undercount "+e+": got "+strconv.FormatInt(got, 10)+
				" want >= "+strconv.FormatInt(want, 10))
	}
}

// TestExactWhenNoCollisions checks a generously sized sketch is exact for a
// handful of elements — the common case.
func TestExactWhenNoCollisions(t *testing.T) {
	s, _ := New(MaxWidth, 4)
	s.AddN("alpha", 7)
	s.AddN("bravo", 3)
	s.AddN("charlie", 11)

	uassert.Equal(t, int64(7), s.Estimate("alpha"))
	uassert.Equal(t, int64(3), s.Estimate("bravo"))
	uassert.Equal(t, int64(11), s.Estimate("charlie"))
}

// TestAbsentIsDefinitiveWhenZero pins the useful direction of the one-sided
// error: zero means definitely never added.
func TestAbsentIsDefinitiveWhenZero(t *testing.T) {
	s, _ := New(MaxWidth, 4)
	s.Add("present")
	uassert.False(t, s.MightHave("definitely-absent"), "a zero estimate is definitive")
}

// TestEstimateBoundedByTotal pins the other side: an estimate can never exceed
// everything that was ever added.
func TestEstimateBoundedByTotal(t *testing.T) {
	s, _ := New(MinWidth, 1)
	for i := 0; i < 100; i++ {
		s.Add("e" + strconv.Itoa(i))
	}
	for i := 0; i < 100; i++ {
		uassert.True(t, s.Estimate("e"+strconv.Itoa(i)) <= s.Total(),
			"no estimate may exceed the total")
	}
}

// TestDeterministicAcrossInstances is what makes this safe on chain: the same
// input yields the same counters everywhere, with no map-order dependence.
func TestDeterministicAcrossInstances(t *testing.T) {
	build := func() *Sketch {
		s, _ := New(32, 3)
		for i := 0; i < 200; i++ {
			s.Add("elem" + strconv.Itoa(i%25))
		}
		return s
	}
	a, b := build(), build()

	for r := 0; r < a.Depth(); r++ {
		ra, rb := a.Row(r), b.Row(r)
		for c := range ra {
			uassert.Equal(t, ra[c], rb[c], "counters must match across instances")
		}
	}
	uassert.Equal(t, a.Estimate("elem7"), b.Estimate("elem7"))
}

func TestIndexIsStableAndInRange(t *testing.T) {
	s, _ := New(64, 3)
	for r := 0; r < 3; r++ {
		i := s.Index("hello", r)
		uassert.True(t, i >= 0 && i < 64, "index must be within the row")
		uassert.Equal(t, i, s.Index("hello", r), "index must be stable")
	}
	uassert.Equal(t, -1, s.Index("hello", -1), "out-of-range row")
	uassert.Equal(t, -1, s.Index("hello", 3))
}

// TestRowsHashIndependently checks the per-row seed actually changes the column,
// which is what makes taking the minimum meaningful.
func TestRowsHashIndependently(t *testing.T) {
	s, _ := New(MaxWidth, MaxDepth)
	first := s.Index("some-element", 0)
	differs := false
	for r := 1; r < s.Depth(); r++ {
		if s.Index("some-element", r) != first {
			differs = true
		}
	}
	uassert.True(t, differs, "rows must not all map to the same column")
}

func TestMerge(t *testing.T) {
	a, _ := New(128, 3)
	b, _ := New(128, 3)
	a.AddN("x", 5)
	b.AddN("x", 7)
	b.AddN("y", 2)

	uassert.NoError(t, a.Merge(b))
	uassert.Equal(t, int64(12), a.Estimate("x"), "merged counts add")
	uassert.Equal(t, int64(2), a.Estimate("y"))
	uassert.Equal(t, int64(14), a.Total())
}

func TestMergeRejectsMismatchedShape(t *testing.T) {
	a, _ := New(128, 3)
	uassert.ErrorIs(t, a.Merge(mustNew(t, 64, 3)), ErrBadWidth)
	uassert.ErrorIs(t, a.Merge(mustNew(t, 128, 2)), ErrBadDepth)
	uassert.Equal(t, int64(0), a.Total(), "a rejected merge changes nothing")
}

func TestReset(t *testing.T) {
	s := NewDefault()
	s.AddN("x", 10)
	s.Reset()

	uassert.Equal(t, int64(0), s.Estimate("x"))
	uassert.Equal(t, int64(0), s.Total())
	uassert.Equal(t, 256, s.Width(), "dimensions survive a reset")
}

func TestClone(t *testing.T) {
	s := NewDefault()
	s.AddN("x", 4)

	cp := s.Clone()
	cp.AddN("x", 6)

	uassert.Equal(t, int64(4), s.Estimate("x"), "clone must not share storage")
	uassert.Equal(t, int64(10), cp.Estimate("x"))
	uassert.Equal(t, s.Width(), cp.Width())
}

func TestRowCopy(t *testing.T) {
	s, _ := New(8, 2)
	s.Add("x")

	row := s.Row(0)
	uassert.Equal(t, 8, len(row))
	row[0] = 999
	uassert.False(t, s.Row(0)[0] == 999, "Row returns a copy")

	uassert.True(t, s.Row(-1) == nil)
	uassert.True(t, s.Row(2) == nil)
}

func mustNew(t *testing.T, w, d int) *Sketch {
	s, err := New(w, d)
	uassert.NoError(t, err)
	return s
}

// Package cowsay is an on-chain Gno port of the classic `cowsay` program:
// it builds an ASCII cow with a speech bubble containing a message — as a
// reusable pure package.
//
// Original: cowsay by Tony Monroe (1999), a Perl program later ported to Go
// many times. This package reimplements the core rendering — bubble framing,
// word-wrapping and the cow art — as pure, deterministic string logic.
//
// A live demo of this package (an interactive cow that says whatever you put in
// the path) is at [r/moul/x/daily/cowsaydemo](/r/moul/x/daily/cowsaydemo/v0).
package cowsay

import (
	"strings"
)

// defaultMessage is shown when no message is supplied.
const defaultMessage = "Moo!"

// wrapWidth is the maximum bubble text width (classic cowsay uses 40).
const wrapWidth = 40

// Say returns the full cowsay art (speech bubble + cow) for msg.
// An empty msg falls back to the default message.
func Say(msg string) string {
	msg = strings.TrimSpace(msg)
	if msg == "" {
		msg = defaultMessage
	}
	lines := wrap(msg, wrapWidth)
	return balloon(lines) + cow
}

// balloon builds the speech bubble around the given (already wrapped) lines.
func balloon(lines []string) string {
	width := maxLen(lines)

	var b strings.Builder
	// top border: " " + "_"*(width+2)
	b.WriteString(" ")
	b.WriteString(strings.Repeat("_", width+2))
	b.WriteString("\n")

	n := len(lines)
	for i, ln := range lines {
		left, right := borderChars(i, n)
		b.WriteString(left)
		b.WriteString(" ")
		b.WriteString(ln)
		b.WriteString(strings.Repeat(" ", width-len(ln)))
		b.WriteString(" ")
		b.WriteString(right)
		b.WriteString("\n")
	}

	// bottom border: " " + "-"*(width+2)
	b.WriteString(" ")
	b.WriteString(strings.Repeat("-", width+2))
	b.WriteString("\n")
	return b.String()
}

// borderChars picks the left/right bubble characters for line i of n.
// Single line uses < >. Multi-line uses / \ for the first row,
// \ / for the last row, and | | for the middle rows.
func borderChars(i, n int) (string, string) {
	if n == 1 {
		return "<", ">"
	}
	switch i {
	case 0:
		return "/", "\\"
	case n - 1:
		return "\\", "/"
	default:
		return "|", "|"
	}
}

// wrap splits text into lines no longer than width, breaking on spaces.
// Words longer than width are hard-split.
func wrap(text string, width int) []string {
	words := strings.Fields(text)
	if len(words) == 0 {
		return []string{""}
	}

	var lines []string
	cur := ""
	for _, w := range words {
		// hard-split a single word that is too long
		for len(w) > width {
			if cur != "" {
				lines = append(lines, cur)
				cur = ""
			}
			lines = append(lines, w[:width])
			w = w[width:]
		}
		if cur == "" {
			cur = w
		} else if len(cur)+1+len(w) <= width {
			cur = cur + " " + w
		} else {
			lines = append(lines, cur)
			cur = w
		}
	}
	if cur != "" {
		lines = append(lines, cur)
	}
	return lines
}

// maxLen returns the length of the longest line.
func maxLen(lines []string) int {
	m := 0
	for _, ln := range lines {
		if len(ln) > m {
			m = len(ln)
		}
	}
	return m
}

// cow is the classic happy cow, aligned under the bubble.
const cow = `        \   ^__^
         \  (oo)\_______
            (__)\       )\/\
                ||----w |
                ||     ||
`

package cowsay

// handrolled-table: the cow's horn line "||----w |" is ASCII art, not a GFM header
// separator. This package renders no table at all, and its production source is live
// on an immutable public path, so the opt-out has to live here.

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestWrap(t *testing.T) {
	tests := []struct {
		name  string
		text  string
		width int
		want  []string
	}{
		{"empty", "", 10, []string{""}},
		{"single", "hello", 10, []string{"hello"}},
		{"wrap two", "aaa bbb ccc", 7, []string{"aaa bbb", "ccc"}},
		{"hard split", "abcdefghij", 4, []string{"abcd", "efgh", "ij"}},
	}
	for _, tt := range tests {
		got := wrap(tt.text, tt.width)
		uassert.Equal(t, len(tt.want), len(got), tt.name+": line count")
		for i := range tt.want {
			uassert.Equal(t, tt.want[i], got[i], tt.name+": line "+tt.want[i])
		}
		// no wrapped line exceeds width
		for _, ln := range got {
			uassert.True(t, len(ln) <= tt.width, tt.name+": within width")
		}
	}
}

func TestBorderChars(t *testing.T) {
	l, r := borderChars(0, 1)
	uassert.Equal(t, "<", l)
	uassert.Equal(t, ">", r)

	l, r = borderChars(0, 3)
	uassert.Equal(t, "/", l)
	uassert.Equal(t, "\\", r)

	l, r = borderChars(1, 3)
	uassert.Equal(t, "|", l)
	uassert.Equal(t, "|", r)

	l, r = borderChars(2, 3)
	uassert.Equal(t, "\\", l)
	uassert.Equal(t, "/", r)
}

func TestMaxLen(t *testing.T) {
	uassert.Equal(t, 0, maxLen([]string{""}))
	uassert.Equal(t, 5, maxLen([]string{"ab", "cde", "fghij"}))
}

func TestSayDefault(t *testing.T) {
	got := Say("")
	uassert.True(t, strings.Contains(got, defaultMessage), "uses default message")
	uassert.True(t, strings.Contains(got, "(oo)"), "contains cow face")
	uassert.True(t, strings.Contains(got, "< Moo! >"), "single-line bubble")
}

func TestSayWrapsMultiline(t *testing.T) {
	msg := "the quick brown fox jumps over the lazy dog many many times over"
	got := Say(msg)
	// multi-line bubbles use slashes, never the single-line angle brackets
	uassert.True(t, strings.Contains(got, "/"), "multi-line top border char")
	uassert.False(t, strings.Contains(got, "< "), "no single-line marker")
}

// Package crc32 implements the CRC-32 checksum as a pure, reusable package.
//
// CRC-32 treats a message as one enormous binary number and takes the remainder
// of dividing it by a fixed polynomial. The bit-reflected, table-driven form
// implemented here is the one everything actually uses — zip, gzip, PNG, and
// Ethernet all speak IEEE.
//
// Three polynomials are provided:
//
//   - IEEE       (0xEDB88320) — zip/gzip/PNG. The default.
//   - Castagnoli (0x82F63B78) — iSCSI/btrfs; better error detection.
//   - Koopman    (0xEB31D82E)
//
// A CRC is an ACCIDENT detector, not a security primitive: it is linear, so
// anyone can craft a different message with the same checksum. Never use it to
// authenticate anything.
//
// A live demo of this package is at
// [r/moul/x/daily/crc32demo](/r/moul/x/daily/crc32demo/v0).
package crc32

import "strings"

// Common reversed polynomials.
const (
	IEEE       = 0xEDB88320
	Castagnoli = 0x82F63B78
	Koopman    = 0xEB31D82E
)

// Table is a precomputed byte-wise lookup table for one polynomial.
type Table [256]uint32

// MakeTable builds the lookup table for a reversed polynomial. Building it once
// and reusing it is the whole point of the table-driven form: it trades 1 KiB
// for eight bit-shifts per byte.
func MakeTable(poly uint32) *Table {
	var t Table
	for i := 0; i < 256; i++ {
		crc := uint32(i)
		for j := 0; j < 8; j++ {
			if crc&1 != 0 {
				crc = (crc >> 1) ^ poly
			} else {
				crc >>= 1
			}
		}
		t[i] = crc
	}
	return &t
}

var ieeeTable = MakeTable(IEEE)

// Update adds the bytes of s to a running checksum.
//
// Takes and returns the RAW register, not the final value: the caller-visible
// checksum is the register XOR 0xFFFFFFFF, so chaining Update calls on final
// values would be wrong. Start from 0 and finish with Finalize.
func Update(crc uint32, t *Table, s string) uint32 {
	for i := 0; i < len(s); i++ {
		crc = t[byte(crc)^s[i]] ^ (crc >> 8)
	}
	return crc
}

// Finalize turns a running register into the checksum.
func Finalize(crc uint32) uint32 { return crc ^ 0xFFFFFFFF }

// ChecksumWith returns the CRC-32 of s under the given table.
func ChecksumWith(s string, t *Table) uint32 {
	return Finalize(Update(0xFFFFFFFF, t, s))
}

// Checksum returns the IEEE CRC-32 of s — the one zip, gzip and PNG use.
func Checksum(s string) uint32 { return ChecksumWith(s, ieeeTable) }

// Hex renders a checksum as eight lowercase hex digits, zero-padded, which is
// how CRCs are conventionally shown.
func Hex(crc uint32) string {
	const digits = "0123456789abcdef"
	var b [8]byte
	for i := 7; i >= 0; i-- {
		b[i] = digits[crc&0xF]
		crc >>= 4
	}
	return string(b[:])
}

// ChecksumHex is Checksum rendered with Hex.
func ChecksumHex(s string) string { return Hex(Checksum(s)) }

// Verify reports whether s has the expected checksum.
func Verify(s string, expected uint32) bool { return Checksum(s) == expected }

// Split returns the checksum of each line of s, in order.
func Split(s string) []string {
	out := []string{}
	for _, line := range strings.Split(s, "\n") {
		out = append(out, ChecksumHex(line))
	}
	return out
}

package crc32

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// Known-answer tests against the published IEEE vectors.
func TestChecksumKnownVectors(t *testing.T) {
	cases := []struct {
		in   string
		want string
	}{
		{"", "00000000"},
		{"a", "e8b7be43"},
		{"abc", "352441c2"},
		{"message digest", "20159d7f"},
		{"abcdefghijklmnopqrstuvwxyz", "4c2750bd"},
		{"123456789", "cbf43926"}, // the standard CRC check value
	}
	for _, c := range cases {
		uassert.Equal(t, c.want, ChecksumHex(c.in))
	}
}

// The classic "check" value: CRC-32/IEEE of "123456789" is 0xCBF43926.
func TestStandardCheckValue(t *testing.T) {
	uassert.Equal(t, uint32(0xCBF43926), Checksum("123456789"))
}

func TestHexIsZeroPadded(t *testing.T) {
	uassert.Equal(t, "00000000", Hex(0))
	uassert.Equal(t, "0000000f", Hex(15))
	uassert.Equal(t, "ffffffff", Hex(0xFFFFFFFF))
	uassert.Equal(t, 8, len(Hex(1)))
}

// A single flipped bit must change the checksum — the entire point.
func TestDetectsSingleBitChange(t *testing.T) {
	base := Checksum("hello world")
	uassert.False(t, base == Checksum("hello worle"))
	uassert.False(t, base == Checksum("Hello world"))
}

// Order matters: a CRC is not a sum.
func TestOrderSensitive(t *testing.T) {
	uassert.False(t, Checksum("ab") == Checksum("ba"))
}

func TestVerify(t *testing.T) {
	uassert.True(t, Verify("abc", 0x352441C2))
	uassert.False(t, Verify("abd", 0x352441C2))
}

// Chaining Update over chunks must equal one shot over the whole message —
// this is why Update takes the raw register rather than a final value.
func TestUpdateIsChunkable(t *testing.T) {
	whole := Checksum("hello world")
	crc := uint32(0xFFFFFFFF)
	crc = Update(crc, ieeeTable, "hello ")
	crc = Update(crc, ieeeTable, "world")
	uassert.Equal(t, whole, Finalize(crc))
}

// Different polynomials must give different answers, and each be stable.
func TestAlternatePolynomials(t *testing.T) {
	c := MakeTable(Castagnoli)
	k := MakeTable(Koopman)
	a := ChecksumWith("123456789", c)
	b := ChecksumWith("123456789", k)
	uassert.False(t, a == Checksum("123456789"))
	uassert.False(t, a == b)
	uassert.Equal(t, a, ChecksumWith("123456789", c)) // stable
}

func TestSplit(t *testing.T) {
	got := Split("a\nabc")
	uassert.Equal(t, 2, len(got))
	uassert.Equal(t, "e8b7be43", got[0])
	uassert.Equal(t, "352441c2", got[1])
}

func TestLongInput(t *testing.T) {
	s := strings.Repeat("gno", 1000)
	uassert.Equal(t, 8, len(ChecksumHex(s)))
	uassert.Equal(t, Checksum(s), Checksum(s))
}

// Package cron parses the classic five-field cron expression and answers the
// only question a schedule exists to answer: when does it next fire.
//
// The grammar is the one every crontab uses, in the order minute, hour,
// day-of-month, month, day-of-week:
//
//	*/15 9-17 * * mon-fri
//	│    │    │ │ │
//	│    │    │ │ └── day of week, 0-7 or sun..sat (0 and 7 are both Sunday)
//	│    │    │ └──── month, 1-12 or jan..dec
//	│    │    └────── day of month, 1-31
//	│    └─────────── hour, 0-23
//	└──────────────── minute, 0-59
//
// Each field is a comma-separated list whose items are a value, a range, a
// star, or any of those followed by a step: 5, 5-30, *, */15, 5-30/5, 5/20.
// The seven @macros are accepted too (@hourly, @daily, @weekly, @monthly,
// @yearly, @annually, @midnight).
//
// A Schedule is immutable once parsed and holds no state, so it is safe to
// build one at package scope and share it. Everything is computed in UTC: a
// block timestamp has no local zone, and a schedule whose answer depended on
// one would not be the same schedule on every validating node.
package cron

import (
	"errors"
	"strconv"
	"strings"
	"time"
)

// horizonYears bounds the search in Next. A cron expression can be perfectly
// well formed and still never fire (February the 30th), so the walk needs a
// stop condition that is not "a match eventually appears". Four years clears
// the longest real gap, the leap day, with a year to spare.
const horizonYears = 5

// Schedule is a parsed cron expression.
type Schedule struct {
	expr string

	minute [60]bool
	hour   [24]bool
	dom    [32]bool // 1..31
	month  [13]bool // 1..12
	dow    [7]bool  // 0..6, Sunday is 0

	// Whether each day field was narrowed from "*". The pair decides how the
	// two are combined; see matchDay.
	domRestricted bool
	dowRestricted bool
}

var macros = map[string]string{
	"@yearly":   "0 0 1 1 *",
	"@annually": "0 0 1 1 *",
	"@monthly":  "0 0 1 * *",
	"@weekly":   "0 0 * * 0",
	"@daily":    "0 0 * * *",
	"@midnight": "0 0 * * *",
	"@hourly":   "0 * * * *",
}

var monthNames = map[string]int{
	"jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
	"jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}

var dayNames = map[string]int{
	"sun": 0, "mon": 1, "tue": 2, "wed": 3, "thu": 4, "fri": 5, "sat": 6,
}

// Parse compiles a cron expression.
//
// It validates the grammar and the ranges, and nothing else: an expression
// that is well formed but can never fire parses successfully, because only
// Next is in a position to discover that.
func Parse(expr string) (*Schedule, error) {
	raw := strings.TrimSpace(expr)
	if raw == "" {
		return nil, errors.New("cron: empty expression")
	}

	spec := raw
	if strings.HasPrefix(spec, "@") {
		expanded, ok := macros[strings.ToLower(spec)]
		if !ok {
			return nil, errors.New("cron: unknown macro " + strconv.Quote(raw))
		}
		spec = expanded
	}

	fields := strings.Fields(spec)
	if len(fields) != 5 {
		return nil, errors.New("cron: want 5 fields, got " + strconv.Itoa(len(fields)) +
			" in " + strconv.Quote(raw))
	}

	s := &Schedule{expr: raw}

	minute, err := parseField(fields[0], 0, 59, nil)
	if err != nil {
		return nil, fieldError("minute", fields[0], err)
	}
	copy(s.minute[:], minute)

	hour, err := parseField(fields[1], 0, 23, nil)
	if err != nil {
		return nil, fieldError("hour", fields[1], err)
	}
	copy(s.hour[:], hour)

	dom, err := parseField(fields[2], 1, 31, nil)
	if err != nil {
		return nil, fieldError("day of month", fields[2], err)
	}
	copy(s.dom[:], dom)
	s.domRestricted = fields[2] != "*"

	month, err := parseField(fields[3], 1, 12, monthNames)
	if err != nil {
		return nil, fieldError("month", fields[3], err)
	}
	copy(s.month[:], month)

	// Day of week is parsed over 0..7 so that 7 and 5-7 stay legal, then
	// folded: Sunday has two spellings and one slot.
	dow, err := parseField(fields[4], 0, 7, dayNames)
	if err != nil {
		return nil, fieldError("day of week", fields[4], err)
	}
	if dow[7] {
		dow[0] = true
	}
	copy(s.dow[:], dow[:7])
	s.dowRestricted = fields[4] != "*"

	return s, nil
}

// MustParse is Parse for an expression written by the programmer rather than
// supplied by a caller. It panics instead of returning an error, so a constant
// schedule can be a package-level variable.
func MustParse(expr string) *Schedule {
	s, err := Parse(expr)
	if err != nil {
		panic(err)
	}
	return s
}

// Expr returns the expression this schedule was parsed from, unmodified. A
// macro is reported as the macro, not as its expansion.
func (s *Schedule) Expr() string { return s.expr }

// Matches reports whether the schedule fires during the minute containing t.
// Seconds and smaller are ignored: cron has no sub-minute resolution.
func (s *Schedule) Matches(t time.Time) bool {
	u := t.UTC()
	return s.month[int(u.Month())] &&
		s.matchDay(u) &&
		s.hour[u.Hour()] &&
		s.minute[u.Minute()]
}

// Next returns the first instant strictly after `after` at which the schedule
// fires, and whether there is one.
//
// The second return value is not decoration. "0 0 30 2 *" is a legal
// expression with no instant behind it, and a caller that assumed a match
// would scan forever.
func (s *Schedule) Next(after time.Time) (time.Time, bool) {
	// Strictly after, and aligned to the minute: a schedule handed its own
	// firing time must answer with the following one, not with itself.
	t := after.UTC().Truncate(time.Minute).Add(time.Minute)
	limit := t.Year() + horizonYears

	for t.Year() <= limit {
		switch {
		case !s.month[int(t.Month())]:
			// Skipping to the first of the next month relies on time.Date
			// normalising month 13 into January of the following year.
			t = time.Date(t.Year(), t.Month()+1, 1, 0, 0, 0, 0, time.UTC)
		case !s.matchDay(t):
			t = time.Date(t.Year(), t.Month(), t.Day()+1, 0, 0, 0, 0, time.UTC)
		case !s.hour[t.Hour()]:
			t = time.Date(t.Year(), t.Month(), t.Day(), t.Hour()+1, 0, 0, 0, time.UTC)
		case !s.minute[t.Minute()]:
			t = t.Add(time.Minute)
		default:
			return t, true
		}
	}
	return time.Time{}, false
}

// NextN returns the next n firing times, in order. It returns fewer, possibly
// none, when the schedule runs out before n are found.
func (s *Schedule) NextN(after time.Time, n int) []time.Time {
	if n <= 0 {
		return nil
	}
	out := make([]time.Time, 0, n)
	t := after
	for i := 0; i < n; i++ {
		next, ok := s.Next(t)
		if !ok {
			break
		}
		out = append(out, next)
		t = next
	}
	return out
}

// matchDay combines the two day fields.
//
// This is the rule the whole package is written for, and it is the one every
// reimplementation gets wrong. When BOTH day fields are narrowed the match is
// their union, not their intersection: "0 0 13 * 5" is the 13th of the month
// OR any Friday, which is why a Friday the 13th crontab is written that way
// and still fires on ordinary Fridays. When only one is narrowed the other
// matches everything, so the union and the intersection coincide and there is
// nothing to decide.
func (s *Schedule) matchDay(t time.Time) bool {
	dom := s.dom[t.Day()]
	dow := s.dow[int(t.Weekday())]
	switch {
	case s.domRestricted && s.dowRestricted:
		return dom || dow
	case s.domRestricted:
		return dom
	case s.dowRestricted:
		return dow
	default:
		return true
	}
}

// parseField expands one comma-separated field into a bitmap of size max+1.
func parseField(field string, min, max int, names map[string]int) ([]bool, error) {
	bits := make([]bool, max+1)
	for _, part := range strings.Split(field, ",") {
		if part == "" {
			return nil, errors.New("empty list item")
		}

		rangePart := part
		step := 1
		if i := strings.Index(part, "/"); i >= 0 {
			rangePart = part[:i]
			n, err := strconv.Atoi(part[i+1:])
			if err != nil {
				return nil, errors.New("step is not a number: " + strconv.Quote(part[i+1:]))
			}
			if n < 1 {
				return nil, errors.New("step must be at least 1, got " + strconv.Itoa(n))
			}
			step = n
		}

		lo, hi, err := parseRange(rangePart, min, max, names, step)
		if err != nil {
			return nil, err
		}
		for v := lo; v <= hi; v += step {
			bits[v] = true
		}
	}
	return bits, nil
}

// parseRange resolves the pre-step half of a list item into inclusive bounds.
func parseRange(s string, min, max int, names map[string]int, step int) (int, int, error) {
	if s == "*" {
		return min, max, nil
	}
	if i := strings.Index(s, "-"); i > 0 {
		lo, err := parseValue(s[:i], min, max, names)
		if err != nil {
			return 0, 0, err
		}
		hi, err := parseValue(s[i+1:], min, max, names)
		if err != nil {
			return 0, 0, err
		}
		if lo > hi {
			return 0, 0, errors.New("range runs backwards: " + strconv.Quote(s))
		}
		return lo, hi, nil
	}
	v, err := parseValue(s, min, max, names)
	if err != nil {
		return 0, 0, err
	}
	if step > 1 {
		// "5/20" is shorthand for "5-max/20": a bare value with a step means
		// start here and keep going, not fire once.
		return v, max, nil
	}
	return v, v, nil
}

// parseValue resolves a single number or three-letter name.
func parseValue(s string, min, max int, names map[string]int) (int, error) {
	if names != nil {
		if v, ok := names[strings.ToLower(s)]; ok {
			return v, nil
		}
	}
	v, err := strconv.Atoi(s)
	if err != nil {
		return 0, errors.New("not a number or a known name: " + strconv.Quote(s))
	}
	if v < min || v > max {
		return 0, errors.New("out of range " + strconv.Itoa(min) + "-" + strconv.Itoa(max) +
			": " + strconv.Itoa(v))
	}
	return v, nil
}

// fieldError names the field a parse failure came from. A bare "out of range"
// is useless when five fields all accept numbers.
func fieldError(name, field string, err error) error {
	return errors.New("cron: " + name + " field " + strconv.Quote(field) + ": " + err.Error())
}

package cron

import (
	"testing"
	"time"
)

// at is shorthand for a UTC instant, so the tables below read as dates.
func at(y int, mo time.Month, d, h, mi int) time.Time {
	return time.Date(y, mo, d, h, mi, 0, 0, time.UTC)
}

func TestParseRejects(t *testing.T) {
	cases := []struct {
		name string
		expr string
	}{
		{"empty", ""},
		{"blank", "   "},
		{"four fields", "* * * *"},
		{"six fields", "* * * * * *"},
		{"minute out of range", "60 * * * *"},
		{"hour out of range", "* 24 * * *"},
		{"day zero", "* * 0 * *"},
		{"month thirteen", "* * * 13 *"},
		{"weekday eight", "* * * * 8"},
		{"backwards range", "* * * * 5-1"},
		{"zero step", "*/0 * * * *"},
		{"negative step", "*/-2 * * * *"},
		{"empty list item", "1,,2 * * * *"},
		{"not a number", "abc * * * *"},
		{"unknown name", "* * * smarch *"},
		{"unknown macro", "@fortnightly"},
		{"macro with fields", "@daily extra"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := Parse(tc.expr); err == nil {
				t.Fatalf("Parse(%q): want error, got nil", tc.expr)
			}
		})
	}
}

func TestNext(t *testing.T) {
	base := at(2026, time.March, 10, 9, 17)
	cases := []struct {
		name string
		expr string
		from time.Time
		want time.Time
	}{
		{"every minute", "* * * * *", base, at(2026, time.March, 10, 9, 18)},
		{"quarter hour", "*/15 * * * *", base, at(2026, time.March, 10, 9, 30)},
		{"top of hour", "0 * * * *", base, at(2026, time.March, 10, 10, 0)},
		{"list", "5,25,45 * * * *", base, at(2026, time.March, 10, 9, 25)},
		{"step from value", "5/20 * * * *", base, at(2026, time.March, 10, 9, 25)},
		{"range with step", "0-30/10 * * * *", base, at(2026, time.March, 10, 9, 20)},
		{"workday morning", "30 8 * * 1-5", base, at(2026, time.March, 11, 8, 30)},
		{"weekend only", "0 12 * * sat,sun", base, at(2026, time.March, 14, 12, 0)},
		{"month list", "0 0 1 jan,jul *", base, at(2026, time.July, 1, 0, 0)},
		{"end of month", "0 0 31 * *", base, at(2026, time.March, 31, 0, 0)},
		{"leap day", "0 0 29 2 *", base, at(2028, time.February, 29, 0, 0)},
		{"next minute is exclusive", "17 9 * * *", base, at(2026, time.March, 11, 9, 17)},
		{"seconds are discarded", "* * * * *", base.Add(42 * time.Second), at(2026, time.March, 10, 9, 18)},
		{"year rolls over", "0 0 1 1 *", base, at(2027, time.January, 1, 0, 0)},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			s, err := Parse(tc.expr)
			if err != nil {
				t.Fatalf("Parse(%q): %v", tc.expr, err)
			}
			got, ok := s.Next(tc.from)
			if !ok {
				t.Fatalf("Next(%q): no match within the horizon", tc.expr)
			}
			if !got.Equal(tc.want) {
				t.Errorf("Next(%q) from %v = %v, want %v", tc.expr, tc.from, got, tc.want)
			}
		})
	}
}

// TestDayOrDay pins the one rule a cron parser is actually written for: when
// both day fields are restricted the match is a UNION, not an intersection.
func TestDayOrDay(t *testing.T) {
	// The 13th of March 2026 is a Friday, so a naive AND would hide the bug.
	// April 2026 separates them: Friday the 3rd comes before the 13th.
	s, err := Parse("0 0 13 * 5")
	if err != nil {
		t.Fatal(err)
	}
	got, ok := s.Next(at(2026, time.March, 20, 0, 0))
	if !ok {
		t.Fatal("no match")
	}
	if want := at(2026, time.March, 27, 0, 0); !got.Equal(want) {
		t.Errorf("first = %v, want %v (a Friday, not the 13th)", got, want)
	}
	got, ok = s.Next(at(2026, time.April, 8, 0, 0))
	if !ok {
		t.Fatal("no match")
	}
	if want := at(2026, time.April, 10, 0, 0); !got.Equal(want) {
		t.Errorf("second = %v, want %v", got, want)
	}
}

func TestDayFieldRestriction(t *testing.T) {
	cases := []struct {
		name string
		expr string
		from time.Time
		want time.Time
	}{
		// Day-of-week alone: every day-of-month qualifies, so it is an AND
		// with a field that matches everything.
		{"dow only", "0 0 * * 3", at(2026, time.March, 10, 0, 0), at(2026, time.March, 11, 0, 0)},
		// Day-of-month alone, same reasoning mirrored.
		{"dom only", "0 0 15 * *", at(2026, time.March, 10, 0, 0), at(2026, time.March, 15, 0, 0)},
		// Neither restricted: the next midnight.
		{"neither", "0 0 * * *", at(2026, time.March, 10, 0, 0), at(2026, time.March, 11, 0, 0)},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			s, err := Parse(tc.expr)
			if err != nil {
				t.Fatal(err)
			}
			got, ok := s.Next(tc.from)
			if !ok {
				t.Fatal("no match")
			}
			if !got.Equal(tc.want) {
				t.Errorf("Next(%q) = %v, want %v", tc.expr, got, tc.want)
			}
		})
	}
}

// TestSundayIsSevenToo pins the historical alias: 0 and 7 are both Sunday, and
// 5-7 therefore has to mean Friday through Sunday rather than running backwards.
func TestSundayIsSevenToo(t *testing.T) {
	from := at(2026, time.March, 10, 0, 0) // a Tuesday
	zero, err := Parse("0 0 * * 0")
	if err != nil {
		t.Fatal(err)
	}
	seven, err := Parse("0 0 * * 7")
	if err != nil {
		t.Fatal(err)
	}
	a, _ := zero.Next(from)
	b, _ := seven.Next(from)
	if !a.Equal(b) {
		t.Errorf("dow 0 gave %v, dow 7 gave %v", a, b)
	}
	if want := at(2026, time.March, 15, 0, 0); !a.Equal(want) {
		t.Errorf("Sunday = %v, want %v", a, want)
	}

	wrap, err := Parse("0 0 * * 5-7")
	if err != nil {
		t.Fatalf("5-7 must span Friday to Sunday: %v", err)
	}
	for _, d := range []int{13, 14, 15} {
		if !wrap.Matches(at(2026, time.March, d, 0, 0)) {
			t.Errorf("5-7 should match March %d", d)
		}
	}
	if wrap.Matches(at(2026, time.March, 16, 0, 0)) {
		t.Error("5-7 should not match Monday")
	}
}

func TestMacros(t *testing.T) {
	cases := []struct {
		macro string
		same  string
	}{
		{"@yearly", "0 0 1 1 *"},
		{"@annually", "0 0 1 1 *"},
		{"@monthly", "0 0 1 * *"},
		{"@weekly", "0 0 * * 0"},
		{"@daily", "0 0 * * *"},
		{"@midnight", "0 0 * * *"},
		{"@hourly", "0 * * * *"},
	}
	from := at(2026, time.March, 10, 9, 17)
	for _, tc := range cases {
		t.Run(tc.macro, func(t *testing.T) {
			m, err := Parse(tc.macro)
			if err != nil {
				t.Fatal(err)
			}
			plain, err := Parse(tc.same)
			if err != nil {
				t.Fatal(err)
			}
			a, _ := m.Next(from)
			b, _ := plain.Next(from)
			if !a.Equal(b) {
				t.Errorf("%s = %v, %s = %v", tc.macro, a, tc.same, b)
			}
			if m.Expr() != tc.macro {
				t.Errorf("Expr() = %q, want the original %q", m.Expr(), tc.macro)
			}
		})
	}
}

// TestImpossible: a schedule with no instant at all must say so rather than
