func TestEmpty(t *testing.T) {
	f := New()
	uassert.Equal(t, 0, f.Len())
	uassert.True(t, f.IsEmpty())
	uassert.False(t, f.Has("a"))
	uassert.True(t, f.Sorted(), "an empty map is trivially sorted")

	_, ok := f.Get("a")
	uassert.False(t, ok)
	_, _, ok = f.At(0)
	uassert.False(t, ok)
}

// TestStaysSortedRegardlessOfInsertionOrder is the core invariant.
func TestStaysSortedRegardlessOfInsertionOrder(t *testing.T) {
	f := New()
	for _, k := range []string{"delta", "alpha", "echo", "bravo", "charlie"} {
		f.Set(k, "v-"+k)
	}
	uassert.Equal(t, "alpha,bravo,charlie,delta,echo", strings.Join(f.Keys(), ","))
	uassert.True(t, f.Sorted())
}

func TestGetSet(t *testing.T) {
	f := New()
	uassert.True(t, f.Set("b", "2"))
	uassert.True(t, f.Set("a", "1"))

	v, ok := f.Get("a")
	uassert.True(t, ok)
	uassert.Equal(t, "1", v)

	_, ok = f.Get("zzz")
	uassert.False(t, ok)
}

func TestSetUpdatesInPlace(t *testing.T) {
	f := New()
	f.Set("a", "1")
	f.Set("b", "2")

	uassert.True(t, f.Set("a", "99"))
	uassert.Equal(t, 2, f.Len(), "updating must not add an entry")

	v, _ := f.Get("a")
	uassert.Equal(t, "99", v)
	uassert.True(t, f.Sorted())
}

func TestValuesFollowKeyOrder(t *testing.T) {
	f := New()
	f.Set("c", "3")
	f.Set("a", "1")
	f.Set("b", "2")
	uassert.Equal(t, "1,2,3", strings.Join(f.Values(), ","))
}

func TestDelete(t *testing.T) {
	f := New()
	for _, k := range []string{"a", "b", "c", "d"} {
		f.Set(k, k)
	}

	uassert.True(t, f.Delete("b"))
	uassert.Equal(t, "a,c,d", strings.Join(f.Keys(), ","), "the gap must close")
	uassert.Equal(t, "a,c,d", strings.Join(f.Values(), ","), "values shift with keys")
	uassert.Equal(t, 3, f.Len())
	uassert.True(t, f.Sorted())

	uassert.False(t, f.Delete("b"), "deleting twice reports false")
}

func TestDeleteEnds(t *testing.T) {
	f := New()
	for _, k := range []string{"a", "b", "c"} {
		f.Set(k, k)
	}
	uassert.True(t, f.Delete("a"))
	uassert.True(t, f.Delete("c"))
	uassert.Equal(t, "b", strings.Join(f.Keys(), ","))
	uassert.True(t, f.Delete("b"))
	uassert.True(t, f.IsEmpty())
}

func TestAt(t *testing.T) {
	f := New()
	f.Set("b", "2")
	f.Set("a", "1")

	k, v, ok := f.At(0)
	uassert.True(t, ok)
	uassert.Equal(t, "a", k)
	uassert.Equal(t, "1", v)

	_, _, ok = f.At(-1)
	uassert.False(t, ok)
	_, _, ok = f.At(2)
	uassert.False(t, ok)
}

func TestIterateAndStop(t *testing.T) {
	f := New()
	for _, k := range []string{"c", "a", "b"} {
		f.Set(k, strings.ToUpper(k))
	}

	var seen []string
	f.Iterate(func(k, v string) bool {
		seen = append(seen, k+"="+v)
		return false
	})
	uassert.Equal(t, "a=A,b=B,c=C", strings.Join(seen, ","))

	count := 0
	f.Iterate(func(k, v string) bool { count++; return true })
	uassert.Equal(t, 1, count, "returning true stops iteration")
}

// TestRange is the query sorted storage makes cheap.
func TestRange(t *testing.T) {
	f := New()
	for _, k := range []string{"a", "b", "c", "d", "e"} {
		f.Set(k, k)
	}

	uassert.Equal(t, "b,c,d", collect(f, "b", "e"), "lo inclusive, hi exclusive")
	uassert.Equal(t, "c,d,e", collect(f, "c", ""), "empty hi runs to the end")
	uassert.Equal(t, "a,b,c,d,e", collect(f, "", ""), "empty bounds cover everything")
	uassert.Equal(t, "", collect(f, "x", "z"), "a range past the end yields nothing")
	uassert.Equal(t, "", collect(f, "c", "c"), "an empty half-open range yields nothing")
}

func TestRangeStops(t *testing.T) {
	f := New()
	for _, k := range []string{"a", "b", "c"} {
		f.Set(k, k)
	}
	n := 0
	f.Range("", "", func(k, v string) bool { n++; return true })
	uassert.Equal(t, 1, n)
}

func TestRangeOnAbsentBoundary(t *testing.T) {
	f := New()
	for _, k := range []string{"a", "c", "e"} {
		f.Set(k, k)
	}
	// "b" and "d" are not present; the range still lands correctly.
	uassert.Equal(t, "c", collect(f, "b", "d"))
}

func TestKeysAndValuesAreCopies(t *testing.T) {
	f := New()
	f.Set("a", "1")
	f.Set("b", "2")

	ks := f.Keys()
	ks[0] = "mutated"
	vs := f.Values()
	vs[0] = "mutated"

	uassert.Equal(t, "a,b", strings.Join(f.Keys(), ","), "callers cannot reorder the map through Keys")
	uassert.Equal(t, "1,2", strings.Join(f.Values(), ","))
}

func TestClone(t *testing.T) {
	f := New()
	f.Set("a", "1")

	cp := f.Clone()
	cp.Set("b", "2")

	uassert.Equal(t, 1, f.Len(), "clone must not share storage")
	uassert.Equal(t, 2, cp.Len())
	uassert.True(t, cp.Sorted())
}

func TestMaxEntries(t *testing.T) {
	f := New()
	for i := 0; i < MaxEntries; i++ {
		uassert.True(t, f.Set(pad(i), "v"), "should accept up to MaxEntries")
	}
	uassert.Equal(t, MaxEntries, f.Len())

	uassert.False(t, f.Set("zzz-overflow", "v"), "a full map refuses a new key")
	uassert.Equal(t, MaxEntries, f.Len())

	uassert.True(t, f.Set(pad(0), "updated"), "a full map still accepts updates")
	v, _ := f.Get(pad(0))
	uassert.Equal(t, "updated", v)
}

// TestDescendingInsertionIsTheSlowPath exercises the worst case for a sorted
// vector — every insert shifts the whole tail — and checks it stays correct.
func TestDescendingInsertionIsTheSlowPath(t *testing.T) {
	f := New()
	for i := 200; i > 0; i-- {
		f.Set(pad(i), strconv.Itoa(i))
	}
	uassert.Equal(t, 200, f.Len())
	uassert.True(t, f.Sorted(), "still sorted after 200 head insertions")

	k, v, _ := f.At(0)
	uassert.Equal(t, pad(1), k)
	uassert.Equal(t, "1", v, "keys and values must stay in step through every shift")
}

func collect(f *FlatMap, lo, hi string) string {
	var out []string
	f.Range(lo, hi, func(k, v string) bool {
		out = append(out, k)
		return false
	})
	return strings.Join(out, ",")
}

// pad zero-pads so string order matches numeric order. ufmt has no width
// flags in gno, so this is done by hand.
func pad(i int) string {
	s := strconv.Itoa(i)
	for len(s) < 6 {
		s = "0" + s
	}
	return s
}

// Package fraction is exact rational arithmetic as a pure, reusable package:
// values are p/q with int64 numerator and denominator, always kept in lowest
// terms with a positive denominator.
//
// This exists because there are no floats worth trusting on chain. 0.1 + 0.2 is
// not 0.3 in binary floating point, and a consensus system cannot afford an
// answer that depends on rounding. A fraction is exact: one third really is one
// third, and only becomes lossy at the moment you ask for a decimal.
//
// Every operation is checked for int64 overflow and returns ok=false rather
// than silently wrapping — a wrapped numerator would be a wrong answer that
// looks fine.
//
// A live demo of this package is at
// [r/moul/x/daily/fractiondemo](/r/moul/x/daily/fractiondemo/v0).
package fraction

import (
	"errors"
	"strconv"
	"strings"
)

// ErrZeroDenominator is returned when a denominator of zero is requested.
var ErrZeroDenominator = errors.New("fraction: zero denominator")

// Fraction is an exact rational number in lowest terms, denominator > 0.
type Fraction struct {
	num, den int64
}

// New returns num/den reduced, or an error when den is zero.
func New(num, den int64) (Fraction, error) {
	if den == 0 {
		return Fraction{}, ErrZeroDenominator
	}
	if den < 0 { // keep the sign in the numerator so comparisons are simple
		num, den = -num, -den
	}
	g := gcd(abs(num), den)
	if g > 1 {
		num, den = num/g, den/g
	}
	return Fraction{num, den}, nil
}

// Int returns n as n/1.
func Int(n int64) Fraction { return Fraction{n, 1} }

// Zero is 0/1.
func Zero() Fraction { return Fraction{0, 1} }

// Num returns the numerator; Den the (always positive) denominator.
func (f Fraction) Num() int64 { return f.num }

// Den returns the denominator, which is always > 0. The zero value of the type
// has den == 0, so treat it as 1 to keep an un-initialised Fraction usable.
func (f Fraction) Den() int64 {
	if f.den == 0 {
		return 1
	}
	return f.den
}

// IsZero reports whether f == 0.
func (f Fraction) IsZero() bool { return f.num == 0 }

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	if a == 0 {
		return 1
	}
	return a
}

// mulOK multiplies with an overflow check.
func mulOK(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	p := a * b
	if p/b != a { // the classic check: dividing back must reproduce a
		return 0, false
	}
	return p, true
}

// addOK adds with an overflow check.
func addOK(a, b int64) (int64, bool) {
	s := a + b
	if (a > 0 && b > 0 && s < 0) || (a < 0 && b < 0 && s >= 0) {
		return 0, false
	}
	return s, true
}

// Add returns f+g. ok is false on int64 overflow.
func (f Fraction) Add(g Fraction) (Fraction, bool) { return combine(f, g, false) }

// Sub returns f-g. ok is false on int64 overflow.
func (f Fraction) Sub(g Fraction) (Fraction, bool) { return combine(f, g, true) }

func combine(f, g Fraction, sub bool) (Fraction, bool) {
	fd, gd := f.Den(), g.Den()
	a, ok1 := mulOK(f.num, gd)
	b, ok2 := mulOK(g.num, fd)
	d, ok3 := mulOK(fd, gd)
	if !ok1 || !ok2 || !ok3 {
		return Fraction{}, false
	}
	if sub {
		b = -b
	}
	n, ok4 := addOK(a, b)
	if !ok4 {
		return Fraction{}, false
	}
	out, err := New(n, d)
	return out, err == nil
}

// Mul returns f*g. ok is false on int64 overflow.
func (f Fraction) Mul(g Fraction) (Fraction, bool) {
	n, ok1 := mulOK(f.num, g.num)
	d, ok2 := mulOK(f.Den(), g.Den())
	if !ok1 || !ok2 {
		return Fraction{}, false
	}
	out, err := New(n, d)
	return out, err == nil
}

// Div returns f/g. ok is false on overflow or division by zero.
func (f Fraction) Div(g Fraction) (Fraction, bool) {
	if g.IsZero() {
		return Fraction{}, false
	}
	n, ok1 := mulOK(f.num, g.Den())
	d, ok2 := mulOK(f.Den(), g.num)
	if !ok1 || !ok2 {
		return Fraction{}, false
	}
	out, err := New(n, d)
	return out, err == nil
}

// Neg returns -f.
func (f Fraction) Neg() Fraction { return Fraction{-f.num, f.Den()} }

// Cmp returns -1, 0 or +1 as f is less than, equal to, or greater than g.
// Compares by cross-multiplication, so it is exact — no decimal conversion.
func (f Fraction) Cmp(g Fraction) int {
	a, ok1 := mulOK(f.num, g.Den())
	b, ok2 := mulOK(g.num, f.Den())
	if !ok1 || !ok2 {
		// fall back to a lossy comparison only when exact would overflow
		fa := float64(f.num) / float64(f.Den())
		fb := float64(g.num) / float64(g.Den())
		switch {
		case fa < fb:
			return -1
		case fa > fb:
			return 1
		}
		return 0
	}
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	}
	return 0
}

// Equal reports exact equality.
func (f Fraction) Equal(g Fraction) bool { return f.Cmp(g) == 0 }

// String renders "p/q", or just "p" when the denominator is 1.
func (f Fraction) String() string {
	if f.Den() == 1 {
		return strconv.FormatInt(f.num, 10)
	}
	return strconv.FormatInt(f.num, 10) + "/" + strconv.FormatInt(f.Den(), 10)
}

// Decimal renders f with exactly places digits after the point, truncated
// toward zero. THIS is where exactness ends — 1/3 cannot be written in decimal,
// so the caller chooses how much to lose and when.
func Decimal(f Fraction, places int) string {
	if places < 0 {
		places = 0
	}
	n, d := f.num, f.Den()
	neg := n < 0
	if neg {
		n = -n
	}
	whole := n / d
	rem := n % d
	var b strings.Builder
	if neg && (whole != 0 || rem != 0) {
		b.WriteByte('-')
	}
	b.WriteString(strconv.FormatInt(whole, 10))
	if places == 0 {
		return b.String()
	}
	b.WriteByte('.')
	for i := 0; i < places; i++ {
		rem *= 10
		b.WriteString(strconv.FormatInt(rem/d, 10))
		rem %= d
	}
	return b.String()
}

package fraction

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func mk(t *testing.T, n, d int64) Fraction {
	t.Helper()
	f, err := New(n, d)
	uassert.NoError(t, err)
	return f
}

func TestNewReduces(t *testing.T) {
	uassert.Equal(t, "1/2", mk(t, 2, 4).String())
	uassert.Equal(t, "2", mk(t, 6, 3).String())
	uassert.Equal(t, "0", mk(t, 0, 5).String())
}

// The sign always lives in the numerator, so -1/2 and 1/-2 are the same value.
func TestSignNormalised(t *testing.T) {
	a := mk(t, 1, -2)
	uassert.Equal(t, "-1/2", a.String())
	uassert.True(t, a.Equal(mk(t, -1, 2)))
	uassert.True(t, mk(t, -2, -4).Equal(mk(t, 1, 2)))
}

func TestZeroDenominator(t *testing.T) {
	_, err := New(1, 0)
	uassert.ErrorIs(t, err, ErrZeroDenominator)
}

// The headline: exact arithmetic where floats would drift.
func TestExactThirds(t *testing.T) {
	third := mk(t, 1, 3)
	sum, ok := third.Add(third)
	uassert.True(t, ok)
	sum, ok = sum.Add(third)
	uassert.True(t, ok)
	uassert.Equal(t, "1", sum.String()) // exactly 1, not 0.9999…
}

func TestArithmetic(t *testing.T) {
	a, b := mk(t, 1, 2), mk(t, 1, 3)
	s, _ := a.Add(b)
	uassert.Equal(t, "5/6", s.String())
	d, _ := a.Sub(b)
	uassert.Equal(t, "1/6", d.String())
	m, _ := a.Mul(b)
	uassert.Equal(t, "1/6", m.String())
	q, _ := a.Div(b)
	uassert.Equal(t, "3/2", q.String())
	uassert.Equal(t, "-1/2", a.Neg().String())
}

func TestDivByZero(t *testing.T) {
	_, ok := mk(t, 1, 2).Div(Zero())
	uassert.False(t, ok)
}

// Overflow must be reported, never silently wrapped into a wrong answer.
func TestOverflowReported(t *testing.T) {
	big := Fraction{num: 1 << 62, den: 3}
	_, ok := big.Mul(Fraction{num: 1 << 62, den: 5})
	uassert.False(t, ok)
	_, ok2 := big.Add(Fraction{num: 1 << 62, den: 7})
	uassert.False(t, ok2)
}

// Comparison is exact: cross-multiplication, never a decimal detour.
func TestCmp(t *testing.T) {
	uassert.Equal(t, -1, mk(t, 1, 3).Cmp(mk(t, 1, 2)))
	uassert.Equal(t, 1, mk(t, 2, 3).Cmp(mk(t, 1, 2)))
	uassert.Equal(t, 0, mk(t, 2, 4).Cmp(mk(t, 1, 2)))
	// 1/3 vs 33333/100000 — a decimal comparison at 5 places would call these equal
	uassert.Equal(t, 1, mk(t, 1, 3).Cmp(mk(t, 33333, 100000)))
}

func TestDecimal(t *testing.T) {
	uassert.Equal(t, "0.333", Decimal(mk(t, 1, 3), 3))
	uassert.Equal(t, "0.5", Decimal(mk(t, 1, 2), 1))
	uassert.Equal(t, "1", Decimal(mk(t, 3, 2), 0)) // truncates toward zero
	uassert.Equal(t, "-0.333", Decimal(mk(t, -1, 3), 3))
	uassert.Equal(t, "2.000", Decimal(Int(2), 3))
	uassert.Equal(t, "0", Decimal(Zero(), 0))
}

// The zero value must behave as 0/1 rather than dividing by zero.
func TestZeroValueUsable(t *testing.T) {
	var f Fraction
	uassert.Equal(t, int64(1), f.Den())
	uassert.True(t, f.IsZero())
	uassert.Equal(t, "0", f.String())
	s, ok := f.Add(Int(1))
	uassert.True(t, ok)
	uassert.Equal(t, "1", s.String())
}

// Package geohash encodes a latitude/longitude pair into the short base32
// string known as a geohash, decodes one back into the cell it names, and
// walks from a cell to the eight around it.
//
// A geohash is a prefix code: every character narrows the box, so two places
// that share a long prefix are close together, and truncating a hash zooms
// out. That is the whole reason to use one on chain, where an avl tree keyed
// by geohash gives a cheap "everything near here" range scan without storing
// any geometry: Get the prefix, iterate, done.
//
//	hash, _ := geohash.Encode(42.6, -5.6, 5)   // "ezs42"
//	box, _ := geohash.DecodeBox("ezs42")       // the cell it names
//	north, _ := geohash.Neighbor("ezs42", geohash.North)
//
// The alphabet is the standard one and deliberately drops a, i, l and o, so a
// hash survives being read aloud or written down. Anything outside it is
// refused rather than quietly skipped.
//
// Everything here is pure arithmetic on exact binary fractions: both world
// ranges are powers of two divided by powers of two, so every box bound is
// representable in a float64 and two identical calls can never disagree. No
// map is iterated and no value is rounded, which is what makes a Render built
// on this deterministic.
//
// A live demo of this package is at
// [r/moul/x/daily/geohashdemo](/r/moul/x/daily/geohashdemo/v0).
package geohash

import "errors"

// Alphabet is the standard geohash base32 alphabet. It omits a, i, l and o so
// that a hash read aloud or copied by hand stays unambiguous.
const Alphabet = "0123456789bcdefghjkmnpqrstuvwxyz"

// MaxPrecision is the longest hash this package will produce or accept: 12
// characters, 60 bits, a cell well under a millimetre across. Past that the
// extra characters say nothing a float64 can still distinguish.
const MaxPrecision = 12

var (
	// ErrPrecision is returned by Encode for a length outside 1..MaxPrecision.
	ErrPrecision = errors.New("geohash: precision out of range")
	// ErrLatitude is returned by Encode for a latitude outside -90..90.
	ErrLatitude = errors.New("geohash: latitude out of range")
	// ErrLongitude is returned by Encode for a longitude outside -180..180.
	ErrLongitude = errors.New("geohash: longitude out of range")
	// ErrEmpty is returned when a hash is required and none was given.
	ErrEmpty = errors.New("geohash: empty hash")
	// ErrTooLong is returned for a hash longer than MaxPrecision.
	ErrTooLong = errors.New("geohash: hash longer than the maximum precision")
	// ErrInvalidChar is returned for a character outside Alphabet, which
	// includes the four letters the alphabet deliberately leaves out.
	ErrInvalidChar = errors.New("geohash: character is not in the geohash alphabet")
	// ErrDirection is returned by Neighbor for a Direction it does not know.
	ErrDirection = errors.New("geohash: unknown direction")
	// ErrNoNeighbor is returned by Neighbor when the step leaves the world:
	// north of the top row, or south of the bottom one. Longitude wraps and
	// never produces this.
	ErrNoNeighbor = errors.New("geohash: no neighbour in that direction")
)

// Box is the rectangle of latitudes and longitudes a geohash names. A geohash
// is a box, never a point, and the shorter the hash the larger the box.
type Box struct {
	MinLat, MaxLat float64
	MinLon, MaxLon float64
}

// Center returns the midpoint of the box, which is what Decode reports.
func (b Box) Center() (lat, lon float64) {
	return (b.MinLat + b.MaxLat) / 2, (b.MinLon + b.MaxLon) / 2
}

// Contains reports whether a point falls inside the box. The lower and left
// edges belong to the box and the upper and right ones do not, matching how
// Encode assigns a point sitting exactly on a midpoint.
func (b Box) Contains(lat, lon float64) bool {
	return lat >= b.MinLat && lat < b.MaxLat && lon >= b.MinLon && lon < b.MaxLon
}

// HeightDeg is the box's north-south extent in degrees.
func (b Box) HeightDeg() float64 { return b.MaxLat - b.MinLat }

// WidthDeg is the box's east-west extent in degrees.
func (b Box) WidthDeg() float64 { return b.MaxLon - b.MinLon }

// Direction names one of the eight cells around a geohash. The values are
// ordered clockwise from north, so adding four modulo eight is the reverse.
type Direction int

// The eight directions, clockwise from north.
const (
	North Direction = iota
	NorthEast
	East
	SouthEast
	South
	SouthWest
	West
	NorthWest
)

// String returns the lowercase hyphenated name, or "unknown" for a value that
// is not one of the eight.
func (d Direction) String() string {
	switch d {
	case North:
		return "north"
	case NorthEast:
		return "north-east"
	case East:
		return "east"
	case SouthEast:
		return "south-east"
	case South:
		return "south"
	case SouthWest:
		return "south-west"
	case West:
		return "west"
	case NorthWest:
		return "north-west"
	}
	return "unknown"
}

// step returns the latitude and longitude offsets, in whole cells, for a
// direction. The second result is false for a direction that is not one of
// the eight.
func (d Direction) step() (dLat, dLon float64, ok bool) {
	switch d {
	case North:
		return 1, 0, true
	case NorthEast:
		return 1, 1, true
	case East:
		return 0, 1, true
	case SouthEast:
		return -1, 1, true
	case South:
		return -1, 0, true
	case SouthWest:
		return -1, -1, true
	case West:
		return 0, -1, true
	case NorthWest:
		return 1, -1, true
	}
	return 0, 0, false
}

// Encode returns the geohash of a point, precision characters long.
//
// Longitude takes the first bit and the two alternate, so an odd number of
// characters gives longitude one bit more than latitude and the cell comes out
// roughly square in degrees. A point sitting exactly on a dividing line goes
// to the upper, or eastern, half.
func Encode(lat, lon float64, precision int) (string, error) {
	if precision < 1 || precision > MaxPrecision {
		return "", ErrPrecision
	}
	if lat < -90 || lat > 90 {
		return "", ErrLatitude
	}
	if lon < -180 || lon > 180 {
		return "", ErrLongitude
	}

	latMin, latMax := -90.0, 90.0
	lonMin, lonMax := -180.0, 180.0

	out := make([]byte, 0, precision)
	ch, bit, even := 0, 0, true
	for len(out) < precision {
		if even {
			mid := (lonMin + lonMax) / 2
			if lon >= mid {
				ch |= 1 << uint(4-bit)
				lonMin = mid
			} else {
				lonMax = mid
			}
		} else {
			mid := (latMin + latMax) / 2
			if lat >= mid {
				ch |= 1 << uint(4-bit)
				latMin = mid
			} else {
				latMax = mid
			}
		}
		even = !even
		if bit < 4 {
			bit++
			continue
		}
		out = append(out, Alphabet[ch])
		ch, bit = 0, 0
	}
	return string(out), nil
}

// Decode returns the centre of the cell a geohash names. The centre is the
// best single point a hash can give: the cell itself is what was encoded, and
// DecodeBox is how to ask how big it is.
func Decode(hash string) (lat, lon float64, err error) {
	b, err := DecodeBox(hash)
	if err != nil {
		return 0, 0, err
	}
	lat, lon = b.Center()
	return lat, lon, nil
}

// DecodeBox returns the cell a geohash names.
func DecodeBox(hash string) (Box, error) {
	if hash == "" {
		return Box{}, ErrEmpty
	}
	if len(hash) > MaxPrecision {
		return Box{}, ErrTooLong
	}

	b := Box{MinLat: -90, MaxLat: 90, MinLon: -180, MaxLon: 180}
	even := true
	for i := 0; i < len(hash); i++ {
		v, ok := symbol(hash[i])
		if !ok {
			return Box{}, ErrInvalidChar
		}
		for _, mask := range [5]int{16, 8, 4, 2, 1} {
			if even {
				mid := (b.MinLon + b.MaxLon) / 2
				if v&mask != 0 {
					b.MinLon = mid
				} else {
					b.MaxLon = mid
				}
			} else {
				mid := (b.MinLat + b.MaxLat) / 2
				if v&mask != 0 {
					b.MinLat = mid
				} else {
					b.MaxLat = mid
				}
			}
			even = !even
		}
	}
	return b, nil
}

// Neighbor returns the geohash of the cell one step away, at the same
// precision.
//
// It works by walking one whole cell from the centre and re-encoding, which is
// exact: every cell bound is a binary fraction, so the step lands on another
// centre rather than near one.
//
// Longitude wraps, so the cell east of the last column is the first column
// again: the antimeridian is a line on a map, not an edge of the world. The
// classic lookup-table implementations report nothing there, which is a
// property of the tables and not of the globe. Latitude genuinely stops, and
// a step past a pole returns ErrNoNeighbor.
func Neighbor(hash string, d Direction) (string, error) {
	dLat, dLon, ok := d.step()
	if !ok {
		return "", ErrDirection
	}
	b, err := DecodeBox(hash)
	if err != nil {
		return "", err
	}
	lat, lon := b.Center()

	lat += dLat * b.HeightDeg()
	if lat > 90 || lat < -90 {
		return "", ErrNoNeighbor
	}
	lon += dLon * b.WidthDeg()
	if lon > 180 {
		lon -= 360
	}
	if lon < -180 {
		lon += 360
	}
	return Encode(lat, lon, len(hash))
}

// Neighbors returns the cells around a geohash, clockwise from north.
//
// The result is short rather than padded when a direction has no cell, which
// only happens at the poles: a caller iterating the result never has to filter
// an empty string out of it.
func Neighbors(hash string) ([]string, error) {
	if _, err := DecodeBox(hash); err != nil {
		return nil, err
	}
	out := make([]string, 0, 8)
	for d := North; d <= NorthWest; d++ {
		n, err := Neighbor(hash, d)
		if err == ErrNoNeighbor {
			continue
		}
		if err != nil {
			return nil, err
		}
		out = append(out, n)
	}
	return out, nil
}

// symbol maps an alphabet character to its five-bit value. It is a linear scan
// rather than a map because the alphabet is 32 bytes long and a package-level
// map would be one more object for every realm that imports this.
func symbol(c byte) (int, bool) {
	for i := 0; i < len(Alphabet); i++ {
		if Alphabet[i] == c {
			return i, true
		}
	}
	return 0, false
}

package geohash

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestEncode(t *testing.T) {
	tests := []struct {
		name      string
		lat, lon  float64
		precision int
		want      string
	}{
		// The two reference vectors every geohash implementation is checked
		// against; both come from the algorithm's public description.
		{"jutland 11 chars", 57.64911, 10.40744, 11, "u4pruydqqvj"},
		{"leon 5 chars", 42.6, -5.6, 5, "ezs42"},
		// Null island sits on both midpoints, so every comparison takes the
		// "greater or equal" branch.
		{"null island", 0, 0, 5, "s0000"},
		{"south west corner", -90, -180, 5, "00000"},
		{"north east corner", 90, 180, 5, "zzzzz"},
		{"precision one", 57.64911, 10.40744, 1, "u"},
		{"shorter hash is a prefix", 57.64911, 10.40744, 4, "u4pr"},
	}
	for _, tt := range tests {
		got, err := Encode(tt.lat, tt.lon, tt.precision)
		uassert.NoError(t, err, tt.name)
		uassert.Equal(t, tt.want, got, tt.name)
	}
}

func TestEncodeErrors(t *testing.T) {
	tests := []struct {
		name      string
		lat, lon  float64
		precision int
	}{
		{"precision zero", 0, 0, 0},
		{"precision negative", 0, 0, -1},
		{"precision too large", 0, 0, MaxPrecision + 1},
		{"latitude above range", 90.1, 0, 5},
		{"latitude below range", -90.1, 0, 5},
		{"longitude above range", 0, 180.1, 5},
		{"longitude below range", 0, -180.1, 5},
	}
	for _, tt := range tests {
		got, err := Encode(tt.lat, tt.lon, tt.precision)
		uassert.Error(t, err, tt.name)
		uassert.Equal(t, "", got, tt.name)
	}
}

func TestDecodeBox(t *testing.T) {
	// The cell the Leon vector lands in. Every bound is an exact binary
	// fraction, which is why they can be compared literally.
	b, err := DecodeBox("ezs42")
	uassert.NoError(t, err)
	uassert.Equal(t, 42.5830078125, b.MinLat)
	uassert.Equal(t, 42.626953125, b.MaxLat)
	uassert.Equal(t, -5.625, b.MinLon)
	uassert.Equal(t, -5.5810546875, b.MaxLon)

	uassert.True(t, b.Contains(42.6, -5.6), "contains its own point")
	uassert.False(t, b.Contains(0, 0), "does not contain null island")

	lat, lon := b.Center()
	uassert.Equal(t, 42.60498046875, lat)
	uassert.Equal(t, -5.60302734375, lon)
}

func TestDecodeIsTheBoxCenter(t *testing.T) {
	lat, lon, err := Decode("ezs42")
	uassert.NoError(t, err)
	b, err := DecodeBox("ezs42")
	uassert.NoError(t, err)
	clat, clon := b.Center()
	uassert.Equal(t, clat, lat)
	uassert.Equal(t, clon, lon)
}

func TestRoundTrip(t *testing.T) {
	// Decoding a hash and re-encoding its centre at the same length gives the
	// hash back: the centre can never fall in a neighbouring cell.
	hashes := []string{"u", "u4", "u4pr", "ezs42", "s0000", "00000", "zzzzz", "u4pruydqqvj"}
	for _, h := range hashes {
		lat, lon, err := Decode(h)
		uassert.NoError(t, err, h)
		got, err := Encode(lat, lon, len(h))
		uassert.NoError(t, err, h)
		uassert.Equal(t, h, got, h)
	}
}

func TestDecodeErrors(t *testing.T) {
	// The alphabet drops a, i, l and o on purpose; anything outside it, and an
	// over-long hash, are refused rather than silently truncated.
	for _, h := range []string{"", "a", "i", "l", "o", "ezs4A", "ezs4 ", "u4pruydqqvjxx"} {
		_, _, err := Decode(h)
		uassert.Error(t, err, h)
	}
}

func TestNeighborIsReversible(t *testing.T) {
	// A cell well inside the grid: stepping away and back is the identity, in
	// all eight directions.
	const h = "ezs42"
	for _, d := range []Direction{North, NorthEast, East, SouthEast, South, SouthWest, West, NorthWest} {
		n, err := Neighbor(h, d)
		uassert.NoError(t, err, d.String())
		uassert.NotEqual(t, h, n, d.String())
		back, err := Neighbor(n, opposite(d))
		uassert.NoError(t, err, d.String())
		uassert.Equal(t, h, back, d.String())
	}
}

func TestNeighborKnownCells(t *testing.T) {
	// Cross-checked against the classic border/neighbour lookup tables, which
	// are a completely different way of computing the same answer.
	tests := []struct {
		dir  Direction
		want string
	}{
		{North, "ezs48"},
		{South, "ezs40"},
		{East, "ezs43"},
		{West, "ezefr"},
		{NorthEast, "ezs49"},
		{SouthWest, "ezefp"},
	}
	for _, tt := range tests {
		got, err := Neighbor("ezs42", tt.dir)
		uassert.NoError(t, err, tt.dir.String())
		uassert.Equal(t, tt.want, got, tt.dir.String())
	}
}

func TestNeighborWrapsLongitude(t *testing.T) {
	// The antimeridian is not an edge of the world: the column east of the
	// last one is the first column again.
	east, err := Neighbor("z", East)
	uassert.NoError(t, err)
	uassert.Equal(t, "b", east)

	west, err := Neighbor("b", West)
	uassert.NoError(t, err)
	uassert.Equal(t, "z", west)
}

func TestNeighborStopsAtThePoles(t *testing.T) {
	// Latitude does not wrap: there is nothing north of the top row.
	_, err := Neighbor("z", North)
	uassert.ErrorIs(t, err, ErrNoNeighbor)

	_, err = Neighbor("0", South)
	uassert.ErrorIs(t, err, ErrNoNeighbor)

	// The same cell still has neighbours sideways and downwards.
	got, err := Neighbor("z", South)
	uassert.NoError(t, err)
	uassert.Equal(t, "x", got)
}

func TestNeighborErrors(t *testing.T) {
	_, err := Neighbor("", North)
	uassert.Error(t, err)

	_, err = Neighbor("ezs4a", North)
	uassert.Error(t, err)

	_, err = Neighbor("ezs42", Direction(42))
	uassert.ErrorIs(t, err, ErrDirection)
}

func TestNeighbors(t *testing.T) {
	got, err := Neighbors("ezs42")
	uassert.NoError(t, err)
	uassert.Equal(t, 8, len(got))
	uassert.Equal(t, "ezs48", got[0]) // North
	uassert.Equal(t, "ezs43", got[2]) // East
	uassert.Equal(t, "ezs40", got[4]) // South
	uassert.Equal(t, "ezefr", got[6]) // West

	// Unique: a repeat would mean the stepping collapsed two directions.
	seen := map[string]bool{}
	for _, n := range got {
		uassert.False(t, seen[n], n)
		seen[n] = true
	}

	// At the pole the row above is missing, and the list is short rather than
	// carrying empty strings a caller would have to filter.
	got, err = Neighbors("z")
	uassert.NoError(t, err)
	uassert.Equal(t, 5, len(got))
	for _, n := range got {
		uassert.NotEqual(t, "", n)
	}
}

func TestDirectionString(t *testing.T) {
	tests := []struct {
		d    Direction
		want string
	}{
		{North, "north"},
		{NorthEast, "north-east"},
		{East, "east"},
		{SouthEast, "south-east"},
		{South, "south"},
		{SouthWest, "south-west"},
		{West, "west"},
		{NorthWest, "north-west"},
		{Direction(42), "unknown"},
	}
	for _, tt := range tests {
		uassert.Equal(t, tt.want, tt.d.String())
	}
}

func TestBoxDimensions(t *testing.T) {
	b, err := DecodeBox("ezs42")
	uassert.NoError(t, err)
	// Five characters is 25 bits: 13 go to longitude, 12 to latitude, and the
	// two halves of the world differ by exactly that factor of two, so the
	// cell comes out square in degrees.
	uassert.Equal(t, 180.0/4096.0, b.HeightDeg())
	uassert.Equal(t, 360.0/8192.0, b.WidthDeg())

	// One more character is five more bits, so the cell is 32 times smaller.
	b6, err := DecodeBox("ezs42d")
	uassert.NoError(t, err)
	uassert.Equal(t, b.HeightDeg()/8, b6.HeightDeg())
	uassert.Equal(t, b.WidthDeg()/4, b6.WidthDeg())
}

// opposite is the test's own inverse of a direction, kept here rather than
// exported so the package surface stays the part callers need.
func opposite(d Direction) Direction {
	return Direction((int(d) + 4) % 8)
}

// Package glob matches shell-style patterns against strings, in two modes:
// plain, where `*` crosses everything, and path, where `/` is a boundary that
// only `**` crosses.
//
// The reason to have it on chain is the allowlist. A realm that decides what a
// caller may touch writes the rule as a pattern (gno.land/r/moul/**), and the
// obvious alternative, strings.HasPrefix, is wrong in a way that only shows up
// in production: the prefix gno.land/r/moul/home also matches
// gno.land/r/moul/homeless, and the prefix a caller gets by trimming /** off
// the rule above, gno.land/r/moul, also matches gno.land/r/moulier/drain, a
// different namespace owned by a different person. A separator-aware matcher
// cannot make either mistake, because a boundary is part of the grammar rather
// than something the caller remembered to append. Remembering to append it is
// no answer either: gno.land/r/moul/home with a slash on the end stops being a
// rule that matches the path it names.
//
// The matcher is iterative with a single backtrack point, so it runs in
// O(len(pattern) * len(name)) time and constant space. That is not a style
// preference. The recursive one-liner every glob tutorial shows is exponential
// on a pattern like a*a*a*a*a*a*b, and a realm that accepts a pattern from a
// caller and runs an exponential matcher on it has handed out a gas bomb.
//
// Matching is byte-oriented, deliberately: `?` matches one byte and a class
// range compares bytes, so this package is for ASCII subjects (package paths,
// bech32 addresses, handles, file names) and not for matching prose. See the
// package README for what that rules out.
//
// A live demo of this package is at
// [r/moul/x/daily/globdemo](/r/moul/x/daily/globdemo/v0).
package glob

import "strings"

// Separator is the byte [MatchPath] treats as a path boundary.
const Separator = '/'

// Match reports whether name matches pattern.
//
//	?          any single byte
//	*          any sequence of bytes, including none
//	[abc]      any one of the listed bytes
//	[a-z]      any byte in the range, ends inclusive
//	[!abc]     any byte NOT listed; [^abc] is the same thing
//	\x         the literal byte x, for any x
//	anything else  itself
//
// `*` crosses every byte, including [Separator]. Use [MatchPath] when the
// subject is a path and a wildcard must stay inside one segment.
//
// An invalid pattern matches nothing. There is no error return, so the choice
// is between inert and permissive, and a bad allowlist entry that matches
// everything is the worse of the two. Ask [Valid] when it matters.
func Match(pattern, name string) bool {
	if !Valid(pattern) {
		return false
	}
	return matchBytes(pattern, name)
}

// MatchPath reports whether name matches pattern, with [Separator] as a
// boundary neither side may cross by accident.
//
// Both are split into segments, and then:
//
//   - a segment that is exactly `**` matches zero or more whole segments
//   - every other segment is matched by [Match] against one segment, so `*`,
//     `?` and a class can never reach past the separator
//
// `**` only crosses as a whole segment. Glued to anything else, as in `a**b`,
// it is an ordinary star confined to its segment.
//
// A [Separator] that is escaped (`a\/b`) or inside a class (`[/]`) belongs to
// its segment and does not split the pattern. Such a pattern matches nothing,
// because a name segment can never contain a separator, and it says so by
// returning false rather than by aborting.
//
// An invalid pattern matches nothing, as in [Match].
func MatchPath(pattern, name string) bool {
	if !Valid(pattern) {
		return false
	}
	return matchSegments(splitPattern(pattern), splitName(name))
}

// Valid reports whether pattern is well formed.
//
// Three things make it malformed, and each of them is a typo a caller makes
// rather than a construct anyone writes on purpose: an unterminated class
// (`[a-z`), an empty one (`[]`, `[!]`), and a trailing backslash with nothing
// to escape (`abc\`).
func Valid(pattern string) bool {
	for i := 0; i < len(pattern); {
		switch pattern[i] {
		case '\\':
			if i+1 >= len(pattern) {
				return false
			}
			i += 2
		case '[':
			j := i + 1
			if j < len(pattern) && (pattern[j] == '!' || pattern[j] == '^') {
				j++
			}
			start := j
			for j < len(pattern) && pattern[j] != ']' {
				if pattern[j] == '\\' {
					j++
					if j >= len(pattern) {
						return false
					}
				}
				j++
			}
			// j == start is an empty class, which is a typo rather than a
			// class that matches nothing: nobody writes one deliberately.
			if j >= len(pattern) || j == start {
				return false
			}
			i = j + 1
		default:
			i++
		}
	}
	return true
}

// Filter returns the elements of names matching pattern, in their original
// order, using [Match].
//
// The result is never nil, so a caller can range and len it with no guard.
func Filter(pattern string, names []string) []string {
	out := []string{}
	if !Valid(pattern) {
		return out
	}
	for _, n := range names {
		if matchBytes(pattern, n) {
			out = append(out, n)
		}
	}
	return out
}

// FilterPath is [Filter] with [MatchPath] semantics.
func FilterPath(pattern string, names []string) []string {
	out := []string{}
	if !Valid(pattern) {
		return out
	}
	psegs := splitPattern(pattern)
	for _, n := range names {
		if matchSegments(psegs, splitName(n)) {
			out = append(out, n)
		}
	}
	return out
}

// Any reports whether name matches at least one of patterns, using [Match].
//
// An invalid entry is skipped rather than failing the whole list: one typo in
// an allowlist should cost that rule and no other.
func Any(patterns []string, name string) bool {
	for _, p := range patterns {
		if Match(p, name) {
			return true
		}
	}
	return false
}

// AnyPath is [Any] with [MatchPath] semantics. This is the allowlist
// primitive: a list of rules, a subject, one boolean.
func AnyPath(patterns []string, name string) bool {
	for _, p := range patterns {
		if MatchPath(p, name) {
			return true
		}
	}
	return false
}

// matchBytes is the matcher proper, over a pattern already known valid.
//
// It walks both strings forward and remembers exactly one position: the most
// recent `*` and how much of name it had consumed when it was reached. On a
// mismatch it returns there and hands that star one more byte. That single
// backtrack point is what keeps the whole thing O(len(pattern)*len(name)) in
// time and O(1) in space, where the recursive formulation branches at every
// star and goes exponential.
//
// It is correct precisely because every other pattern element consumes exactly
// one byte: a later star can always absorb whatever an earlier one gives back,
// so there is never a reason to reconsider any star but the last.
func matchBytes(pattern, name string) bool {
	px, nx := 0, 0
	starPx, starNx := -1, -1

	for nx < len(name) {
		if px < len(pattern) {
			if pattern[px] == '*' {
				// Record the star and try to match the rest with it
				// consuming nothing. Consecutive stars collapse naturally:
				// the last one simply overwrites the mark.
				starPx, starNx = px, nx
				px++
				continue
			}
			if ok, next := matchOne(pattern, px, name[nx]); ok {
				px = next
				nx++
				continue
			}
		}
		if starPx < 0 {
			return false
		}
		starNx++
		px, nx = starPx+1, starNx
	}

	// name is exhausted; the pattern may only have stars left.
	for px < len(pattern) && pattern[px] == '*' {
		px++
	}
	return px == len(pattern)
}

// matchOne reports whether the single-byte pattern element at px matches b,
// and returns the index just past that element.
//
// The pattern is already known valid, which is why this can index past px
// without checking: Valid has established that an escape has a byte after it
// and a class has its closing bracket.
func matchOne(pattern string, px int, b byte) (bool, int) {
	switch pattern[px] {
	case '?':
		return true, px + 1
	case '\\':
		return pattern[px+1] == b, px + 2
	case '[':
		return matchClass(pattern, px, b)
	default:
		return pattern[px] == b, px + 1
	}
}

// matchClass evaluates the bracket expression starting at px against b and
// returns the index just past its closing bracket.
//
// There is no POSIX leading-`]` rule: a `]` inside a class is written `\]`.
// One way to say it beats two, and the one that survives is the one that also
// works for `-` and `\`.
func matchClass(pattern string, px int, b byte) (bool, int) {
	i := px + 1
	negated := false
	if pattern[i] == '!' || pattern[i] == '^' {
		negated = true
		i++
	}

	found := false
	for pattern[i] != ']' {
		lo := pattern[i]
		if lo == '\\' {
			i++
			lo = pattern[i]
		}
		i++

		// A '-' is a range only with something other than ']' after it, which
		// is what makes [a-] and [-a] literal dashes rather than errors.
		hi := lo
		if pattern[i] == '-' && pattern[i+1] != ']' {
			i++
			hi = pattern[i]
			if hi == '\\' {
				i++
				hi = pattern[i]
			}
			i++
		}

		if lo <= b && b <= hi {
			found = true
		}
	}
	return found != negated, i + 1
}

// splitName splits a subject on [Separator]. A name carries no pattern syntax,
// so there is nothing to protect and a plain split is right.
func splitName(name string) []string {
	return strings.Split(name, string(Separator))
}

// splitPattern splits a pattern on every [Separator] that is not escaped and
// not inside a character class.
//
// A plain strings.Split is wrong here, and wrong by aborting rather than by
// answering: it cuts `a\/b` into `a\` and `b`, handing matchBytes a segment
// whose trailing backslash has nothing after it, and `[/]` into `[` and `]`,
// handing matchClass a bracket with no closing one. Both then index past the
// end of the piece they were given, out of a Render that cannot be redeployed.
// Splitting with the escape and the class in mind keeps every pattern element
// whole, so each segment is itself a valid pattern.
//
// The resulting segment can still never match, since a name segment cannot
// contain a separator. That is the correct answer and this returns it.
func splitPattern(pattern string) []string {
	segs := []string{}
	start := 0
	inClass := false
	for i := 0; i < len(pattern); i++ {
		switch pattern[i] {
		case '\\':
			// Valid has established there is a byte after it.
			i++
		case '[':
			inClass = true
		case ']':
			inClass = false
		case Separator:
			if inClass {
				continue
			}
			segs = append(segs, pattern[start:i])
			start = i + 1
		}
	}
	return append(segs, pattern[start:])
}

// matchSegments is matchBytes one level up: the same single-backtrack walk,
// with `**` for the star and a whole segment for the byte.
//
// Writing it twice rather than generalising is the cheaper of the two: the
// element test differs (a byte equality against a glob call), the alphabet
// differs, and the shared version would take a comparison function and be
// longer than both. What the duplication buys is that the zero-segment case,
// `a/**/b` matching `a/b`, falls out of the algorithm instead of needing the
// special case a segment-by-segment walk requires.
func matchSegments(psegs, nsegs []string) bool {
	pi, ni := 0, 0
	starPi, starNi := -1, -1

	for ni < len(nsegs) {
		if pi < len(psegs) {
			if psegs[pi] == "**" {
				starPi, starNi = pi, ni
				pi++
				continue
			}
			if matchBytes(psegs[pi], nsegs[ni]) {
				pi++
				ni++
				continue
			}
		}
		if starPi < 0 {
			return false
		}
		starNi++
		pi, ni = starPi+1, starNi
	}

	for pi < len(psegs) && psegs[pi] == "**" {
		pi++
	}
	return pi == len(psegs)
}

