// Package ringbuffer is a fixed-capacity FIFO that overwrites its oldest entry
// when full, as a pure, reusable package.
//
// This is the bounded cousin of an unbounded queue, and the bound is the point:
// on chain an unbounded queue is an unbounded storage bill, whereas a ring
// buffer's cost is decided once, at construction. It is the right shape for
// "last N events", "recent messages", or any rolling window.
//
// Backed by a flat slice with head/length indices — no per-element allocation,
// no shifting on Pop.
//
// A live demo of this package is at
// [r/moul/x/daily/ringbufferdemo](/r/moul/x/daily/ringbufferdemo/v0).
package ringbuffer

// MaxCap bounds a buffer so allocation stays predictable.
const MaxCap = 4096

// RingBuffer is a fixed-capacity FIFO of strings.
type RingBuffer struct {
	buf  []string
	head int // index of the oldest element
	n    int // number of live elements
}

// New returns an empty buffer of the given capacity, clamped to [0, MaxCap].
func New(capacity int) *RingBuffer {
	if capacity < 0 {
		capacity = 0
	}
	if capacity > MaxCap {
		capacity = MaxCap
	}
	return &RingBuffer{buf: make([]string, capacity)}
}

// Cap returns the capacity.
func (r *RingBuffer) Cap() int { return len(r.buf) }

// Len returns how many elements are live.
func (r *RingBuffer) Len() int { return r.n }

// Full reports whether the next Push will overwrite.
func (r *RingBuffer) Full() bool { return len(r.buf) > 0 && r.n == len(r.buf) }

// Empty reports whether there is nothing to read.
func (r *RingBuffer) Empty() bool { return r.n == 0 }

// Push appends v. When the buffer is full the OLDEST element is dropped to make
// room, and that element is returned with dropped=true — losing data silently
// is the one thing a rolling window must not do.
//
// A zero-capacity buffer accepts nothing and reports the value straight back.
func (r *RingBuffer) Push(v string) (evicted string, dropped bool) {
	if len(r.buf) == 0 {
		return v, true
	}
	if r.n == len(r.buf) {
		evicted = r.buf[r.head]
		r.buf[r.head] = v
		r.head = (r.head + 1) % len(r.buf)
		return evicted, true
	}
	r.buf[(r.head+r.n)%len(r.buf)] = v
	r.n++
	return "", false
}

// Pop removes and returns the oldest element; ok is false when empty.
func (r *RingBuffer) Pop() (v string, ok bool) {
	if r.n == 0 {
		return "", false
	}
	v = r.buf[r.head]
	r.buf[r.head] = "" // release the reference; don't pin a string we no longer own
	r.head = (r.head + 1) % len(r.buf)
	r.n--
	return v, true
}

// Peek returns the oldest element without removing it.
func (r *RingBuffer) Peek() (v string, ok bool) {
	if r.n == 0 {
		return "", false
	}
	return r.buf[r.head], true
}

// At returns the i-th element counting from the oldest (0 = oldest).
func (r *RingBuffer) At(i int) (v string, ok bool) {
	if i < 0 || i >= r.n {
		return "", false
	}
	return r.buf[(r.head+i)%len(r.buf)], true
}

// Slice returns the live elements oldest-first, as an independent copy.
func (r *RingBuffer) Slice() []string {
	out := make([]string, 0, r.n)
	for i := 0; i < r.n; i++ {
		out = append(out, r.buf[(r.head+i)%len(r.buf)])
	}
	return out
}

// Reset empties the buffer, releasing every stored reference.
func (r *RingBuffer) Reset() {
	for i := range r.buf {
		r.buf[i] = ""
	}
	r.head, r.n = 0, 0
}

// Package rle implements run-length encoding as a pure, reusable package: runs
// of a repeated byte collapse to a count and the byte.
//
// The encoding is `<count><char>` with counts in decimal, e.g. "aaabbc" →
// "3a2b1c". Every run is emitted with its count, including runs of one — a
// uniform grammar is cheaper to decode and impossible to get subtly wrong,
// at the cost of expanding data that has no runs at all. RLE is a *win only on
// runny data*; Encode can legitimately produce output longer than its input,
// and the demo shows exactly that case rather than hiding it.
//
// Digits cannot appear in the input, since they would be indistinguishable from
// a count on the way back; Encode rejects them rather than round-tripping wrong.
//
// A live demo of this package is at
// [r/moul/x/daily/rledemo](/r/moul/x/daily/rledemo/v0).
package rle

import (
	"errors"
	"strconv"
	"strings"
)

// MaxLen bounds input so encode/decode gas stays predictable.
const MaxLen = 4096

var (
	// ErrTooLong is returned when input exceeds MaxLen.
	ErrTooLong = errors.New("rle: input too long")
	// ErrDigit is returned when input contains a digit, which would be
	// ambiguous with a run count.
	ErrDigit = errors.New("rle: input must not contain digits")
	// ErrMalformed is returned when decoding input that is not <count><char>.
	ErrMalformed = errors.New("rle: malformed input")
)

// Encode collapses runs of repeated bytes into <count><char> pairs.
func Encode(s string) (string, error) {
	if len(s) > MaxLen {
		return "", ErrTooLong
	}
	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			return "", ErrDigit
		}
	}
	if s == "" {
		return "", nil
	}
	var b strings.Builder
	run := 1
	for i := 1; i <= len(s); i++ {
		if i < len(s) && s[i] == s[i-1] {
			run++
			continue
		}
		b.WriteString(strconv.Itoa(run))
		b.WriteByte(s[i-1])
		run = 1
	}
	return b.String(), nil
}

// Decode expands <count><char> pairs back into the original string.
func Decode(s string) (string, error) {
	if len(s) > MaxLen {
		return "", ErrTooLong
	}
	var b strings.Builder
	i := 0
	for i < len(s) {
		j := i
		for j < len(s) && s[j] >= '0' && s[j] <= '9' {
			j++
		}
		if j == i || j == len(s) { // no count, or a count with no character
			return "", ErrMalformed
		}
		n, err := strconv.Atoi(s[i:j])
		if err != nil || n <= 0 {
			return "", ErrMalformed
		}
		if b.Len()+n > MaxLen {
			return "", ErrTooLong // a short input can decode to an enormous one
		}
		b.WriteString(strings.Repeat(string(s[j]), n))
		i = j + 1
	}
	return b.String(), nil
}

// Ratio returns len(encoded)/len(original) as a percentage, rounded down.
// Over 100 means the encoding made the data BIGGER, which is the honest
// outcome for input without runs.
func Ratio(original, encoded string) int {
	if len(original) == 0 {
		return 0
	}
	return len(encoded) * 100 / len(original)
}

