func TestString(t *testing.T) {
	g := FromPairs([][2]string{{"app", "lib"}, {"app", "core"}})
	uassert.Equal(t, "app <- core, lib\ncore\nlib\n", g.String())
}

// A wide diamond: both middles are ready at once and must come out sorted.
func TestDiamond(t *testing.T) {
	g := FromPairs([][2]string{
		{"top", "left"},
		{"top", "right"},
		{"left", "base"},
		{"right", "base"},
	})
	uassert.Equal(t, "base,left,right,top", order(t, g))
}

// Package trie is a prefix tree (trie) for autocomplete, as a pure, reusable
// package: insert words, then ask for every word sharing a prefix.
//
// Everything is deterministic and allocation-friendly so it runs reproducibly
// on-chain: no maps in the hot path (map iteration order is unspecified, which
// would make Render output vary), no clocks, no chain imports. Children are
// kept in a slice sorted by rune, so completions always come out in
// lexicographic order — the same input always yields the same output.
//
// A live demo of this package (a gnoweb autocomplete box) is at
// [r/moul/x/daily/triedemo](/r/moul/x/daily/triedemo/v0).
package trie

import "sort"

// MaxWordLen bounds a single word so insertion gas stays predictable.
const MaxWordLen = 64

// node is one position in the tree. Children are ordered by Key so walks are
// deterministic; `terminal` marks the end of an inserted word (so "car" can be
// a word even when "carpet" is also stored).
type node struct {
	key      rune
	terminal bool
	children []*node
}

// Trie is a prefix tree. The zero value is an empty, ready-to-use Trie.
type Trie struct {
	root  node
	count int
}

// New returns an empty Trie.
func New() *Trie { return &Trie{} }

// Len returns how many distinct words the Trie holds.
func (t *Trie) Len() int { return t.count }

// child finds n's child for rune r, or nil. The slice is sorted, so this is a
// binary search.
func (n *node) child(r rune) *node {
	i := sort.Search(len(n.children), func(i int) bool { return n.children[i].key >= r })
	if i < len(n.children) && n.children[i].key == r {
		return n.children[i]
	}
	return nil
}

// addChild inserts a child for rune r, keeping children sorted by key.
func (n *node) addChild(r rune) *node {
	i := sort.Search(len(n.children), func(i int) bool { return n.children[i].key >= r })
	if i < len(n.children) && n.children[i].key == r {
		return n.children[i]
	}
	c := &node{key: r}
	n.children = append(n.children, nil)
	copy(n.children[i+1:], n.children[i:])
	n.children[i] = c
	return c
}

// Insert adds word to the Trie and reports whether it was newly added.
// The empty string and words longer than MaxWordLen are rejected (false).
// Inserting the same word twice is a no-op.
func (t *Trie) Insert(word string) bool {
	rs := []rune(word)
	if len(rs) == 0 || len(rs) > MaxWordLen {
		return false
	}
	n := &t.root
	for _, r := range rs {
		n = n.addChild(r)
	}
	if n.terminal {
		return false
	}
	n.terminal = true
	t.count++
	return true
}

// Contains reports whether word was inserted as a complete word. A stored
// "carpet" does not make "car" Contains-true — only Insert does.
func (t *Trie) Contains(word string) bool {
	n := t.find(word)
	return n != nil && n.terminal
}

// HasPrefix reports whether any stored word starts with prefix. The empty
// prefix matches whenever the Trie is non-empty.
func (t *Trie) HasPrefix(prefix string) bool {
	if prefix == "" {
		return t.count > 0
	}
	return t.find(prefix) != nil
}

// find walks to the node for s, or returns nil when the path is absent.
func (t *Trie) find(s string) *node {
	n := &t.root
	for _, r := range s {
		n = n.child(r)
		if n == nil {
			return nil
		}
	}
	return n
}

// Complete returns up to limit words starting with prefix, in lexicographic
// order. A limit <= 0 means "no cap". An absent prefix yields an empty slice
// (never nil), so callers can range over the result unconditionally.
//
// The empty prefix lists the whole Trie, which is what makes this usable as a
// plain sorted listing too.
func (t *Trie) Complete(prefix string, limit int) []string {
	out := []string{}
	start := t.find(prefix)
	if start == nil {
		return out
	}
	collect(start, []rune(prefix), &out, limit)
	return out
}

// collect appends every word under n (depth-first, children already sorted)
// to *out, stopping once limit is reached.
func collect(n *node, path []rune, out *[]string, limit int) {
	if limit > 0 && len(*out) >= limit {
		return
	}
	if n.terminal {
		*out = append(*out, string(path))
	}
	for _, c := range n.children {
		if limit > 0 && len(*out) >= limit {
			return
		}
		collect(c, append(path, c.key), out, limit)
	}
}

// Words returns every stored word in lexicographic order.
func (t *Trie) Words() []string { return t.Complete("", 0) }

// FromWords builds a Trie from words, skipping any the Trie rejects.
func FromWords(words []string) *Trie {
	t := New()
	for _, w := range words {
		t.Insert(w)
	}
	return t
}

package trie

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestInsertAndContains(t *testing.T) {
	cases := []struct {
		name     string
		word     string
		wantOK   bool
		contains bool
	}{
		{"plain word", "car", true, true},
		{"empty rejected", "", false, false},
		{"too long rejected", strings.Repeat("a", MaxWordLen+1), false, false},
		{"exactly max accepted", strings.Repeat("b", MaxWordLen), true, true},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			tr := New()
			uassert.Equal(t, c.wantOK, tr.Insert(c.word))
			uassert.Equal(t, c.contains, tr.Contains(c.word))
		})
	}
}

func TestInsertIsIdempotent(t *testing.T) {
	tr := New()
	uassert.True(t, tr.Insert("gno"))
	uassert.False(t, tr.Insert("gno"))
	uassert.Equal(t, 1, tr.Len())
}

// A prefix of a stored word is not itself a word until inserted.
func TestPrefixIsNotAWord(t *testing.T) {
	tr := FromWords([]string{"carpet"})
	uassert.False(t, tr.Contains("car"))
	uassert.True(t, tr.HasPrefix("car"))
	uassert.True(t, tr.Contains("carpet"))
}

func TestCompleteIsLexicographic(t *testing.T) {
	// deliberately inserted out of order
	tr := FromWords([]string{"carpet", "car", "cat", "dog", "cart"})
	got := tr.Complete("car", 0)
	want := []string{"car", "carpet", "cart"}
	uassert.Equal(t, strings.Join(want, ","), strings.Join(got, ","))
}

func TestCompleteLimit(t *testing.T) {
	tr := FromWords([]string{"a", "ab", "abc", "abcd"})
	uassert.Equal(t, 2, len(tr.Complete("a", 2)))
	uassert.Equal(t, 4, len(tr.Complete("a", 0)))
	uassert.Equal(t, 4, len(tr.Complete("a", -1)))
}

func TestCompleteUnknownPrefixIsEmptyNotNil(t *testing.T) {
	tr := FromWords([]string{"gno"})
	got := tr.Complete("zzz", 0)
	uassert.Equal(t, 0, len(got))
	// must be safe to range over / join without a nil check
	uassert.Equal(t, "", strings.Join(got, ","))
}

func TestEmptyPrefixListsEverything(t *testing.T) {
	tr := FromWords([]string{"beta", "alpha", "gamma"})
	uassert.Equal(t, "alpha,beta,gamma", strings.Join(tr.Words(), ","))
	uassert.True(t, tr.HasPrefix(""))
	uassert.False(t, New().HasPrefix(""))
}

func TestUnicode(t *testing.T) {
	tr := FromWords([]string{"éclair", "école", "zèbre"})
	uassert.Equal(t, "éclair,école", strings.Join(tr.Complete("é", 0), ","))
	uassert.True(t, tr.Contains("zèbre"))
}

// Children are kept sorted on insert, so output order never depends on
// insertion order — the property that keeps Render deterministic on-chain.
func TestOrderIndependentOfInsertionOrder(t *testing.T) {
	a := FromWords([]string{"delta", "alpha", "charlie", "bravo"})
	b := FromWords([]string{"bravo", "charlie", "alpha", "delta"})
	uassert.Equal(t, strings.Join(a.Words(), ","), strings.Join(b.Words(), ","))
}

package varint

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// Append takes and returns a byte slice rather than a string, so packing a
// sequence reuses one buffer instead of copying the whole prefix per value.
// A string accumulator makes PutUvarints quadratic in the encoded size, which
// on chain is gas a caller pays to produce a result they already had.
func TestAppendReusesOneBuffer(t *testing.T) {
	buf := make([]byte, 0, 32)
	buf = AppendUvarint(buf, 300)
	buf = AppendVarint(buf, -1)
	buf = AppendUvarint(buf, 16384)
	uassert.Equal(t, "ac020180 8001"[0:0]+hex(string(buf)), "ac0201808001")

	// The same bytes the one-shot helpers produce, so the two cannot diverge.
	uassert.Equal(t, PutUvarint(300)+PutVarint(-1)+PutUvarint(16384), string(buf))
}

func TestSequenceHelpersMatchAppend(t *testing.T) {
	xs := []uint64{0, 1, 127, 128, 300, maxUint64}
	buf := []byte{}
	for _, x := range xs {
		buf = AppendUvarint(buf, x)
	}
	uassert.Equal(t, string(buf), PutUvarints(xs))

	ys := []int64{0, -1, 1, minInt64, maxInt64}
	sbuf := []byte{}
	for _, y := range ys {
		sbuf = AppendVarint(sbuf, y)
	}
	uassert.Equal(t, string(sbuf), PutVarints(ys))
}

// Package varint implements LEB128 / protobuf-style variable-length integers
// over strings, with one deliberate restriction: it only accepts the canonical
// encoding of a value.
//
// A varint stores an integer in base 128, least significant group first. Each
// byte carries seven payload bits and a continuation bit in the high position,
// so values below 128 cost one byte, below 16384 two, and a full uint64 at most
// ten. Signed values go through zigzag first, which interleaves positives and
// negatives so that small magnitudes of either sign stay short.
//
// Live demo: [r/moul/x/daily/varintdemo](/r/moul/x/daily/varintdemo/v0).
package varint

import "errors"

// MaxLen is the longest canonical encoding of a uint64: ten groups of seven
// bits covers 70 bits, which is the first multiple of seven past 64.
const MaxLen = 10

var (
	// ErrTruncated is returned when the input ends inside a varint, meaning
	// the last byte read still had its continuation bit set.
	ErrTruncated = errors.New("varint: truncated")
	// ErrOverflow is returned when the encoded value does not fit in 64 bits.
	ErrOverflow = errors.New("varint: value overflows uint64")
	// ErrNotCanonical is returned for an encoding that is longer than it needs
	// to be, such as a value padded with trailing continuation groups.
	ErrNotCanonical = errors.New("varint: non-canonical encoding")
	// ErrTrailing is returned by the all-at-once decoders when bytes remain
	// after the last complete value.
	ErrTrailing = errors.New("varint: trailing bytes")
)

// PutUvarint returns the canonical encoding of x.
func PutUvarint(x uint64) string {
	return string(AppendUvarint(make([]byte, 0, MaxLen), x))
}

// AppendUvarint appends the encoding of x to dst and returns the extended
// slice, the same shape as Go's encoding/binary.
//
// It takes a byte slice and not a string on purpose: a string accumulator
// copies the whole prefix on every append, which makes packing a sequence
// quadratic in the encoded size. On chain that is gas paid to rebuild bytes
// the caller already had.
func AppendUvarint(dst []byte, x uint64) []byte {
	for x >= 0x80 {
		dst = append(dst, byte(x)|0x80)
		x >>= 7
	}
	return append(dst, byte(x))
}

// PutVarint returns the canonical encoding of x, zigzagged first.
func PutVarint(x int64) string {
	return PutUvarint(ZigZag(x))
}

// AppendVarint appends the zigzagged encoding of x to dst.
func AppendVarint(dst []byte, x int64) []byte {
	return AppendUvarint(dst, ZigZag(x))
}

// Len reports how many bytes PutUvarint(x) would produce, without encoding it.
func Len(x uint64) int {
	n := 1
	for x >= 0x80 {
		x >>= 7
		n++
	}
	return n
}

// LenVarint reports how many bytes PutVarint(x) would produce.
func LenVarint(x int64) int {
	return Len(ZigZag(x))
}

// Uvarint decodes the varint at the start of s and reports how many bytes it
// consumed. The rest of s is ignored, so a stream is read by reslicing.
func Uvarint(s string) (uint64, int, error) {
	var x uint64
	var shift uint
	for i := 0; i < len(s); i++ {
		b := s[i]
		if i == MaxLen-1 {
			// The tenth group may only carry the single bit left over from
			// 63; anything above that, continuation included, overflows.
			if b > 1 {
				return 0, 0, ErrOverflow
			}
		}
		x |= uint64(b&0x7f) << shift
		if b < 0x80 {
			if i > 0 && b == 0 {
				// A zero final group means the value was padded: the same
				// number has a shorter encoding, so this one is not canonical.
				return 0, 0, ErrNotCanonical
			}
			return x, i + 1, nil
		}
		shift += 7
	}
	return 0, 0, ErrTruncated
}

// Varint decodes the zigzagged varint at the start of s.
func Varint(s string) (int64, int, error) {
	u, n, err := Uvarint(s)
	if err != nil {
		return 0, 0, err
	}
	return UnZigZag(u), n, nil
}

// ZigZag maps a signed value onto an unsigned one so that small magnitudes of
// either sign stay small: 0, -1, 1, -2, 2 become 0, 1, 2, 3, 4.
func ZigZag(x int64) uint64 {
	return uint64(x<<1) ^ uint64(x>>63)
}

// UnZigZag is the inverse of [ZigZag].
func UnZigZag(u uint64) int64 {
	return int64(u>>1) ^ -int64(u&1)
}

// PutUvarints encodes every value in xs back to back, into one buffer.
func PutUvarints(xs []uint64) string {
	buf := make([]byte, 0, len(xs)+1)
	for _, x := range xs {
		buf = AppendUvarint(buf, x)
	}
	return string(buf)
}

// Uvarints decodes a string that is nothing but varints. It fails rather than
// returning a partial result: a trailing fragment is corruption, not a value.
func Uvarints(s string) ([]uint64, error) {
	out := []uint64{}
	for len(s) > 0 {
		x, n, err := Uvarint(s)
		if err != nil {
			if err == ErrTruncated {
				return nil, ErrTrailing
			}
			return nil, err
		}
		out = append(out, x)
		s = s[n:]
	}
	return out, nil
}

// PutVarints encodes every value in xs back to back, zigzagged, into one
// buffer.
func PutVarints(xs []int64) string {
	buf := make([]byte, 0, len(xs)+1)
	for _, x := range xs {
		buf = AppendVarint(buf, x)
	}
	return string(buf)
}

// Varints decodes a string that is nothing but zigzagged varints.
func Varints(s string) ([]int64, error) {
	us, err := Uvarints(s)
	if err != nil {
		return nil, err
	}
	out := make([]int64, len(us))
	for i, u := range us {
		out[i] = UnZigZag(u)
	}
	return out, nil
}

package varint

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

const (
	minInt64  = -1 << 63
	maxInt64  = 1<<63 - 1
	maxUint64 = 1<<64 - 1
)

// hex renders a byte string as lowercase hex, so a failing vector prints the
// bytes rather than mojibake.
func hex(s string) string {
	const digits = "0123456789abcdef"
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		b.WriteByte(digits[s[i]>>4])
		b.WriteByte(digits[s[i]&0x0f])
	}
	return b.String()
}

// The protobuf base-128 vectors, one per group boundary plus the documented
// 300 example and the full 64-bit maximum.
func TestUvarintVectors(t *testing.T) {
	cases := []struct {
		in   uint64
		want string
	}{
		{0, "00"},
		{1, "01"},
		{127, "7f"},
		{128, "8001"},
		{300, "ac02"},
		{16383, "ff7f"},
		{16384, "808001"},
		{maxUint64, "ffffffffffffffffff01"},
	}
	for _, c := range cases {
		got := PutUvarint(c.in)
		uassert.Equal(t, c.want, hex(got))

		back, n, err := Uvarint(got)
		uassert.NoError(t, err)
		uassert.Equal(t, c.in, back)
		uassert.Equal(t, len(got), n)
	}
}

func TestLenAgreesWithEncoding(t *testing.T) {
	for _, x := range []uint64{0, 1, 127, 128, 16383, 16384, 2097151, 2097152, maxUint64} {
		uassert.Equal(t, len(PutUvarint(x)), Len(x))
	}
	// The boundary is what the groups are for: one byte up to 127.
	uassert.Equal(t, 1, Len(127))
	uassert.Equal(t, 2, Len(128))
	uassert.Equal(t, MaxLen, Len(maxUint64))
}

func TestZigZagVectors(t *testing.T) {
	cases := []struct {
		in   int64
		want uint64
	}{
		{0, 0},
		{-1, 1},
		{1, 2},
		{-2, 3},
		{2, 4},
		{maxInt64, maxUint64 - 1},
		{minInt64, maxUint64},
	}
	for _, c := range cases {
		uassert.Equal(t, c.want, ZigZag(c.in))
		uassert.Equal(t, c.in, UnZigZag(c.want))
	}
}

func TestVarintRoundTrip(t *testing.T) {
	for _, x := range []int64{0, -1, 1, -64, 63, -1000000, 1000000, minInt64, maxInt64} {
		enc := PutVarint(x)
		uassert.Equal(t, len(enc), LenVarint(x))

		back, n, err := Varint(enc)
		uassert.NoError(t, err)
		uassert.Equal(t, x, back)
		uassert.Equal(t, len(enc), n)
	}
}

// Zigzag is the whole reason signed values are not encoded directly: -1 as a
// two's complement uint64 is ten bytes, as a zigzag it is one.
func TestZigZagKeepsSmallNegativesShort(t *testing.T) {
	uassert.Equal(t, 1, LenVarint(-1))
	uassert.Equal(t, 1, LenVarint(-64))
	uassert.Equal(t, 2, LenVarint(-65))
	uassert.Equal(t, MaxLen, Len(uint64(0xffffffffffffffff))) // the same -1, unzigzagged
}

func TestRejectsNonCanonical(t *testing.T) {
	cases := []struct {
		name, in string
	}{
		{"zero padded once", "\x80\x00"},
		{"one padded once", "\x81\x00"},
		{"zero padded thrice", "\x80\x80\x80\x00"},
		{"full width padding", "\xff\xff\xff\xff\xff\xff\xff\xff\xff\x00"},
	}
	for _, c := range cases {
		_, _, err := Uvarint(c.in)
		uassert.ErrorIs(t, err, ErrNotCanonical)
	}
	// A single zero byte is canonical: it is the only encoding of 0.
	x, n, err := Uvarint("\x00")
	uassert.NoError(t, err)
	uassert.Equal(t, uint64(0), x)
	uassert.Equal(t, 1, n)
}

func TestRejectsTruncated(t *testing.T) {
	for _, s := range []string{"", "\x80", "\xff\xff", strings.Repeat("\xff", 9)} {
		_, _, err := Uvarint(s)
		uassert.ErrorIs(t, err, ErrTruncated)
	}
}

func TestRejectsOverflow(t *testing.T) {
	// Ten groups carry 70 bits; the tenth may only hold the one bit left of 64.
	_, _, err := Uvarint(strings.Repeat("\xff", 9) + "\x02")
	uassert.ErrorIs(t, err, ErrOverflow)

	// An eleventh group is unreachable, so it reads as overflow too.
	_, _, err = Uvarint(strings.Repeat("\xff", 10) + "\x01")
	uassert.ErrorIs(t, err, ErrOverflow)

	// Exactly at the limit is fine.
	x, n, err := Uvarint(strings.Repeat("\xff", 9) + "\x01")
	uassert.NoError(t, err)
	uassert.Equal(t, uint64(maxUint64), x)
	uassert.Equal(t, MaxLen, n)
}

func TestUvarintReadsOnlyItsOwnPrefix(t *testing.T) {
	s := PutUvarint(300) + PutUvarint(1) + "leftover"
	x, n, err := Uvarint(s)
	uassert.NoError(t, err)
	uassert.Equal(t, uint64(300), x)
	uassert.Equal(t, 2, n)

	x, n, err = Uvarint(s[n:])
	uassert.NoError(t, err)
	uassert.Equal(t, uint64(1), x)
	uassert.Equal(t, 1, n)
}

func TestSequences(t *testing.T) {
	in := []uint64{0, 1, 127, 128, 300, maxUint64}
	enc := PutUvarints(in)
	uassert.Equal(t, 1+1+1+2+2+10, len(enc))

	out, err := Uvarints(enc)
	uassert.NoError(t, err)
	uassert.Equal(t, len(in), len(out))
	for i := range in {
		uassert.Equal(t, in[i], out[i])
	}

	signed := []int64{0, -1, 1, minInt64, maxInt64}
	back, err := Varints(PutVarints(signed))
	uassert.NoError(t, err)
	uassert.Equal(t, len(signed), len(back))
	for i := range signed {
		uassert.Equal(t, signed[i], back[i])
	}
}

// A partial value at the end is corruption, and returning the values read so
// far would hand a caller a silently short list.
func TestSequenceRefusesTrailingFragment(t *testing.T) {
	_, err := Uvarints(PutUvarint(300) + "\x80")
	uassert.ErrorIs(t, err, ErrTrailing)

	_, err = Varints(PutVarint(-5) + "\xff")
	uassert.ErrorIs(t, err, ErrTrailing)

	out, err := Uvarints("")
	uassert.NoError(t, err)
	uassert.Equal(t, 0, len(out))
}

func TestAppendBuildsInPlace(t *testing.T) {
	var buf []byte
	buf = AppendUvarint(buf, 300)
	buf = AppendVarint(buf, -1)
	uassert.Equal(t, "ac0201", hex(string(buf)))
}

// Package envelope reads and forwards the coins a transaction attached to a
// call: the `-send` field of a `MsgCall`, credited to the called realm's address
// before a line of its code runs.
//
// It exists because "payable" is not a keyword in gno, it is a runtime fact. The
// VM rejects a `MsgCall` that carried coins the callee never looked at
// (gno.land/pkg/sdk/vm/keeper.go, `if !send.IsZero() && !*OriginSendObserved`),
// and reading the envelope is what counts as looking. So every realm that
// accepts payment writes the same three things by hand: read the amount, abort
// with something the caller can act on when it is zero or the wrong denom, and
// forward or keep it. This package is those three things.
//
// # Native coins are push-only, which is why this matters
//
// A realm cannot pull a native coin. `banker.SendCoins` panics unless the
// `from` address is the banker's own realm address, so there is no allowance
// and no `TransferFrom` for a native denom. The envelope is the entire inbound
// path: either the holder signs a bank send, or they attach coins to a call and
// the callee reads them here.
//
// That is also why a GRC20 needs `Approve` and a native coin does not. The GRC20
// grants standing authority to a spender; the envelope grants authority over one
// message and expires with it.
//
// # Who may forward, which is not about depth
//
// [Forward] mints a `BankerTypeOriginSend` banker, and `NewBanker` accepts that
// type only when `rlm.Previous().IsUserCall()` holds. `Realm.IsUserCall` is
// literally `pkgPath == ""` (gnovm/stdlibs/chain/runtime/frame.gno), so the test
// is about WHO entered the realm, not about how deep inside it you are:
//
//   - `maketx call` straight into the realm: fine, and the realm may pass its
//     `cur` down through as many of its own helpers as it likes. Measured at
//     three nested calls, and through a function value and a closure.
//   - realm A calls realm B, and B tries to forward: refused. B's previous is a
//     code realm, so the envelope it was handed is not B's to route.
//   - `maketx run`: refused. The run package is a code realm
//     (`<domain>/e/<addr>/run`), so `IsUserCall` is false there too, and every
//     payable function is therefore unreachable from a run script.
//
// The reading helpers have none of these conditions: they go through
// `unsafe.OriginSend()`, a context read that works anywhere, including inside a
// `Render`.
//
package envelope

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
)

// Amount returns how much of denom this message's envelope carried, and zero
// when it carried none. Reading it is what makes the call payable.
func Amount(denom string) int64 {
	return unsafe.OriginSend().AmountOf(denom)
}

// All returns the whole envelope, every denom in it.
//
// A call can be paid in several denoms at once, which is a property of the bank
// rather than of any realm: a `Coins` set holds up to 256 of them. A realm that
// only wants one should use [Only].
func All() chain.Coins {
	return unsafe.OriginSend()
}

// IsEmpty reports whether nothing was attached to this call.
func IsEmpty() bool {
	return len(unsafe.OriginSend()) == 0
}

// Require returns [Amount] and aborts when it is zero, with a message naming the
// flag the caller left out.
//
// The message is the point. "insufficient funds" sends somebody to their wallet;
// naming the denom and the flag sends them to the fix.
func Require(denom string) int64 {
	amount := Amount(denom)
	if amount <= 0 {
		panic("this call must be paid: attach coins with -send <amount>" + denom)
	}
	return amount
}

// RequireAtLeast is [Require] with a floor, and names both numbers when the
// envelope falls short.
func RequireAtLeast(denom string, min int64) int64 {
	amount := Require(denom)
	if amount < min {
		panic(ufmt.Sprintf("this call costs at least %d%s, the envelope carried %d",
			min, denom, amount))
	}
	return amount
}

// RequireExactly is [Require] for a fixed price, and refuses an overpayment as
// well as an underpayment.
//
// Refusing to be overpaid is the unusual half, and it is deliberate: a realm
// that silently keeps the excess has invented a fee nobody agreed to, and a
// realm that refunds it has to move coins back out, which is a second failure
// mode. Aborting costs the caller one transaction and nothing else.
func RequireExactly(denom string, price int64) int64 {
	amount := Require(denom)
	if amount != price {
		panic(ufmt.Sprintf("this call costs exactly %d%s, the envelope carried %d",
			price, denom, amount))
	}
	return amount
}

// Only is [Require] plus a refusal of anything else in the envelope.
//
// Use it wherever the realm has no code that would ever move a second denom,
// because coins it does not handle are coins stranded at its address forever:
// they are not refunded, and only the realm's own code can ever send them on.
func Only(denom string) int64 {
	amount := Require(denom)
	for _, coin := range unsafe.OriginSend() {
		if coin.Denom != denom {
			panic(ufmt.Sprintf("this call takes %s only, the envelope also carried %d%s",
				denom, coin.Amount, coin.Denom))
		}
	}
	return amount
}

// Forward sends coins from the calling realm's address to `to`, bounded by this
// message's envelope.
//
// The banker it mints can spend the envelope and nothing else: not the realm's
// own balance, not a previous message's payment. That is what makes a routing
// function safe to write, and it is enforced by the VM rather than by the code
// here (`ctx.OriginSend.IsAllGTE(spent)`).
//
// It must be reached from a call a USER made into this realm; see the package
// doc for what that rules out.
//
// The leading `_ int` is not decoration: a non-realm package may not declare a
// crossing function, so a `p/` helper that needs a realm handle threads it as a
// later parameter. That is the same shape `p/nt/grc20`'s tellers use, and gno
// refuses the file outright without it ("crossing function (realm first
// argument) declared in non-realm package").
//
// This function has no test in this package either, for the same reason it has
// that signature: minting the banker calls `rlm.Previous()`, and a `p/` test has
// no realm frame to walk ("frame not found: cannot seek beyond origin caller
// override"). It is exercised from `r/moul/x/nativeify`'s tests instead.
func Forward(_ int, rlm realm, to address, coins chain.Coins) {
	banker.NewBanker(banker.BankerTypeOriginSend, rlm).SendCoins(rlm.Address(), to, coins)
}

// ForwardAll forwards everything the envelope carried of denom, and returns it.
// It aborts when the envelope carried none, like [Require].
func ForwardAll(_ int, rlm realm, to address, denom string) int64 {
	amount := Require(denom)
	Forward(0, rlm, to, chain.NewCoins(chain.NewCoin(denom, amount)))
	return amount
}

// BalanceOf returns what addr holds of denom right now, straight from the bank.
//
// It takes an address rather than a realm handle because it needs no authority
// at all: a readonly banker is constructible from anywhere, including a Render.
// Pass `cur.Address()` for the realm's own balance, envelope included.
func BalanceOf(addr address, denom string) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, denom)
}

package envelope

import (
	"chain"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

const (
	coin  = "/gno.land/r/moul/x/moultest/v0:moultest"
	other = "ugnot"
)

func pay(coins ...chain.Coin) {
	testing.SetOriginSend(chain.NewCoins(coins...))
}

func TestReadsAnEmptyEnvelope(cur realm, t *testing.T) {
	pay()
	uassert.True(t, IsEmpty())
	uassert.Equal(t, int64(0), Amount(coin))
	uassert.Equal(t, 0, len(All()))
