// Package framelab probes, at runtime, which realm frame pure-package code
// executes in when a realm forwards its own `cur` into it.
//
// The whole instance-per-realm ("factory") pattern rests on the answer: if a
// p/ helper acting on `cur` binds to the *importing realm's* identity, then a
// 20-line instance realm can hold state and funds while every line of logic
// lives in one shared pure package. If instead the frame shifts, the pattern
// is dead and each instance has to carry its own copy of the logic.
package framelab

import "gno.land/p/nt/grc20/v0"

// The leading `_ int` is mandatory, not cosmetic: gno rejects a function whose
// FIRST parameter is `realm` when it is declared in a pure package ("crossing
// function declared in non-realm package"). Same reason grc20's Teller methods
// are shaped `Transfer(_ int, rlm realm, ...)`. The name matters too: only the
// first realm argument of a real crossing function may be called `cur`.
//
// Who reports the frame identity as seen from inside pure-package code.
func Who(_ int, rlm realm) (pkgPath string, addr address, isCurrent bool) {
	return rlm.PkgPath(), rlm.Address(), rlm.IsCurrent()
}

// Pull performs the operation the pattern actually needs: a GRC20 pull done by
// pure-package code, under the importing realm's identity. It returns the
// address the teller bound to, which is the claim under test.
func Pull(_ int, rlm realm, tok *grc20.Token, from address, amount int64) address {
	self := rlm.Address()
	err := tok.RealmTeller(0, rlm).TransferFrom(0, rlm, from, self, amount)
	if err != nil {
		panic(err)
	}
	return self
}

// Package accrual is stock that fills at a rate while nobody is playing: the
// resource field of an idle game, the warehouse of a 4X, anything whose state
// is a function of how long it has been left alone.
//
// The shape is always the same. Store what you had and when, and compute the
// rest on demand; a player who does nothing for a month costs nothing, and the
// realm needs no cron, no keeper and no per-block hook. That much is obvious.
// What is not obvious is that the obvious implementation is wrong in three
// ways, each of which has been observed in this repository rather than
// reasoned about.
//
// # 1. Re-anchoring to now makes acting more often pay
//
// Written naively, a claim advances the anchor to now and computes
// elapsed/Period whole periods of production. The division truncates, so every
// claim silently forfeits the part-period it lands in, and a player who claims
// twice forfeits twice. Run in reverse on a decaying stat it is worse than
// unfair, it is free: [r/moul/x/daily/tamagotchi] decayed by elapsed/2 and
// elapsed/3, so at elapsed == 1 it decayed by nothing at all, and feeding once
// per block made the pet immortal while every other cadence died inside 240
// blocks. It was fixed in #221.
//
// The invariant that rules it out is worth stating on its own, because it is
// the whole contract of this package:
//
//	Advance(s, a, c) == Advance(Advance(s, a, b), b, c)   for a <= b <= c
//
// How often you call must not change where you end up. [Rate.Advance] gets
// there by advancing the anchor only by the WHOLE periods it paid for, leaving
// the remainder on the clock rather than throwing it away. TestSplitInvariant
// asserts it over pseudo-random partitions rather than over a handful of
// hand-picked spans, because the hand-picked spans are exactly the ones a
// wrong implementation already passes.
//
// # 2. A view that does not share the write path's arithmetic drifts from it
//
// The same realm had a second copy of the decay for its Render, so the page
// showed a pet the next call would not honour. Two implementations of one rule
// means one of them is the stale one somebody acts on. Here there is one
// function: [Rate.At] is [Rate.Advance] with the anchor discarded, so a view
// cannot disagree with a write even in principle.
//
// # 3. A projection that is not closed form cannot be rendered at all
//
// Render runs under a query gas limit and may not write, so whatever it
// computes has to be bounded however long the player was away. Anything
// iterative, stepping a simulation once per block, is fine in a transaction
// and unusable in a page: the player who comes back after a month is exactly
// the one whose page times out. Everything here is O(1) in elapsed time, which
// is the property that makes a live-updating page possible, not an
// optimisation.
//
// Times are int64 and the unit is the caller's, block heights or unix seconds,
// as long as it is consistent. Prefer a timestamp: a block-height rate drifts
// in wall-clock terms every time the chain's block time moves, and gno.land's
// has moved from about 4.1s to 3.405s inside one month. Nothing here reads the
// chain, so a realm can test a year of its own economy without one.
//
// A game built on this package is at
// [r/moul/x/games/idle](/r/moul/x/games/idle/v0).
//
// [r/moul/x/daily/tamagotchi]: /r/moul/x/daily/tamagotchi/v0
package accrual

import "errors"

const maxInt64 = int64(9223372036854775807)

var (
	// ErrBadAmount is returned when the amount produced per period is not
	// positive. A zero rate is a bug in the caller, not a valid still life:
	// it makes Full unanswerable and every Advance a no-op.
	ErrBadAmount = errors.New("accrual: amount must be positive")
	// ErrBadPeriod is returned when the period is not positive.
	ErrBadPeriod = errors.New("accrual: period must be positive")
	// ErrBadCap is returned when the cap is negative. Zero is legal and
	// means unbounded.
	ErrBadCap = errors.New("accrual: cap must not be negative")
	// ErrNegativeStock is returned when the stock handed in is negative,
	// which would let a caller mint by going through zero.
	ErrNegativeStock = errors.New("accrual: stock must not be negative")
	// ErrBackwards is returned when now falls before the anchor. Time moving
	// backwards is a caller bug (a stored anchor from another clock, a test
	// that rewound), and silently treating it as zero elapsed would hide it.
	ErrBackwards = errors.New("accrual: now must not fall before the anchor")
	// ErrOverflow is returned when the arithmetic would wrap int64.
	ErrOverflow = errors.New("accrual: int64 overflow")
)

// Rate is production per unit of time, against a ceiling. Construct with New
// so the invariants are checked once instead of on every call.
type Rate struct {
	Amount int64 // produced each whole Period
	Period int64 // time units in one period
	Cap    int64 // ceiling on the stock; zero means unbounded
}

// New validates and returns a Rate. A zero cap means unbounded.
func New(amount, period, capacity int64) (Rate, error) {
	if amount <= 0 {
		return Rate{}, ErrBadAmount
	}
	if period <= 0 {
		return Rate{}, ErrBadPeriod
	}
	if capacity < 0 {
		return Rate{}, ErrBadCap
	}
	return Rate{Amount: amount, Period: period, Cap: capacity}, nil
}

// Advance returns the stock and the new anchor at time now, given stock held
// since anchor.
//
// The new anchor is NOT now. It is the anchor plus the whole periods actually
// paid out, so the part-period in progress stays on the clock and splitting a
// span into pieces yields exactly what advancing it in one go would:
//
//	Advance(s, a, c) == Advance(Advance(s, a, b), b, c)   for a <= b <= c
//
// Production past the cap is lost, which is what a cap is for. Saturation is
// idempotent, so it does not break the equality above, and it means a CAPPED
// rate can never return ErrOverflow: the answer is the cap however long the
// player was away. Only an uncapped rate can run out of int64.
func (r Rate) Advance(stock, anchor, now int64) (int64, int64, error) {
	if err := r.check(); err != nil {
		return 0, 0, err
	}
	if stock < 0 {
		return 0, 0, ErrNegativeStock
	}
	if now < anchor {
		return 0, 0, ErrBackwards
	}
	// now-anchor wraps only when the anchor is negative and now is far
	// enough above it. maxInt64+anchor is safe to compute precisely because
	// anchor is negative there.
	if anchor < 0 && now > maxInt64+anchor {
		return 0, 0, ErrOverflow
	}

	periods := (now - anchor) / r.Period

	// The anchor only moves by what was paid for. periods*r.Period cannot
	// overflow, it is at most now-anchor, and adding it back cannot pass now.
	newAnchor := anchor + periods*r.Period

	if r.Cap > 0 && stock >= r.Cap {
		return stock, newAnchor, nil
	}

	// Production is only computed when its exact value can matter. A capped
	// rate whose payout would wrap int64 has an answer regardless of what
	// that payout is, so it gets one instead of an error.
	if periods > maxInt64/r.Amount {
		return r.saturate(newAnchor)
	}
	produced := periods * r.Amount
	if produced > maxInt64-stock {
		return r.saturate(newAnchor)
	}

	total := stock + produced
	if r.Cap > 0 && total > r.Cap {
		total = r.Cap
	}
	return total, newAnchor, nil
}

// saturate answers an accrual too large for int64: the cap if there is one,
// and an error if there is not. A capped Rate therefore never overflows,
// which is the property that lets a realm size a warehouse without also
// having to bound its own lifetime.
func (r Rate) saturate(newAnchor int64) (int64, int64, error) {
	if r.Cap == 0 {
		return 0, 0, ErrOverflow
	}
	return r.Cap, newAnchor, nil
}

// At is Advance with the anchor discarded: the read-only view of the same
// arithmetic, for a Render that must not write. It is defined in terms of
// Advance on purpose, so a page can never show a number a write would not
// honour.
func (r Rate) At(stock, anchor, now int64) (int64, error) {
	got, _, err := r.Advance(stock, anchor, now)
	return got, err
}

// Full returns the time at which the stock first reaches the cap, for a realm
// that wants to tell a player when their production starts being wasted.
//
// An uncapped rate returns zero, meaning never. A stock already at or past the
// cap returns the anchor, meaning now.
func (r Rate) Full(stock, anchor int64) (int64, error) {
	if err := r.check(); err != nil {
		return 0, err
	}
	if stock < 0 {
		return 0, ErrNegativeStock
	}
	if r.Cap == 0 {
		return 0, nil
	}
	if stock >= r.Cap {
		return anchor, nil
	}

	// Whole periods needed to cover the shortfall, rounded UP: the cap is
	// reached by the payout that crosses it, not by the one before.
	need := r.Cap - stock
	periods := need / r.Amount
	if need%r.Amount != 0 {
		periods++
	}
	if periods > maxInt64/r.Period {
		return 0, ErrOverflow
	}
	span := periods * r.Period
	if span > maxInt64-anchor {
		return 0, ErrOverflow
	}
	return anchor + span, nil
}

// check rejects a zero Rate built by struct literal instead of New, so a
// caller that skipped the constructor gets the same error it would have.
func (r Rate) check() error {
	if r.Amount <= 0 {
		return ErrBadAmount
	}
	if r.Period <= 0 {
		return ErrBadPeriod
	}
	if r.Cap < 0 {
		return ErrBadCap
	}
	return nil
}

package accrual

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func mustNew(t *testing.T, amount, period, capacity int64) Rate {
	t.Helper()
	r, err := New(amount, period, capacity)
	uassert.NoError(t, err)
	return r
}

func TestNewValidation(t *testing.T) {
	cases := []struct {
		name                     string
		amount, period, capacity int64
		want                     error
	}{
		{"zero amount", 0, 60, 100, ErrBadAmount},
		{"negative amount", -1, 60, 100, ErrBadAmount},
		{"zero period", 1, 0, 100, ErrBadPeriod},
		{"negative period", 1, -60, 100, ErrBadPeriod},
		{"negative cap", 1, 60, -1, ErrBadCap},
		{"zero cap is unbounded", 1, 60, 0, nil},
		{"all positive", 5, 60, 100, nil},
	}
	for _, tc := range cases {
		_, err := New(tc.amount, tc.period, tc.capacity)
		if tc.want == nil {
			uassert.NoError(t, err, tc.name)
			continue
		}
		uassert.ErrorIs(t, err, tc.want, tc.name)
	}
}

func TestAdvance(t *testing.T) {
	cases := []struct {
		name                     string
		amount, period, capacity int64
		stock, anchor, now       int64
		wantStock, wantAnchor    int64
	}{
		{"nothing elapsed", 1, 60, 0, 0, 1000, 1000, 0, 1000},
		{"less than one period", 1, 60, 0, 0, 1000, 1059, 0, 1000},
		{"exactly one period", 1, 60, 0, 0, 1000, 1060, 1, 1060},
		{"one period and change keeps the change", 1, 60, 0, 0, 1000, 1119, 1, 1060},
		{"ten periods", 3, 60, 0, 0, 1000, 1600, 30, 1600},
		{"adds to what was held", 3, 60, 0, 7, 1000, 1600, 37, 1600},
		{"saturates at the cap", 1, 60, 10, 0, 1000, 9000, 10, 8980},
		{"already full produces nothing", 1, 60, 10, 10, 1000, 9000, 10, 8980},
		{"over the cap is left alone", 1, 60, 10, 25, 1000, 9000, 25, 8980},
		{"uncapped keeps going", 1, 60, 0, 0, 0, 604800, 10080, 604800},
	}
	for _, tc := range cases {
		r := mustNew(t, tc.amount, tc.period, tc.capacity)
		gotStock, gotAnchor, err := r.Advance(tc.stock, tc.anchor, tc.now)
		uassert.NoError(t, err, tc.name)
		uassert.Equal(t, tc.wantStock, gotStock, tc.name+": stock")
		uassert.Equal(t, tc.wantAnchor, gotAnchor, tc.name+": anchor")
	}
}

// TestAnchorKeepsTheRemainder pins the one decision the whole package rests
// on: the new anchor is not now. Advancing to a time halfway through a period
// leaves that half on the clock, which is what makes splitting free.
func TestAnchorKeepsTheRemainder(t *testing.T) {
	r := mustNew(t, 1, 60, 0)
	_, anchor, err := r.Advance(0, 0, 599)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(540), anchor, "anchor must stop at the last whole period, not at now")
}

// TestSplitInvariant is the contract of this package:
//
//	Advance(s, a, c) == Advance(Advance(s, a, b), b, c)
//
// It runs over pseudo-random partitions rather than hand-picked ones, because
// an implementation that re-anchors to now passes every round span and only
// fails on the ones that land mid-period. The generator is a fixed LCG, so a
// failure is reproducible.
func TestSplitInvariant(t *testing.T) {
	rates := []Rate{
		mustNew(t, 1, 60, 0),      // one a minute, unbounded
		mustNew(t, 7, 13, 0),      // coprime, so remainders never line up
		mustNew(t, 1, 60, 500),    // capped
		mustNew(t, 250, 3600, 0),  // coarse period
		mustNew(t, 1, 1, 0),       // degenerate: every tick pays
		mustNew(t, 3, 1000, 1234), // capped and coarse
	}

	seed := uint64(0x9E3779B97F4A7C15)
	next := func(n int64) int64 {
		seed = seed*6364136223846793005 + 1442695040888963407
		return int64(seed>>33) % n
	}

	for _, r := range rates {
		for i := 0; i < 400; i++ {
			start := next(10000)
			span := next(100000)
			stock := next(600)
			end := start + span

			wantStock, wantAnchor, err := r.Advance(stock, start, end)
			uassert.NoError(t, err)

			// Cut the span into between one and six pieces and walk them.
			cuts := next(6) + 1
			gotStock, gotAnchor := stock, start
			at := start
			for c := int64(0); c < cuts; c++ {
				remaining := end - at
				if remaining <= 0 {
					break
				}
				step := next(remaining + 1)
				if c == cuts-1 {
					step = remaining
				}
				at += step
				gotStock, gotAnchor, err = r.Advance(gotStock, gotAnchor, at)
				uassert.NoError(t, err)
			}
			// Land on the end whatever the cuts did.
			gotStock, gotAnchor, err = r.Advance(gotStock, gotAnchor, end)
			uassert.NoError(t, err)

			uassert.Equal(t, wantStock, gotStock, "split stock diverged")
			uassert.Equal(t, wantAnchor, gotAnchor, "split anchor diverged")
		}
	}
}

// TestClaimingEveryTickIsNotFree is the regression for the bug this package
// exists to make unrepresentable. r/moul/x/daily/tamagotchi truncated its
// per-call decay, so acting every tick cost nothing and acting rarely cost
// everything. Here the two agree exactly.
func TestClaimingEveryTickIsNotFree(t *testing.T) {
	r := mustNew(t, 1, 60, 0)
	const span = 6000 // 100 whole periods

	oneShot, _, err := r.Advance(0, 0, span)
	uassert.NoError(t, err)

	for _, cadence := range []int64{1, 2, 7, 60, 61, 599, 3000} {
		stock, anchor := int64(0), int64(0)
		for at := cadence; at <= span; at += cadence {
			stock, anchor, err = r.Advance(stock, anchor, at)
			uassert.NoError(t, err)
		}
		stock, _, err = r.Advance(stock, anchor, span)
		uassert.NoError(t, err)
		uassert.Equal(t, oneShot, stock, "cadence changed the payout")
	}
}

// TestAtMatchesAdvance pins that the read path cannot drift from the write
// path, which was the second and quieter half of the tamagotchi bug.
func TestAtMatchesAdvance(t *testing.T) {
	r := mustNew(t, 5, 17, 900)
	for now := int64(3); now < 4000; now += 37 {
		want, _, err := r.Advance(11, 3, now)
		uassert.NoError(t, err)
		got, err := r.At(11, 3, now)
		uassert.NoError(t, err)
		uassert.Equal(t, want, got, "At diverged from Advance")
	}
}

func TestAdvanceRejects(t *testing.T) {
	r := mustNew(t, 1, 60, 0)

	_, _, err := r.Advance(-1, 0, 100)
	uassert.ErrorIs(t, err, ErrNegativeStock)

	_, _, err = r.Advance(0, 100, 99)
	uassert.ErrorIs(t, err, ErrBackwards)

	// A Rate built by literal instead of New is still checked.
	_, _, err = Rate{}.Advance(0, 0, 100)
	uassert.ErrorIs(t, err, ErrBadAmount)
	_, _, err = Rate{Amount: 1}.Advance(0, 0, 100)
	uassert.ErrorIs(t, err, ErrBadPeriod)
	_, _, err = Rate{Amount: 1, Period: 1, Cap: -1}.Advance(0, 0, 100)
	uassert.ErrorIs(t, err, ErrBadCap)
}

func TestAdvanceOverflow(t *testing.T) {
	// An uncapped rate that would pass int64 refuses rather than wrapping
	// into a negative stock, which is how a large vesting grant once
	// reported a negative balance.
	r := mustNew(t, maxInt64/2, 1, 0)
	_, _, err := r.Advance(0, 0, 100)
	uassert.ErrorIs(t, err, ErrOverflow)

	// The same rate with a cap always has an answer, so it gives one
	// instead of an error, whichever of the two guards it trips.
	capped := mustNew(t, maxInt64/2, 1, 1000)
	got, anchor, err := capped.Advance(0, 0, 100)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(1000), got)
	uassert.Equal(t, int64(100), anchor, "a saturated advance still moves the anchor")

	got, _, err = capped.Advance(999, 0, 1)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(1000), got, "the sum guard saturates too")

	// A negative anchor far enough below now wraps the elapsed span itself.
	slow := mustNew(t, 1, maxInt64, 0)
	_, _, err = slow.Advance(0, -10, maxInt64-5)
	uassert.ErrorIs(t, err, ErrOverflow)
}

func TestFull(t *testing.T) {
	cases := []struct {
		name                     string
		amount, period, capacity int64
		stock, anchor            int64
		want                     int64
	}{
		{"uncapped never fills", 1, 60, 0, 0, 1000, 0},
		{"already full is now", 1, 60, 10, 10, 1000, 1000},
		{"past full is now", 1, 60, 10, 99, 1000, 1000},
		{"empty takes the whole cap", 1, 60, 10, 0, 1000, 1600},
		{"partly full takes the rest", 1, 60, 10, 4, 1000, 1360},
		{"rounds up to the payout that crosses", 3, 60, 10, 0, 0, 240},
		{"exact division does not round up", 5, 60, 10, 0, 0, 120},
	}
	for _, tc := range cases {
		r := mustNew(t, tc.amount, tc.period, tc.capacity)
		got, err := r.Full(tc.stock, tc.anchor)
		uassert.NoError(t, err, tc.name)
		uassert.Equal(t, tc.want, got, tc.name)
	}
}

// TestFullAgreesWithAdvance checks the two halves of the API against each
// other: at the time Full names, the stock is at the cap, and one period
// earlier it is not.
func TestFullAgreesWithAdvance(t *testing.T) {
	for _, r := range []Rate{
		mustNew(t, 1, 60, 10),
		mustNew(t, 3, 60, 10),
		mustNew(t, 7, 13, 1000),
		mustNew(t, 250, 3600, 875),
	} {
		full, err := r.Full(0, 0)
		uassert.NoError(t, err)

		atFull, err := r.At(0, 0, full)
		uassert.NoError(t, err)
		uassert.Equal(t, r.Cap, atFull, "not full at the time Full named")

		before, err := r.At(0, 0, full-r.Period)
		uassert.NoError(t, err)
		if before >= r.Cap {
			t.Errorf("already full a period early: %d >= %d", before, r.Cap)
		}
	}
}

func TestFullRejects(t *testing.T) {
	r := mustNew(t, 1, 60, 10)
	_, err := r.Full(-1, 0)
	uassert.ErrorIs(t, err, ErrNegativeStock)

	_, err = Rate{}.Full(0, 0)
	uassert.ErrorIs(t, err, ErrBadAmount)

	far := mustNew(t, 1, maxInt64/2, 1000)
	_, err = far.Full(0, 0)
	uassert.ErrorIs(t, err, ErrOverflow)
}

// Package clock is a deadline that actions push forward, with the two guards a
// naive "extend on every action" clock lacks.
//
// Any last-action-wins game has the same clock: every action buys more time, so
// the game ends only when nobody acts. Written naively it has two failure modes,
// and both have been observed on chain rather than reasoned about.
//
// The first is that it never ends. If the grant per action is constant, a
// contested pot is extended forever and the prize is always worth one more
// action. Life is the terminator: an absolute end, fixed when the clock opens,
// that no bump can pass. A game with real money in it needs one.
//
// The second is the opposite, and it shows up as soon as the grant decays to
// relieve the pressure of the first: a grant that is a share of the life left
// shrinks toward zero near the end, so the last stretch becomes too short for a
// transaction to land in, and whoever is holding when that happens simply wins.
// Floor is the anti-snipe: a bump always leaves at least that much on the
// clock, however little is left to share.
//
// Times are int64 and the unit is the caller's: block heights or unix seconds,
// as long as it is consistent. Nothing here reads the chain, so a realm can
// test its whole endgame without one.
//
// A game built on this package is at
// [r/moul/x/games/lastwords](/r/moul/x/games/lastwords/v0).
package clock

import "errors"

const maxInt64 = int64(9223372036854775807)

var (
	// ErrBadWindow is returned when the opening grant is not positive.
	ErrBadWindow = errors.New("clock: window must be positive")
	// ErrBadFloor is returned when the floor is negative or exceeds the window.
	ErrBadFloor = errors.New("clock: floor must be between zero and the window")
	// ErrBadLife is returned when the life is negative, or positive but shorter
	// than the opening window, which would close the clock before it opened.
	ErrBadLife = errors.New("clock: life must be zero (unbounded) or at least the window")
	// ErrBadShare is returned when a share is outside 0..100.
	ErrBadShare = errors.New("clock: share must be a percentage between 0 and 100")
	// ErrUnbounded is returned when a share of the remaining life is asked of a
	// clock that has no hard end to measure against.
	ErrUnbounded = errors.New("clock: a share of the life needs a bounded clock")
	// ErrOverflow is returned when the requested times do not fit in an int64.
	ErrOverflow = errors.New("clock: times overflow int64")
)

// Clock is a deadline plus the three bounds that make it terminate: the window
// a bump grants, the floor a bump always leaves, and the life it can never pass.
//
// The zero Clock is not usable; build one with New.
type Clock struct {
	start    int64
	deadline int64
	window   int64
	floor    int64
	life     int64 // 0 means unbounded
}

// New opens a clock at now, due now+window.
//
// window is what a plain Bump grants. floor is the minimum a bump leaves on the
// clock, and must not exceed the window (a floor above the window would mean
// every bump granting more than the window, which is not a floor). life is the
// total lifetime from now, after which the deadline can no longer move; zero
// leaves the clock unbounded, which is the shape that never terminates, so pass
// it deliberately.
func New(now, window, floor, life int64) (*Clock, error) {
	if window <= 0 {
		return nil, ErrBadWindow
	}
	if floor < 0 || floor > window {
		return nil, ErrBadFloor
	}
	if life < 0 || (life > 0 && life < window) {
		return nil, ErrBadLife
	}
	if window > maxInt64-now || life > maxInt64-now {
		return nil, ErrOverflow
	}
	return &Clock{
		start:    now,
		deadline: now + window,
		window:   window,
		floor:    floor,
		life:     life,
	}, nil
}

// Start returns when the clock opened.
func (c *Clock) Start() int64 { return c.start }

// Deadline returns the time the clock currently expires at.
func (c *Clock) Deadline() int64 { return c.deadline }

// Window returns the grant a plain Bump aims for.
func (c *Clock) Window() int64 { return c.window }

// Floor returns the minimum a bump leaves on the clock.
func (c *Clock) Floor() int64 { return c.floor }

// Life returns the configured lifetime, zero when unbounded.
func (c *Clock) Life() int64 { return c.life }

// HardEnd returns the time no bump can push the deadline past, or zero when the
// clock is unbounded.
func (c *Clock) HardEnd() int64 {
	if c.life == 0 {
		return 0
	}
	return c.start + c.life
}

// Expired reports whether the clock has run out at now. The deadline itself is
// past it: a clock due at 100 is expired at 100, so an action and an expiry can
// never both be valid at the same instant.
func (c *Clock) Expired(now int64) bool { return now >= c.deadline }

// Remaining returns how much time is left at now, never negative.
func (c *Clock) Remaining(now int64) int64 {
	if now >= c.deadline {
		return 0
	}
	return c.deadline - now
}

// Elapsed returns how long the clock has been open at now, never negative.
func (c *Clock) Elapsed(now int64) int64 {
	if now <= c.start {
		return 0
	}
	return now - c.start
}

// Final reports whether the deadline has reached the hard end, so no further
// bump can move it. A game should say so on its page: it is the only moment at
// which holding is worth more than acting.
func (c *Clock) Final() bool { return c.life > 0 && c.deadline >= c.HardEnd() }

// Bump extends the deadline by the window. See BumpBy for the guards.
func (c *Clock) Bump(now int64) int64 { return c.BumpBy(now, c.window) }

// BumpBy extends the deadline to now+grant and returns the new deadline.
//
// The caller owns the policy, so grant is whatever it wants: a constant, a share
// of what is left, a function of the amount paid. The clock owns the four
// invariants that policy keeps getting wrong:
//
//   - An expired clock never restarts. Once it has run out the deadline is
//     frozen, so a late action cannot reopen a settled game.
//   - The deadline never moves backwards. A small grant late in the game leaves
//     the existing deadline alone rather than shortening it.
//   - A bump always leaves at least the floor on the clock, so a decaying grant
//     cannot be shaved below the time a transaction needs to land.
//   - The deadline never passes the hard end.
func (c *Clock) BumpBy(now, grant int64) int64 {
	if c.Expired(now) {
		return c.deadline
	}
	if grant < c.floor {
		grant = c.floor
	}
	want := c.deadline
	if grant <= maxInt64-now && now+grant > want {
		want = now + grant
	} else if grant > maxInt64-now {
		want = maxInt64
	}
	if end := c.HardEnd(); c.life > 0 && want > end {
		want = end
	}
	c.deadline = want
	return c.deadline
}

// BumpShare grants pct percent of the time left until the hard end, and is the
// decaying grant a converging game wants.
//
// A grant that is a share of what is left on the DEADLINE cannot extend
// anything: now+(deadline-now)*pct/100 is always before the deadline itself. A
// share of the distance to the hard end is the one that works. Each action
// closes a fraction of the gap, so the deadline crawls toward the hard end and
// the grants shrink as it does, which is exactly the "the pot is worth one more
// action" pressure a fixed grant never relieves. The floor is what stops the
// tail of that curve from becoming too short to act in.
//
// It requires a bounded clock: there is no distance to share without one.
func (c *Clock) BumpShare(now, pct int64) (int64, error) {
	if c.life == 0 {
		return c.deadline, ErrUnbounded
	}
	if pct < 0 || pct > 100 {
		return c.deadline, ErrBadShare
	}
	left := c.HardEnd() - now
	if left < 0 {
		left = 0
	}
	var grant int64
	if left > maxInt64/100 {
		grant = left / 100 * pct // lossy, but only where exactness is meaningless
	} else {
		grant = left * pct / 100 // multiply first, so a small gap still grants
	}
	return c.BumpBy(now, grant), nil
}

package clock

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func mustNew(t *testing.T, now, window, floor, life int64) *Clock {
	t.Helper()
	c, err := New(now, window, floor, life)
	uassert.NoError(t, err)
	return c
}

func TestNewValidation(t *testing.T) {
	cases := []struct {
		name                     string
		now, window, floor, life int64
		want                     error
	}{
		{"zero window", 0, 0, 0, 0, ErrBadWindow},
		{"negative window", 0, -1, 0, 0, ErrBadWindow},
		{"negative floor", 0, 100, -1, 0, ErrBadFloor},
		{"floor above window", 0, 100, 101, 0, ErrBadFloor},
		{"negative life", 0, 100, 10, -1, ErrBadLife},
		{"life shorter than window", 0, 100, 10, 99, ErrBadLife},
		{"window overflows", maxInt64 - 5, 100, 0, 0, ErrOverflow},
		{"life overflows", maxInt64 - 500, 100, 0, 1000, ErrOverflow},
		{"unbounded is legal", 0, 100, 10, 0, nil},
		{"life equal to window is legal", 0, 100, 10, 100, nil},
		{"floor equal to window is legal", 0, 100, 100, 0, nil},
	}
	for _, tc := range cases {
		_, err := New(tc.now, tc.window, tc.floor, tc.life)
		if tc.want == nil {
			uassert.NoError(t, err, tc.name)
			continue
		}
		uassert.ErrorIs(t, err, tc.want, tc.name)
	}
}

func TestOpensDueAtWindow(t *testing.T) {
	c := mustNew(t, 1000, 100, 10, 500)
	uassert.Equal(t, int64(1000), c.Start())
	uassert.Equal(t, int64(1100), c.Deadline())
	uassert.Equal(t, int64(1500), c.HardEnd())
	uassert.Equal(t, int64(100), c.Remaining(1000))
	uassert.Equal(t, int64(0), c.Elapsed(1000))
	uassert.False(t, c.Expired(1099))
	uassert.True(t, c.Expired(1100), "the deadline itself is expired")
	uassert.False(t, c.Final())
}

func TestUnboundedHasNoHardEnd(t *testing.T) {
	c := mustNew(t, 0, 100, 0, 0)
	uassert.Equal(t, int64(0), c.HardEnd())
	uassert.False(t, c.Final(), "an unbounded clock is never final")
	c.Bump(90)
	c.Bump(180)
	uassert.Equal(t, int64(280), c.Deadline(), "nothing caps it")
}

// TestBumpNeverMovesBackwards is the invariant a caller supplying its own grant
// gets wrong first: a late, small grant must not shorten the clock.
func TestBumpNeverMovesBackwards(t *testing.T) {
	c := mustNew(t, 0, 1000, 0, 0)
	uassert.Equal(t, int64(1000), c.Deadline())

	uassert.Equal(t, int64(1000), c.BumpBy(10, 5), "now+5 is before the deadline")
	uassert.Equal(t, int64(1000), c.BumpBy(900, 0), "a zero grant leaves it alone")
	uassert.Equal(t, int64(1100), c.BumpBy(900, 200), "a grant past the deadline moves it")
}

// TestFloorSurvivesATinyGrant is the anti-snipe: whatever the policy grants, a
// bump leaves at least the floor, so the last stretch stays reachable.
func TestFloorSurvivesATinyGrant(t *testing.T) {
	c := mustNew(t, 0, 1000, 50, 0)
	c.BumpBy(990, 1)
	uassert.Equal(t, int64(1040), c.Deadline(), "1 was raised to the floor of 50")
	uassert.Equal(t, int64(50), c.Remaining(990))

	c2 := mustNew(t, 0, 1000, 50, 0)
	c2.BumpBy(990, 0)
	uassert.Equal(t, int64(50), c2.Remaining(990), "even a zero grant leaves the floor")
}

// TestHardEndCapsEveryBump is the terminator: without it a contested clock is
// extended forever and the game has no end.
func TestHardEndCapsEveryBump(t *testing.T) {
	c := mustNew(t, 0, 100, 10, 250)
	uassert.Equal(t, int64(250), c.HardEnd())

	c.BumpBy(90, 100)
	uassert.Equal(t, int64(190), c.Deadline())
	c.BumpBy(180, 100)
	uassert.Equal(t, int64(250), c.Deadline(), "capped at the hard end, not 280")
	uassert.True(t, c.Final())

	c.BumpBy(240, 1000000)
	uassert.Equal(t, int64(250), c.Deadline(), "the cap holds against any grant")
	uassert.Equal(t, int64(10), c.Remaining(240), "and it beats the floor")
}

// TestExpiredClockNeverRestarts stops a late action from reopening a settled
// game, which is the difference between a closed pot and a stolen one.
func TestExpiredClockNeverRestarts(t *testing.T) {
	c := mustNew(t, 0, 100, 10, 0)
	uassert.True(t, c.Expired(100))
	uassert.Equal(t, int64(100), c.BumpBy(100, 500), "exactly at the deadline")
	uassert.Equal(t, int64(100), c.Bump(5000), "long after")
	uassert.Equal(t, int64(0), c.Remaining(100))

	settled := mustNew(t, 0, 100, 10, 1000)
	uassert.True(t, settled.Expired(100))
	got, err := settled.BumpShare(200, 50)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(100), got, "not even a large share reopens it")
}

func TestBumpShareValidation(t *testing.T) {
	c := mustNew(t, 0, 100, 0, 500)
	_, err := c.BumpShare(10, -1)
	uassert.ErrorIs(t, err, ErrBadShare)
	_, err = c.BumpShare(10, 101)
	uassert.ErrorIs(t, err, ErrBadShare)
	uassert.Equal(t, int64(100), c.Deadline(), "a rejected share changes nothing")

	unbounded := mustNew(t, 0, 100, 0, 0)
	_, err = unbounded.BumpShare(10, 50)
	uassert.ErrorIs(t, err, ErrUnbounded, "no hard end, nothing to take a share of")
}

// TestBumpShareDecays is why the share grant exists: each action closes a
// fraction of the gap to the hard end, so the grants shrink as the game runs
// and the pressure to act one more time is relieved instead of compounding.
func TestBumpShareDecays(t *testing.T) {
	c := mustNew(t, 0, 100, 1, 1000)
	first, err := c.BumpShare(10, 50)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(505), first, "half the 990 left to the hard end")

	second, err := c.BumpShare(500, 50)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(750), second, "half of the 500 now left, a smaller grant")

	third, err := c.BumpShare(700, 50)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(850), third, "smaller again")
	uassert.True(t, third < c.HardEnd(), "it approaches the hard end without reaching it")
}

// TestBumpShareRoundingStillGrants is the multiply-first lesson: a share of a
// gap smaller than the divisor must not truncate to a zero grant.
func TestBumpShareRoundingStillGrants(t *testing.T) {
	// 52 due, 50 left to the hard end: a tenth of that is 5, and dividing
	// before multiplying would truncate it to a grant of zero.
	c := mustNew(t, 0, 52, 0, 100)
	got, err := c.BumpShare(50, 10)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(55), got, "a tenth of the 50 left is 5, not 0")
}

func TestBumpShareRespectsFloorAndCap(t *testing.T) {
	c := mustNew(t, 0, 100, 20, 150)
	got, err := c.BumpShare(95, 10) // a tenth of the 55 left is 5, floored to 20
	uassert.NoError(t, err)
	uassert.Equal(t, int64(115), got)

	got, err = c.BumpShare(110, 100) // would be 150 exactly, and never past it
	uassert.NoError(t, err)
	uassert.Equal(t, int64(150), got)
	uassert.True(t, c.Final())
}

// TestHugeGrantDoesNotWrap keeps a bump total at the extremes: a wrapped
// deadline would land in the past and settle the game instantly.
func TestHugeGrantDoesNotWrap(t *testing.T) {
	c := mustNew(t, 0, 100, 0, 0)
	uassert.Equal(t, maxInt64, c.BumpBy(50, maxInt64), "clamped, not wrapped")
	uassert.True(t, c.Deadline() > 0)

	big := mustNew(t, maxInt64/2, 1000, 0, maxInt64/4)
	got, err := big.BumpShare(maxInt64/2+1, 100)
	uassert.NoError(t, err)
	uassert.True(t, got > maxInt64/2, "a huge remaining share does not wrap")
}

func TestElapsedAndRemainingAreNeverNegative(t *testing.T) {
	c := mustNew(t, 100, 100, 0, 0)
	uassert.Equal(t, int64(0), c.Elapsed(50), "before the start")
	uassert.Equal(t, int64(100), c.Remaining(100))
	uassert.Equal(t, int64(0), c.Remaining(9999), "long past the deadline")
	uassert.Equal(t, int64(9899), c.Elapsed(9999))
}

// Package prorata splits an integer amount across weighted claimants without
// leaking or inventing a unit.
//
// Every payout in a game is this operation: a pot, a roster, and a weight each.
// Written the obvious way, `amount*weight/total` per claimant, it is wrong in
// two ways that only show up with real money in the contract. The shares are
// each rounded down, so their sum is short of the amount by up to one unit per
// claimant, and that dust either accumulates in the contract forever or gets
// handed to whoever the code happens to pay last. And `amount*weight` overflows
// an int64 long before either factor does, which turns a large payout negative.
//
// Split fixes both. It distributes by largest remainder: floor every share,
// then hand the leftover units out one at a time to the claimants whose
// truncated fraction was largest, ties going to the lower index. The result
// sums to EXACTLY the amount, every time, and the rule is deterministic, so
// every node computes the same split and a Render of it does not change between
// calls.
//
// Nothing here reads the chain and nothing holds coins: the caller owns the
// roster and the custody. A game built on this package is at
// [r/moul/x/games/lastwords](/r/moul/x/games/lastwords/v0).
package prorata

import (
	"errors"
	"sort"
)

const maxInt64 = int64(9223372036854775807)

var (
	// ErrNegativeAmount is returned when the amount to split is negative.
	ErrNegativeAmount = errors.New("prorata: amount must not be negative")
	// ErrNegativeWeight is returned when any weight is negative.
	ErrNegativeWeight = errors.New("prorata: weights must not be negative")
	// ErrNoWeight is returned when there is nobody to pay, or every weight is
	// zero. The caller must decide where the amount goes instead: silently
	// returning an empty split would strand it.
	ErrNoWeight = errors.New("prorata: total weight is zero, nothing to split across")
	// ErrOverflow is returned when the arithmetic does not fit in an int64.
	ErrOverflow = errors.New("prorata: weights overflow int64")
)

// Split divides amount across weights and returns one share per weight, in the
// same order. The shares sum to exactly amount.
//
// A zero weight is allowed and receives nothing, including no remainder unit:
// somebody with no claim is not paid dust.
func Split(amount int64, weights []int64) ([]int64, error) {
	if amount < 0 {
		return nil, ErrNegativeAmount
	}
	total, err := Total(weights)
	if err != nil {
		return nil, err
	}
	if total == 0 {
		return nil, ErrNoWeight
	}

	shares := make([]int64, len(weights))
	if amount == 0 {
		return shares, nil
	}

	// Floor each share, and keep the truncated numerator to rank by.
	rems := make([]entry, 0, len(weights))
	assigned := int64(0)
	for i, w := range weights {
		if w == 0 {
			continue
		}
		share, rem, err := divide(amount, w, total)
		if err != nil {
			return nil, err
		}
		shares[i] = share
		assigned += share
		rems = append(rems, entry{index: i, rem: rem})
	}

	// Hand the leftover out by largest remainder. There are strictly fewer
	// leftover units than claimants, so one pass over the ranking is enough.
	left := amount - assigned
	if left <= 0 {
		return shares, nil
	}
	sort.Sort(byRemainder(rems))
	for i := 0; i < len(rems) && left > 0; i++ {
		shares[rems[i].index]++
		left--
	}
	return shares, nil
}

// Share returns what one weight is owed out of amount, rounded down. It is the
// "what would I get" query, and deliberately does NOT account for the
// remainder: use Split when the shares have to add up.
func Share(amount, weight, total int64) (int64, error) {
	if amount < 0 {
		return 0, ErrNegativeAmount
	}
	if weight < 0 || total < 0 {
		return 0, ErrNegativeWeight
	}
	if total == 0 {
		return 0, ErrNoWeight
	}
	if weight > total {
		weight = total
	}
	share, _, err := divide(amount, weight, total)
	return share, err
}

// Total sums weights, refusing an int64 overflow rather than wrapping into a
// negative total that would make every share nonsense.
func Total(weights []int64) (int64, error) {
	sum := int64(0)
	for _, w := range weights {
		if w < 0 {
			return 0, ErrNegativeWeight
		}
		if w > maxInt64-sum {
			return 0, ErrOverflow
		}
		sum += w
	}
	return sum, nil
}

// divide returns amount*weight/total rounded down, plus the remainder of that
// division, without ever computing amount*weight.
//
// It splits the amount into whole multiples of total and what is left over:
// amount = q*total + r, so amount*weight/total is exactly q*weight +
// r*weight/total. The first term is exact and the second multiplies a value
// already smaller than total, which is what keeps the product in range.
func divide(amount, weight, total int64) (share, rem int64, err error) {
	q := amount / total
	r := amount % total
	if weight != 0 && q > maxInt64/weight {
		return 0, 0, ErrOverflow
	}
	whole := q * weight
	if weight != 0 && r > maxInt64/weight {
		return 0, 0, ErrOverflow
	}
	part := r * weight
	if whole > maxInt64-part/total {
		return 0, 0, ErrOverflow
	}
	return whole + part/total, part % total, nil
}

// entry is one claimant's truncated fraction, for ranking the leftover.
type entry struct {
	index int
	rem   int64
}

// byRemainder ranks by largest truncated remainder, ties by lowest index, so
// the split is identical on every node.
type byRemainder []entry

func (b byRemainder) Len() int      { return len(b) }
func (b byRemainder) Swap(i, j int) { b[i], b[j] = b[j], b[i] }
func (b byRemainder) Less(i, j int) bool {
	if b[i].rem != b[j].rem {
		return b[i].rem > b[j].rem
	}
	return b[i].index < b[j].index
}

package prorata

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func sum(xs []int64) int64 {
	t := int64(0)
	for _, x := range xs {
		t += x
	}
	return t
}

func TestSplitTable(t *testing.T) {
	cases := []struct {
		name    string
		amount  int64
		weights []int64
		want    []int64
	}{
		{"exact thirds", 99, []int64{1, 1, 1}, []int64{33, 33, 33}},
		{"one unit of dust, to the lowest index", 10, []int64{1, 1, 1}, []int64{4, 3, 3}},
		{"two units of dust", 11, []int64{1, 1, 1}, []int64{4, 4, 3}},
		{"uneven weights", 100, []int64{1, 2, 3}, []int64{17, 33, 50}},
		{"a single claimant takes it all", 7, []int64{5}, []int64{7}},
		{"zero weight is paid nothing", 10, []int64{0, 1, 1}, []int64{0, 5, 5}},
		{"zero weight is not paid dust either", 10, []int64{0, 1, 1, 1}, []int64{0, 4, 3, 3}},
		{"nothing to split", 0, []int64{3, 1}, []int64{0, 0}},
		{"amount smaller than the roster", 2, []int64{1, 1, 1, 1}, []int64{1, 1, 0, 0}},
		{"weight dominates", 1000, []int64{999, 1}, []int64{999, 1}},
	}
	for _, tc := range cases {
		got, err := Split(tc.amount, tc.weights)
		uassert.NoError(t, err, tc.name)
		uassert.Equal(t, len(tc.want), len(got), tc.name)
		for i := range tc.want {
			uassert.Equal(t, tc.want[i], got[i], tc.name)
		}
	}
}

// TestSplitAlwaysSumsToTheAmount is the whole point: a split that is short by
// dust strands coins in the realm forever, and one that is over cannot be paid.
func TestSplitAlwaysSumsToTheAmount(t *testing.T) {
	weightsets := [][]int64{
		{1, 1, 1},
		{1, 2, 3, 4, 5, 6, 7},
		{7, 0, 1},
		{100, 1},
		{3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3},
		{1},
		{999983, 17, 5},
	}
	for _, ws := range weightsets {
		for amount := int64(0); amount < 60; amount++ {
			got, err := Split(amount, ws)
			uassert.NoError(t, err)
			uassert.Equal(t, amount, sum(got), "shares must sum to the amount")
		}
		for _, amount := range []int64{1000, 123457, 999999999} {
			got, err := Split(amount, ws)
			uassert.NoError(t, err)
			uassert.Equal(t, amount, sum(got))
		}
	}
}

// TestLargestRemainderWins pins the allocation rule, so a payout cannot quietly
// change to "whoever the loop paid last".
func TestLargestRemainderWins(t *testing.T) {
	// total 10, amount 4: floors are 0,0,1,1 with remainders 4,8,2,6.
	got, err := Split(4, []int64{1, 2, 3, 4})
	uassert.NoError(t, err)
	uassert.Equal(t, int64(0), got[0], "smallest remainder, no extra unit")
	uassert.Equal(t, int64(1), got[1], "largest remainder, gets one")
	uassert.Equal(t, int64(1), got[2], "floor 1, remainder 2, gets none")
	uassert.Equal(t, int64(2), got[3], "second largest, gets the other")
	uassert.Equal(t, int64(4), sum(got))
}

func TestSplitValidation(t *testing.T) {
	_, err := Split(-1, []int64{1})
	uassert.ErrorIs(t, err, ErrNegativeAmount)

	_, err = Split(10, []int64{1, -1})
	uassert.ErrorIs(t, err, ErrNegativeWeight)

	_, err = Split(10, nil)
	uassert.ErrorIs(t, err, ErrNoWeight, "an empty roster is the caller's problem, not dust")

	_, err = Split(10, []int64{0, 0})
	uassert.ErrorIs(t, err, ErrNoWeight, "every weight zero is the same problem")
}

// TestNoOverflowOnLargePots is the second failure mode: amount*weight wraps
// negative long before either factor is anywhere near the limit.
func TestNoOverflowOnLargePots(t *testing.T) {
	// A pot of 10^18 ugnot split across weights that would overflow if
	// multiplied together first.
	pot := int64(1000000000000000000)
	got, err := Split(pot, []int64{3000000000, 1000000000})
	uassert.NoError(t, err)
	uassert.Equal(t, pot, sum(got))
	uassert.Equal(t, int64(750000000000000000), got[0])
	uassert.Equal(t, int64(250000000000000000), got[1])

	got, err = Split(maxInt64, []int64{1, 1})
	uassert.NoError(t, err)
	uassert.Equal(t, maxInt64, sum(got), "even the largest possible pot")

	_, err = Total([]int64{maxInt64, 1})
	uassert.ErrorIs(t, err, ErrOverflow, "a wrapped total makes every share nonsense")
}

func TestShare(t *testing.T) {
	got, err := Share(100, 1, 3)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(33), got, "rounded down, the remainder is Split's job")

	got, err = Share(1000000000000000000, 3000000000, 4000000000)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(750000000000000000), got)

	got, err = Share(100, 7, 3)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(100), got, "a weight above the total is clamped, never over-paid")

	_, err = Share(10, 1, 0)
	uassert.ErrorIs(t, err, ErrNoWeight)
	_, err = Share(-1, 1, 2)
	uassert.ErrorIs(t, err, ErrNegativeAmount)
	_, err = Share(10, -1, 2)
	uassert.ErrorIs(t, err, ErrNegativeWeight)
}

func TestTotal(t *testing.T) {
	got, err := Total([]int64{1, 2, 3})
	uassert.NoError(t, err)
	uassert.Equal(t, int64(6), got)

	got, err = Total(nil)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(0), got, "empty sums to zero; Split is what refuses it")
}

package grc20wrap

import (
	"math/overflow"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
)

// leg is one component of a Basket.
type leg struct {
	tok    *grc20.Token
	teller grc20.Teller
	per    int64 // units escrowed per meta unit
	held   int64 // units escrowed so far
}

// Basket issues ONE meta-token over several underlying GRC20s at fixed
// proportions. Minting a meta unit escrows every leg's `per` amount; redeeming
// hands all of them back.
//
// A two-leg basket is the interesting one: it makes a pair tradable, quotable
// and transferable as a single object, without a price oracle, an AMM or any
// notion of what the legs are worth. The basket never values anything - it only
// ever swaps a fixed bundle for a receipt and back, so it cannot be arbitraged
// or drained. What it CAN do is let the market price the bundle, which is
// exactly how an index token works.
//
// Proportions are fixed at creation. Rebalancing would mean revaluing the legs,
// which needs a price, which is a different contract.
type Basket struct {
	legs []*leg
	home address
	tok  *grc20.Token
	led  *grc20.PrivateLedger
}

// NewBasket issues a meta-token over tokens[i], escrowing parts[i] units of
// each per meta unit.
//
// Both slices must be the same length, hold at least two entries, name no token
// twice, and every part must be positive. As with NewVault, pass the owning
// realm's own cur: escrow lands at that realm's address.
func NewBasket(tokens []*grc20.Token, parts []int64, name, symbol string, decimals int, id seqid.ID, rlm realm) *Basket {
	if len(tokens) < 2 || len(tokens) != len(parts) {
		panic(ErrBadLegs)
	}
	legs := make([]*leg, 0, len(tokens))
	for i, t := range tokens {
		if t == nil {
			panic(ErrNilToken)
		}
		if parts[i] <= 0 {
			panic(ErrBadLegs)
		}
		for _, seen := range legs {
			if seen.tok.ID() == t.ID() {
				panic(ErrBadLegs)
			}
		}
		legs = append(legs, &leg{
			tok:    t,
			teller: t.RealmTeller(0, rlm),
			per:    parts[i],
		})
	}
	tok, led := grc20.NewToken(name, symbol, decimals, id, rlm)
	return &Basket{
		legs: legs,
		home: rlm.Address(),
		tok:  tok,
		led:  led,
	}
}

// Token is the meta-token this basket issues.
func (b *Basket) Token() *grc20.Token { return b.tok }

// Home is the escrow account: the host realm's address.
func (b *Basket) Home() address { return b.home }

// Legs is the number of components.
func (b *Basket) Legs() int { return len(b.legs) }

// Leg returns the i-th component: its token, the units escrowed per meta unit,
// and the units escrowed so far.
func (b *Basket) Leg(i int) (*grc20.Token, int64, int64) {
	l := b.legs[i]
	return l.tok, l.per, l.held
}

// Solvent reports whether every leg's escrow account still covers what the
// basket recorded taking in.
func (b *Basket) Solvent() bool {
	for _, l := range b.legs {
		if l.tok.BalanceOf(b.home) < l.held {
			return false
		}
	}
	return true
}

// Fuse escrows per*units of every leg from `from` and mints `units` of the meta
// token to it.
//
// `from` must have approved b.Home() on EVERY leg first. The whole basket is
// priced and checked before the first transfer, so a caller short on leg two
// gets an error with leg one untouched.
func (b *Basket) Fuse(_ int, rlm realm, from address, units int64) error {
	if units <= 0 {
		return ErrInvalidAmount
	}
	need := make([]int64, len(b.legs))
	for i, l := range b.legs {
		n, ok := overflow.Mul64(l.per, units)
		if !ok {
			return ErrOverflow
		}
		if l.tok.BalanceOf(from) < n {
			return ErrShortBalance
		}
		if l.tok.Allowance(from, b.home) < n {
			return ErrShortAllowance
		}
		need[i] = n
	}
	// Past here every leg was checked, so a failure is an invariant
	// violation and the transaction must not stand.
	for i, l := range b.legs {
		if err := l.teller.TransferFrom(0, rlm, from, b.home, need[i]); err != nil {
			panic(err)
		}
		l.held += need[i]
	}
	if err := b.led.Mint(from, units); err != nil {
		panic(err)
	}
	return nil
}

// Defuse burns `units` of the meta token held by `to` and returns every leg's
// share of the escrow to it.
func (b *Basket) Defuse(_ int, rlm realm, to address, units int64) error {
	if units <= 0 {
		return ErrInvalidAmount
	}
	give := make([]int64, len(b.legs))
	for i, l := range b.legs {
		n, ok := overflow.Mul64(l.per, units)
		if !ok {
			return ErrOverflow
		}
		if n > l.held {
			return ErrUnbacked
		}
		give[i] = n
	}
	if err := b.led.Burn(to, units); err != nil {
		return err
	}
	for i, l := range b.legs {
		l.held -= give[i]
		if err := l.teller.Transfer(0, rlm, to, give[i]); err != nil {
			panic(err)
		}
	}
	return nil
}

// Move transfers meta units between two accounts.
func (b *Basket) Move(from, to address, amount int64) error {
	if amount <= 0 {
		return ErrInvalidAmount
	}
	return b.led.Transfer(from, to, amount)
}

// Allow sets `spender`'s allowance over `owner`'s meta balance.
func (b *Basket) Allow(owner, spender address, amount int64) error {
	return b.led.Approve(owner, spender, amount)
}

// MoveFrom spends `spender`'s allowance over `owner`'s meta balance.
func (b *Basket) MoveFrom(spender, owner, to address, amount int64) error {
	if amount <= 0 {
		return ErrInvalidAmount
	}
	return b.led.TransferFrom(owner, spender, to, amount)
}

// Summary renders the basket as a markdown block.
func (b *Basket) Summary() string {
	s := ufmt.Sprintf("**%s** (%s) - meta-token over %d legs\n\n",
		b.tok.GetName(), b.tok.GetSymbol(), len(b.legs))
	s += ufmt.Sprintf("- meta supply: %d\n", b.tok.TotalSupply())
	for _, l := range b.legs {
		s += ufmt.Sprintf("- leg %s: %d per unit, %d escrowed\n",
			l.tok.GetSymbol(), l.per, l.held)
	}
	if b.Solvent() {
		s += "- solvent: yes\n"
	} else {
		s += "- solvent: **NO**\n"
	}
	return s
}

package grc20wrap

import (
	"testing"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

const (
	pairPath   = "gno.land/r/test/pair"
	basketPath = "gno.land/r/test/basket"
)

// mintPair issues two independent tokens from one foreign realm and funds the
// holders with both.
func mintPair(cur realm, t *testing.T, red, blue int64, funded ...address) (*grc20.Token, *grc20.PrivateLedger, *grc20.Token, *grc20.PrivateLedger) {
	t.Helper()
	testing.SetRealm(testing.NewCodeRealm(pairPath))
	rt, rl := grc20.NewToken("Red", "RED", 4, 0, cur)
	bt, bl := grc20.NewToken("Blue", "BLUE", 4, 1, cur)
	for _, a := range funded {
		urequire.NoError(t, rl.Mint(a, red))
		urequire.NoError(t, bl.Mint(a, blue))
	}
	return rt, rl, bt, bl
}

func TestFuseAndDefuse(cur realm, t *testing.T) {
	red, redLed, blue, blueLed := mintPair(cur, t, 1_000, 1_000, alice)

	testing.SetRealm(testing.NewCodeRealm(basketPath))
	b := NewBasket(
		[]*grc20.Token{red, blue},
		[]int64{1, 2},
		"Purple", "PURPLE", 4, 0, cur,
	)
	approve(cur, t, redLed, alice, b.Home(), 1_000)
	approve(cur, t, blueLed, alice, b.Home(), 1_000)

	urequire.NoError(t, b.Fuse(0, cur, alice, 10))
	uassert.Equal(t, int64(10), b.Token().BalanceOf(alice))
	uassert.Equal(t, int64(990), red.BalanceOf(alice))
	uassert.Equal(t, int64(980), blue.BalanceOf(alice))

	_, per, held := b.Leg(0)
	uassert.Equal(t, int64(1), per)
	uassert.Equal(t, int64(10), held)
	_, per, held = b.Leg(1)
	uassert.Equal(t, int64(2), per)
	uassert.Equal(t, int64(20), held)
	uassert.True(t, b.Solvent())

	urequire.NoError(t, b.Defuse(0, cur, alice, 4))
	uassert.Equal(t, int64(6), b.Token().TotalSupply())
	uassert.Equal(t, int64(994), red.BalanceOf(alice))
	uassert.Equal(t, int64(988), blue.BalanceOf(alice))

	// Out entirely: the basket closes empty on both legs.
	urequire.NoError(t, b.Defuse(0, cur, alice, 6))
	uassert.Equal(t, int64(0), b.Token().TotalSupply())
	_, _, held = b.Leg(0)
	uassert.Equal(t, int64(0), held)
	_, _, held = b.Leg(1)
	uassert.Equal(t, int64(0), held)
	uassert.Equal(t, int64(1_000), red.BalanceOf(alice))
	uassert.Equal(t, int64(1_000), blue.BalanceOf(alice))
}

// The whole basket is priced before the first transfer, so being short on the
// SECOND leg leaves the first one untouched. Without the pre-pass this is where
// a partially-applied mint would come from.
func TestFuseChecksEveryLegBeforeMovingAny(cur realm, t *testing.T) {
	red, redLed, blue, blueLed := mintPair(cur, t, 1_000, 10, alice)

	testing.SetRealm(testing.NewCodeRealm(basketPath))
	b := NewBasket(
		[]*grc20.Token{red, blue},
		[]int64{1, 2},
		"Purple", "PURPLE", 4, 0, cur,
	)
	approve(cur, t, redLed, alice, b.Home(), 1_000)
	approve(cur, t, blueLed, alice, b.Home(), 1_000)

	// 100 units needs 100 RED (fine) and 200 BLUE (alice has 10).
	uassert.ErrorIs(t, b.Fuse(0, cur, alice, 100), ErrShortBalance)
	uassert.Equal(t, int64(1_000), red.BalanceOf(alice))
	uassert.Equal(t, int64(0), b.Token().TotalSupply())

	// Same for a missing allowance on the second leg only.
	approve(cur, t, blueLed, alice, b.Home(), 0)
	urequire.NoError(t, blueLed.Mint(alice, 1_000))
	uassert.ErrorIs(t, b.Fuse(0, cur, alice, 5), ErrShortAllowance)
	uassert.Equal(t, int64(1_000), red.BalanceOf(alice))
	uassert.Equal(t, int64(0), b.Token().TotalSupply())
}

func TestDefuseStopsAtTheBalance(cur realm, t *testing.T) {
	red, redLed, blue, blueLed := mintPair(cur, t, 1_000, 1_000, alice, bob)

	testing.SetRealm(testing.NewCodeRealm(basketPath))
	b := NewBasket(
		[]*grc20.Token{red, blue},
		[]int64{1, 1},
		"Purple", "PURPLE", 4, 0, cur,
	)
	for _, a := range []address{alice, bob} {
		approve(cur, t, redLed, a, b.Home(), 1_000)
		approve(cur, t, blueLed, a, b.Home(), 1_000)
	}

	urequire.NoError(t, b.Fuse(0, cur, alice, 50))
	uassert.ErrorContains(t, b.Defuse(0, cur, bob, 1), "insufficient balance")
	uassert.ErrorIs(t, b.Defuse(0, cur, alice, 0), ErrInvalidAmount)
	_, _, held := b.Leg(0)
	uassert.Equal(t, int64(50), held)
}

func TestNewBasketRejectsBadLegs(cur realm, t *testing.T) {
	red, _, blue, _ := mintPair(cur, t, 1_000, 1_000)

	testing.SetRealm(testing.NewCodeRealm(basketPath))

	// A one-leg basket is a Vault; say so instead of pretending.
	uassert.PanicsContains(t, cur, "at least two legs", func() {
		NewBasket([]*grc20.Token{red}, []int64{1}, "X", "X", 4, 0, cur)
	})
	// Mismatched slices.
	uassert.PanicsContains(t, cur, "at least two legs", func() {
		NewBasket([]*grc20.Token{red, blue}, []int64{1}, "X", "X", 4, 0, cur)
	})
	// A zero part would let a leg be minted for free.
	uassert.PanicsContains(t, cur, "at least two legs", func() {
		NewBasket([]*grc20.Token{red, blue}, []int64{1, 0}, "X", "X", 4, 0, cur)
	})
	// The same token twice is two accountings of one balance.
	uassert.PanicsContains(t, cur, "at least two legs", func() {
		NewBasket([]*grc20.Token{red, red}, []int64{1, 1}, "X", "X", 4, 0, cur)
	})
	uassert.PanicsContains(t, cur, "nil underlying token", func() {
		NewBasket([]*grc20.Token{red, nil}, []int64{1, 1}, "X", "X", 4, 0, cur)
	})
}

func TestBasketMoveAndAllowance(cur realm, t *testing.T) {
	red, redLed, blue, blueLed := mintPair(cur, t, 1_000, 1_000, alice)

	testing.SetRealm(testing.NewCodeRealm(basketPath))
	b := NewBasket(
		[]*grc20.Token{red, blue},
		[]int64{1, 1},
		"Purple", "PURPLE", 4, 0, cur,
	)
	approve(cur, t, redLed, alice, b.Home(), 1_000)
	approve(cur, t, blueLed, alice, b.Home(), 1_000)
	urequire.NoError(t, b.Fuse(0, cur, alice, 100))

	urequire.NoError(t, b.Move(alice, bob, 40))
	uassert.Equal(t, int64(40), b.Token().BalanceOf(bob))
	urequire.NoError(t, b.Allow(alice, bob, 30))
	urequire.NoError(t, b.MoveFrom(bob, alice, carl, 30))
	uassert.Equal(t, int64(30), b.Token().BalanceOf(carl))
	uassert.ErrorIs(t, b.MoveFrom(bob, alice, carl, 0), ErrInvalidAmount)

	// bob holds meta units he never minted, and can still split them.
	urequire.NoError(t, b.Defuse(0, cur, bob, 40))
	uassert.Equal(t, int64(40), red.BalanceOf(bob))
	uassert.Equal(t, int64(40), blue.BalanceOf(bob))
}

func TestBasketSummary(cur realm, t *testing.T) {
	red, redLed, blue, blueLed := mintPair(cur, t, 1_000, 1_000, alice)

	testing.SetRealm(testing.NewCodeRealm(basketPath))
	b := NewBasket(
		[]*grc20.Token{red, blue},
		[]int64{1, 2},
		"Purple", "PURPLE", 4, 0, cur,
	)
	approve(cur, t, redLed, alice, b.Home(), 1_000)
	approve(cur, t, blueLed, alice, b.Home(), 1_000)
	urequire.NoError(t, b.Fuse(0, cur, alice, 7))

	want := "**Purple** (PURPLE) - meta-token over 2 legs\n\n" +
		"- meta supply: 7\n" +
		"- leg RED: 1 per unit, 7 escrowed\n" +
		"- leg BLUE: 2 per unit, 14 escrowed\n" +
		"- solvent: yes\n"
	uassert.Equal(t, want, b.Summary())
}

package grc20wrap

import "gno.land/p/nt/ufmt/v0"

// Policy is a wrapper's personality. It sets the exchange rate in both
// directions and can veto a move of the wrapped token.
//
// Every method receives the vault, so a policy can price against live state -
// escrow, supply, custody - instead of a frozen constant. Embed OneToOne to
// write a policy that only overrides what it cares about.
type Policy interface {
	// WrapRate returns how many wrapped units `in` underlying units mint.
	// It is called BEFORE the escrow moves, so v.Held() excludes `in`.
	WrapRate(v *Vault, in int64) (int64, error)

	// UnwrapRate returns how many underlying units `in` wrapped units
	// release. It is called before the burn, so v.Supply() includes `in`.
	UnwrapRate(v *Vault, in int64) (int64, error)

	// CanMove vetoes a transfer of the wrapped token between two accounts.
	CanMove(v *Vault, from, to address, amount int64) error

	// Name labels the policy in a catalogue. Short, lowercase.
	Name() string
}

// OneToOne is the boring wrapper: one underlying unit in, one wrapped unit
// out, and no restriction on who may hold the result. Useful on its own as a
// pure custody receipt, and as the embedded base of every policy below.
type OneToOne struct{}

func (OneToOne) WrapRate(v *Vault, in int64) (int64, error) { return in, nil }

func (OneToOne) UnwrapRate(v *Vault, in int64) (int64, error) { return in, nil }

func (OneToOne) CanMove(v *Vault, from, to address, amount int64) error { return nil }

func (OneToOne) Name() string { return "1:1" }

// Ratio re-denominates: Num wrapped units per Den underlying units. Both terms
// must be positive.
//
// Ratio{Num: 1000, Den: 1} turns one underlying unit into a thousand wrapped
// ones, which is how you give a token three more decimals without touching the
// realm that issued it. The reverse direction divides, so a redemption that
// rounds to zero is refused (ErrDust) rather than silently burning value: with
// Num=1000, unwrapping 999 wrapped units returns nothing and is rejected.
type Ratio struct {
	OneToOne
	Num int64
	Den int64
}

func (r Ratio) WrapRate(v *Vault, in int64) (int64, error) {
	if r.Num <= 0 || r.Den <= 0 {
		return 0, ErrBadRatio
	}
	return mulDiv(in, r.Num, r.Den)
}

func (r Ratio) UnwrapRate(v *Vault, in int64) (int64, error) {
	if r.Num <= 0 || r.Den <= 0 {
		return 0, ErrBadRatio
	}
	return mulDiv(in, r.Den, r.Num)
}

func (r Ratio) Name() string { return ufmt.Sprintf("%d:%d", r.Num, r.Den) }

// Soulbound wraps another policy and refuses every transfer of the wrapped
// token. Rates are whatever Base says; a nil Base means OneToOne.
//
// The result is an account-bound receipt: anyone can wrap into it and anyone
// can unwrap back out, but the wrapped unit itself never changes hands. That
// makes it a membership badge, a proof of deposit, or a vote weight that
// cannot be rented - while the underlying stays fully liquid one step away.
//
// The veto binds signing users only; see the package doc.
type Soulbound struct {
	Base Policy
}

func (s Soulbound) base() Policy {
	if s.Base == nil {
		return OneToOne{}
	}
	return s.Base
}

func (s Soulbound) WrapRate(v *Vault, in int64) (int64, error) {
	return s.base().WrapRate(v, in)
}

func (s Soulbound) UnwrapRate(v *Vault, in int64) (int64, error) {
	return s.base().UnwrapRate(v, in)
}

func (s Soulbound) CanMove(v *Vault, from, to address, amount int64) error {
	return ErrSoulbound
}

func (s Soulbound) Name() string { return "soulbound/" + s.base().Name() }

// Pool prices in shares instead of units: the wrapped token is a claim on a
// fraction of the escrow rather than on a fixed amount.
//
//	wrap:   shares = in * supply / held      (1:1 while the pool is empty)
//	unwrap: units  = in * held  / supply
//
// Nothing changes until someone calls Vault.Donate, which adds escrow without
// minting shares. Every outstanding share is then worth more, permanently and
// for everyone at once. That is the whole yield-bearing-token pattern in two
// lines of arithmetic: a fee sink, a staking reward, an airdrop to holders, all
// the same operation.
//
// Two honest caveats:
//
//   - Division truncates, so a share is always worth marginally less than its
//     exact fraction. The remainder stays in the pool, which is the safe
//     direction: a vault can never promise more than it holds.
//   - A first depositor can wrap one unit, donate a large amount, and make
//     every later deposit smaller than one share round to zero in their favour
//     (the ERC-4626 inflation attack). Seed the pool at creation, or keep the
//     wrapped token's decimals well above the underlying's, before using this
//     anywhere real.
type Pool struct {
	OneToOne
}

func (Pool) WrapRate(v *Vault, in int64) (int64, error) {
	supply, held := v.Supply(), v.Held()
	if supply == 0 || held == 0 {
		return in, nil
	}
	return mulDiv(in, supply, held)
}

func (Pool) UnwrapRate(v *Vault, in int64) (int64, error) {
	supply := v.Supply()
	if supply == 0 {
		return 0, ErrDust
	}
	return mulDiv(in, v.Held(), supply)
}

func (Pool) Name() string { return "pool" }

// Fee takes a basis-point haircut in both directions on top of Base (nil means
// OneToOne). 100 BPS is 1%.
//
// The haircut is not paid to anyone: it stays escrowed. Over a plain base that
// only strands value, so Fee is meant to sit over Pool, where the stranded
// units raise what every remaining share redeems for. The wrapper then pays its
// holders out of its own turnover, and paying twice - in and out - costs more
// than holding.
type Fee struct {
	Base      Policy
	WrapBPS   int64
	UnwrapBPS int64
}

func (f Fee) base() Policy {
	if f.Base == nil {
		return OneToOne{}
	}
	return f.Base
}

// cut removes bps basis points from amount.
func cut(amount, bps int64) (int64, error) {
	if bps < 0 || bps > 10000 {
		return 0, ErrBadBPS
	}
	taken, err := mulDiv(amount, bps, 10000)
	if err != nil {
		return 0, err
	}
	return amount - taken, nil
}

func (f Fee) WrapRate(v *Vault, in int64) (int64, error) {
	out, err := f.base().WrapRate(v, in)
	if err != nil {
		return 0, err
	}
	return cut(out, f.WrapBPS)
}

func (f Fee) UnwrapRate(v *Vault, in int64) (int64, error) {
	out, err := f.base().UnwrapRate(v, in)
	if err != nil {
		return 0, err
	}
	return cut(out, f.UnwrapBPS)
}

func (f Fee) CanMove(v *Vault, from, to address, amount int64) error {
	return f.base().CanMove(v, from, to, amount)
}

func (f Fee) Name() string {
	return ufmt.Sprintf("fee(%d/%dbps)/%s", f.WrapBPS, f.UnwrapBPS, f.base().Name())
}

package grc20wrap

import (
	"math"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// Every policy here is stateless, so it prices correctly against a nil vault.
// Pool is the one that reads the vault, and it is covered end to end in
// TestPoolSharesAppreciate.
func TestStatelessRates(t *testing.T) {
	cases := []struct {
		name      string
		pol       Policy
		wrapIn    int64
		wrapOut   int64
		unwrapIn  int64
		unwrapOut int64
	}{
		{"one to one", OneToOne{}, 7, 7, 7, 7},
		{"kilo", Ratio{Num: 1_000, Den: 1}, 7, 7_000, 7_000, 7},
		{"kilo truncates on the way out", Ratio{Num: 1_000, Den: 1}, 1, 1_000, 2_500, 2},
		{"milli", Ratio{Num: 1, Den: 1_000}, 7_000, 7, 7, 7_000},
		{"two for three", Ratio{Num: 2, Den: 3}, 9, 6, 6, 9},
		{"soulbound keeps its base rate", Soulbound{Base: Ratio{Num: 2, Den: 1}}, 5, 10, 10, 5},
		{"soulbound with no base is 1:1", Soulbound{}, 5, 5, 5, 5},
		{"one percent both ways", Fee{WrapBPS: 100, UnwrapBPS: 100}, 1_000, 990, 1_000, 990},
		{"a haircut under one unit rounds to nothing", Fee{WrapBPS: 100}, 55, 55, 55, 55},
	}

	for _, tc := range cases {
		got, err := tc.pol.WrapRate(nil, tc.wrapIn)
		uassert.NoError(t, err, tc.name)
		uassert.Equal(t, tc.wrapOut, got, tc.name+" (wrap)")

		got, err = tc.pol.UnwrapRate(nil, tc.unwrapIn)
		uassert.NoError(t, err, tc.name)
		uassert.Equal(t, tc.unwrapOut, got, tc.name+" (unwrap)")
	}
}

func TestRateErrors(t *testing.T) {
	cases := []struct {
		name      string
		pol       Policy
		in        int64
		wrapErr   error
		unwrapErr error
	}{
		{"zero numerator", Ratio{Num: 0, Den: 1}, 5, ErrBadRatio, ErrBadRatio},
		{"negative denominator", Ratio{Num: 2, Den: -1}, 5, ErrBadRatio, ErrBadRatio},
		// Only the multiplying direction can overflow; the dividing one
		// just returns a very small number.
		{"overflowing numerator", Ratio{Num: math.MaxInt64, Den: 1}, 3, ErrOverflow, nil},
		{"basis points above 100%", Fee{WrapBPS: 10_001, UnwrapBPS: 10_001}, 100, ErrBadBPS, ErrBadBPS},
		{"negative basis points", Fee{WrapBPS: -1, UnwrapBPS: -1}, 100, ErrBadBPS, ErrBadBPS},
	}

	for _, tc := range cases {
		_, err := tc.pol.WrapRate(nil, tc.in)
		if tc.wrapErr == nil {
			uassert.NoError(t, err, tc.name+" (wrap)")
		} else {
			uassert.ErrorIs(t, err, tc.wrapErr, tc.name+" (wrap)")
		}

		_, err = tc.pol.UnwrapRate(nil, tc.in)
		if tc.unwrapErr == nil {
			uassert.NoError(t, err, tc.name+" (unwrap)")
		} else {
			uassert.ErrorIs(t, err, tc.unwrapErr, tc.name+" (unwrap)")
		}
	}
}

func TestPolicyNames(t *testing.T) {
	uassert.Equal(t, "1:1", OneToOne{}.Name())
	uassert.Equal(t, "1000:1", Ratio{Num: 1_000, Den: 1}.Name())
	uassert.Equal(t, "pool", Pool{}.Name())
	uassert.Equal(t, "soulbound/1:1", Soulbound{}.Name())
	uassert.Equal(t, "soulbound/pool", Soulbound{Base: Pool{}}.Name())
	uassert.Equal(t, "fee(0/100bps)/pool", Fee{Base: Pool{}, UnwrapBPS: 100}.Name())
}

func TestOnlySoulboundVetoes(t *testing.T) {
	uassert.NoError(t, OneToOne{}.CanMove(nil, alice, bob, 1))
	uassert.NoError(t, Ratio{Num: 1, Den: 1}.CanMove(nil, alice, bob, 1))
	uassert.NoError(t, Pool{}.CanMove(nil, alice, bob, 1))
	uassert.NoError(t, Fee{Base: Pool{}}.CanMove(nil, alice, bob, 1))
	uassert.ErrorIs(t, Soulbound{}.CanMove(nil, alice, bob, 1), ErrSoulbound)
	// A fee over a soulbound base inherits the veto.
	uassert.ErrorIs(t, Fee{Base: Soulbound{}}.CanMove(nil, alice, bob, 1), ErrSoulbound)
}

// Package grc20wrap builds derived GRC20 tokens on top of existing ones.
//
// Two shapes:
//
//   - Vault wraps ONE underlying token. It escrows underlying units at the
//     host realm's address and issues its own GRC20 against that escrow. A
//     Policy sets the exchange rate in both directions and may veto a move of
//     the wrapped token, which is where a wrapper stops being plumbing and
//     becomes a pattern: 1:1 custody, a denomination change, a
//     non-transferable receipt, a share in a growing pool.
//   - Basket wraps SEVERAL. One meta-token is minted against fixed parts of
//     every leg and splits back into them on redemption.
//
// Neither type holds chain state of its own beyond the GRC20 ledger it
// creates, so a realm keeps them wherever it likes.
//
// # How custody works
//
// Escrow lands at the HOST REALM's address. A vault moves it through
// grc20.RealmTeller, which binds eagerly to that address, so a vault can only
// ever spend what its own realm holds. Pulling a user's tokens in therefore
// takes the ordinary allowance route: the user approves the host realm's
// address on the underlying token, through that token realm's own entry
// point, and the vault draws on the allowance as itself.
//
// # Reverting, not returning
//
// Wrapping is two ledger writes on two different tokens, and gno has no
// rollback short of a panic: a returned error does not undo what already ran.
// Every method here therefore validates while nothing has moved and returns an
// error, then panics if a write fails after the point of no return. Aborting
// the transaction is the only atomicity available.
//
// # What a Policy can and cannot enforce
//
// A Policy veto binds end users, not realms. Moving the wrapped token through
// Vault.Move is the only path a signing account has, because MsgCall cannot
// build the realm argument grc20's tellers require. Another realm holding the
// wrapped token can always call grc20.RealmTeller on it and move its OWN
// balance. Soulbound means "no user can pass it on", not "it can never move".
//
// Live demo: gno.land/r/moul/x/grc20wrapdemo/v0.
package grc20wrap

import (
	"errors"
	"math/overflow"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
)

var (
	ErrNilToken       = errors.New("grc20wrap: nil underlying token")
	ErrInvalidAmount  = errors.New("grc20wrap: amount must be positive")
	ErrDust           = errors.New("grc20wrap: amount rounds to zero")
	ErrUnbacked       = errors.New("grc20wrap: payout exceeds this vault's escrow")
	ErrSoulbound      = errors.New("grc20wrap: soulbound, the wrapped token cannot change hands")
	ErrOverflow       = errors.New("grc20wrap: arithmetic overflow")
	ErrBadRatio       = errors.New("grc20wrap: ratio terms must be positive")
	ErrBadBPS         = errors.New("grc20wrap: basis points must be within 0..10000")
	ErrBadLegs        = errors.New("grc20wrap: a basket needs at least two legs, each with a positive part")
	ErrShortBalance   = errors.New("grc20wrap: insufficient balance on a leg")
	ErrShortAllowance = errors.New("grc20wrap: insufficient allowance on a leg")
)

// Vault escrows one underlying GRC20 and issues another against it.
//
// The escrow account is the host realm's own address, shared with every other
// vault that realm creates. Separation between them is the per-vault Held()
// counter, not separate accounts: a vault only ever releases what it recorded
// taking in, so the realm-wide invariant is sum(Held) <= Custody().
type Vault struct {
	under  *grc20.Token
	teller grc20.Teller // bound to home, eagerly, at construction
	home   address
	tok    *grc20.Token
	led    *grc20.PrivateLedger
	pol    Policy
	held   int64
}

// NewVault issues a new GRC20 backed by units of under.
//
// Call it from the realm that will own the vault, forwarding that realm's own
// cur: both the teller binding and the new token's origRealm are taken from it
// and cannot be forged afterwards. id disambiguates several tokens minted by
// the same realm - allocate it from one persistent seqid.ID.
//
// A nil pol means OneToOne.
func NewVault(under *grc20.Token, pol Policy, name, symbol string, decimals int, id seqid.ID, rlm realm) *Vault {
	if under == nil {
		panic(ErrNilToken)
	}
	if pol == nil {
		pol = OneToOne{}
	}
	tok, led := grc20.NewToken(name, symbol, decimals, id, rlm)
	return &Vault{
		under:  under,
		teller: under.RealmTeller(0, rlm),
		home:   rlm.Address(),
		tok:    tok,
		led:    led,
		pol:    pol,
	}
}

// Token is the wrapped token this vault issues. It is safe to hand out: a
// *grc20.Token carries metadata and read access, never the authority to debit
// anybody.
func (v *Vault) Token() *grc20.Token { return v.tok }

// Underlying is the token held in escrow.
func (v *Vault) Underlying() *grc20.Token { return v.under }

// Policy is this vault's personality.
func (v *Vault) Policy() Policy { return v.pol }

// Home is the escrow account: the host realm's address.
func (v *Vault) Home() address { return v.home }

// Held is the underlying escrowed for THIS vault, by its own accounting.
func (v *Vault) Held() int64 { return v.held }

// Supply is the wrapped token in circulation.
func (v *Vault) Supply() int64 { return v.tok.TotalSupply() }

// Custody is the underlying actually sitting at the escrow account. It covers
// every vault the host realm created over the same underlying, plus anything
// sent there by mistake, so Custody >= Held is necessary for solvency and
// sufficient only when this is the realm's single vault over that token.
func (v *Vault) Custody() int64 { return v.under.BalanceOf(v.home) }

// Solvent reports whether the escrow account still covers what this vault
// recorded taking in. False means the host realm moved the underlying behind
// the vault's back.
func (v *Vault) Solvent() bool { return v.Custody() >= v.held }

// Wrap escrows amount units of the underlying from `from` and mints the
// wrapped token to `from`, returning how much was minted.
//
// `from` must already have granted v.Home() an allowance of at least amount on
// the underlying token, set through that token realm's own entry point.
func (v *Vault) Wrap(_ int, rlm realm, from address, amount int64) (int64, error) {
	if amount <= 0 {
		return 0, ErrInvalidAmount
	}
	out, err := v.pol.WrapRate(v, amount)
	if err != nil {
		return 0, err
	}
	if out <= 0 {
		return 0, ErrDust
	}
	// Last point at which nothing has moved.
	if err := v.teller.TransferFrom(0, rlm, from, v.home, amount); err != nil {
		return 0, err
	}
	held, ok := overflow.Add64(v.held, amount)
	if !ok {
		panic(ErrOverflow)
	}
	v.held = held
	if err := v.led.Mint(from, out); err != nil {
		// The escrow already moved; only aborting the tx can undo it.
		panic(err)
	}
	return out, nil
}

// Unwrap burns amount wrapped units held by `from` and releases the underlying
// back to it, returning how much was released.
func (v *Vault) Unwrap(_ int, rlm realm, from address, amount int64) (int64, error) {
	if amount <= 0 {
		return 0, ErrInvalidAmount
	}
	out, err := v.pol.UnwrapRate(v, amount)
	if err != nil {
		return 0, err
	}
	if out <= 0 {
		return 0, ErrDust
	}
	if out > v.held {
		return 0, ErrUnbacked
	}
	// Burn first: it is the step that can legitimately fail on a short
	// balance, and it fails before anything has moved.
	if err := v.led.Burn(from, amount); err != nil {
		return 0, err
	}
	v.held -= out
	if err := v.teller.Transfer(0, rlm, from, out); err != nil {
		// The burn already happened; only aborting the tx can undo it.
		panic(err)
	}
	return out, nil
}

// Donate escrows amount units of the underlying without minting anything.
//
// Under a pool policy this is how the wrapper gets interesting: the donation
// raises what every outstanding wrapped unit redeems for, so anyone can make
// every holder richer and nobody can take it back out except by holding.
// `from` must have approved v.Home() on the underlying, as for Wrap.
func (v *Vault) Donate(_ int, rlm realm, from address, amount int64) error {
	if amount <= 0 {
		return ErrInvalidAmount
	}
	if err := v.teller.TransferFrom(0, rlm, from, v.home, amount); err != nil {
		return err
	}
	held, ok := overflow.Add64(v.held, amount)
	if !ok {
		panic(ErrOverflow)
	}
	v.held = held
	return nil
}

// Move transfers wrapped units after the policy has had its say. It is the
// only path a signing user has to move the wrapped token; see the package doc
// for what that does and does not guarantee.
func (v *Vault) Move(from, to address, amount int64) error {
	if amount <= 0 {
		return ErrInvalidAmount
	}
	if err := v.pol.CanMove(v, from, to, amount); err != nil {
		return err
	}
	return v.led.Transfer(from, to, amount)
}

// Allow sets `spender`'s allowance over `owner`'s wrapped balance.
//
// The policy is deliberately not consulted: an allowance moves nothing. It is
// checked when the allowance is spent, in MoveFrom, so a policy that starts
// vetoing later still binds allowances granted before.
func (v *Vault) Allow(owner, spender address, amount int64) error {
	return v.led.Approve(owner, spender, amount)
}

// MoveFrom spends `spender`'s allowance over `owner`'s wrapped balance, after
// the policy has had its say.
func (v *Vault) MoveFrom(spender, owner, to address, amount int64) error {
	if amount <= 0 {
		return ErrInvalidAmount
	}
	if err := v.pol.CanMove(v, owner, to, amount); err != nil {
		return err
	}
	return v.led.TransferFrom(owner, spender, to, amount)
}

// Summary renders the vault as a markdown block.
func (v *Vault) Summary() string {
	s := ufmt.Sprintf("**%s** (%s) - %s wrapper over %s\n\n",
		v.tok.GetName(), v.tok.GetSymbol(), v.pol.Name(), v.under.GetSymbol())
	s += ufmt.Sprintf("- wrapped supply: %d\n", v.Supply())
	s += ufmt.Sprintf("- escrowed underlying: %d\n", v.held)
	s += ufmt.Sprintf("- realm custody: %d\n", v.Custody())
	if v.Solvent() {
		s += "- solvent: yes\n"
	} else {
		s += "- solvent: **NO**\n"
	}
	return s
}

// mulDiv returns a*b/c, rejecting an overflowing product and a zero divisor.
// The division truncates toward zero, which always rounds in the vault's
// favour rather than the holder's.
func mulDiv(a, b, c int64) (int64, error) {
	if c <= 0 {
		return 0, ErrBadRatio
	}
	p, ok := overflow.Mul64(a, b)
	if !ok {
		return 0, ErrOverflow
	}
	return p / c, nil
}

package merkle

import "crypto/sha256"

// encodeSlices renders items in the wire shape crypto/merkle.HashFromByteSlices
// expects: a 4-byte big-endian count, then per item a 4-byte big-endian length
// followed by its bytes. The native side decodes this back into [][]byte; gno
// cannot hand a slice of slices to a native directly.
func encodeSlices(items [][]byte) []byte {
	n := 0
	for _, it := range items {
		n += 4 + len(it)
	}
	out := make([]byte, 0, 4+n)
	out = appendBE32(out, len(items))
	for _, it := range items {
		out = appendBE32(out, len(it))
		out = append(out, it...)
	}
	return out
}

func appendBE32(dst []byte, n int) []byte {
	return append(dst, byte(n>>24), byte(n>>16), byte(n>>8), byte(n))
}

// hashSortedPair is the commutative node hash: SHA256 over the two children in
// ascending byte order, so a proof needs no left/right flag. Used only by
// VerifySorted.
func hashSortedPair(a, b []byte) []byte {
	d := make([]byte, 0, len(a)+len(b))
	if less(a, b) {
		d = append(append(d, a...), b...)
	} else {
		d = append(append(d, b...), a...)
	}
	h := sha256.Sum256(d)
	return h[:]
}

// less reports a < b in lexicographic byte order. gno's bytes package is
// available, but keeping the comparison here keeps this package import-light.
func less(a, b []byte) bool {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return len(a) < len(b)
}

func equal(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// Package merkle builds and verifies Merkle inclusion proofs on gno.land.
//
// It wraps the `crypto/merkle` stdlib, which is native (implemented in Go,
// gas-metered) and shipped with the chain, and which had no callers anywhere
// before this package. Verification is a single native call, so it costs about
// a seventh of the equivalent hand-rolled loop in Gno.
//
// # The scheme
//
// The tree is the Tendermint simple tree, byte-for-byte the one tm2 uses for
// block headers, so a proof produced here verifies against any Tendermint
// tooling and vice versa. Two properties matter and neither is optional:
//
//   - Leaves and inner nodes are DOMAIN SEPARATED. A leaf hashes as
//     SHA256(0x00 || leaf), an inner node as SHA256(0x01 || left || right).
//     Without that tag an attacker who can choose a 64-byte leaf preimage can
//     present an inner node as if it were a leaf: the second-preimage attack.
//     Schemes that hash leaves bare (OpenZeppelin's `MerkleProof`,
//     merkletreejs defaults, `p/demo/merkle`) are safe only as long as no leaf
//     preimage can be exactly 64 bytes, which is an accident of encoding
//     rather than a property of the design.
//   - Proofs are INDEX BOUND. A proof carries its leaf index and the total
//     leaf count, and the verifier recomputes the tree shape from them. A
//     proof for index i cannot be replayed at index j, and a proof of the
//     wrong length is rejected rather than folded.
//
// The tree is NOT padded to a power of two. Following Tendermint, a tree of n
// leaves splits at the largest power of two below n, which makes the shape a
// function of n alone. Duplicating or promoting an odd trailing leaf, as
// Bitcoin and merkletreejs do, lets two different leaf sets produce one root.
//
// # Bounds
//
// Verify refuses proofs deeper than MaxDepth. An unbounded sibling list is a
// loop whose length an untrusted caller picks; the caller pays the gas, but
// there is no reason to accept 10,000 siblings for a tree that cannot hold
// more than 2^64 leaves.
//
// # Reproducing a tree off chain
//
// Any Tendermint implementation agrees with this one. In Go:
//
//	import "github.com/gnolang/gno/tm2/pkg/crypto/merkle"
//	root, proofs := merkle.SimpleProofsFromByteSlices(leaves)
//
// # What this package cannot do
//
// It verifies a leaf against a root YOU SUPPLY. A realm has no access to the
// block header or the app hash (`chain/runtime` exposes only ChainID,
// ChainDomain, ChainHeight and GetSessionInfo), so no realm can check that a
// root is the chain's own. Anything built on this is trust-minimised relative
// to a committed root, never trustless. See `r/moul/x/provable/v0` for what
// gno.land can and cannot prove about itself.
//
// Live demo: gno.land/r/moul/x/provable/v0
package merkle

import (
	"crypto/merkle"
	"encoding/hex"
	"errors"
	"strings"
)

// HashSize is the length in bytes of every node hash (SHA256).
const HashSize = 32

// MaxDepth caps the sibling count Verify will fold. A tree of 2^64 leaves has
// depth 64, so nothing legitimate ever exceeds it.
const MaxDepth = 64

var (
	ErrEmptyTree    = errors.New("merkle: tree has no leaves")
	ErrIndexRange   = errors.New("merkle: leaf index out of range")
	ErrProofTooDeep = errors.New("merkle: proof deeper than MaxDepth")
	ErrBadHex       = errors.New("merkle: sibling is not valid hex")
	ErrBadHashSize  = errors.New("merkle: sibling is not 32 bytes")
)

// LeafHash returns SHA256(0x00 || leaf), the Tendermint leaf hash.
func LeafHash(leaf []byte) []byte { return merkle.LeafHash(leaf) }

// InnerHash returns SHA256(0x01 || left || right), the Tendermint inner hash.
func InnerHash(left, right []byte) []byte { return merkle.InnerHash(left, right) }

// Proof is an inclusion proof for one leaf of a tree of Total leaves.
//
// Siblings are ordered leaf first, root last: Siblings[0] is the leaf's
// immediate sibling and the final entry is the other child of the root. This
// is Tendermint's "aunts" order.
type Proof struct {
	Index    int
	Total    int
	Siblings [][]byte
}

// Tree is an immutable Merkle tree over a fixed list of leaves.
//
// It holds the leaves, so it is meant to be built inside one call (from
// arguments, or from a bounded realm collection) rather than kept in realm
// storage. For an append-only log that stores only O(log n) state, use
// gno.land/p/moul/x/mmr/v0 instead.
type Tree struct {
	leaves [][]byte
	root   []byte
}

// New builds a tree over leaves, in the order given. The order is part of the
// commitment: the same set in a different order is a different root.
func New(leaves [][]byte) *Tree {
	cp := make([][]byte, len(leaves))
	for i, l := range leaves {
		b := make([]byte, len(l))
		copy(b, l)
		cp[i] = b
	}
	t := &Tree{leaves: cp}
	if len(cp) > 0 {
		t.root = merkle.HashFromByteSlices(encodeSlices(cp))
	}
	return t
}

// Size returns the number of leaves.
func (t *Tree) Size() int { return len(t.leaves) }

// Root returns the tree root. It is nil for an empty tree, matching
// Tendermint, where the root of nothing is nothing rather than a hash of
// nothing.
//
// The nil is produced here rather than passed through: a native that returns
// Go nil hands gno back a NON-NIL zero-length slice, so `== nil` on a value
// straight out of crypto/merkle never fires. Test len(), not nil, on anything
// that crossed that boundary.
func (t *Tree) Root() []byte { return t.root }

// RootHex returns Root hex-encoded, the form to paste into a realm call.
func (t *Tree) RootHex() string { return hex.EncodeToString(t.root) }

// Proof returns the inclusion proof for the leaf at index.
func (t *Tree) Proof(index int) (Proof, error) {
	if len(t.leaves) == 0 {
		return Proof{}, ErrEmptyTree
	}
	if index < 0 || index >= len(t.leaves) {
		return Proof{}, ErrIndexRange
	}
	return Proof{
		Index:    index,
		Total:    len(t.leaves),
		Siblings: aunts(t.leaves, index),
	}, nil
}

// aunts collects the sibling hashes on the path from leaves[index] to the
// root, leaf first. It mirrors Tendermint's split-point recursion exactly; any
// divergence here produces proofs the native verifier rejects.
func aunts(leaves [][]byte, index int) [][]byte {
	if len(leaves) <= 1 {
		return nil
	}
	k := splitPoint(len(leaves))
	if index < k {
		sub := aunts(leaves[:k], index)
		return append(sub, subtreeRoot(leaves[k:]))
	}
	sub := aunts(leaves[k:], index-k)
	return append(sub, subtreeRoot(leaves[:k]))
}

func subtreeRoot(leaves [][]byte) []byte {
	return merkle.HashFromByteSlices(encodeSlices(leaves))
}

// splitPoint returns the largest power of two strictly less than length.
func splitPoint(length int) int {
	if length < 2 {
		return 0
	}
	k := 1
	for k<<1 < length {
		k <<= 1
	}
	return k
}

// Verify reports whether leaf really sits at p.Index of a tree of p.Total
// leaves whose root is root. It is one native call plus the bounds checks.
//
// Every failure is a false rather than a panic, so a realm can decide whether
// a bad proof is a revert or a branch.
func (p Proof) Verify(root, leaf []byte) bool {
	if len(root) != HashSize || p.Total <= 0 || p.Index < 0 || p.Index >= p.Total {
		return false
	}
	if len(p.Siblings) > MaxDepth {
		return false
	}
	flat := make([]byte, 0, len(p.Siblings)*HashSize)
	for _, s := range p.Siblings {
		if len(s) != HashSize {
			return false
		}
		flat = append(flat, s...)
	}
	return merkle.VerifySimpleProof(root, leaf, p.Index, p.Total, flat)
}

// Hex renders the siblings as a comma-separated hex list, the form a user
// pastes into a transaction. Index and Total travel as their own arguments.
func (p Proof) Hex() string {
	parts := make([]string, len(p.Siblings))
	for i, s := range p.Siblings {
		parts[i] = hex.EncodeToString(s)
	}
	return strings.Join(parts, ",")
}

// ParseProof rebuilds a Proof from the arguments of a realm call. An empty or
// whitespace-only sibling list is valid: it is the proof for a one-leaf tree.
func ParseProof(index, total int, hexSiblings string) (Proof, error) {
	p := Proof{Index: index, Total: total}
	s := strings.TrimSpace(hexSiblings)
	if s == "" {
		return p, nil
	}
	parts := strings.Split(s, ",")
	if len(parts) > MaxDepth {
		return Proof{}, ErrProofTooDeep
	}
	for _, raw := range parts {
		raw = strings.TrimSpace(raw)
		if raw == "" {
			continue
		}
		b, err := hex.DecodeString(raw)
		if err != nil {
			return Proof{}, ErrBadHex
		}
		if len(b) != HashSize {
			return Proof{}, ErrBadHashSize
		}
		p.Siblings = append(p.Siblings, b)
	}
	return p, nil
}

// VerifySorted folds a commutative, sorted-pair proof: node = SHA256(min || max)
// at every step, which is what OpenZeppelin's MerkleProof and merkletreejs
// produce. Provided for verifying trees built by existing Solidity tooling.
//
// PREFER Proof.Verify. This scheme is strictly weaker:
//
//   - It is not domain separated, so it is sound only while no leaf preimage
//     can be 64 bytes long. Pass an ALREADY HASHED leaf, and double-hash it if
//     the producer does (OpenZeppelin's StandardMerkleTree does).
//   - It is not index bound, so a proof carries no position and the fold
//     accepts any depth up to MaxDepth.
//
// leafHash must be the 32-byte hash of the leaf, not the leaf.
func VerifySorted(root, leafHash []byte, siblings [][]byte) bool {
	if len(root) != HashSize || len(leafHash) != HashSize {
		return false
	}
	if len(siblings) > MaxDepth {
		return false
	}
	node := leafHash
	for _, s := range siblings {
		if len(s) != HashSize {
			return false
		}
		node = hashSortedPair(node, s)
	}
	return equal(node, root)
}

