// This package is that arithmetic. It is pure integer maths with no chain
// imports, so a realm can call it inside a Render and an off-chain bot can
// reuse the identical formula.
//
// The single fact worth remembering is the ratio. One byte freed refunds 100
// ugnot, and at the lowest gas price mainnet has actually accepted one ugnot
// buys 1000 gas. So a byte is worth 100,000 gas, and any deletion costing less
// than that per byte pays for itself.
//
// Demo realms: gno.land/r/moul/x/reaper for reaping expired state, and
// gno.land/r/moul/x/compact for the compaction half.
package storagecost

import (
	"gno.land/p/g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv/kit/num/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	// DefaultStoragePrice is the ugnot locked per byte of realm state, the
	// default of the chain's vm:p:storage_price parameter. It is governance
	// settable, so read it from the chain rather than trusting this constant
	// when real money depends on the answer.
	DefaultStoragePrice int64 = 100

	// GasPerUgnotFloor is how much gas one ugnot buys at the lowest gas price
	// mainnet has been observed to accept, 0.001 ugnot per gas. It is a floor,
	// not a promise: the fee a node requires tracks gas_wanted, so asking for
	// more headroom raises the fee proportionally.
	GasPerUgnotFloor int64 = 1000

	// payloadOverheadNum/payloadOverheadDen approximate what a payload really
	// costs once the realm has wrapped it in an object. Measured at 1.85x: ten
	// 1,024-byte strings in a realm slice cost 18,984 bytes of state, 1,898
	// each. It is an estimate and nothing more. The authoritative number is
	// the chain's own, from the vm/qstorage query or a StorageDepositEvent.
	payloadOverheadNum int64 = 185
	payloadOverheadDen int64 = 100

	// BytesPerTreeNode is the realm state one balanced-tree container node
	// occupies, for the tree containers in this namespace (p/moul/ulist and
	// what is built on it).
	//
	// Measured twice, agreeing exactly. Compacting 8 dead nodes on mainnet
	// freed 6,848 bytes (2026-09-23), and 31 nodes in the local integration
	// harness freed 26,536. Both give 856.
	//
	// It is a property of the node, not of the element: the node costs this
	// whether the value it carried was 8 bytes or 1,024. That is what makes
	// EstimateNodes accurate where EstimateBytes is only indicative.
	BytesPerTreeNode int64 = 856

	ugnotPerGNOT int64 = 1_000_000
)

// Refund is the deposit returned for freeing bytes at the given price per
// byte. Returns 0 for non-positive inputs rather than panicking, so a Render
// on a realm with no state still works.
func Refund(bytes, pricePerByte int64) int64 {
	if bytes <= 0 || pricePerByte <= 0 {
		return 0
	}
	return bytes * pricePerByte
}

// BreakEvenBytes is the fewest bytes whose refund covers a fee: the point
// where a cleanup stops costing money and starts making it. Below this many
// bytes the transaction is charity.
func BreakEvenBytes(feeUgnot, pricePerByte int64) int64 {
	if pricePerByte <= 0 {
		return 0
	}
	if feeUgnot <= 0 {
		return 0
	}
	// Round up: freeing exactly feeUgnot/pricePerByte bytes must cover the fee.
	return (feeUgnot + pricePerByte - 1) / pricePerByte
}

// GasFee is the fee a transaction asking for gasWanted must pay at a gas price
// of num/den ugnot per gas, rounded up.
//
// The fee tracks gas_wanted rather than gas_used, so unused headroom is paid
// for. Pass the ceiling you will actually put in the transaction, not what you
// expect to burn.
func GasFee(gasWanted, num, den int64) int64 {
	if gasWanted <= 0 || num <= 0 || den <= 0 {
		return 0
	}
	return (gasWanted*num + den - 1) / den
}

// FloorGasFee is GasFee at the lowest gas price mainnet has accepted.
func FloorGasFee(gasWanted int64) int64 {
	return GasFee(gasWanted, 1, GasPerUgnotFloor)
}

// EstimateBytes guesses the realm state a payload of this many bytes will
// occupy, applying the measured object overhead.
//
// It is for sizing a bounty in a Render, where being within a factor of two
// beats reporting the raw payload length. Never settle an accounting question
// with it.
func EstimateBytes(payloadBytes int64) int64 {
	if payloadBytes <= 0 {
		return 0
	}
	return payloadBytes * payloadOverheadNum / payloadOverheadDen
}

// EstimateNodes is the realm state a count of dead container nodes occupies,
// and so what compacting them frees.
//
// Prefer it to EstimateBytes wherever the caller can count, which for a
// compaction it always can. EstimateBytes scales a payload length by a ratio
// measured at one size and is wrong at the others: a per-entry floor dominates
// at the small end, and a realm advertising a bounty that way under-reported
// by 25x against what the cleanup actually returned on chain (2026-09-23).
// Counting nodes has no such failure mode. The container reports the exact
// number, and every node costs the same.
//
// Still an estimate. BytesPerTreeNode is measured rather than derived, and the
// chain's own StorageDepositEvent remains the only settlement.
func EstimateNodes(nodes int64) int64 {
	if nodes <= 0 {
		return 0
	}
	return nodes * BytesPerTreeNode
}

// Quote is a complete answer for one candidate cleanup.
type Quote struct {
	Bytes     int64 // bytes the cleanup would free
	Refund    int64 // ugnot returned for them
	Fee       int64 // ugnot the transaction will cost
	Net       int64 // Refund - Fee; negative means it costs more than it pays
	BreakEven int64 // bytes needed to cover Fee
}

// Worth reports whether the cleanup pays for itself.
func (q Quote) Worth() bool { return q.Net > 0 }

// String renders the quote as one line of markdown-safe text, for a Render.
func (q Quote) String() string {
	verdict := "not worth it yet"
	if q.Worth() {
		verdict = "worth " + FormatGNOT(q.Net)
	}
	return ufmt.Sprintf(
		"%d bytes, refunds %s against %s of gas, break-even %d bytes: %s",
		q.Bytes, FormatGNOT(q.Refund), FormatGNOT(q.Fee), q.BreakEven, verdict,
	)
}

// Evaluate prices one cleanup: freeing bytes in a transaction asking for
// gasWanted, at a storage price of pricePerByte and a gas price of num/den
// ugnot per gas.
func Evaluate(bytes, pricePerByte, gasWanted, num, den int64) Quote {
	fee := GasFee(gasWanted, num, den)
	refund := Refund(bytes, pricePerByte)
	return Quote{
		Bytes:     bytes,
		Refund:    refund,
		Fee:       fee,
		Net:       refund - fee,
		BreakEven: BreakEvenBytes(fee, pricePerByte),
	}
}

// EvaluateAtFloor is Evaluate at the default storage price and the floor gas
// price: the best case, and the one to quote when advertising a bounty.
func EvaluateAtFloor(bytes, gasWanted int64) Quote {
	return Evaluate(bytes, DefaultStoragePrice, gasWanted, 1, GasPerUgnotFloor)
}

// FormatGNOT renders ugnot as GNOT with trailing zeros trimmed, because a
// bounty shown in ugnot is unreadable and gno has no floats.
//
// It delegates to [p/moul/kit/num], which owns amount formatting. v0 did it by
// hand with `amount = -amount`, and since that leaves math.MinInt64 negative
// both the whole and the fractional part then carried their own sign:
// FormatGNOT(math.MinInt64) returned "--9223372036854.-775808 GNOT". No caller
// in this repo can reach it, but the function is exported and a formatter that
// can return a non-number is not one.
func FormatGNOT(amount int64) string {
	return num.GNOTf(amount)
}

package storagecost

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestRefund(t *testing.T) {
	tests := []struct {
		name  string
		bytes int64
		price int64
		want  int64
	}{
		{"one byte at the default price", 1, DefaultStoragePrice, 100},
		{"the measured reap", 17835, DefaultStoragePrice, 1783500},
		{"the measured compact", 830, DefaultStoragePrice, 83000},
		{"zero bytes", 0, DefaultStoragePrice, 0},
		{"negative bytes are not a credit", -100, DefaultStoragePrice, 0},
		{"a free chain refunds nothing", 1000, 0, 0},
		{"a ten-fold price rise", 1000, 1000, 1000000},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			uassert.Equal(t, tt.want, Refund(tt.bytes, tt.price))
		})
	}
}

func TestBreakEvenBytes(t *testing.T) {
	tests := []struct {
		name string
		fee  int64
		want int64
	}{
		// A 2.6M gas call at the floor costs 2,600 ugnot, so 26 bytes.
		{"the canonical 2.6M gas call", 2600, 26},
		{"rounds up, never down", 101, 2},
		{"exactly one byte", 100, 1},
		{"a fee below one byte still needs a byte", 1, 1},
		{"no fee, no threshold", 0, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := BreakEvenBytes(tt.fee, DefaultStoragePrice)
			uassert.Equal(t, tt.want, got)
			// The definition: this many bytes covers the fee, one fewer does not.
			if tt.want > 0 {
				uassert.True(t, Refund(got, DefaultStoragePrice) >= tt.fee)
				uassert.False(t, Refund(got-1, DefaultStoragePrice) >= tt.fee)
			}
		})
	}
	uassert.Equal(t, int64(0), BreakEvenBytes(1000, 0))
}

func TestGasFee(t *testing.T) {
	// The floor mainnet has actually accepted: 1 ugnot per 1000 gas.
	uassert.Equal(t, int64(5000), FloorGasFee(5_000_000))
	uassert.Equal(t, int64(2500), FloorGasFee(2_500_000))
	// Rounds up, so a fee is never short.
	uassert.Equal(t, int64(1), FloorGasFee(1))
	uassert.Equal(t, int64(0), FloorGasFee(0))
	// The harness price used in the measurements, 1.2 ugnot per gas.
	uassert.Equal(t, int64(6_000_000), GasFee(5_000_000, 12, 10))
	uassert.Equal(t, int64(0), GasFee(5_000_000, 0, 10))
	uassert.Equal(t, int64(0), GasFee(5_000_000, 1, 0))
}

func TestEvaluateReproducesTheMeasuredReap(t *testing.T) {
	// The measured run: 17,835 bytes freed by a call that used 4,120,876 gas,
	// so gas_wanted 5,000,000 at the floor. Net +1,778,500 ugnot.
	q := EvaluateAtFloor(17835, 5_000_000)
	uassert.Equal(t, int64(1783500), q.Refund)
	uassert.Equal(t, int64(5000), q.Fee)
	uassert.Equal(t, int64(1778500), q.Net)
	uassert.Equal(t, int64(50), q.BreakEven)
	uassert.True(t, q.Worth())
}

func TestEvaluateReproducesTheMeasuredCompact(t *testing.T) {
	q := EvaluateAtFloor(830, 2_500_000)
	uassert.Equal(t, int64(83000), q.Refund)
	uassert.Equal(t, int64(2500), q.Fee)
	uassert.Equal(t, int64(80500), q.Net)
	uassert.True(t, q.Worth())
}

func TestEvaluateAtTheHarnessPriceIsALoss(t *testing.T) {
	// The same reap priced at 1.2 ugnot/gas, 1200x the floor, loses money.
	// This is why the gas price cannot be baked into a contract.
	q := Evaluate(17835, DefaultStoragePrice, 5_000_000, 12, 10)
	uassert.Equal(t, int64(6_000_000), q.Fee)
	uassert.False(t, q.Worth())
	uassert.True(t, q.Net < 0)
}

func TestQuoteString(t *testing.T) {
	worth := EvaluateAtFloor(17835, 5_000_000)
	uassert.Equal(t,
		"17835 bytes, refunds 1.7835 GNOT against 0.005 GNOT of gas, break-even 50 bytes: worth 1.7785 GNOT",
		worth.String())

	loss := Evaluate(10, DefaultStoragePrice, 5_000_000, 12, 10)
	uassert.Equal(t,
		"10 bytes, refunds 0.001 GNOT against 6 GNOT of gas, break-even 60000 bytes: not worth it yet",
		loss.String())
}

func TestFormatGNOT(t *testing.T) {
	tests := []struct {
		amount int64
		want   string
	}{
		{0, "0 GNOT"},
		{1, "0.000001 GNOT"},
		{100, "0.0001 GNOT"},
		{1_000_000, "1 GNOT"},
		{1_500_000, "1.5 GNOT"},
		{1_783_500, "1.7835 GNOT"},
		{978_743_800, "978.7438 GNOT"},
		{-2_100, "-0.0021 GNOT"},
		{1_000_001, "1.000001 GNOT"},
	}
	for _, tt := range tests {
		uassert.Equal(t, tt.want, FormatGNOT(tt.amount))
	}
}

func TestEstimateBytes(t *testing.T) {
	// Measured: a 1,024-byte payload occupied 1,898 bytes of realm state.
	uassert.Equal(t, int64(1894), EstimateBytes(1024))
	uassert.Equal(t, int64(0), EstimateBytes(0))
	uassert.Equal(t, int64(0), EstimateBytes(-5))
	// Monotonic, which is all a bounty estimate really needs.
	uassert.True(t, EstimateBytes(2048) > EstimateBytes(1024))
}

// TestFormatGNOTIsTotal pins what v0 could not do. v0 negated in int64, so at
// math.MinInt64 both halves kept a sign and it returned
// "--9223372036854.-775808 GNOT". Delegating to kit/num is the fix; this
// asserts the contract rather than the delegation.
func TestFormatGNOTIsTotal(t *testing.T) {
	const minInt64 = -9223372036854775808
	uassert.Equal(t, "-9223372036854.775808 GNOT", FormatGNOT(minInt64))
	uassert.Equal(t, "-1.5 GNOT", FormatGNOT(-1500000))
	uassert.Equal(t, "-0.000001 GNOT", FormatGNOT(-1))
	uassert.Equal(t, "1.5 GNOT", FormatGNOT(1500000))
	uassert.Equal(t, "0 GNOT", FormatGNOT(0))
}

func TestEstimateNodes(t *testing.T) {
	cases := []struct {
		name  string
		nodes int64
		want  int64
	}{
		{"none", 0, 0},
		{"negative is not an error", -5, 0},
		// The mainnet measurement this constant comes from: compacting a
		// drained 8-node board returned 6,848 bytes.
		{"the mainnet sample", 8, 6848},
		// And the local harness, which agreed to the byte.
		{"the local harness sample", 31, 26536},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, EstimateNodes(tc.nodes), tc.name)
	}
}

// TestEstimateNodesBeatsEstimateBytesOnTheCaseThatBurnedUs pins the reason
// EstimateNodes exists, not just what it computes.
//
// A realm advertised a bounty by running the payload length of five small
// entries through EstimateBytes and got 481 bytes. Reaping and compacting them
// actually returned 11,972. The payload path cannot see either the per-entry
// floor or the container, and no existing test could catch that because they
// all fed EstimateBytes the 1,024-byte payloads its ratio was measured on.
func TestEstimateNodesBeatsEstimateBytesOnTheCaseThatBurnedUs(t *testing.T) {
	const payload = 8 + 231 + 7 + 5 + 9 // the five note bodies, 260 bytes
	const reallyFreed = 11972

	guess := EstimateBytes(payload)
	uassert.True(t, guess*20 < reallyFreed,
		"EstimateBytes is still supposed to be the bad one here")

	// The container half is the part that is countable, and counting it gets
	// most of the way there on its own: 8 nodes were the larger share.
	counted := EstimateNodes(8)
	uassert.True(t, counted > guess*10,
		"counting nodes should dominate guessing from payload")
	uassert.True(t, counted <= reallyFreed,
		"counting nodes must never over-advertise")
}

package vmkit

import "errors"

// ErrTruncated is returned by every Reader method that runs past the end of
// the buffer. A snapshot is consensus state, so a short read is always a hard
// error and never a zero value.
var ErrTruncated = errors.New("vmkit: truncated snapshot")

// ErrBadSnapshot is returned when a snapshot is well-formed but not for this
// machine: wrong magic, wrong version, or a field outside its legal range.
var ErrBadSnapshot = errors.New("vmkit: snapshot is not for this machine")

// Writer builds a snapshot. Every integer is fixed-width big-endian and every
// byte slice is length-prefixed, so the encoding is canonical: the same
// machine state always produces the same bytes, on every node.
//
// Machines are not required to use it, but a machine that invents its own
// layout owes the zoo an explanation, because the cross-VM snapshot cost
// comparison only means something when the encodings match.
type Writer struct {
	buf []byte
}

// NewWriter returns a Writer with room for n bytes reserved up front.
func NewWriter(n int) *Writer {
	if n < 0 {
		n = 0
	}
	return &Writer{buf: make([]byte, 0, n)}
}

// Byte appends one byte.
func (w *Writer) Byte(b byte) { w.buf = append(w.buf, b) }

// Uint32 appends a 4-byte big-endian value.
func (w *Writer) Uint32(v uint32) {
	w.buf = append(w.buf, byte(v>>24), byte(v>>16), byte(v>>8), byte(v))
}

// Uint64 appends an 8-byte big-endian value.
func (w *Writer) Uint64(v uint64) {
	w.buf = append(w.buf,
		byte(v>>56), byte(v>>48), byte(v>>40), byte(v>>32),
		byte(v>>24), byte(v>>16), byte(v>>8), byte(v))
}

// Int appends a signed value, zig-zag encoded into a Uint64 so that small
// negative numbers do not cost eight 0xff bytes.
func (w *Writer) Int(v int64) {
	u := uint64(v) << 1
	if v < 0 {
		u = ^u
	}
	w.Uint64(u)
}

// Bytes appends a length-prefixed byte slice.
func (w *Writer) Bytes(p []byte) {
	w.Uint32(uint32(len(p)))
	w.buf = append(w.buf, p...)
}

// String appends a length-prefixed string.
func (w *Writer) String(s string) { w.Bytes([]byte(s)) }

// Out returns the encoded bytes.
func (w *Writer) Out() []byte { return w.buf }

// Reader consumes a snapshot written by [Writer].
//
// It latches the first error it hits: a caller may decode a whole struct and
// check [Reader.Err] once at the end, instead of after every field. Every
// method returns a zero value once the Reader is in error.
type Reader struct {
	buf []byte
	pos int
	err error
}

// NewReader returns a Reader over b.
func NewReader(b []byte) *Reader { return &Reader{buf: b} }

// Err returns the first error hit, or nil.
func (r *Reader) Err() error { return r.err }

// Remaining reports how many bytes are left unread.
func (r *Reader) Remaining() int {
	if r.pos > len(r.buf) {
		return 0
	}
	return len(r.buf) - r.pos
}

// Fail latches err, so a machine can reject a field its own rules forbid and
// have it surface through [Reader.Err] like any decoding failure.
func (r *Reader) Fail(err error) {
	if r.err == nil {
		r.err = err
	}
}

func (r *Reader) take(n int) []byte {
	if r.err != nil {
		return nil
	}
	if n < 0 || r.pos+n > len(r.buf) {
		r.err = ErrTruncated
		return nil
	}
	out := r.buf[r.pos : r.pos+n]
	r.pos += n
	return out
}

// Byte reads one byte.
func (r *Reader) Byte() byte {
	p := r.take(1)
	if p == nil {
		return 0
	}
	return p[0]
}

// Uint32 reads a 4-byte big-endian value.
func (r *Reader) Uint32() uint32 {
	p := r.take(4)
	if p == nil {
		return 0
	}
	return uint32(p[0])<<24 | uint32(p[1])<<16 | uint32(p[2])<<8 | uint32(p[3])
}

// Uint64 reads an 8-byte big-endian value.
func (r *Reader) Uint64() uint64 {
	p := r.take(8)
	if p == nil {
		return 0
	}
	return uint64(p[0])<<56 | uint64(p[1])<<48 | uint64(p[2])<<40 | uint64(p[3])<<32 |
		uint64(p[4])<<24 | uint64(p[5])<<16 | uint64(p[6])<<8 | uint64(p[7])
}

// Int reads a zig-zag encoded signed value written by [Writer.Int].
func (r *Reader) Int() int64 {
	u := r.Uint64()
	v := int64(u >> 1)
	if u&1 != 0 {
		v = ^v
	}
	return v
}

// Bytes reads a length-prefixed byte slice. The result is a copy, so a
// machine can keep it without aliasing the snapshot it was handed.
func (r *Reader) Bytes() []byte {
	n := int(r.Uint32())
	p := r.take(n)
	if p == nil {
		return nil
	}
	out := make([]byte, n)
	copy(out, p)
	return out
}

// String reads a length-prefixed string.
func (r *Reader) String() string {
	p := r.take(int(r.Uint32()))
	if p == nil {
		return ""
	}
	return string(p)
}

package vmkit

// Unmetered is the fuel value that disables the budget: a [Meter] built with
// it never reports exhaustion. It exists so a benchmark can measure the
// dispatch loop without the meter in it, and so a trusted caller can run a
// program to completion in one slice. Gas remains the real backstop.
const Unmetered int64 = -1

// Meter is a fuel budget being spent. It allocates nothing after
// construction, because it sits in the hot path of every guest instruction.
type Meter struct {
	budget int64 // Unmetered, or the number of units this slice may spend
	used   int64
}

// NewMeter returns a meter good for `budget` units, or an unmetered one when
// budget is [Unmetered]. A budget of zero is a meter with nothing to spend,
// which is a legitimate way to ask "is this instance still runnable".
func NewMeter(budget int64) *Meter {
	if budget < 0 {
		budget = Unmetered
	}
	return &Meter{budget: budget}
}

// Charge spends n units and reports whether they were available. On false
// nothing is spent, so the caller can stop before executing the instruction
// it could not pay for. That ordering is what makes a resumed machine
// re-execute exactly the instruction it stopped at, and no other.
func (m *Meter) Charge(n int64) bool {
	if m.budget == Unmetered {
		m.used += n
		return true
	}
	if m.used+n > m.budget {
		return false
	}
	m.used += n
	return true
}

// Used reports how much fuel has been spent.
func (m *Meter) Used() int64 { return m.used }

// Remaining reports what is left, or [Unmetered].
func (m *Meter) Remaining() int64 {
	if m.budget == Unmetered {
		return Unmetered
	}
	return m.budget - m.used
}

// Exhausted reports whether the next single unit would fail.
func (m *Meter) Exhausted() bool { return !m.affordable(1) }

func (m *Meter) affordable(n int64) bool {
	return m.budget == Unmetered || m.used+n <= m.budget
}

package vmkit

import "errors"

// ErrNotGranted is returned by a [Host] for a capability the instance was
// never given. A guest that ignores the error and keeps going is a guest bug;
// a machine should turn it into a [Trapped] status.
var ErrNotGranted = errors.New("vmkit: capability not granted")

// Host is everything a guest program can reach outside its own memory.
//
// It is deliberately small, and deliberately handed in rather than looked up:
// a guest has exactly the authority its [Host] carries. Gno realm code has
// ambient authority through the realm frame, so the guest is where the
// capability-secure version can actually be tried.
//
// Every method must be deterministic across replays of the same block. Now
// and Height come from the chain, never from a wall clock.
type Host interface {
	// Caller is the address that called the realm running this guest.
	Caller() address
	// Origin is the address that signed the transaction.
	Origin() address
	// Now is block time in Unix seconds, never wall time.
	Now() int64
	// Height is the block height.
	Height() int64

	// Get reads from storage scoped to this instance. A miss is nil.
	Get(key []byte) []byte
	// Set writes to storage scoped to this instance.
	Set(key, val []byte)

	// Input is the immutable call input for this slice of execution: the
	// guest's calldata, argv, or stdin depending on the machine. A machine
	// tracks its own read cursor, in its snapshot, so that resuming reads
	// the byte it had not read yet.
	Input() []byte
	// Output appends to the guest's output buffer.
	Output(p []byte)

	// Emit writes a chain event. kv is a flat list of alternating keys and
	// values; an odd trailing element is dropped.
	Emit(typ string, kv ...string)
	// Send transfers amount ugnot to `to`, and returns [ErrNotGranted]
	// unless the deploying realm funded this instance with a budget.
	Send(to address, amount int64) error
	// Log records a diagnostic line. Never consensus-relevant.
	Log(msg string)
}

package vmkit

import (
	"errors"

	"gno.land/p/nt/avl/v0"
)

// ErrNoInstance is returned when an id names nothing.
var ErrNoInstance = errors.New("vmkit: no such instance")

// ErrBudgetExhausted is returned when an instance has already spent its total
// fuel budget, so there is nothing left to step.
var ErrBudgetExhausted = errors.New("vmkit: instance fuel budget exhausted")

// Instance is one guest program as a realm stores it: the code, the machine
// state between slices, and the accounting that survives the transaction.
//
// It holds a snapshot rather than a [Machine], on purpose. A realm keeps
// bytes; the machine is rebuilt for the slice that needs it and thrown away
// after. That is what makes the storage cost of a paused program measurable,
// which is the whole kill criterion for continuations: if resuming costs more
// than re-running, continuations are theater.
type Instance struct {
	ID    string
	Owner address
	VM    string // which guest machine the Program is for

	Program  []byte
	Snapshot []byte

	Status Status
	Trap   string

	// FuelUsed is the total across every slice run so far.
	FuelUsed int64
	// FuelBudget caps FuelUsed across the instance's whole life, or is
	// [Unmetered] for no cap.
	FuelBudget int64

	// Slices counts how many transactions have stepped this instance.
	Slices int64

	Output []byte
}

// NewInstance returns an instance ready for its first slice.
func NewInstance(id string, owner address, vm string, program []byte, budget int64) *Instance {
	if budget < 0 {
		budget = Unmetered
	}
	prog := make([]byte, len(program))
	copy(prog, program)
	return &Instance{
		ID:         id,
		Owner:      owner,
		VM:         vm,
		Program:    prog,
		Status:     Running,
		FuelBudget: budget,
	}
}

// Remaining reports the fuel left in the instance's total budget, or
// [Unmetered].
func (i *Instance) Remaining() int64 {
	if i.FuelBudget == Unmetered {
		return Unmetered
	}
	left := i.FuelBudget - i.FuelUsed
	if left < 0 {
		return 0
	}
	return left
}

// Slice returns how much fuel the next call to [Instance.Run] may spend when
// the caller asks for `want`: `want` clamped to what the budget still allows.
func (i *Instance) Slice(want int64) int64 {
	left := i.Remaining()
	if left == Unmetered {
		return want
	}
	if want == Unmetered || want > left {
		return left
	}
	return want
}

// Run steps m for one slice of at most `fuel` units and folds the result back
// into the instance: the new snapshot, the status, the fuel spent, and
// anything the guest wrote to h.
//
// m must be a fresh machine loaded from i.Program; Run restores i.Snapshot
// into it when there is one, so the caller never has to remember the order.
// The instance is left untouched when Restore fails, which means a snapshot
// that cannot be decoded costs the caller gas but never corrupts the stored
// program.
func (i *Instance) Run(m Machine, h Host, fuel int64) error {
	if i.Status.Done() && i.Status != Running {
		return ErrBudgetExhausted
	}
	if len(i.Snapshot) > 0 {
		if err := m.Restore(i.Snapshot); err != nil {
			return err
		}
	}
	slice := i.Slice(fuel)
	if slice == 0 {
		i.Status = OutOfFuel
		return ErrBudgetExhausted
	}

	used, status := m.Step(h, slice)

	i.FuelUsed += used
	i.Slices++
	i.Snapshot = m.Snapshot()
	i.Status = status
	i.Trap = TrapReason(m)
	if status == Running && i.Remaining() == 0 {
		i.Status = OutOfFuel
	}
	return nil
}

// Store is the avl-backed set of instances a realm owns, keyed by id.
type Store struct {
	tree *avl.Tree
}

// NewStore returns an empty store.
func NewStore() *Store { return &Store{tree: avl.NewTree()} }

// Set writes an instance, replacing any instance with the same id.
func (s *Store) Set(i *Instance) {
	if i == nil {
		return
	}
	s.tree.Set(i.ID, i)
}

// Get returns the instance with this id, or nil.
func (s *Store) Get(id string) *Instance {
	v := s.tree.Get(id)
	if v == nil {
		return nil
	}
	inst, ok := v.(*Instance)
	if !ok {
		return nil
	}
	return inst
}

// Remove deletes an instance and reports whether it existed.
func (s *Store) Remove(id string) bool {
	_, removed := s.tree.Remove(id)
	return removed
}

// Size returns how many instances are stored.
func (s *Store) Size() int { return s.tree.Size() }

// Iterate walks every instance in key order, stopping early when fn returns
// true.
func (s *Store) Iterate(fn func(*Instance) bool) {
	s.tree.Iterate("", "", func(_ string, v any) bool {
		inst, ok := v.(*Instance)
		if !ok {
			return false
		}
		return fn(inst)
	})
}

// ReverseIterate walks every instance in descending key order, which is how a
// realm renders newest-first when ids are zero-padded and ascending.
func (s *Store) ReverseIterate(fn func(*Instance) bool) {
	s.tree.ReverseIterate("", "", func(_ string, v any) bool {
		inst, ok := v.(*Instance)
		if !ok {
			return false
		}
		return fn(inst)
	})
}

// Package vmkit is the host ABI shared by every guest virtual machine that
// runs inside a gno realm: a stepping contract with an explicit fuel budget,
// a capability-scoped [Host], and a snapshot format that lets a guest program
// outlive the transaction that started it.
//
// A guest VM implements [Machine]. Everything else in this package is the
// machinery a VM should not have to write twice: the [Meter], the [Codec] the
// snapshots are built from, an in-memory [TestHost], and the avl-backed
// [Store] a realm keeps its instances in.
//
// The three things the ABI exists to fix:
//
//   - Fuel is the interface, not the backstop. Running out of fuel yields
//     [OutOfFuel] plus a machine that can be snapshotted, never a panic. Gas
//     still bounds the transaction, but a guest that stops is a normal outcome.
//   - Continuations. Snapshot and Restore mean a program runs across blocks.
//     The realm stores the bytes, and the next caller pays for the next slice.
//     Gno realm code itself cannot pause; a guest can.
//   - Capabilities, not ambient authority. A guest gets exactly the [Host] it
//     was handed. No Send without a grant, no storage outside its own scope.
//
// Live demo: [r/moul/x/vm/bfdemo](/r/moul/x/vm/bfdemo/v0), running the
// [p/moul/x/vm/bf](/p/moul/x/vm/bf/v0) guest.
package vmkit

// Status is the outcome of a call to [Machine.Step].
type Status int

const (
	// Running means the machine stopped because it ran out of the fuel
	// handed to this slice, but the program has not finished. It is
	// resumable: snapshot it, and step it again later.
	Running Status = iota

	// Halted means the program reached its end. Terminal.
	Halted

	// Trapped means the guest did something the machine refuses to do:
	// an invalid instruction, an out-of-range access, a capability it was
	// not granted. Terminal.
	Trapped

	// OutOfFuel means the instance exhausted its total budget, not just the
	// fuel for this slice. Terminal unless the owner raises the budget.
	OutOfFuel
)

// String renders the status as the lowercase word used in realm output.
func (s Status) String() string {
	switch s {
	case Running:
		return "running"
	case Halted:
		return "halted"
	case Trapped:
		return "trapped"
	case OutOfFuel:
		return "out of fuel"
	}
	return "unknown"
}

// Done reports whether the status is terminal, i.e. stepping again is
// pointless without operator intervention.
func (s Status) Done() bool { return s != Running }

// Machine is one guest virtual machine, mid-execution.
//
// Step runs until the program halts, traps, or burns `fuel` units, whichever
// comes first, and reports how much fuel it actually used. A Machine must
// charge at least one unit per guest instruction so that a fuel budget is a
// real bound on work; beyond that the unit is the VM's own business, and
// [r/moul/x/vm/bfdemo](/r/moul/x/vm/bfdemo/v0) compares them by measurement
// rather than by trusting the number.
//
// Snapshot must round-trip through Restore: a machine stepped to exhaustion,
// snapshotted, restored and stepped again must produce exactly what the same
// machine stepped in one go would have. That property is what makes a guest
// program a contract instead of a function call.
type Machine interface {
	Step(h Host, fuel int64) (used int64, status Status)
	Snapshot() []byte
	Restore(b []byte) error
}

// Trapper is an optional refinement of [Machine]: a machine that can explain
// why it trapped. Kept out of [Machine] so the core ABI stays three methods.
type Trapper interface {
	// Trap returns the reason for a [Trapped] status, or "" when the
	// machine has not trapped.
	Trap() string
}

// TrapReason returns m's trap reason when m implements [Trapper], else "".
func TrapReason(m Machine) string {
	if t, ok := m.(Trapper); ok {
		return t.Trap()
	}
	return ""
}

package vmkit

import "gno.land/p/nt/avl/v0"

// TestHost is a deterministic in-memory [Host] for unit tests and for
// measuring a machine without a chain under it.
//
// Nothing here reads the chain, so a test that uses it produces the same
// numbers on every host. Storage is an avl tree rather than a map because gno
// map iteration order is unspecified, and [TestHost.Keys] has to be stable for
// a test to assert on it.
//
// Send is denied unless [TestHost.Grant] funded a budget, which is how the
// capability rule gets tested: a guest that tries to send without a grant must
// come back [Trapped], not silently succeed.
type TestHost struct {
	caller address
	origin address
	now    int64
	height int64

	store *avl.Tree // hex key -> []byte

	in     []byte
	out    []byte
	events []string
	logs   []string

	sendBudget int64
	sends      []Transfer
}

// Transfer records one successful [TestHost.Send].
type Transfer struct {
	To     address
	Amount int64
}

// NewTestHost returns a host with no capabilities granted, height 1, time 0,
// and empty input.
func NewTestHost() *TestHost {
	return &TestHost{
		height: 1,
		store:  avl.NewTree(),
	}
}

// WithCaller sets the address the guest sees as its caller and origin.
func (h *TestHost) WithCaller(a address) *TestHost {
	h.caller, h.origin = a, a
	return h
}

// WithOrigin overrides the origin separately from the caller.
func (h *TestHost) WithOrigin(a address) *TestHost { h.origin = a; return h }

// WithTime sets the block time in Unix seconds.
func (h *TestHost) WithTime(t int64) *TestHost { h.now = t; return h }

// WithHeight sets the block height.
func (h *TestHost) WithHeight(n int64) *TestHost { h.height = n; return h }

// WithInput sets the guest's call input.
func (h *TestHost) WithInput(p []byte) *TestHost {
	h.in = make([]byte, len(p))
	copy(h.in, p)
	return h
}

// Grant funds the send capability with a budget in ugnot. Without it, Send
// returns [ErrNotGranted].
func (h *TestHost) Grant(budget int64) *TestHost { h.sendBudget = budget; return h }

func (h *TestHost) Caller() address { return h.caller }
func (h *TestHost) Origin() address { return h.origin }
func (h *TestHost) Now() int64      { return h.now }
func (h *TestHost) Height() int64   { return h.height }
func (h *TestHost) Input() []byte   { return h.in }

func (h *TestHost) Get(key []byte) []byte {
	v := h.store.Get(hexKey(key))
	if v == nil {
		return nil
	}
	stored := v.([]byte)
	out := make([]byte, len(stored))
	copy(out, stored)
	return out
}

func (h *TestHost) Set(key, val []byte) {
	cp := make([]byte, len(val))
	copy(cp, val)
	h.store.Set(hexKey(key), cp)
}

func (h *TestHost) Output(p []byte) { h.out = append(h.out, p...) }

func (h *TestHost) Emit(typ string, kv ...string) {
	line := typ
	for i := 0; i+1 < len(kv); i += 2 {
		line += " " + kv[i] + "=" + kv[i+1]
	}
	h.events = append(h.events, line)
}

func (h *TestHost) Send(to address, amount int64) error {
	if amount <= 0 || amount > h.sendBudget {
		return ErrNotGranted
	}
	h.sendBudget -= amount
	h.sends = append(h.sends, Transfer{To: to, Amount: amount})
	return nil
}

func (h *TestHost) Log(msg string) { h.logs = append(h.logs, msg) }

// Out returns everything the guest has written, as bytes.
func (h *TestHost) Out() []byte { return h.out }

// OutString returns everything the guest has written, as a string.
func (h *TestHost) OutString() string { return string(h.out) }

// ResetOut discards the output buffer, so one host can measure several runs.
func (h *TestHost) ResetOut() { h.out = nil }

// Events returns the rendered events, in emission order.
func (h *TestHost) Events() []string { return h.events }

// Logs returns the diagnostic lines, in emission order.
func (h *TestHost) Logs() []string { return h.logs }

// Sends returns the transfers that succeeded, in order.
func (h *TestHost) Sends() []Transfer { return h.sends }

// Keys returns every storage key the guest wrote, hex-encoded, in sorted
// order.
func (h *TestHost) Keys() []string {
	out := []string{}
	h.store.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

const hexDigits = "0123456789abcdef"

// hexKey encodes a raw key as hex so that arbitrary bytes, including a zero
// byte, survive being used as an avl key.
func hexKey(key []byte) string {
	out := make([]byte, 0, len(key)*2)
	for _, c := range key {
		out = append(out, hexDigits[c>>4], hexDigits[c&0x0f])
	}
	return string(out)
}

package vmkit

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// counter is a toy [Machine] used to test the kit itself without dragging in
// a real guest VM: it writes one byte per step and halts after `total` of
// them. Anything that works here is a property of the ABI, not of brainfuck.
type counter struct {
	total int64
	done  int64
	trap  string
}

func (c *counter) Step(h Host, fuel int64) (int64, Status) {
	m := NewMeter(fuel)
	var used int64
	for c.done < c.total {
		if !m.Charge(1) {
			return used, Running
		}
		used++
		c.done++
		h.Output([]byte{byte('a' + (c.done-1)%26)})
	}
	return used, Halted
}

func (c *counter) Snapshot() []byte {
	w := NewWriter(24)
	w.Int(c.total)
	w.Int(c.done)
	w.String(c.trap)
	return w.Out()
}

func (c *counter) Restore(b []byte) error {
	r := NewReader(b)
	total := r.Int()
	done := r.Int()
	trap := r.String()
	if err := r.Err(); err != nil {
		return err
	}
	c.total, c.done, c.trap = total, done, trap
	return nil
}

func (c *counter) Trap() string { return c.trap }

func TestStatusString(t *testing.T) {
	cases := []struct {
		s    Status
		want string
		done bool
	}{
		{Running, "running", false},
		{Halted, "halted", true},
		{Trapped, "trapped", true},
		{OutOfFuel, "out of fuel", true},
		{Status(99), "unknown", true},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, tc.s.String())
		uassert.Equal(t, tc.done, tc.s.Done())
	}
}

func TestMeterCharge(t *testing.T) {
	m := NewMeter(10)
	uassert.True(t, m.Charge(4))
	uassert.Equal(t, int64(4), m.Used())
	uassert.Equal(t, int64(6), m.Remaining())

	// A charge that does not fit spends nothing, so the caller can stop
	// before the instruction it cannot pay for.
	uassert.False(t, m.Charge(7))
	uassert.Equal(t, int64(4), m.Used())

	uassert.True(t, m.Charge(6))
	uassert.True(t, m.Exhausted())
	uassert.False(t, m.Charge(1))
}

func TestMeterUnmetered(t *testing.T) {
	m := NewMeter(Unmetered)
	uassert.True(t, m.Charge(1 << 40))
	uassert.False(t, m.Exhausted())
	uassert.Equal(t, Unmetered, m.Remaining())
}

func TestMeterZeroBudget(t *testing.T) {
	m := NewMeter(0)
	uassert.True(t, m.Exhausted())
	uassert.False(t, m.Charge(1))
	uassert.Equal(t, int64(0), m.Used())
}

func TestCodecRoundTrip(t *testing.T) {
	w := NewWriter(0)
	w.Byte(0xab)
	w.Uint32(0xdeadbeef)
	w.Uint64(0x0102030405060708)
	w.Int(-1234567)
	w.Int(0)
	w.Int(1234567)
	w.Bytes([]byte{0, 1, 2, 255})
	w.String("gno.land")

	r := NewReader(w.Out())
	uassert.Equal(t, uint64(0xab), uint64(r.Byte()))
	uassert.Equal(t, uint64(0xdeadbeef), uint64(r.Uint32()))
	uassert.Equal(t, uint64(0x0102030405060708), r.Uint64())
	uassert.Equal(t, int64(-1234567), r.Int())
	uassert.Equal(t, int64(0), r.Int())
	uassert.Equal(t, int64(1234567), r.Int())
	uassert.Equal(t, 4, len(r.Bytes()))
	uassert.Equal(t, "gno.land", r.String())
	uassert.NoError(t, r.Err())
	uassert.Equal(t, 0, r.Remaining())
}

func TestCodecIsCanonical(t *testing.T) {
	// The same state must always produce the same bytes: a snapshot is
	// consensus state, so two nodes encoding it differently is a fork.
	build := func() []byte {
		w := NewWriter(0)
		w.Int(-7)
		w.String("x")
		w.Uint32(9)
		return w.Out()
	}
	uassert.Equal(t, string(build()), string(build()))
}

func TestCodecTruncated(t *testing.T) {
	r := NewReader([]byte{1, 2})
	r.Uint64()
	uassert.ErrorIs(t, r.Err(), ErrTruncated)
	// Once latched, every later read is a zero value and the error stands.
	uassert.Equal(t, "", r.String())
	uassert.ErrorIs(t, r.Err(), ErrTruncated)
}

func TestCodecBytesAreCopied(t *testing.T) {
	w := NewWriter(0)
	w.Bytes([]byte{1, 2, 3})
	buf := w.Out()
	r := NewReader(buf)
	got := r.Bytes()
	buf[len(buf)-1] = 99 // mutate the snapshot under the reader
	uassert.Equal(t, 3, len(got))
	uassert.Equal(t, uint64(3), uint64(got[2]))
}

func TestTestHostStorage(t *testing.T) {
	h := NewTestHost()
	uassert.Equal(t, 0, len(h.Get([]byte("missing"))))

	h.Set([]byte{0, 1}, []byte("zero-prefixed"))
	h.Set([]byte("k"), []byte("v"))
	uassert.Equal(t, "zero-prefixed", string(h.Get([]byte{0, 1})))
	uassert.Equal(t, "v", string(h.Get([]byte("k"))))

	// Keys are hex so a zero byte survives, and sorted so a test can pin
	// them.
	keys := h.Keys()
	uassert.Equal(t, 2, len(keys))
	uassert.Equal(t, "0001", keys[0])
	uassert.Equal(t, "6b", keys[1])
}

func TestTestHostStorageIsCopied(t *testing.T) {
	h := NewTestHost()
	val := []byte("abc")
	h.Set([]byte("k"), val)
	val[0] = 'z'
	uassert.Equal(t, "abc", string(h.Get([]byte("k"))))

	got := h.Get([]byte("k"))
	got[0] = 'z'
	uassert.Equal(t, "abc", string(h.Get([]byte("k"))))
}

func TestTestHostSendNeedsAGrant(t *testing.T) {
	to := address("g1manfred47kzduec920z88wfr64ylksmdcedlf5")

	h := NewTestHost()
	uassert.ErrorIs(t, h.Send(to, 100), ErrNotGranted)
	uassert.Equal(t, 0, len(h.Sends()))

	h.Grant(150)
	uassert.NoError(t, h.Send(to, 100))
	uassert.Equal(t, 1, len(h.Sends()))
	uassert.Equal(t, int64(100), h.Sends()[0].Amount)

	// The grant is a budget, not a switch.
	uassert.ErrorIs(t, h.Send(to, 100), ErrNotGranted)
	uassert.NoError(t, h.Send(to, 50))
}

func TestTestHostEventsAndInput(t *testing.T) {
	h := NewTestHost().WithInput([]byte("hi")).WithHeight(42).WithTime(1700000000)
	uassert.Equal(t, "hi", string(h.Input()))
	uassert.Equal(t, int64(42), h.Height())
	uassert.Equal(t, int64(1700000000), h.Now())

	h.Emit("run", "id", "1", "status", "halted")
	h.Emit("odd", "dangling")
	uassert.Equal(t, 2, len(h.Events()))
	uassert.Equal(t, "run id=1 status=halted", h.Events()[0])
	uassert.Equal(t, "odd", h.Events()[1]) // odd trailing element dropped
}

func TestInstanceRunsToCompletion(t *testing.T) {
	inst := NewInstance("1", address("g1x"), "counter", []byte("5"), Unmetered)
	h := NewTestHost()
	uassert.NoError(t, inst.Run(&counter{total: 5}, h, Unmetered))
	uassert.Equal(t, "halted", inst.Status.String())
	uassert.Equal(t, int64(5), inst.FuelUsed)
	uassert.Equal(t, int64(1), inst.Slices)
	uassert.Equal(t, "abcde", h.OutString())
}

func TestInstanceResumesAcrossSlices(t *testing.T) {
	// The property that makes a guest program a contract: five slices of
	// one unit must equal one slice of five.
	inst := NewInstance("1", address("g1x"), "counter", []byte("5"), Unmetered)
	h := NewTestHost()
	for i := 0; i < 5; i++ {
		// A realm holds bytes, not a machine: every slice loads a fresh
		// one from the program and lets Restore carry the state over.
		uassert.NoError(t, inst.Run(&counter{total: 5}, h, 1))
	}
	uassert.Equal(t, "halted", inst.Status.String())
	uassert.Equal(t, int64(5), inst.FuelUsed)
	uassert.Equal(t, int64(5), inst.Slices)
	uassert.Equal(t, "abcde", h.OutString())
}

func TestInstanceStopsAtItsBudget(t *testing.T) {
	inst := NewInstance("1", address("g1x"), "counter", []byte("10"), 3)
	h := NewTestHost()
	uassert.NoError(t, inst.Run(&counter{total: 10}, h, Unmetered))
	uassert.Equal(t, "out of fuel", inst.Status.String())
	uassert.Equal(t, int64(3), inst.FuelUsed)
	uassert.Equal(t, int64(0), inst.Remaining())
	uassert.Equal(t, "abc", h.OutString())

	// A second call has nothing to spend and says so instead of looping.
	uassert.ErrorIs(t, inst.Run(&counter{}, h, Unmetered), ErrBudgetExhausted)
}

func TestInstanceSliceClamps(t *testing.T) {
	inst := NewInstance("1", address("g1x"), "counter", nil, 10)
	inst.FuelUsed = 7
	uassert.Equal(t, int64(3), inst.Slice(100))
	uassert.Equal(t, int64(2), inst.Slice(2))
	uassert.Equal(t, int64(3), inst.Slice(Unmetered))

	open := NewInstance("2", address("g1x"), "counter", nil, Unmetered)
	uassert.Equal(t, int64(5), open.Slice(5))
	uassert.Equal(t, Unmetered, open.Slice(Unmetered))
}

func TestInstanceRejectsABadSnapshot(t *testing.T) {
	inst := NewInstance("1", address("g1x"), "counter", []byte("5"), Unmetered)
	inst.Snapshot = []byte{1, 2, 3} // too short for the counter's three fields
	err := inst.Run(&counter{}, NewTestHost(), Unmetered)
	uassert.ErrorIs(t, err, ErrTruncated)
	// The instance is untouched: a snapshot that cannot be decoded costs
	// gas but never corrupts the stored program.
	uassert.Equal(t, int64(0), inst.Slices)
	uassert.Equal(t, "5", string(inst.Program))
}

func TestStore(t *testing.T) {
	s := NewStore()
	uassert.Equal(t, 0, s.Size())
	uassert.Equal(t, true, s.Get("nope") == nil)

	s.Set(NewInstance("001", address("g1a"), "counter", nil, Unmetered))
	s.Set(NewInstance("002", address("g1b"), "counter", nil, Unmetered))
	s.Set(NewInstance("003", address("g1c"), "counter", nil, Unmetered))
	uassert.Equal(t, 3, s.Size())
	uassert.Equal(t, "002", s.Get("002").ID)

	ids := ""
	s.Iterate(func(i *Instance) bool { ids += i.ID + " "; return false })
	uassert.Equal(t, "001 002 003 ", ids)

	rev := ""
	s.ReverseIterate(func(i *Instance) bool { rev += i.ID + " "; return false })
	uassert.Equal(t, "003 002 001 ", rev)

	// Early stop.
	first := ""
	s.Iterate(func(i *Instance) bool { first = i.ID; return true })
	uassert.Equal(t, "001", first)

	uassert.True(t, s.Remove("002"))
	uassert.False(t, s.Remove("002"))
	uassert.Equal(t, 2, s.Size())
}

func TestTrapReason(t *testing.T) {
	uassert.Equal(t, "boom", TrapReason(&counter{trap: "boom"}))
	uassert.Equal(t, "", TrapReason(&counter{}))
}

// Package capwallet issues narrow, bounded, revocable capabilities to
// agents — instead of handing an agent a wallet key and hoping its prompt
// stays safe.
//
// The demo makes three ideas that are usually conflated stand apart:
//
//   - identity      — "this is agent Percy"
//   - authorization — "Percy may call this function on this realm"
//   - approval      — "Percy may do it at most N times, for ≤ M coins,
//                      before block H, and I can revoke it at any moment"
//
// A capability is the third thing: a least-privilege grant with a ceiling,
// an expiry, a use counter and a kill switch. Other realms consult
// Authorized() before honoring an agent action; the granter revokes with
// one call the instant something looks wrong.
package capwallet

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

// Use records one exercise of a capability.
type Use struct {
	By     address
	Coins  int64
	Height int64
}

// Capability is a least-privilege grant from a granter to a principal.
type Capability struct {
	ID            uint64
	Granter       address
	Principal     address // the only address that may exercise it
	TargetRealm   string  // realm the capability is scoped to
	Function      string  // function the capability authorizes
	MaxCoins      int64   // per-exercise ceiling in ugnot (0 = none allowed)
	ValidUntil    int64   // block height after which it expires (0 = never)
	RemainingUses uint32  // exercises left (0 = exhausted)
	ArgsPolicy    string  // human-readable note on allowed arguments
	Revoked       bool
	GrantedAt     int64
	Uses          []Use
}

var caps []*Capability // index 0 => ID 1

// Grant issues a capability. The caller becomes its granter and can revoke
// it later. validUntil is an absolute block height (0 = no expiry).
func Grant(
	cur realm,
	principal address,
	targetRealm, function string,
	maxCoins, validUntil int64,
	uses uint32,
	argsPolicy string,
) uint64 {
	assert(targetRealm != "" && function != "", "target realm and function required")
	assert(uses > 0, "must grant at least one use")

	id := uint64(len(caps)) + 1
	c := &Capability{
		ID:            id,
		Granter:       cur.Previous().Address(),
		Principal:     principal,
		TargetRealm:   targetRealm,
		Function:      function,
		MaxCoins:      maxCoins,
		ValidUntil:    validUntil,
		RemainingUses: uses,
		ArgsPolicy:    argsPolicy,
		GrantedAt:     runtime.ChainHeight(),
	}
	caps = append(caps, c)
	chain.Emit("CapabilityGranted",
		"id", ufmt.Sprintf("%d", id),
		"principal", principal.String(),
		"target", targetRealm+"."+function,
	)
	return id
}

// Exercise consumes one use of a capability. Only the principal may call it,
// and every bound is checked: not revoked, not expired, uses remaining, and
// coins within the ceiling. On success the use is recorded and the counter
// decremented.
func Exercise(cur realm, id uint64, coins int64) {
	c := mustGet(id)
	caller := cur.Previous().Address()
	assert(caller == c.Principal, "caller is not the capability principal")
	assertUsable(c)
	assert(coins <= c.MaxCoins, ufmt.Sprintf("coins %d exceed capability ceiling %d", coins, c.MaxCoins))

	c.RemainingUses--
	c.Uses = append(c.Uses, Use{By: caller, Coins: coins, Height: runtime.ChainHeight()})
	chain.Emit("CapabilityExercised",
		"id", ufmt.Sprintf("%d", id),
		"coins", ufmt.Sprintf("%d", coins),
		"remaining", ufmt.Sprintf("%d", c.RemainingUses),
	)
}

// Revoke disables a capability immediately. Only the granter may revoke.
func Revoke(cur realm, id uint64) {
	c := mustGet(id)
	assert(cur.Previous().Address() == c.Granter, "only the granter may revoke")
	c.Revoked = true
	chain.Emit("CapabilityRevoked", "id", ufmt.Sprintf("%d", id))
}

// ---- read-only API for gating realms ----

// Authorized reports whether principal may exercise capability id for the
// given coin amount right now — the check a target realm runs before acting.
// It never mutates state or consumes a use.
func Authorized(id uint64, principal address, coins int64) bool {
	if id < 1 || id > uint64(len(caps)) {
		return false
	}
	c := caps[id-1]
	if c.Principal != principal || !usable(c) {
		return false
	}
	return coins <= c.MaxCoins
}

// Get returns a copy of a capability.
func Get(id uint64) Capability { return *mustGet(id) }

// Count returns the number of capabilities issued.
func Count() int { return len(caps) }

// ---- internal ----

func usable(c *Capability) bool {
	if c.Revoked || c.RemainingUses == 0 {
		return false
	}
	if c.ValidUntil != 0 && runtime.ChainHeight() > c.ValidUntil {
		return false
	}
	return true
}

func assertUsable(c *Capability) {
	assert(!c.Revoked, "capability revoked")
	assert(c.RemainingUses > 0, "capability exhausted")
	assert(c.ValidUntil == 0 || runtime.ChainHeight() <= c.ValidUntil, "capability expired")
}

func mustGet(id uint64) *Capability {
	assert(id >= 1 && id <= uint64(len(caps)), "unknown capability")
	return caps[id-1]
}

func assert(cond bool, msg string) {
	if !cond {
		panic(msg)
	}
}

// Render shows all capabilities, or one capability's detail + usage at :<id>.
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	return renderCap(parseID(path))
}

func renderIndex() string {
	var sb strings.Builder
	sb.WriteString("# Capability Wallet\n\n")
	sb.WriteString("_Don't give an agent a wallet. Give it a capability._\n\n")
	if len(caps) == 0 {
		sb.WriteString("_No capabilities granted yet._\n")
		return sb.String()
	}
	sb.WriteString("| # | Principal | Scope | Ceiling | Uses left | State |\n")
	sb.WriteString("|---|---|---|---|---|---|\n")
	for _, c := range caps {
		sb.WriteString(ufmt.Sprintf("| [%d](/r/moul/agents/capwallet/v0:%d) | %s | `%s.%s` | %d ugnot | %d | %s |\n",
			c.ID, c.ID, short(c.Principal), c.TargetRealm, c.Function, c.MaxCoins, c.RemainingUses, state(c)))
	}
	return sb.String()
}

func renderCap(id uint64) string {
	c := mustGet(id)
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Capability #%d\n\n", c.ID))
	sb.WriteString(ufmt.Sprintf("- **State:** %s\n", state(c)))
	sb.WriteString(ufmt.Sprintf("- **Granter:** %s\n", c.Granter.String()))
	sb.WriteString(ufmt.Sprintf("- **Principal:** %s\n", c.Principal.String()))
	sb.WriteString(ufmt.Sprintf("- **Scope:** `%s.%s`\n", c.TargetRealm, c.Function))
	sb.WriteString(ufmt.Sprintf("- **Per-use ceiling:** %d ugnot\n", c.MaxCoins))
	if c.ValidUntil == 0 {
		sb.WriteString("- **Expires:** never\n")
	} else {
		sb.WriteString(ufmt.Sprintf("- **Expires at height:** %d (now %d)\n", c.ValidUntil, runtime.ChainHeight()))
	}
	sb.WriteString(ufmt.Sprintf("- **Uses remaining:** %d\n", c.RemainingUses))
	sb.WriteString(ufmt.Sprintf("- **Args policy:** %s\n\n", c.ArgsPolicy))

	sb.WriteString(ufmt.Sprintf("## Exercise log (%d)\n\n", len(c.Uses)))
	if len(c.Uses) == 0 {
		sb.WriteString("_Never exercised._\n")
		return sb.String()
	}
	sb.WriteString("| By | Coins | Height |\n|---|---|---|\n")
	for _, u := range c.Uses {
		sb.WriteString(ufmt.Sprintf("| %s | %d | %d |\n", short(u.By), u.Coins, u.Height))
	}
	return sb.String()
}

func state(c *Capability) string {
	if c.Revoked {
		return "🚫 revoked"
	}
	if c.RemainingUses == 0 {
		return "· exhausted"
	}
	if c.ValidUntil != 0 && runtime.ChainHeight() > c.ValidUntil {
		return "⏳ expired"
	}
	return "✅ live"
}

func parseID(s string) uint64 {
	var n uint64
	for i := 0; i < len(s); i++ {
		ch := s[i]
		assert(ch >= '0' && ch <= '9', "invalid capability path: "+s)
		n = n*10 + uint64(ch-'0')
	}
	return n
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

package capwallet

import (
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	owner = testutils.TestAddress("owner")
	percy = testutils.TestAddress("percy")
	mallory = testutils.TestAddress("mallory")
)

func TestGrantAndExercise(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(owner))
	// Percy may call r/moul/issues.Assign, ≤5 GNOT, 2 times, no expiry.
	id := Grant(cross(cur), percy, "gno.land/r/moul/issues", "Assign", 5000000, 0, 2, "issue IDs 100-200")

	// Read-only gate other realms use.
	uassert.True(t, Authorized(id, percy, 5000000))
	uassert.False(t, Authorized(id, percy, 5000001)) // over ceiling
	uassert.False(t, Authorized(id, mallory, 1))      // wrong principal

	testing.SetRealm(testing.NewUserRealm(percy))
	Exercise(cross(cur), id, 3000000)
	uassert.Equal(t, uint32(1), Get(id).RemainingUses)
	Exercise(cross(cur), id, 1000000)
	uassert.Equal(t, uint32(0), Get(id).RemainingUses)

	// Exhausted.
	uassert.False(t, Authorized(id, percy, 1))
	uassert.AbortsWithMessage(t, cur, "capability exhausted", func(cur realm) {
		Exercise(cur, id, 1)
	})
}

func TestCeilingEnforced(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(owner))
	id := Grant(cross(cur), percy, "r/x", "F", 100, 0, 3, "")
	testing.SetRealm(testing.NewUserRealm(percy))
	uassert.AbortsWithMessage(t, cur, "coins 101 exceed capability ceiling 100", func(cur realm) {
		Exercise(cur, id, 101)
	})
}

func TestOnlyPrincipal(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(owner))
	id := Grant(cross(cur), percy, "r/x", "F", 100, 0, 3, "")
	testing.SetRealm(testing.NewUserRealm(mallory))
	uassert.AbortsWithMessage(t, cur, "caller is not the capability principal", func(cur realm) {
		Exercise(cur, id, 1)
	})
}

func TestRevoke(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(owner))
	id := Grant(cross(cur), percy, "r/x", "F", 100, 0, 3, "")

	// Only the granter may revoke.
	testing.SetRealm(testing.NewUserRealm(mallory))
	uassert.AbortsWithMessage(t, cur, "only the granter may revoke", func(cur realm) {
		Revoke(cur, id)
	})

	testing.SetRealm(testing.NewUserRealm(owner))
	Revoke(cross(cur), id)
	uassert.False(t, Authorized(id, percy, 1))
	testing.SetRealm(testing.NewUserRealm(percy))
	uassert.AbortsWithMessage(t, cur, "capability revoked", func(cur realm) {
		Exercise(cur, id, 1)
	})
}

func TestExpiry(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(owner))
	h := int64(0) // ChainHeight in tests starts at 0; set expiry in the past-ish
	_ = h
	// Grant valid only up to height 1.
	id := Grant(cross(cur), percy, "r/x", "F", 100, 1, 3, "")
	testing.SkipHeights(5) // now well past height 1
	uassert.False(t, Authorized(id, percy, 1))
	testing.SetRealm(testing.NewUserRealm(percy))
	uassert.AbortsWithMessage(t, cur, "capability expired", func(cur realm) {
		Exercise(cur, id, 1)
	})

	uassert.True(t, len(Render("")) > 0)
	uassert.True(t, len(Render("1")) > 0)
}

// Package gnomem is a shared, contestable memory for multiple agents.
//
// Most "agent memory" products store text and retrieve similar chunks.
// That works for one agent talking to itself. It breaks the moment several
// independent agents — possibly run by different people, on different
// models — must maintain a *shared* understanding of the same world and
// sometimes disagree about it.
//
// gnomem models memory not as text but as a graph of structured claims.
// Each claim is a (subject, predicate, object) triple with an author,
// evidence and a confidence. Other agents can support it, contest it, add
// evidence, supersede it with a better claim, or trigger adjudication. No
// agent can silently erase an inconvenient finding: claims can be
// superseded or retracted, but the history stays visible and ordered.
//
// The point of the demo is the structure, not access control: anyone may
// write. Gating *who* may write to which claim is exactly what the
// capability-wallet demo adds on top.
package gnomem

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

// Status is a claim's position in the argument lifecycle.
type Status string

const (
	StatusProposed   Status = "proposed"   // asserted, no endorsements yet
	StatusSupported  Status = "supported"  // has support, no live contest
	StatusContested  Status = "contested"  // at least one live contest
	StatusAccepted   Status = "accepted"   // adjudicated true (terminal)
	StatusRetracted  Status = "retracted"  // adjudicated false / withdrawn (terminal)
	StatusSuperseded Status = "superseded" // replaced by a better claim (terminal)
)

// Endorsement is a support or contest signal from one agent.
type Endorsement struct {
	Agent      address
	Confidence uint8 // 0..100
	Note       string
	Height     int64
}

// Evidence points at off-chain material backing (or refuting) a claim.
type Evidence struct {
	By     address
	Kind   string // "report", "exploit", "dataset", "citation", ...
	Hash   string // commitment to the off-chain artifact
	Height int64
}

// Claim is one node in the shared memory graph.
type Claim struct {
	ID           uint64
	Subject      string
	Predicate    string
	Object       string
	Author       address
	Confidence   uint8
	Status       Status
	CreatedAt    int64
	Supports     []Endorsement
	Contests     []Endorsement
	Evidence     []Evidence
	SupersededBy uint64 // 0 if none
	Supersedes   uint64 // 0 if none
	Resolver     address
	ResolvedAt   int64
}

var claims []*Claim // index 0 => ID 1

// ProposeClaim asserts a new (subject, predicate, object) triple.
func ProposeClaim(cur realm, subject, predicate, object, evidenceHash string, confidence uint8) uint64 {
	assert(subject != "" && predicate != "" && object != "", "empty triple field")
	assertConfidence(confidence)

	id := uint64(len(claims)) + 1
	c := &Claim{
		ID:         id,
		Subject:    subject,
		Predicate:  predicate,
		Object:     object,
		Author:     cur.Previous().Address(),
		Confidence: confidence,
		Status:     StatusProposed,
		CreatedAt:  runtime.ChainHeight(),
	}
	if evidenceHash != "" {
		c.Evidence = append(c.Evidence, Evidence{
			By: c.Author, Kind: "initial", Hash: evidenceHash, Height: c.CreatedAt,
		})
	}
	claims = append(claims, c)
	chain.Emit("ClaimProposed", "id", ufmt.Sprintf("%d", id), "subject", subject, "predicate", predicate)
	return id
}

// SupportClaim endorses a claim. Support never overrides a live contest —
// a contested claim stays contested until adjudicated.
func SupportClaim(cur realm, id uint64, confidence uint8, note string) {
	c := mustOpen(id)
	assertConfidence(confidence)
	c.Supports = append(c.Supports, Endorsement{
		Agent: cur.Previous().Address(), Confidence: confidence, Note: note, Height: runtime.ChainHeight(),
	})
	if c.Status == StatusProposed {
		c.Status = StatusSupported
	}
	chain.Emit("ClaimSupported", "id", ufmt.Sprintf("%d", id))
}

// ContestClaim challenges a claim, optionally attaching refuting evidence.
func ContestClaim(cur realm, id uint64, note, evidenceHash string) {
	c := mustOpen(id)
	agent := cur.Previous().Address()
	h := runtime.ChainHeight()
	c.Contests = append(c.Contests, Endorsement{
		Agent: agent, Confidence: 0, Note: note, Height: h,
	})
	if evidenceHash != "" {
		c.Evidence = append(c.Evidence, Evidence{By: agent, Kind: "refutation", Hash: evidenceHash, Height: h})
	}
	c.Status = StatusContested
	chain.Emit("ClaimContested", "id", ufmt.Sprintf("%d", id))
}

// AddEvidence attaches supporting or contextual off-chain material.
func AddEvidence(cur realm, id uint64, kind, hash string) {
	c := mustOpen(id)
	assert(hash != "", "empty evidence hash")
	c.Evidence = append(c.Evidence, Evidence{
		By: cur.Previous().Address(), Kind: kind, Hash: hash, Height: runtime.ChainHeight(),
	})
}

// SupersedeClaim replaces an open claim with a new one. The old claim is
// marked superseded (terminal) and linked to its replacement, so the
// correction is visible rather than a silent overwrite.
func SupersedeClaim(cur realm, oldID uint64, subject, predicate, object, evidenceHash string, confidence uint8) uint64 {
	old := mustOpen(oldID)
	newID := ProposeClaim(cur, subject, predicate, object, evidenceHash, confidence)
	newC := claims[newID-1]
	newC.Supersedes = oldID
	old.Status = StatusSuperseded
	old.SupersededBy = newID
	chain.Emit("ClaimSuperseded", "old", ufmt.Sprintf("%d", oldID), "new", ufmt.Sprintf("%d", newID))
	return newID
}

// ResolveClaim adjudicates an open claim as accepted (true) or retracted
// (false/withdrawn). The resolver's address is recorded — resolution is
// itself a provenance-bearing act, not an anonymous verdict.
func ResolveClaim(cur realm, id uint64, accepted bool) {
	c := mustOpen(id)
	if accepted {
		c.Status = StatusAccepted
	} else {
		c.Status = StatusRetracted
	}
	c.Resolver = cur.Previous().Address()
	c.ResolvedAt = runtime.ChainHeight()
	chain.Emit("ClaimResolved", "id", ufmt.Sprintf("%d", id), "status", string(c.Status))
}

// ---- read-only API ----

// Get returns a copy of a claim by id.
func Get(id uint64) Claim { return *mustGet(id) }

// Count returns the number of claims in the graph.
func Count() int { return len(claims) }

// IsOpen reports whether a claim can still be supported/contested/resolved.
func IsOpen(id uint64) bool { return isOpen(mustGet(id).Status) }

// ---- internal ----

func isOpen(s Status) bool {
	return s == StatusProposed || s == StatusSupported || s == StatusContested
}

func mustGet(id uint64) *Claim {
	assert(id >= 1 && id <= uint64(len(claims)), "unknown claim")
	return claims[id-1]
}

func mustOpen(id uint64) *Claim {
	c := mustGet(id)
	assert(isOpen(c.Status), "claim is resolved (terminal): "+string(c.Status))
	return c
}

func assertConfidence(c uint8) { assert(c <= 100, "confidence must be 0..100") }

func assert(cond bool, msg string) {
	if !cond {
		panic(msg)
	}
}

// Render shows the full graph, or one claim's argument tree at :<id>.
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	return renderClaim(parseID(path))
}

func renderIndex() string {
	var sb strings.Builder
	sb.WriteString("# GnoMem — Contested Shared Memory\n\n")
	sb.WriteString(ufmt.Sprintf("A graph of %d structured claim(s) maintained by multiple agents.\n\n", len(claims)))
	if len(claims) == 0 {
		sb.WriteString("_No claims yet._\n")
		return sb.String()
	}
	sb.WriteString("| # | Claim | Status | ✋ support | ⚔ contest |\n")
	sb.WriteString("|---|---|---|---|---|\n")
	for _, c := range claims {
		sb.WriteString(ufmt.Sprintf("| [%d](/r/moul/agents/gnomem/v0:%d) | %s | %s | %d | %d |\n",
			c.ID, c.ID, triple(c), statusBadge(c.Status), len(c.Supports), len(c.Contests)))
	}
	return sb.String()
}

func renderClaim(id uint64) string {
	c := mustGet(id)
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Claim #%d\n\n", c.ID))
	sb.WriteString(ufmt.Sprintf("> **%s**\n\n", triple(c)))
	sb.WriteString(ufmt.Sprintf("- **Status:** %s\n", statusBadge(c.Status)))
	sb.WriteString(ufmt.Sprintf("- **Author:** %s\n", short(c.Author)))
	sb.WriteString(ufmt.Sprintf("- **Author confidence:** %d/100\n", c.Confidence))
	sb.WriteString(ufmt.Sprintf("- **Created at height:** %d\n", c.CreatedAt))
	if c.Supersedes != 0 {
		sb.WriteString(ufmt.Sprintf("- **Supersedes:** [#%d](/r/moul/agents/gnomem/v0:%d)\n", c.Supersedes, c.Supersedes))
	}
	if c.SupersededBy != 0 {
		sb.WriteString(ufmt.Sprintf("- **Superseded by:** [#%d](/r/moul/agents/gnomem/v0:%d)\n", c.SupersededBy, c.SupersededBy))
	}
	if c.ResolvedAt != 0 {
		sb.WriteString(ufmt.Sprintf("- **Resolved by:** %s at height %d\n", short(c.Resolver), c.ResolvedAt))
	}
	sb.WriteString("\n")

	sb.WriteString(ufmt.Sprintf("## ✋ Support (%d)\n\n", len(c.Supports)))
	renderEndorsements(&sb, c.Supports)
	sb.WriteString(ufmt.Sprintf("## ⚔ Contest (%d)\n\n", len(c.Contests)))
	renderEndorsements(&sb, c.Contests)

	sb.WriteString(ufmt.Sprintf("## 📎 Evidence (%d)\n\n", len(c.Evidence)))
	if len(c.Evidence) == 0 {
		sb.WriteString("_None._\n")
	} else {
		sb.WriteString("| By | Kind | Commitment | Height |\n|---|---|---|---|\n")
		for _, e := range c.Evidence {
			sb.WriteString(ufmt.Sprintf("| %s | %s | `%s` | %d |\n", short(e.By), e.Kind, shortHash(e.Hash), e.Height))
		}
	}
	return sb.String()
}

func renderEndorsements(sb *strings.Builder, es []Endorsement) {
	if len(es) == 0 {
		sb.WriteString("_None._\n\n")
		return
	}
	sb.WriteString("| Agent | Confidence | Note | Height |\n|---|---|---|---|\n")
	for _, e := range es {
		sb.WriteString(ufmt.Sprintf("| %s | %d | %s | %d |\n", short(e.Agent), e.Confidence, e.Note, e.Height))
	}
	sb.WriteString("\n")
}

func triple(c *Claim) string {
	return ufmt.Sprintf("%s — %s — %s", c.Subject, c.Predicate, c.Object)
}

func statusBadge(s Status) string {
	switch s {
	case StatusAccepted:
		return "✅ accepted"
	case StatusRetracted:
		return "🚫 retracted"
	case StatusSuperseded:
		return "♻️ superseded"
	case StatusContested:
		return "⚔ contested"
	case StatusSupported:
		return "✋ supported"
	default:
		return "· proposed"
	}
}

func parseID(s string) uint64 {
	var n uint64
	for i := 0; i < len(s); i++ {
		c := s[i]
		assert(c >= '0' && c <= '9', "invalid claim path: "+s)
		n = n*10 + uint64(c-'0')
	}
	return n
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func shortHash(s string) string {
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

package gnomem

import (
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	researcher = testutils.TestAddress("researcher")
	skeptic    = testutils.TestAddress("skeptic")
	judge      = testutils.TestAddress("judge")
)

// The canonical scenario from the design: a researcher proposes, a skeptic
// contests with an exploit, an adjudicator supersedes with the corrected
// claim.
func TestContestedThenSuperseded(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(researcher))
	id := ProposeClaim(cross(cur), "foo/v2", "is", "safe to deploy", "report#H1", 82)
	uassert.Equal(t, uint64(1), id)
	uassert.Equal(t, string(StatusProposed), string(Get(id).Status))

	// Skeptic contests with a refutation.
	testing.SetRealm(testing.NewUserRealm(skeptic))
	ContestClaim(cross(cur), id, "unbounded allocation", "exploit#H2")
	uassert.Equal(t, string(StatusContested), string(Get(id).Status))
	uassert.True(t, IsOpen(id))

	// Adjudicator supersedes with the corrected claim.
	testing.SetRealm(testing.NewUserRealm(judge))
	newID := SupersedeClaim(cross(cur), id, "foo/v2", "is", "unsafe before commit abc123", "report#H3", 95)
	uassert.Equal(t, uint64(2), newID)

	old := Get(id)
	uassert.Equal(t, string(StatusSuperseded), string(old.Status))
	uassert.Equal(t, newID, old.SupersededBy)
	uassert.False(t, IsOpen(id)) // superseded is terminal

	newC := Get(newID)
	uassert.Equal(t, id, newC.Supersedes)
	uassert.Equal(t, 1, len(newC.Evidence)) // the initial report#H3

	uassert.True(t, len(Render("")) > 0)
	uassert.True(t, len(Render("1")) > 0)
	uassert.True(t, len(Render("2")) > 0)
}

func TestSupportThenAccept(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(researcher))
	id := ProposeClaim(cross(cur), "gnovm", "supports", "persistent object graphs", "", 90)

	testing.SetRealm(testing.NewUserRealm(skeptic))
	SupportClaim(cross(cur), id, 88, "confirmed in docs")
	uassert.Equal(t, string(StatusSupported), string(Get(id).Status))

	testing.SetRealm(testing.NewUserRealm(judge))
	ResolveClaim(cross(cur), id, true)
	uassert.Equal(t, string(StatusAccepted), string(Get(id).Status))
	uassert.False(t, IsOpen(id))
}

func TestCannotMutateTerminal(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(researcher))
	id := ProposeClaim(cross(cur), "x", "is", "y", "", 50)
	ResolveClaim(cross(cur), id, false) // retracted, terminal

	uassert.AbortsWithMessage(t, cur, "claim is resolved (terminal): retracted", func(cur realm) {
		SupportClaim(cur, id, 10, "too late")
	})
}

func TestBadInputs(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(researcher))
	uassert.AbortsWithMessage(t, cur, "empty triple field", func(cur realm) {
		ProposeClaim(cur, "", "is", "y", "", 10)
	})
	uassert.AbortsWithMessage(t, cur, "confidence must be 0..100", func(cur realm) {
		ProposeClaim(cur, "a", "b", "c", "", 200)
	})
}

// Package maintainer models an AI agent stewarding a versioned on-chain
// package — without ever letting it deploy on its own authority.
//
// The agent can do the tedious, valuable parts: open a version proposal,
// collect reviews, record CI test attestations, write release notes,
// deprecate a vulnerable version, keep a compatibility matrix. What it
// cannot do is ship. Approval is gated by an explicit, machine-checked
// policy:
//
//	tests pass  AND  ≥ MinReviewers independent reviews  AND
//	every review scores ≥ MinScore  AND  the challenge window has elapsed
//
// This is the difference between "an agent with commit access" and "an
// agent that drives a process a human (or a DAO, or a policy) still gates."
// The realm records *approved* releases; the actual package publish is a
// separate, deliberately human/authority step.
package maintainer

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

const (
	MinReviewers = 2  // independent reviews required
	MinScore     = 80 // minimum score every reviewer must give
)

// Review is one reviewer's score for a proposal.
type Review struct {
	By     address
	Score  uint8 // 0..100
	Note   string
	Height int64
}

// Proposal is a candidate new version working its way toward approval.
type Proposal struct {
	ID             uint64
	Version        string
	ArtifactHash   string // commitment to the package source
	Proposer       address
	Reviews        []Review
	TestsPass      bool
	TestsAttestor  address
	OpenedAt       int64
	ChallengeUntil int64 // approval blocked until height passes this
	Approved       bool
	ApprovedAt     int64
}

// Release is an approved (and possibly later deprecated) version.
type Release struct {
	Version          string
	ArtifactHash     string
	ReleasedAt       int64
	Deprecated       bool
	DeprecatedReason string
}

var (
	proposals []*Proposal        // index 0 => ID 1
	releases  []*Release         // in release order
	byVersion = map[string]*Release{}
)

// Propose opens a version proposal with a challenge window of the given
// number of blocks (during which reviews accrue and approval is blocked).
func Propose(cur realm, version, artifactHash string, challengeBlocks int64) uint64 {
	assert(version != "", "empty version")
	assert(artifactHash != "", "empty artifact hash")
	assert(challengeBlocks >= 0, "negative challenge window")
	_, exists := byVersion[version]
	assert(!exists, "version already released: "+version)

	id := uint64(len(proposals)) + 1
	h := runtime.ChainHeight()
	proposals = append(proposals, &Proposal{
		ID:             id,
		Version:        version,
		ArtifactHash:   artifactHash,
		Proposer:       cur.Previous().Address(),
		OpenedAt:       h,
		ChallengeUntil: h + challengeBlocks,
	})
	chain.Emit("VersionProposed", "id", ufmt.Sprintf("%d", id), "version", version)
	return id
}

// AddReview records a reviewer's score. Reviewers must be independent of the
// proposer, and each address reviews at most once.
func AddReview(cur realm, propID uint64, score uint8, note string) {
	p := mustProposal(propID)
	assert(!p.Approved, "proposal already approved")
	assert(score <= 100, "score must be 0..100")
	reviewer := cur.Previous().Address()
	assert(reviewer != p.Proposer, "proposer cannot review own proposal")
	for _, r := range p.Reviews {
		assert(r.By != reviewer, "reviewer already reviewed")
	}
	p.Reviews = append(p.Reviews, Review{By: reviewer, Score: score, Note: note, Height: runtime.ChainHeight()})
	chain.Emit("VersionReviewed", "id", ufmt.Sprintf("%d", propID), "score", ufmt.Sprintf("%d", score))
}

// AttestTests records whether CI's test suite passed for the proposal.
func AttestTests(cur realm, propID uint64, pass bool) {
	p := mustProposal(propID)
	assert(!p.Approved, "proposal already approved")
	p.TestsPass = pass
	p.TestsAttestor = cur.Previous().Address()
	chain.Emit("TestsAttested", "id", ufmt.Sprintf("%d", propID), "pass", boolStr(pass))
}

// Approve promotes a proposal to a release iff every policy condition holds.
// It panics with the first unmet condition — the policy is the gate, not a
// suggestion.
func Approve(cur realm, propID uint64) {
	p := mustProposal(propID)
	assert(!p.Approved, "proposal already approved")
	assert(p.TestsPass, "policy: tests have not passed")
	assert(len(p.Reviews) >= MinReviewers, ufmt.Sprintf("policy: need %d reviews, have %d", MinReviewers, len(p.Reviews)))
	for _, r := range p.Reviews {
		assert(r.Score >= MinScore, ufmt.Sprintf("policy: review from %s scored %d < %d", short(r.By), r.Score, MinScore))
	}
	assert(runtime.ChainHeight() > p.ChallengeUntil, "policy: challenge window still open")

	p.Approved = true
	p.ApprovedAt = runtime.ChainHeight()
	rel := &Release{Version: p.Version, ArtifactHash: p.ArtifactHash, ReleasedAt: p.ApprovedAt}
	releases = append(releases, rel)
	byVersion[p.Version] = rel
	chain.Emit("VersionApproved", "id", ufmt.Sprintf("%d", propID), "version", p.Version)
}

// Deprecate flags a released version (e.g. a vulnerability was found).
func Deprecate(cur realm, version, reason string) {
	rel, ok := byVersion[version]
	assert(ok, "unknown version: "+version)
	rel.Deprecated = true
	rel.DeprecatedReason = reason
	chain.Emit("VersionDeprecated", "version", version)
}

// ---- read-only API ----

// LatestVersion returns the most recently released version, or "".
func LatestVersion() string {
	if len(releases) == 0 {
		return ""
	}
	return releases[len(releases)-1].Version
}

// IsDeprecated reports whether a released version is deprecated.
func IsDeprecated(version string) bool {
	rel, ok := byVersion[version]
	return ok && rel.Deprecated
}

// GetProposal returns a copy of a proposal.
func GetProposal(id uint64) Proposal { return *mustProposal(id) }

// ---- internal ----

func mustProposal(id uint64) *Proposal {
	assert(id >= 1 && id <= uint64(len(proposals)), "unknown proposal")
	return proposals[id-1]
}

func boolStr(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

func assert(cond bool, msg string) {
	if !cond {
		panic(msg)
	}
}

// Render shows the release matrix + open proposals, or one proposal at :<id>.
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	return renderProposal(parseID(path))
}

func renderIndex() string {
	var sb strings.Builder
	sb.WriteString("# Agent Package Maintainer\n\n")
	sb.WriteString(ufmt.Sprintf("_The agent drives the process; the policy still gates the ship._ "))
	sb.WriteString(ufmt.Sprintf("Approval needs tests + ≥%d reviews each ≥%d + an elapsed challenge window.\n\n", MinReviewers, MinScore))

	sb.WriteString("## Releases\n\n")
	if len(releases) == 0 {
		sb.WriteString("_No releases yet._\n\n")
	} else {
		sb.WriteString("| Version | Released @ | State |\n|---|---|---|\n")
		for _, r := range releases {
			st := "✅ current"
			if r.Deprecated {
				st = "⚠ deprecated: " + r.DeprecatedReason
			}
			sb.WriteString(ufmt.Sprintf("| %s | %d | %s |\n", r.Version, r.ReleasedAt, st))
		}
		sb.WriteString("\n")
	}

	sb.WriteString("## Proposals\n\n")
	if len(proposals) == 0 {
		sb.WriteString("_None._\n")
		return sb.String()
	}
	sb.WriteString("| # | Version | Tests | Reviews | Approved |\n|---|---|---|---|---|\n")
	for _, p := range proposals {
		sb.WriteString(ufmt.Sprintf("| [%d](/r/moul/agents/maintainer/v0:%d) | %s | %s | %d | %t |\n",
			p.ID, p.ID, p.Version, boolStr(p.TestsPass), len(p.Reviews), p.Approved))
	}
	return sb.String()
}

func renderProposal(id uint64) string {
	p := mustProposal(id)
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Proposal #%d — %s\n\n", p.ID, p.Version))
	sb.WriteString(ufmt.Sprintf("- **Artifact:** `%s`\n", shortHash(p.ArtifactHash)))
	sb.WriteString(ufmt.Sprintf("- **Proposer:** %s\n", short(p.Proposer)))
	sb.WriteString(ufmt.Sprintf("- **Tests pass:** %t\n", p.TestsPass))
	sb.WriteString(ufmt.Sprintf("- **Challenge window until height:** %d (now %d)\n", p.ChallengeUntil, runtime.ChainHeight()))
	sb.WriteString(ufmt.Sprintf("- **Approved:** %t\n\n", p.Approved))

	sb.WriteString(ufmt.Sprintf("## Policy checklist\n\n"))
	sb.WriteString(check(p.TestsPass, "tests pass"))
	sb.WriteString(check(len(p.Reviews) >= MinReviewers, ufmt.Sprintf("≥%d independent reviews (have %d)", MinReviewers, len(p.Reviews))))
	minOK := true
	for _, r := range p.Reviews {
		if r.Score < MinScore {
			minOK = false
		}
	}
	sb.WriteString(check(len(p.Reviews) > 0 && minOK, ufmt.Sprintf("every review ≥%d", MinScore)))
	sb.WriteString(check(runtime.ChainHeight() > p.ChallengeUntil, "challenge window elapsed"))
	sb.WriteString("\n")

	sb.WriteString(ufmt.Sprintf("## Reviews (%d)\n\n", len(p.Reviews)))
	if len(p.Reviews) == 0 {
		sb.WriteString("_None._\n")
		return sb.String()
	}
	sb.WriteString("| Reviewer | Score | Note | Height |\n|---|---|---|---|\n")
	for _, r := range p.Reviews {
		sb.WriteString(ufmt.Sprintf("| %s | %d | %s | %d |\n", short(r.By), r.Score, r.Note, r.Height))
	}
	return sb.String()
}

func check(ok bool, label string) string {
	box := "❌"
	if ok {
		box = "✅"
	}
	return ufmt.Sprintf("- %s %s\n", box, label)
}

func parseID(s string) uint64 {
	var n uint64
	for i := 0; i < len(s); i++ {
		ch := s[i]
		assert(ch >= '0' && ch <= '9', "invalid proposal path: "+s)
		n = n*10 + uint64(ch-'0')
	}
	return n
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func shortHash(s string) string {
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

package maintainer

import (
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	bot = testutils.TestAddress("maintainerbot")
	rev1 = testutils.TestAddress("rev1")
	rev2 = testutils.TestAddress("rev2")
)

func TestPolicyGate(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(bot))
	id := Propose(cross(cur), "v2", "artifact#H", 3) // 3-block challenge window

	// Approval blocked: no tests, no reviews, window open.
	uassert.AbortsWithMessage(t, cur, "policy: tests have not passed", func(cur realm) {
		Approve(cur, id)
	})

	AttestTests(cross(cur), id, true)
	uassert.AbortsWithMessage(t, cur, "policy: need 2 reviews, have 0", func(cur realm) {
		Approve(cur, id)
	})

	// One low review blocks on the min-score rule.
	testing.SetRealm(testing.NewUserRealm(rev1))
	AddReview(cross(cur), id, 90, "looks good")
	testing.SetRealm(testing.NewUserRealm(rev2))
	AddReview(cross(cur), id, 70, "concerns")
	testing.SetRealm(testing.NewUserRealm(bot))
	uassert.AbortsWithMessage(t, cur, "policy: review from "+short(rev2)+" scored 70 < 80", func(cur realm) {
		Approve(cur, id)
	})
}

func TestFullApprovalPath(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(bot))
	id := Propose(cross(cur), "v3", "artifact#H3", 2)
	AttestTests(cross(cur), id, true)

	testing.SetRealm(testing.NewUserRealm(rev1))
	AddReview(cross(cur), id, 85, "ok")
	testing.SetRealm(testing.NewUserRealm(rev2))
	AddReview(cross(cur), id, 95, "great")

	// Challenge window still open -> blocked.
	testing.SetRealm(testing.NewUserRealm(bot))
	uassert.AbortsWithMessage(t, cur, "policy: challenge window still open", func(cur realm) {
		Approve(cur, id)
	})

	testing.SkipHeights(10)
	Approve(cross(cur), id)
	uassert.True(t, GetProposal(id).Approved)
	uassert.Equal(t, "v3", LatestVersion())

	// Deprecate it.
	Deprecate(cross(cur), "v3", "CVE-xyz")
	uassert.True(t, IsDeprecated("v3"))

	uassert.True(t, len(Render("")) > 0)
	uassert.True(t, len(Render("1")) > 0)
}

func TestProposerCannotReview(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(bot))
	id := Propose(cross(cur), "v4", "a#4", 0)
	uassert.AbortsWithMessage(t, cur, "proposer cannot review own proposal", func(cur realm) {
		AddReview(cur, id, 100, "self five")
	})
}

// Package passport is an on-chain identity and lifecycle registry for
// autonomous (AI) agents.
//
// The premise: a long-lived agent identity is *weak* evidence. The code,
// model, prompt, owner, operating keys and runtime behind an identity can
// all change silently. A blockchain cannot preserve an agent's cognition;
// it can only preserve the *history* of what an identity claimed to be and
// who controlled it, in an order nobody can rewrite.
//
// So this realm does not try to prove an agent is trustworthy. It records
// registration, ownership transfers, operator changes and — crucially —
// runtime changes, and it surfaces them so a reader can judge how much the
// identity has drifted since it was created.
package passport

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Status is the lifecycle state of an agent identity.
type Status string

const (
	StatusActive    Status = "active"
	StatusSuspended Status = "suspended"
	StatusRetired   Status = "retired"
)

// Endpoint advertises where the agent can be reached or discovered
// (e.g. an MCP server, an A2A endpoint, a DID document, an ENS name).
type Endpoint struct {
	Kind string // "mcp", "a2a", "did", "url", ...
	URI  string
}

// Event is one entry in an agent's append-only lifecycle log.
type Event struct {
	Height int64
	Actor  address
	Kind   string // "register", "transfer", "add-operator", "set-runtime", ...
	Detail string
}

// Agent is a persistent, importable identity object. Other realms can
// import this package and ask questions like IsActive / IsOperator
// directly, instead of parsing NFT metadata scattered across contracts.
type Agent struct {
	ID        string
	Owner     address
	Operators []address
	Runtime   string // free-form runtime descriptor, e.g. "claude-opus-4-8@<commit>"
	Endpoints []Endpoint
	Caps      []string // declared capability slugs
	Status    Status
	CreatedAt int64
	UpdatedAt int64
	History   []Event
}

var agents = avl.NewTree() // id -> *Agent

// Register creates a new agent identity owned by the caller. The id must
// be a non-empty, previously unused slug.
func Register(cur realm, id, runtimeDesc string) {
	assert(id != "", "empty agent id")
	assert(!agents.Has(id), "agent id already registered: "+id)

	caller := cur.Previous().Address()
	h := runtime.ChainHeight()
	a := &Agent{
		ID:        id,
		Owner:     caller,
		Runtime:   runtimeDesc,
		Status:    StatusActive,
		CreatedAt: h,
		UpdatedAt: h,
	}
	a.log(h, caller, "register", "runtime="+runtimeDesc)
	agents.Set(id, a)
	chain.Emit("AgentRegistered", "id", id, "owner", caller.String())
}

// Transfer hands ownership of an agent to a new address. Only the current
// owner may call it. Ownership changes are the single most important thing
// to keep visible: the operator behind an identity may become someone else.
func Transfer(cur realm, id string, newOwner address) {
	a, caller := mustOwn(cur, id)
	old := a.Owner
	a.Owner = newOwner
	a.touch(caller, "transfer", old.String()+" -> "+newOwner.String())
	chain.Emit("AgentTransferred", "id", id, "from", old.String(), "to", newOwner.String())
}

// AddOperator authorizes an additional address to act as this agent.
func AddOperator(cur realm, id string, op address) {
	a, caller := mustOwn(cur, id)
	for _, e := range a.Operators {
		assert(e != op, "already an operator")
	}
	a.Operators = append(a.Operators, op)
	a.touch(caller, "add-operator", op.String())
	chain.Emit("AgentOperatorAdded", "id", id, "operator", op.String())
}

// SetRuntime records a change of the agent's runtime/model. This is logged
// loudly: a runtime change means the thing acting under this identity is
// (partly) a different thing than before.
func SetRuntime(cur realm, id, runtimeDesc string) {
	a, caller := mustOwn(cur, id)
	old := a.Runtime
	a.Runtime = runtimeDesc
	a.touch(caller, "set-runtime", old+" -> "+runtimeDesc)
	chain.Emit("AgentRuntimeChanged", "id", id, "runtime", runtimeDesc)
}

// AddEndpoint advertises a discovery/interaction endpoint.
func AddEndpoint(cur realm, id, kind, uri string) {
	a, caller := mustOwn(cur, id)
	a.Endpoints = append(a.Endpoints, Endpoint{Kind: kind, URI: uri})
	a.touch(caller, "add-endpoint", kind+":"+uri)
}

// DeclareCapability records a capability the agent claims to offer. Note:
// this is a *claim*, not proof. Validation belongs to other realms
// (see the receipt and gnomem demos).
func DeclareCapability(cur realm, id, capab string) {
	a, caller := mustOwn(cur, id)
	a.Caps = append(a.Caps, capab)
	a.touch(caller, "declare-capability", capab)
}

// Suspend and Retire move the lifecycle forward. Retire is terminal.
func Suspend(cur realm, id string) { setStatus(cur, id, StatusSuspended) }
func Retire(cur realm, id string)  { setStatus(cur, id, StatusRetired) }

// Reactivate returns a suspended agent to active. A retired agent cannot
// be reactivated.
func Reactivate(cur realm, id string) {
	a, caller := mustOwn(cur, id)
	assert(a.Status != StatusRetired, "retired agents cannot be reactivated")
	a.Status = StatusActive
	a.touch(caller, "reactivate", "")
}

// ---- read-only API other realms and readers can rely on ----

// Get returns a copy of the agent record; panics if unknown.
func Get(id string) Agent {
	return *mustGet(id)
}

// Exists reports whether an id is registered.
func Exists(id string) bool { return agents.Has(id) }

// IsActive reports whether the agent exists and is in the active state.
func IsActive(id string) bool {
	if !agents.Has(id) {
		return false
	}
	return agents.Get(id).(*Agent).Status == StatusActive
}

// IsOperator reports whether addr is the owner or a listed operator of an
// active agent — the check other realms should gate agent actions on.
func IsOperator(id string, addr address) bool {
	if !agents.Has(id) {
		return false
	}
	a := agents.Get(id).(*Agent)
	if a.Status != StatusActive {
		return false
	}
	if a.Owner == addr {
		return true
	}
	for _, op := range a.Operators {
		if op == addr {
			return true
		}
	}
	return false
}

// Count returns the number of registered agents.
func Count() int { return agents.Size() }

// ---- internal helpers ----

func setStatus(cur realm, id string, s Status) {
	a, caller := mustOwn(cur, id)
	assert(a.Status != StatusRetired, "agent is retired")
	a.Status = s
	a.touch(caller, "status", string(s))
	chain.Emit("AgentStatusChanged", "id", id, "status", string(s))
}

func mustGet(id string) *Agent {
	assert(agents.Has(id), "unknown agent: "+id)
	return agents.Get(id).(*Agent)
}

func mustOwn(cur realm, id string) (*Agent, address) {
	a := mustGet(id)
	caller := cur.Previous().Address()
	assert(caller == a.Owner, "caller is not the owner of "+id)
	return a, caller
}

func (a *Agent) log(h int64, actor address, kind, detail string) {
	a.History = append(a.History, Event{Height: h, Actor: actor, Kind: kind, Detail: detail})
}

func (a *Agent) touch(actor address, kind, detail string) {
	h := runtime.ChainHeight()
	a.UpdatedAt = h
	a.log(h, actor, kind, detail)
}

func assert(cond bool, msg string) {
	if !cond {
		panic(msg)
	}
}

// Render shows the registry, or a single agent's profile + lifecycle log
// at r/moul/agents/passport/v0:<id>. The profile deliberately foregrounds
// drift: how many owner and runtime changes have happened since creation.
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	return renderAgent(path)
}

func renderIndex() string {
	var sb strings.Builder
	sb.WriteString("# Agent Passport\n\n")
	sb.WriteString(ufmt.Sprintf("On-chain identity & lifecycle registry — %d agent(s).\n\n", agents.Size()))
	if agents.Size() == 0 {
		sb.WriteString("_No agents registered yet._\n")
		return sb.String()
	}
	sb.WriteString("| Agent | Owner | Runtime | Status |\n")
	sb.WriteString("|---|---|---|---|\n")
	agents.Iterate("", "", func(key string, v any) bool {
		a := v.(*Agent)
		sb.WriteString(ufmt.Sprintf("| [%s](/r/moul/agents/passport/v0:%s) | %s | %s | %s |\n",
			a.ID, a.ID, short(a.Owner), a.Runtime, string(a.Status)))
		return false
	})
	return sb.String()
}

func renderAgent(id string) string {
	a := mustGet(id)
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Agent: %s\n\n", a.ID))
	sb.WriteString(ufmt.Sprintf("- **Status:** %s\n", string(a.Status)))
	sb.WriteString(ufmt.Sprintf("- **Owner:** %s\n", a.Owner.String()))
	sb.WriteString(ufmt.Sprintf("- **Runtime:** %s\n", a.Runtime))
	sb.WriteString(ufmt.Sprintf("- **Created at height:** %d\n", a.CreatedAt))
	sb.WriteString(ufmt.Sprintf("- **Last updated at height:** %d\n\n", a.UpdatedAt))

	owners, runtimes := 0, 0
	for _, e := range a.History {
		switch e.Kind {
		case "transfer":
			owners++
		case "set-runtime":
			runtimes++
		}
	}
	sb.WriteString("## Drift\n\n")
	sb.WriteString(ufmt.Sprintf("What the chain actually proves about this identity — how much it has changed:\n\n"))
	sb.WriteString(ufmt.Sprintf("- Ownership changes since creation: **%d**\n", owners))
	sb.WriteString(ufmt.Sprintf("- Runtime changes since creation: **%d**\n\n", runtimes))

	if len(a.Operators) > 0 {
		sb.WriteString("## Operators\n\n")
		for _, op := range a.Operators {
			sb.WriteString("- " + op.String() + "\n")
		}
		sb.WriteString("\n")
	}
	if len(a.Endpoints) > 0 {
		sb.WriteString("## Endpoints\n\n")
		for _, e := range a.Endpoints {
			sb.WriteString(ufmt.Sprintf("- `%s`: %s\n", e.Kind, e.URI))
		}
		sb.WriteString("\n")
	}
	if len(a.Caps) > 0 {
		sb.WriteString("## Declared capabilities\n\n")
		sb.WriteString("> These are self-declared claims, not proofs.\n\n")
		for _, c := range a.Caps {
			sb.WriteString("- " + c + "\n")
		}
		sb.WriteString("\n")
	}

	sb.WriteString("## Lifecycle log (append-only)\n\n")
	sb.WriteString("| Height | Actor | Event | Detail |\n")
	sb.WriteString("|---|---|---|---|\n")
	for _, e := range a.History {
		sb.WriteString(ufmt.Sprintf("| %d | %s | %s | %s |\n", e.Height, short(e.Actor), e.Kind, e.Detail))
	}
	return sb.String()
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

