// Package staking is a simplified, accounting-only port of Synthetix
// StakingRewards to gno.land. Users stake a fungible amount; rewards accrue
// every block, proportional to each staker's share of the total staked,
// at a fixed rewardPerBlock. There is no real coin transfer — balances and
// rewards are plain uint64 accounting (a demonstration of the classic
// "reward-per-token" accumulator pattern).
package staking

import (
	"strconv"

	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

const (
	// rewardPerBlock is the fixed number of reward units distributed across
	// ALL stakers on every block, split by stake share.
	rewardPerBlock = uint64(100)
	// precision scales the reward-per-token accumulator to avoid truncation.
	precision = uint64(1_000_000)
)

type account struct {
	staked     uint64 // currently staked amount
	rewardPaid uint64 // reward-per-token snapshot at the account's last update
	reward     uint64 // accrued-but-unclaimed rewards
	minted     uint64 // rewards moved into the caller's reward balance
}

var (
	accounts          avl.Tree // address string -> *account
	totalStaked       uint64
	rewardPerTokenAcc uint64 // global accumulator, scaled by precision
	lastUpdateBlock   uint64
)

// --- pure helpers (unit-tested) ------------------------------------------

// computeRewardPerToken advances the accumulator by the rewards earned per
// staked unit over `elapsed` blocks. With no stake, the accumulator is frozen.
func computeRewardPerToken(stored, rate, elapsed, total uint64) uint64 {
	if total == 0 {
		return stored
	}
	return stored + (rate*elapsed*precision)/total
}

// computeEarned returns total rewards owed to an account given its stake, the
// current accumulator, the accumulator value already paid, and prior accrual.
func computeEarned(balance, rptCurrent, rptPaid, accrued uint64) uint64 {
	return accrued + (balance*(rptCurrent-rptPaid))/precision
}

// --- internals ------------------------------------------------------------

func currentBlock() uint64 { return uint64(runtime.ChainHeight()) }

func getOrCreate(addr string) *account {
	if v := accounts.Get(addr); v != nil {
		return v.(*account)
	}
	acc := &account{}
	accounts.Set(addr, acc)
	return acc
}

// accrue rolls the global accumulator forward to the current block and folds
// the caller's freshly-earned rewards into its stored balance. Mirrors the
// Synthetix `updateReward(account)` modifier.
func accrue(addr string) *account {
	elapsed := currentBlock() - lastUpdateBlock
	rewardPerTokenAcc = computeRewardPerToken(rewardPerTokenAcc, rewardPerBlock, elapsed, totalStaked)
	lastUpdateBlock = currentBlock()

	acc := getOrCreate(addr)
	acc.reward = computeEarned(acc.staked, rewardPerTokenAcc, acc.rewardPaid, acc.reward)
	acc.rewardPaid = rewardPerTokenAcc
	return acc
}

// --- exported transactions (crossing) ------------------------------------

// Stake adds `amount` to the caller's staked balance.
func Stake(cur realm, amount uint64) {
	if amount == 0 {
		panic("staking: amount must be > 0")
	}
	addr := unsafe.PreviousRealm().Address().String()
	acc := accrue(addr)
	acc.staked += amount
	totalStaked += amount
	chain.Emit("Staked", "addr", addr, "amount", strconv.FormatUint(amount, 10))
}

// Withdraw removes `amount` from the caller's staked balance.
func Withdraw(cur realm, amount uint64) {
	if amount == 0 {
		panic("staking: amount must be > 0")
	}
	addr := unsafe.PreviousRealm().Address().String()
	acc := accrue(addr)
	if amount > acc.staked {
		panic("staking: insufficient staked balance")
	}
	acc.staked -= amount
	totalStaked -= amount
	chain.Emit("Withdrawn", "addr", addr, "amount", strconv.FormatUint(amount, 10))
}

// GetReward mints all accrued rewards into the caller's reward balance and
// resets the accrual counter. Returns the amount minted this call.
func GetReward(cur realm) uint64 {
	addr := unsafe.PreviousRealm().Address().String()
	acc := accrue(addr)
	claimed := acc.reward
	acc.reward = 0
	acc.minted += claimed
	chain.Emit("RewardPaid", "addr", addr, "amount", strconv.FormatUint(claimed, 10))
	return claimed
}

// --- read-only ------------------------------------------------------------

// Earned reports the rewards currently owed to `addr` (accrued but unminted),
// projected to the current block without mutating any state.
func Earned(addr address) uint64 {
	v := accounts.Get(addr.String())
	if v == nil {
		return 0
	}
	acc := v.(*account)
	elapsed := currentBlock() - lastUpdateBlock
	rpt := computeRewardPerToken(rewardPerTokenAcc, rewardPerBlock, elapsed, totalStaked)
	return computeEarned(acc.staked, rpt, acc.rewardPaid, acc.reward)
}

// StakedOf reports the current staked balance of `addr`.
func StakedOf(addr address) uint64 {
	if v := accounts.Get(addr.String()); v != nil {
		return v.(*account).staked
	}
	return 0
}

// Render renders pool stats and a stakers table.
func Render(path string) string {
	out := "# Staking Rewards\n\n"
	out += "Simplified Synthetix-style staking (accounting-only, no coin transfer).\n\n"
	out += "- **Total staked:** " + strconv.FormatUint(totalStaked, 10) + "\n"
	out += "- **Reward rate:** " + strconv.FormatUint(rewardPerBlock, 10) + " / block (split across stakers)\n"
	out += "- **Block height:** " + strconv.FormatUint(currentBlock(), 10) + "\n\n"

	if accounts.Size() == 0 {
		out += "_No stakers yet. Call `Stake(amount)` to join._\n"
		return out
	}

	out += "## Stakers\n\n"
	out += "| Address | Staked | Earned (pending) | Minted |\n"
	out += "|---|---|---|---|\n"

	elapsed := currentBlock() - lastUpdateBlock
	rpt := computeRewardPerToken(rewardPerTokenAcc, rewardPerBlock, elapsed, totalStaked)
	accounts.Iterate("", "", func(key string, value interface{}) bool {
		acc := value.(*account)
		earned := computeEarned(acc.staked, rpt, acc.rewardPaid, acc.reward)
		out += "| " + key +
			" | " + strconv.FormatUint(acc.staked, 10) +
			" | " + strconv.FormatUint(earned, 10) +
			" | " + strconv.FormatUint(acc.minted, 10) + " |\n"
		return false
	})
	return out
}

package staking

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestComputeRewardPerToken(t *testing.T) {
	// No stakers: accumulator is frozen at its stored value.
	uassert.Equal(t, uint64(42), computeRewardPerToken(42, 100, 10, 0))

	// rate=100, elapsed=2, total=200, precision=1e6 => 100*2*1e6/200 = 1e6.
	uassert.Equal(t, precision, computeRewardPerToken(0, 100, 2, 200))

	// Accumulation builds on the stored value.
	uassert.Equal(t, 2*precision, computeRewardPerToken(precision, 100, 2, 200))
}

func TestComputeEarned(t *testing.T) {
	// balance=50, delta=precision => 50*1e6/1e6 = 50.
	uassert.Equal(t, uint64(50), computeEarned(50, precision, 0, 0))

	// Prior accrual is added on top.
	uassert.Equal(t, uint64(57), computeEarned(50, precision, 0, 7))

	// Only the un-paid portion of the accumulator counts.
	uassert.Equal(t, uint64(50), computeEarned(50, 3*precision, 2*precision, 0))

	// Zero stake earns only what was already accrued.
	uassert.Equal(t, uint64(9), computeEarned(0, 5*precision, 0, 9))
}

// Package streak is an on-chain check-in streak tracker: call CheckIn once per
// "day" to keep a streak alive, miss one and it resets to 1.
//
// There is no wall clock on-chain, so a "day" here is a fixed window of
// BlocksPerDay blocks: day = ChainHeight() / BlocksPerDay. That makes every
// streak decision a pure function of block height — deterministic, replayable,
// and impossible to game by waiting for a favourable timestamp.
//
// State is per-caller and append-only in spirit: an address's best streak is
// never lowered, so breaking a run costs the current streak but not the record.
//
// This is a stateful app with nothing reusable to extract, so it ships as a
// lone realm rather than a p/ library + demo pair.
package streak

import (
	"sort"
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// BlocksPerDay is the length of a check-in window, in blocks. Chosen so a
// window is a meaningful stretch of chain activity while keeping tests and
// demos quick to reason about.
const BlocksPerDay = 1000

// maxLeaderboard caps how many entries Render lists.
const maxLeaderboard = 10

// record is one address's streak state.
type record struct {
	current int   // consecutive days up to lastDay
	best    int   // highest current ever reached; never lowered
	lastDay int64 // day index of the most recent check-in
	totalIn int   // total check-ins ever
}

// users maps address string -> *record.
var users = avl.NewTree()

// today returns the current day index: block height divided into fixed windows.
func today() int64 { return runtime.ChainHeight() / BlocksPerDay }

// CheckIn records a check-in for the caller and returns the resulting streak.
//
// Checking in twice in the same window is rejected — the streak only moves when
// the window does. A gap of exactly one window continues the streak; any larger
// gap restarts it at 1.
func CheckIn(cur realm) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("only an EOA via MsgCall can check in")
	}
	addr := prev.Address()
	day := today()

	r := get(addr)
	if r == nil {
		r = &record{}
		users.Set(addr.String(), r)
	} else {
		switch {
		case r.totalIn > 0 && r.lastDay == day:
			panic("already checked in for day " + strconv.FormatInt(day, 10))
		case r.totalIn > 0 && r.lastDay == day-1:
			// consecutive window: the streak continues below
		default:
			// missed at least one window: the run is broken
			r.current = 0
		}
	}

	r.current++
	r.lastDay = day
	r.totalIn++
	if r.current > r.best {
		r.best = r.current
	}

	chain.Emit("CheckIn",
		"addr", addr.String(),
		"day", strconv.FormatInt(day, 10),
		"streak", strconv.Itoa(r.current),
	)
	return r.current
}

// get returns the caller's record, or nil.
//
// avl/v0's Get returns a single `any` (not the value, ok pair Go maps use), so
// a missing key surfaces as a nil interface rather than a second return value.
func get(addr address) *record {
	v := users.Get(addr.String())
	if v == nil {
		return nil
	}
	return v.(*record)
}

// Current returns addr's live streak — 0 once a window has been missed, even
// though the stored value only updates on the next check-in.
func Current(addr address) int {
	r := get(addr)
	if r == nil {
		return 0
	}
	day := today()
	if r.lastDay != day && r.lastDay != day-1 {
		return 0
	}
	return r.current
}

// Best returns addr's record streak, which is never lowered.
func Best(addr address) int {
	r := get(addr)
	if r == nil {
		return 0
	}
	return r.best
}

// Day returns the current day index.
func Day() int64 { return today() }

// entry is a flattened record for rendering.
type entry struct {
	addr    string
	current int
	best    int
	total   int
}

// byBest ranks entries by best streak descending, then by address so equal
// scores always come out in the same order (Render must be deterministic).
type byBest []entry

func (e byBest) Len() int      { return len(e) }
func (e byBest) Swap(i, j int) { e[i], e[j] = e[j], e[i] }
func (e byBest) Less(i, j int) bool {
	if e[i].best != e[j].best {
		return e[i].best > e[j].best
	}
	return e[i].addr < e[j].addr
}

// Render renders the streak board for gnoweb.
//
//	Render("")          / Render("/") -> leaderboard by best streak
//	Render("/<address>")             -> that address's standing
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Check-in Streaks\n\n")
	b.WriteString("A \"day\" is ")
	b.WriteString(strconv.Itoa(BlocksPerDay))
	b.WriteString(" blocks — there is no clock on-chain, so streaks are decided by block height alone.\n\n")
	b.WriteString("Current day: **")
	b.WriteString(strconv.FormatInt(today(), 10))
	b.WriteString("**\n\n")

	if q := parseArg(path); q != "" {
		return b.String() + renderOne(q)
	}

	entries := all()
	if len(entries) == 0 {
		b.WriteString("_Nobody has checked in yet._\n\n")
		b.WriteString("> Call `CheckIn()` to start a streak.\n")
		return b.String()
	}

	// gno's sort has Sort(Interface) but no Slice(), so ranking goes through an
	// explicit sort.Interface. Ties break on address so the board is stable.
	sort.Sort(byBest(entries))
	if len(entries) > maxLeaderboard {
		entries = entries[:maxLeaderboard]
	}

	b.WriteString("| # | address | current | best | check-ins |\n|---|---|---|---|---|\n")
	for i, e := range entries {
		b.WriteString("| ")
		b.WriteString(strconv.Itoa(i + 1))
		b.WriteString(" | `")
		b.WriteString(e.addr)
		b.WriteString("` | ")
		b.WriteString(strconv.Itoa(e.current))
		b.WriteString(" | ")
		b.WriteString(strconv.Itoa(e.best))
		b.WriteString(" | ")
		b.WriteString(strconv.Itoa(e.total))
		b.WriteString(" |\n")
	}
	return b.String()
}

// renderOne renders a single address's standing.
func renderOne(q string) string {
	addr := address(q)
	var b strings.Builder
	b.WriteString("## `")
	b.WriteString(q)
	b.WriteString("`\n\n")
	if !addr.IsValid() {
		b.WriteString("_Not a valid address._\n")
		return b.String()
	}
	r := get(addr)
	if r == nil {
		b.WriteString("_No check-ins yet._\n")
		return b.String()
	}
	b.WriteString("- current streak: **")
	b.WriteString(strconv.Itoa(Current(addr)))
	b.WriteString("**\n- best streak: **")
	b.WriteString(strconv.Itoa(r.best))
	b.WriteString("**\n- total check-ins: **")
	b.WriteString(strconv.Itoa(r.totalIn))
	b.WriteString("**\n- last check-in: day **")
	b.WriteString(strconv.FormatInt(r.lastDay, 10))
	b.WriteString("**\n")
	return b.String()
}

// all flattens the tree into a slice.
func all() []entry {
	out := []entry{}
	users.Iterate("", "", func(k string, v any) bool {
		r := v.(*record)
		out = append(out, entry{
			addr:    k,
			current: Current(address(k)),
			best:    r.best,
			total:   r.totalIn,
		})
		return false
	})
	return out
}

// parseArg extracts the first path segment.
func parseArg(path string) string {
	s := strings.TrimSpace(path)
	s = strings.TrimPrefix(s, "/")
	if i := strings.IndexByte(s, '/'); i >= 0 {
		s = s[:i]
	}
	return s
}

package streak

import (
	"strconv"
	"strings"
	"testing"

	"chain/runtime"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// reset clears realm state between tests.
func reset() { users = avl.NewTree() }

// alignDay moves to the start of the next check-in window, so a test begins on
// a clean day boundary. testing only exposes a RELATIVE SkipHeights (there is
// no absolute height setter, and no testing.Height), so days are driven
// forward from wherever the previous test left the chain — never assume an
// absolute day number, ask Day().
func alignDay() {
	if rem := runtime.ChainHeight() % BlocksPerDay; rem != 0 {
		testing.SkipHeights(BlocksPerDay - rem)
	}
}

// advanceDays moves the chain forward by n whole windows.
func advanceDays(n int64) { testing.SkipHeights(n * BlocksPerDay) }

// checkIn runs a check-in as addr.
func checkIn(cur realm, addr address) int {
	testing.SetRealm(testing.NewUserRealm(addr))
	return CheckIn(cross(cur))
}

func TestFirstCheckInStartsAtOne(cur realm, t *testing.T) {
	reset()
	alignDay()
	alice := testutils.TestAddress("alice")

	uassert.Equal(t, 1, checkIn(cur, alice))
	uassert.Equal(t, 1, Current(alice))
	uassert.Equal(t, 1, Best(alice))
}

func TestConsecutiveDaysExtendStreak(cur realm, t *testing.T) {
	reset()
	alignDay()
	alice := testutils.TestAddress("alice")

	uassert.Equal(t, 1, checkIn(cur, alice))
	advanceDays(1)
	uassert.Equal(t, 2, checkIn(cur, alice))
	advanceDays(1)
	uassert.Equal(t, 3, checkIn(cur, alice))
	uassert.Equal(t, 3, Best(alice))
}

// The whole point of the realm: a missed window restarts the run at 1, but the
// record survives.
func TestMissedDayResetsCurrentButKeepsBest(cur realm, t *testing.T) {
	reset()
	alignDay()
	alice := testutils.TestAddress("alice")

	checkIn(cur, alice)
	advanceDays(1)
	checkIn(cur, alice)
	uassert.Equal(t, 2, Best(alice))

	advanceDays(7) // a long gap
	uassert.Equal(t, 1, checkIn(cur, alice))
	uassert.Equal(t, 1, Current(alice))
	uassert.Equal(t, 2, Best(alice))
}

func TestTwiceInSameDayPanics(cur realm, t *testing.T) {
	reset()
	alignDay()
	alice := testutils.TestAddress("alice")
	checkIn(cur, alice)

	testing.SetRealm(testing.NewUserRealm(alice))
	rec := revive(func() { CheckIn(cross(cur)) })
	uassert.True(t, rec != nil)
}

// Current() reports the live truth: once the window lapses the streak is 0,
// even though the stored record still holds the old value until the next
// check-in rewrites it.
func TestCurrentGoesStaleWithoutACheckIn(cur realm, t *testing.T) {
	reset()
	alignDay()
	alice := testutils.TestAddress("alice")
	checkIn(cur, alice)

	advanceDays(1) // yesterday — still within reach
	uassert.Equal(t, 1, Current(alice))
	advanceDays(1) // gap: the run is over
	uassert.Equal(t, 0, Current(alice))
	uassert.Equal(t, 1, Best(alice)) // record untouched
}

func TestStreaksAreIndependentPerAddress(cur realm, t *testing.T) {
	reset()
	alignDay()
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")

	checkIn(cur, alice)
	advanceDays(1)
	checkIn(cur, alice)
	checkIn(cur, bob)

	uassert.Equal(t, 2, Current(alice))
	uassert.Equal(t, 1, Current(bob))
}

func TestUnknownAddressIsZero(t *testing.T) {
	reset()
	carol := testutils.TestAddress("carol")
	uassert.Equal(t, 0, Current(carol))
	uassert.Equal(t, 0, Best(carol))
}

func TestRenderEmptyBoard(t *testing.T) {
	reset()
	out := Render("")
	uassert.True(t, strings.Contains(out, "Nobody has checked in yet"))
	uassert.True(t, strings.Contains(out, "Current day: **"+strconv.FormatInt(Day(), 10)+"**"))
}

func TestRenderRanksByBest(cur realm, t *testing.T) {
	reset()
	alignDay()
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")
	// alice reaches 2, bob only 1
	checkIn(cur, alice)
	advanceDays(1)
	checkIn(cur, alice)
	checkIn(cur, bob)

	out := Render("")
	ai := strings.Index(out, alice.String())
	bi := strings.Index(out, bob.String())
	uassert.True(t, ai >= 0)
	uassert.True(t, bi >= 0)
	uassert.True(t, ai < bi) // alice ranks first
}

func TestRenderSingleAddress(cur realm, t *testing.T) {
	reset()
	alignDay()
	alice := testutils.TestAddress("alice")
	checkIn(cur, alice)

	out := Render("/" + alice.String())
	uassert.True(t, strings.Contains(out, "current streak: **1**"))
	uassert.True(t, strings.Contains(out, "total check-ins: **1**"))
}

